**提示 1：** 考虑每杯咖啡的作用。

**提示 2：** 二分最后一杯的作用。

考虑每天的每杯咖啡的作用是什么：第一杯 $k$ ，第二杯 $k-1$ ，以此类推，直到最后一杯可能工作量已经不够了，会有一个边界的问题。

整体是单调递减的。我们相当于要求其中前 $m$ 大的数值之和。

于是考虑二分这个数值，我们可以分别统计每天大于这个数值的有多少杯咖啡，借此检查边界应该更大还是更小。

找到边界后，我们先对严格更大的数求和，并计数，剩余部分都刚好等于边界，加进来即可。

时间复杂度为 $\mathcal{O}(n\log M)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m, k = MII()
    nums = LII()

    max_full_cups = [0] * n

    for i in range(n):
        nums[i] = fmin(nums[i], k * (k + 1) // 2)
        l, r = 1, k
        while l <= r:
            mid = (l + r) // 2
            if (2 * k - mid + 1) * mid // 2 <= nums[i]: l = mid + 1
            else: r = mid - 1
        max_full_cups[i] = r

    l, r = 1, k

    while l <= r:
        mid = (l + r) // 2
        total = 0

        for i in range(n):
            x = max_full_cups[i]
            if mid >= k + 1 - x:
                total += k - mid + 1
            else:
                total += x
                if nums[i] - (2 * k - x + 1) * x // 2 >= mid:
                    total += 1

            if total >= m: break

        if total >= m: l = mid + 1
        else: r = mid - 1

    ans = 0
    total = 0

    for i in range(n):
        x = max_full_cups[i]
        if r >= k + 1 - x:
            total += k - r + 1
            ans += (k + r) * (k - r + 1) // 2
        else:
            total += x
            ans += (2 * k - x + 1) * x // 2

            if nums[i] - (2 * k - x + 1) * x // 2 >= r:
                total += 1
                ans += nums[i] - (2 * k - x + 1) * x // 2

    print(ans + (m - total) * r)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, m, k;
	cin >> n >> m >> k;

	vector<long long> nums(n);
	for (auto &x: nums) cin >> x;

	vector<int> max_full_cups(n);

	for (int i = 0; i < n; i ++) {
		nums[i] = min(nums[i], 1ll * k * (k + 1) / 2);

		int l = 1, r = k;
		while (l <= r) {
			int mid = (l + r) / 2;
			if (1ll * (2 * k - mid + 1) * mid / 2 <= nums[i]) l = mid + 1;
			else r = mid - 1;
		}
		max_full_cups[i] = r;
	}

	int l = 1, r = k;

	while (l <= r) {
		int mid = (l + r) / 2, total = 0;

		for (int i = 0; i < n; i ++) {
			int x = max_full_cups[i];
			if (mid >= k + 1 - x) total += k - mid + 1;
			else {
				total += x;
				if (nums[i] - 1ll * (2 * k - x + 1) * x / 2 >= mid) total ++;
			}
			if (total >= m) break;
		}
		if (total >= m) l = mid + 1;
		else r = mid - 1;
	}

	long long ans = 0;
	int total = 0;

	for (int i = 0; i < n; i ++) {
		int x = max_full_cups[i];
		if (r >= k + 1 - x) {
			total += k - r + 1;
			ans += 1ll * (k + r) * (k - r + 1) / 2;
		}
		else {
			total += x;
			ans += 1ll * (2 * k - x + 1) * x / 2;

			if (nums[i] - 1ll * (2 * k - x + 1) * x / 2 >= r) {
				total ++;
				ans += nums[i] - 1ll * (2 * k - x + 1) * x / 2;
			}
		}
	}

	cout << ans + 1ll * (m - total) * r;

	return 0;
}
```

**提示 1：** DP，要设计什么状态？如何确定子树的顺序？

每个子树要维护什么呢？

首先是走完这一棵子树的总改变量 $ws[u]$ ，不然走完这棵子树变成什么都不知道了。

同时有的子树需要走完，有的子树只需要走进去遍历每个点，因此还需要维护这两种情况下分别的最小所需的初始能量。需要走完的记为 $dp_0[u]$ ，不需要走完的记为 $dp_1[u]$ 。

$ws[u]$ 只是个求和，很好维护。

$dp_0[u]$ 怎么维护呢？我们假设已经确定了各个子树的遍历顺序 $i_1,i_2,\dots,i_k$ ，则其结果是：

$$
\max(0, nums[u]+\max(dp_0[i_1], -ws[i_1]+dp_0[i_2],\dots,-ws[i_1]-ws[i_2]-\dots-ws[i_{k-1}]+dp_0[i_k]))
$$

我们要调整 $i_1,i_2,\dots,i_k$ 的顺序让这个数值尽可能小。

对于其中 $ws[i]\geq 0$ 的部分，走完这棵子树会多赚到能量。因此我们可以在开头将它们按照 $dp_0[i]$ 升序排列，可以使得开头完成正的改变量，同时 $\max(dp_0[i_1], -ws[i_1]+dp_0[i_2],\dots,-ws[i_1]-ws[i_2]-\dots-ws[i_{k-1}]+dp_0[i_k])$ 不会比这里的第一个 $\min dp_0[i]$ 更小，因为你迟早要走到第一个可以赚能量的子树，此时的要求不会比 $\min dp_0[i]$ 低。

对于其中 $ws[i]\lt 0$ 的部分其中相邻的两项 $i,j$ ，我们要比较的等价于 $\max(dp_0[i],-ws[i]+dp_0[j])$ 和 $\max(dp_0[j],-ws[j]+dp_0[i])$ 。

此时我们只需比较 $ws[i]+dp_0[i]$ 和 $ws[j]+dp_0[j]$ ，因为如果 $ws[i]+dp_0[i]\gt ws[j]+dp_0[j]$ ，则 $dp_0[i]\lt -ws[j]+dp_0[i]$ ，同时 $-ws[i]+dp_0[j]\lt -ws[j]+dp_0[i]$ ，也就是前者的两个元素都严格小于后者的一个元素，因此满足小于关系。反向的逻辑也是成立的。同时等号的情况下，先后顺序并不影响。

综上，按照这个关键字排序，依次遍历，即可更新 $dp_0[u]$ 。

$dp_1[u]$ 呢？相当于挑选一棵子树最后遍历，其余的子树的相对顺序和前面的 $dp_0[u]$ 一致。

所以可以在排序的序列上，去掉一个位置的元素 —— 也就是找到去掉这个元素的前缀和后缀，看其合并的结果，再加上这棵子树对应的 $dp_1[i]$ 的情况。

最终的更新可能来自于三个部分——前缀部分经历的最低要求、前缀子树遍历完后在后缀遍历一部分的最低要求、以及前后缀都遍历完再在自己的子树中遍历的最低要求。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    nums = LII()

    path = [[] for _ in range(n)]

    for _ in range(n - 1):
        u, v, w = MII()
        u -= 1
        v -= 1
        path[u].append(w * n + v)
        path[v].append(w * n + u)

    parent = [-1] * n
    que = [0]

    for u in que:
        for msk in path[u]:
            w, v = divmod(msk, n)
            if parent[u] != v:
                parent[v] = u
                que.append(v)

    dp0 = [0] * n
    dp1 = [inf] * n
    tot = [0] * n

    for u in reversed(que):
        v0 = []
        v1 = []
        ws = []

        for msk in path[u]:
            w, v = divmod(msk, n)
            if parent[v] == u:
                v0.append(fmax(w + dp0[v], 2 * w + tot[v]))
                v1.append(w + dp1[v])
                ws.append(2 * w + tot[v])
                tot[u] += 2 * w + tot[v]

        k = len(v0)

        if k == 0:
            dp0[u] = 0
            dp1[u] = 0
        else:
            gain = [i for i in range(k) if ws[i] <= 0]
            cost = [i for i in range(k) if ws[i] > 0]
            gain.sort(key=lambda x: v0[x])
            cost.sort(key=lambda x: ws[x] - v0[x])
            st_range = gain + cost

            suff = [0] * (k + 1)
            for idx in range(k - 1, -1, -1):
                i = st_range[idx]
                suff[idx] = fmax(suff[idx + 1] + ws[i], v0[i])

            cur_w = 0
            for idx in range(k):
                i = st_range[idx]
                dp1[u] = fmin(dp1[u], max(dp0[u], suff[idx + 1] + cur_w, tot[u] - ws[i] + v1[i]))
                dp0[u] = fmax(dp0[u], v0[i] + cur_w)
                cur_w += ws[i]

        dp0[u] = fmax(dp0[u] - nums[u], 0)
        dp1[u] = fmax(dp1[u] - nums[u], 0)
        tot[u] -= nums[u]

    print(dp1[0])
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	vector<int> nums(n);
	for (auto &x: nums) cin >> x;

	vector<vector<pair<int, int>>> path(n);

	for (int i = 0; i < n - 1; i ++) {
		int u, v, w;
		cin >> u >> v >> w;
		u --, v --;
		path[u].emplace_back(v, w);
		path[v].emplace_back(u, w);
	}

	long long inf = 4e18;

	auto dfs = [&] (auto &self, int u, int p) -> array<long long, 3> {
		vector<long long> v0s, v1s, w0s;
		long long dp0 = 0, dp1 = inf, tot = 0;

		for (auto &[v, w]: path[u]) {
			if (v != p) {
				auto [v0, v1, w0] = self(self, v, u);
				v0s.emplace_back(max(w + v0, 2 * w + w0));
				v1s.emplace_back(w + v1);
				w0s.emplace_back(2 * w + w0);
				tot += 2 * w + w0;
			}
		}

		int k = v0s.size();

		if (k) {
			vector<int> gain, cost;
			for (int i = 0; i < k; i ++) {
				if (w0s[i] <= 0) gain.emplace_back(i);
				else cost.emplace_back(i);
			}

			sort(gain.begin(), gain.end(), [&] (int i, int j) {return v0s[i] < v0s[j];});
			sort(cost.begin(), cost.end(), [&] (int i, int j) {return w0s[i] - v0s[i] < w0s[j] - v0s[j];});

			vector<int> st_range;
			st_range.insert(st_range.end(), gain.begin(), gain.end());
			st_range.insert(st_range.end(), cost.begin(), cost.end());

			vector<long long> suff(k + 1, 0);

			for (int idx = k - 1; idx >= 0; idx --) {
				int i = st_range[idx];
				suff[idx] = max(suff[idx + 1] + w0s[i], v0s[i]);
			}

			long long cur_w = 0;
			for (int idx = 0; idx < k; idx ++) {
				int i = st_range[idx];
				dp1 = min(dp1, max({dp0, suff[idx + 1] + cur_w, tot - w0s[i] + v1s[i]}));
				dp0 = max(dp0, v0s[i] + cur_w);
				cur_w += w0s[i];
			}
		}
		else {
			dp0 = 0;
			dp1 = 0;
		}

		dp0 = max(dp0 - nums[u], 0ll);
		dp1 = max(dp1 - nums[u], 0ll);
		tot -= nums[u];

		return {dp0, dp1, tot};
	};

	cout << dfs(dfs, 0, -1)[1];

	return 0;
}
```

**提示 1：** 考虑每次操作会对当前的分数和有啥影响。

**提示 2：** 交换相邻两次操作会如何改变这个结果？

最小值和最大值是完全对称的，只要你把所有的 $x$ 换成 $n+1-x$ 就求出来了。我们下面求最大值。

假设初始情况下分数和为 $V$ ，评论者数量为 $cnt$ ，如果评论者的类型是 S ，则对结果进行 $+k$ 操作；如果类型是 D，则将 $V$ 更新为 $\max(V+1,\min(V+n,cnt\times k))$ 。称 $\max(B,\min(A,x))$ 操作为 $clip(x,A,B)$ 。

假设某两个操作相邻，则：

- 如果两个评论者都是 S 类型的，则不会改变最终结果。

- 如果是 S, D 类型的，设数值分别为 $x_1,x_2$ ，两种操作的方式的结果分别是 $clip((cnt+1)\times x_2,x+x_1+1,x+x_2+n)$ 和 $clip(cnt\times x_2,x+1,x+n)+x_1=clip(cnt\times x_2+x_1,x+x_1+1,x+x_1+n)$ ，两者之间的大小关系只取决于 $x_1,x_2$ 的大小关系。

- 如果是两个 D 类型的，设数值分别为 $x_1,x_2$ ，也应当把小数值放前面（可以自行验证，直接用式子描述比较复杂，直观上是先把容易让数值变小的操作先做掉，后面的限制更小，且后面的数值更大在 $cnt$ 更大的时候效果更好）。

所以综上，只需把 $x$ 较大的操作放后面做就行。按照这点排序即可。而 $x$ 数值相同的任意调换顺序是不影响答案的。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m = MII()

    types = []
    score = []

    for _ in range(m):
        t, x = LI()
        types.append(1 if t == 'S' else 0)
        score.append(int(x))

    def solve():
        cnt = 0
        cur = 0
        for i in sorted(range(m), key=lambda x: score[x]):
            cnt += 1
            if types[i]: cur += score[i]
            else: cur = fmin(cur + n, fmax(cur + 1, score[i] * cnt))
        return cur / cnt

    mx = solve()

    for i in range(m):
        score[i] = n + 1 - score[i]

    mn = n + 1 - solve()

    print(f'{mn:.15f} {mx:.15f}')
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, k;
	cin >> n >> k;

	vector<pair<char, int>> readers(k);
	for (auto &[t, x]: readers) cin >> t >> x;

	sort(readers.begin(), readers.end(), [&] (pair<char, int> &x, pair<char, int> &y) {
		return x.second < y.second;
	});

	auto f = [&] () -> long double {
		long long tot = 0, cnt = 0;
		for (auto &[t, x]: readers) {
			cnt ++;
			if (t == 'S') tot += x;
			else tot = max(tot + 1, min(tot + n, cnt * x));
		}
		return (long double)tot / cnt;
	};

	auto mx = f();

	reverse(readers.begin(), readers.end());
	for (auto &[t, x]: readers) x = n + 1 - x;

	auto mn = f();
	mn = n + 1 - mn;

	cout << fixed << setprecision(15) << mn << ' ' << mx;

	return 0;
}
```

**提示 1：** DP ，如何找到转移区间？

右端点固定时，左端点越靠左，MEX 数值越大（单调不减）。

所以，考虑到第 $i$ 个位置截断的方案数是 $dp[i]$ ，则考虑最后一段的左端点，一定形成一个连续的区间，因此我们只需将这个区间内的总方案数转移到 $dp[i]$ 即可。

如何找到这个区间呢？我们可以维护 MEX 不超过 $x$ 的最小左端点，可以用一个数组，统计严格小于 $x$ 的元素出现了多少个，一旦有元素没有出现，这个位置就开始合法了。然后用 $x=r$ 和 $x=l-1$ 的两个端点即可确定。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, l, r = MII()
    nums = LII()
    r += 1

    mod = 998244353

    v1 = [0] * l
    v2 = [0] * r

    p1 = 0
    p2 = 0

    c1 = 0
    c2 = 0

    fen = FenwickTree(n + 1)
    fen.add(0, 1)

    for i in range(n):
        if nums[i] < l:
            if v1[nums[i]] == 0: c1 += 1
            v1[nums[i]] += 1

        if nums[i] < r:
            if v2[nums[i]] == 0: c2 += 1
            v2[nums[i]] += 1

        while p1 <= i and c1 == l:
            if nums[p1] < l:
                v1[nums[p1]] -= 1
                if v1[nums[p1]] == 0:
                    c1 -= 1
            p1 += 1

        while p2 <= i and c2 == r:
            if nums[p2] < r:
                v2[nums[p2]] -= 1
                if v2[nums[p2]] == 0:
                    c2 -= 1
            p2 += 1

        fen.add(i + 1, fen.rsum(p2, p1 - 1) % mod)

    print(fen.rsum(n, n))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, l, r, mod = 998244353;
	cin >> n >> l >> r;

	vector<int> nums(n);
	for (auto &x: nums) cin >> x;

	r ++;

	vector<int> v1(l, 0), v2(r, 0);
	int p1 = 0, p2 = 0;
	int c1 = 0, c2 = 0;

	atcoder::fenwick_tree<long long> fen(n + 1);
	fen.add(0, 1);

	for (int i = 0; i < n; i ++) {
		if (nums[i] < l) {
			if (!v1[nums[i]]) c1 ++;
			v1[nums[i]] ++;
		}

		if (nums[i] < r) {
			if (!v2[nums[i]]) c2 ++;
			v2[nums[i]] ++;
		}

		while (p1 <= i && c1 == l) {
			if (nums[p1] < l) {
				v1[nums[p1]] --;
				if (!v1[nums[p1]]) c1 --;
			}
			p1 ++;
		}

		while (p2 <= i && c2 == r) {
			if (nums[p2] < r) {
				v2[nums[p2]] --;
				if (!v2[nums[p2]]) c2 --;
			}
			p2 ++;
		}

		fen.add(i + 1, fen.sum(p2, p1) % mod);
	}

	cout << fen.sum(n, n + 1);

	return 0;
}
```

**提示 1：** 考虑不得不动的元素，以及其他元素为了使得这些元素能到目标位置需要做什么。

首先，如果一个元素在移动前和移动后既不在同一行，也不在同一列，那一定没办法达成。

否则，首先考虑那些行内需要移动的元素——它们的前后顺序不能变，因为同色的不能在同一个格子内，所以需要一开始就保持正确的顺序。

同列的元素的上下顺序也不能变，也需要一开始就满足从上到下升序。

同时，一个元素从一个位置移动到另一个位置的过程中，途径的那些不动的元素一定只能是另一个颜色的——不然没办法绕开来。这里可以用差分数组来更新（起点到终点的区间）。

那如果横着走或者竖着走都会经过这个格子，那就产生了矛盾了。所以还需要判这件事儿。

而在上述条件都满足的情况下，我们可以让异色的元素先让开位置，再把同色的在这一行排好，再把异色元素挪回来。每行的元素 / 每列的元素都可以这么解决。

时间复杂度为 $\mathcal{O}(n^2)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    grid = [LGMI() for _ in range(n)]

    tag = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if grid[i][j] // n == i:
                tag[i][j] |= 1
            if grid[i][j] % n == j:
                tag[i][j] |= 2

            if tag[i][j] == 0:
                exit(print('No'))

    block_tag = [[0] * n for _ in range(n)]

    for i in range(n):
        cur = -1
        diff = [0] * n

        for j in range(n):
            if tag[i][j] == 1:
                if grid[i][j] < cur:
                    exit(print('No'))
                cur = grid[i][j]

                l, r = grid[i][j] % n, j
                if l > r: l, r = r, l
                diff[l + 1] += 1
                diff[r] -= 1

        for j in range(1, n):
            diff[j] += diff[j - 1]

        for j in range(n):
            if diff[j] and tag[i][j] == 3:
                block_tag[i][j] += 1

    for j in range(n):
        cur = -1
        diff = [0] * n

        for i in range(n):
            if tag[i][j] == 2:
                if grid[i][j] < cur:
                    exit(print('No'))
                cur = grid[i][j]

                l, r = grid[i][j] // n, i
                if l > r: l, r = r, l
                diff[l + 1] += 1
                diff[r] -= 1

        for i in range(1, n):
            diff[i] += diff[i - 1]

        for i in range(n):
            if diff[i] and tag[i][j] == 3:
                block_tag[i][j] += 1

    for i in range(n):
        for j in range(n):
            if block_tag[i][j] == 2:
                exit(print('No'))

    print('Yes')
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	vector<vector<int>> grid(n, vector<int>(n));
	for (auto &x: grid) for (auto &y: x) cin >> y, y --;

	vector<vector<int>> tag(n, vector<int>(n, 0));

	for (int i = 0; i < n; i ++) {
		for (int j = 0; j < n; j ++) {
			if (grid[i][j] / n == i) tag[i][j] |= 1;
			if (grid[i][j] % n == j) tag[i][j] |= 2;
			if (!tag[i][j]) return cout << "No", 0;
		}
	}

	vector<vector<int>> block_tag(n, vector<int>(n, 0));

	for (int i = 0; i < n; i ++) {
		int cur = -1;
		vector<int> diff(n, 0);

		for (int j = 0; j < n; j ++) {
			if (tag[i][j] == 1) {
				if (grid[i][j] < cur) return cout << "No", 0;
				cur = grid[i][j];

				int l = grid[i][j] % n, r = j;
				if (l > r) swap(l, r);
				diff[l + 1] ++, diff[r] --;
			}
		}

		for (int j = 1; j < n; j ++) diff[j] += diff[j - 1];

		for (int j = 0; j < n; j ++) {
			if (diff[j] && tag[i][j] == 3) {
				block_tag[i][j] ++;
			}
		}
	}

	for (int j = 0; j < n; j ++) {
		int cur = 0;
		vector<int> diff(n, 0);

		for (int i = 0; i < n; i ++) {
			if (tag[i][j] == 2) {
				if (grid[i][j] < cur) return cout << "No", 0;
				cur = grid[i][j];

				int l = grid[i][j] / n, r = i;
				if (l > r) swap(l, r);
				diff[l + 1] ++, diff[r] --;
			}
		}

		for (int i = 1; i < n; i ++) diff[i] += diff[i - 1];

		for (int i = 0; i < n; i ++) {
			if (diff[i] && tag[i][j] == 3) {
				block_tag[i][j] ++;
			}
		}
	}

	for (auto &x: block_tag) for (auto &y: x) if (y == 2) return cout << "No", 0;

	cout << "Yes";

	return 0;
}
