**提示 1：** 哪些人会必胜？

我们用总组数 $\binom{n}{k}$ 减去不合法的组数即可。

什么情况下会有个人必胜呢？就是这个人的两个参数比其余的任何人都高。

所以我们枚举这个人，统计两项都严格劣于这个人的人数 $c$ ，减去分别的 $\binom{c}{k}$ 即可。

时间复杂度为 $\mathcal{O}(n^2)$ ，如果用二维数点可以进一步优化到 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, k = MII()
    p = LII()
    s = LII()

    mod = 998244353
    f = Factorial(n, mod)

    ans = f.combi(n, k)

    for i in range(n):
        c = 0
        for j in range(n):
            if p[j] < p[i] and s[j] < s[i]:
                c += 1

        ans -= f.combi(c, k - 1)
        ans %= mod

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, k, mod = 998244353;
	cin >> n >> k;

	vector<int> p(n), s(n);
	for (auto &x: p) cin >> x;
	for (auto &x: s) cin >> x;

	vector<int> f(n + 1), g(n + 1);
	f[0] = 1;
	for (int i = 1; i <= n; i ++) f[i] = 1ll * f[i - 1] * i % mod;
	g[n] = quickPow(f[n], mod - 2, mod);
	for (int i = n; i >= 1; i --) g[i - 1] = 1ll * g[i] * i % mod;

	auto comb = [&] (int x, int y) -> int {
		if (y < 0 || y > x) return 0;
		return 1ll * f[x] * g[y] % mod * g[x - y] % mod;
	};

	int ans = comb(n, k);

	for (int i = 0; i < n; i ++) {
		int c = 0;
		for (int j = 0; j < n; j ++) {
			if (p[j] < p[i] && s[j] < s[i]) {
				c ++;
			}
		}
		ans += mod - comb(c, k - 1);
		ans %= mod;
	}

	cout << ans;

	return 0;
}
```

**提示 1：** 想想 $\lceil\log_2n!\rceil-1$ 是怎么来的。

每一步比较相当于一个分类器，把全集分为两个部分，只留下其中的一个部分。

而在 $\lceil\log_2n!\rceil-1$ 次操作下，每次保留较大的那个部分，最后剩下的排列数量一定不小于 $2$ ，也就是没有完成排序。

而如何留方案数较多的部分呢？可以假定其中的一种情况，用 bitmask DP 算出这种情况的方案数，再用总方案数减去它就可以得到另一种情况的方案数。

最后如何得到另一个排列呢？相当于要找最终序列的另一个拓扑序。于是在拓扑排序的过程中，一旦可以选择不等于给定拓扑序的对应位置元素，我们就选它，这样就能完成任务了。

时间复杂度为 $\mathcal{O}(n 2^n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    path = [0] * n

    dp = [0] * (1 << n)
    dp[0] = 1

    def count_method():
        for i in range(1, 1 << n):
            dp[i] = 0
            cur = i

            while cur:
                v = cur & -cur
                bit = v.bit_length() - 1
                if path[bit] & i == 0:
                    dp[i] += dp[i - v]
                cur -= v

        return dp[-1]

    total = math.factorial(n)

    while True:
        query = LI()

        if query[0] == '?':
            x = int(query[1]) - 1
            y = int(query[2]) - 1

            orig = path[x]
            path[x] |= 1 << y
            w1 = count_method()
            path[x] = orig

            w2 = total - w1

            if w1 >= w2:
                path[x] |= 1 << y
                total = w1
                print('<', flush=True)
            else:
                path[y] |= 1 << x
                total = w2
                print('>', flush=True)

        else:
            p = [int(x) - 1 for x in query[1:]]
            indeg = [0] * n

            for i in range(n):
                for j in range(n):
                    if path[i] >> j & 1:
                        indeg[j] += 1

            cur = []
            stk = [i for i in range(n) if indeg[i] == 0]

            for _ in range(n):
                if len(stk) > 1 and stk[-1] == p[len(cur)]:
                    stk.reverse()

                u = stk.pop()
                cur.append(u)

                for v in range(n):
                    if path[u] >> v & 1:
                        indeg[v] -= 1
                        if indeg[v] == 0:
                            stk.append(v)

            print('!', *(x + 1 for x in cur), flush=True)

            break
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	long long total_method = 1;
	for (int i = 1; i <= n; i ++) total_method *= i;

	vector<int> path(n, 0);
	vector<long long> dp(1 << n, 0);
	dp[0] = 1;

	auto count_method = [&] () -> long long {
		for (int i = 1; i < (1 << n); i ++) {
			dp[i] = 0;
			int cur = i;

			while (cur) {
				int bit = __builtin_ctz(cur);
				if ((path[bit] & i) == 0) dp[i] += dp[i - (1 << bit)];
				cur -= cur & -cur;
			}
		}
		return dp.back();
	};

	while (true) {
		char c;
		cin >> c;

		if (c == '?') {
			int x, y;
			cin >> x >> y;
			x --, y --;

			int orig = path[x];
			path[x] |= 1 << y;
			long long w1 = count_method();
			path[x] = orig;

			long long w2 = total_method - w1;

			if (w1 >= w2) {
				path[x] |= 1 << y;
				total_method = w1;
				cout << '<' << endl;
			}
			else {
				path[y] |= 1 << x;
				total_method = w2;
				cout << '>' << endl;
			}
		}
		else {
			vector<int> p(n);
			for (auto &x: p) cin >> x, x --;

			vector<int> indeg(n);

			for (int i = 0; i < n; i ++) {
				for (int j = 0; j < n; j ++) {
					if (path[i] >> j & 1) {
						indeg[j] ++;
					}
				}
			}

			vector<int> cur, stk;

			for (int i = 0; i < n; i ++) {
				if (indeg[i] == 0) {
					stk.emplace_back(i);
				}
			}

			for (int i = 0; i < n; i ++) {
				if (stk.size() > 1 && stk.back() == p[cur.size()])
					reverse(stk.begin(), stk.end());

				int u = stk.back();
				stk.pop_back();
				cur.emplace_back(u);

				for (int v = 0; v < n; v ++) {
					if (path[u] >> v & 1) {
						indeg[v] --;
						if (indeg[v] == 0) stk.emplace_back(v);
					}
				}
			}

			cout << '!';
			for (auto &x: cur) cout << ' ' << x + 1;
			cout << endl;

			break;
		}
	}

	return 0;
}
```

**提示 1：** 假设我们知道了目标数值，最少操作几次呢？

假设我们已经知道了目标数组的最终数值，此时，每一段不等于目标数值的段落，设长度为 $len$ ，至少需要 $len$ 次平移操作，才能让这一段的每个位置都被目标数组的最终数值遍历过一次（因为一次平移只能多覆盖这一段的一个位置）。

所以最小的平移次数等于最长的不等于目标数值的段落长度（考虑成环形数组）。

而这也是可以取到的，只往一个方向移动就行。然后一旦遇到可以赋值的位置赋值即可——因为还有赋值操作，对结果加上 $n$ 即可。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    nums = LII()

    M = 10 ** 5 + 5

    first_pos = [-1] * M
    last_pos = [-1] * M

    res = [0] * M

    for i in range(n):
        if first_pos[nums[i]] == -1:
            first_pos[nums[i]] = i
        else:
            res[nums[i]] = fmax(res[nums[i]], i - last_pos[nums[i]] - 1)
        last_pos[nums[i]] = i

    ans = n

    for i in range(M):
        if first_pos[i] != -1:
            res[i] = fmax(res[i], first_pos[i] + n - 1 - last_pos[i])
            ans = fmin(ans, res[i])

    print(ans + n)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, M = 1e5 + 5;
	cin >> n;

	vector<int> first_pos(M, -1), last_pos(M, -1), res(M);

	for (int i = 0; i < n; i ++) {
		int x;
		cin >> x;

		if (first_pos[x] == -1) first_pos[x] = i;
		else res[x] = max(res[x], i - last_pos[x] - 1);

		last_pos[x] = i;
	}

	int ans = n;

	for (int i = 0; i < M; i ++) {
		if (first_pos[i] != -1) {
			res[i] = max(res[i], first_pos[i] + n - 1 - last_pos[i]);
			ans = min(ans, res[i]);
		}
	}

	cout << ans + n;

	return 0;
}
