**提示 1：** 如果知道区间里各个元素的频率，就可以快速求答案了。如何计算区间内的频率信息呢？

如果我们知道了区间内各个元素的频率，接下来怎么做呢？

枚举第一个数组选的元素是 $1,2,\dots,\lfloor\sqrt{k}\rfloor$ 中的哪一个，设选的是 $i$ ，则我们要统计第二个数组中不超过 $\lfloor k/ i \rfloor$ 的元素个数。

同样接下来枚举第二个数组选的元素是哪一个，进行一样的流程。

最后，这样多算了两个元素都不超过 $\lfloor\sqrt{k}\rfloor$ 的情况，去掉它们即可。

那如何得到区间内各个元素的出现频率呢？直接莫队，新增元素和删去元素的时候在树状数组里操作即可。这样空间也控制在线性了。

时间复杂度为 $\mathcal{O}(q\log q+n\sqrt{q}\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, q = MII()
    v1 = LII()
    v2 = LII()

    ls = []
    rs = []
    ks = []

    for _ in range(q):
        l, r, k = MII()
        ls.append(l - 1)
        rs.append(r)
        ks.append(k)

    ans = [0] * q

    B = 320

    st_range = sorted(range(q), key=lambda x: (ls[x] // B, rs[x] if ls[x] // B % 2 else -rs[x]))

    M = 10 ** 5 + 1
    cnt1 = [0] * M
    fen1 = FenwickTree(M)
    cnt2 = [0] * M
    fen2 = FenwickTree(M)

    pl = 0
    pr = 0

    for i in st_range:
        l = ls[i]
        r = rs[i]
        k = ks[i]

        while pl > l:
            pl -= 1

            if v1[pl] < M:
                cnt1[v1[pl]] += 1
                fen1.add(v1[pl], 1)

            if v2[pl] < M:
                cnt2[v2[pl]] += 1
                fen2.add(v2[pl], 1)

        while pr < r:
            if v1[pr] < M:
                cnt1[v1[pr]] += 1
                fen1.add(v1[pr], 1)

            if v2[pr] < M:
                cnt2[v2[pr]] += 1
                fen2.add(v2[pr], 1)

            pr += 1

        while pl < l:
            if v1[pl] < M:
                cnt1[v1[pl]] -= 1
                fen1.add(v1[pl], -1)

            if v2[pl] < M:
                cnt2[v2[pl]] -= 1
                fen2.add(v2[pl], -1)

            pl += 1

        while pr > r:
            pr -= 1

            if v1[pr] < M:
                cnt1[v1[pr]] -= 1
                fen1.add(v1[pr], -1)

            if v2[pr] < M:
                cnt2[v2[pr]] -= 1
                fen2.add(v2[pr], -1)

        bound = math.isqrt(k)
        w1 = 0
        w2 = 0

        for cur in range(1, bound + 1):
            ans[i] += cnt1[cur] * fen2.rsum(0, k // cur)
            w1 += cnt1[cur]

            ans[i] += cnt2[cur] * fen1.rsum(0, k // cur)
            w2 += cnt2[cur]

        ans[i] -= w1 * w2

    print('\n'.join(map(str, ans)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, q;
	cin >> n >> q;

	vector<int> v1(n), v2(n);
	for (auto &x: v1) cin >> x;
	for (auto &x: v2) cin >> x;

	vector<array<int, 3>> queries(q);
	for (auto &[l, r, k]: queries) cin >> l >> r >> k, l --;

	int B = 320;

	vector<int> order(q);

	iota(order.begin(), order.end(), 0);
	sort(order.begin(), order.end(), [&] (int i, int j) {
		int l1 = queries[i][0] / B, r1 = queries[i][1];
		int l2 = queries[j][0] / B, r2 = queries[j][1];

		if (l1 != l2) return l1 < l2;
		if (l1 % 2) return r1 < r2;
		else return r1 > r2;
	});

	int M = 1e5 + 1;
	vector<int> cnt1(M, 0), cnt2(M, 0);
	atcoder::fenwick_tree<int> fen1(M), fen2(M);

	vector<long long> outs(q);

	int pl = 0, pr = 0;

	for (auto &qidx: order) {
		auto [l, r, k] = queries[qidx];

		while (pl > l) {
			pl --;
			if (v1[pl] < M) {
				cnt1[v1[pl]] ++;
				fen1.add(v1[pl], 1);
			}
			if (v2[pl] < M) {
				cnt2[v2[pl]] ++;
				fen2.add(v2[pl], 1);
			}
		}

		while (pr < r) {
			if (v1[pr] < M) {
				cnt1[v1[pr]] ++;
				fen1.add(v1[pr], 1);
			}
			if (v2[pr] < M) {
				cnt2[v2[pr]] ++;
				fen2.add(v2[pr], 1);
			}
			pr ++;
		}

		while (pl < l) {
			if (v1[pl] < M) {
				cnt1[v1[pl]] --;
				fen1.add(v1[pl], -1);
			}
			if (v2[pl] < M) {
				cnt2[v2[pl]] --;
				fen2.add(v2[pl], -1);
			}
			pl ++;
		}

		while (pr > r) {
			pr --;
			if (v1[pr] < M) {
				cnt1[v1[pr]] --;
				fen1.add(v1[pr], -1);
			}
			if (v2[pr] < M) {
				cnt2[v2[pr]] --;
				fen2.add(v2[pr], -1);
			}
		}

		long long ans = 0;
		int w1 = 0, w2 = 0;

		for (int i = 1; i * i <= k; i ++) {
			ans += 1ll * cnt1[i] * fen2.sum(0, k / i + 1);
			ans += 1ll * cnt2[i] * fen1.sum(0, k / i + 1);
			w1 += cnt1[i], w2 += cnt2[i];
		}

		ans -= 1ll * w1 * w2;
		outs[qidx] = ans;
	}

	for (auto &v: outs) cout << v << '\n';

	return 0;
}
```

**提示 1：** 如何统计 $X$ 以下有多少个满足条件的数。

直接算第 $x$ 个数是不方便的。所以考虑二分，如果我们能统计 $X$ 以下有多少个符合条件的数，我们只需找到这样的 $X$ 的最小值即可。

而这件事儿可以用容斥来做。先分别减去 $2^2,3^2,5^2,\dots$ 等质数的平方的倍数。

但至少有两个质数平方的因子的数会被多算，于是减掉 $(p_1p_2)^2$ 形式的数的倍数。

但三个质因子的又被多加了，于是应该减去。

类似地，得到多个质因子的情况，因子个数为奇数的情况下系数为负，否则为正。

而开根号后的范围在 $\sqrt{M}$ 量级，因此我们统计这个范围内每个元素的质因子个数——注意上面开根号后因子个数都是 $1$ ，所以一旦有一个因子有超过 $1$ 次，则这个数对应的系数为 $0$ 。

整体系数类似莫比乌斯反演那一套。

最后根据上述逻辑统计即可。如果有不清楚的细节可以看后面的代码。

时间复杂度为 $\mathcal{O}(\sqrt{M}\log M)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    M = 200000

    is_prime = [1] * M
    is_prime[0] = 0
    is_prime[1] = 0

    miu = [1] * M

    for i in range(M):
        if is_prime[i]:
            for j in range(i, M, i):
                is_prime[j] = 0
                miu[j] *= -1

                if j // i % i == 0:
                    miu[j] = 0

    chosen = [i for i in range(1, M) if miu[i]]

    t = II()
    outs = []

    for _ in range(t):
        x = II()

        l, r = 1, 4 * 10 ** 10
        while l <= r:
            mid = (l + r) // 2

            cnt = 0

            for i in chosen:
                cnt += miu[i] * (mid // i // i)

            if cnt >= x: r = mid - 1
            else: l = mid + 1

        outs.append(l)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int M = 2e5;

	vector<int> is_prime(M, 1);
	is_prime[0] = 0, is_prime[1] = 0;

	vector<int> miu(M, 1);

	for (int i = 1; i <= M; i ++) {
		if (is_prime[i]) {
			for (int j = i; j <= M; j += i) {
				is_prime[j] = 0;
				miu[j] *= -1;
				if (j / i % i == 0) miu[j] = 0;
			}
		}
	}

	vector<int> chosen;
	for (int i = 1; i < M; i ++) if (miu[i]) chosen.emplace_back(i);

	int t;
	cin >> t;

	while (t --) {
		long long target;
		cin >> target;

		long long l = 1, r = 4e10;

		while (l <= r) {
			long long mid = (l + r) / 2, cnt = 0;
			for (auto &x: chosen) {
				cnt += miu[x] * (mid / x / x);
			}
			if (cnt >= target) r = mid - 1;
			else l = mid + 1;
 		}

		cout << l << '\n';
	}

	return 0;
}
