**提示 1：** 找到一个最小的不可达的集合。怎么做？

我们尝试找一个不可达的集合。

首先，这个集合包含 $n$ 。

而任意一个不在这个集合的点，都得满足其只有至多一半的边指向这个集合。一旦不满足这个条件，这个点就得加入集合中。

我们可以不断执行这个操作，怎么执行呢？直接用反图，找到指向它的点，维护每个点指向集合的边数。此时，一旦边数超越了界限，这个点加入集合。

整个写法类似于拓扑排序。

这样，我们找到了不可达的点形成的最小集合。而一旦这个集合包含 $1$ ，也就推出了矛盾。

否则，我们只需去掉那些从可达位置指向不可达位置的边即可。合法性显然。

时间复杂度为 $\mathcal{O}(n+m)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    for _ in range(t):
        n, m = MII()
        rev_path = [[] for _ in range(n)]
        out_deg = [0] * n

        for _ in range(m):
            u, v = GMI()
            rev_path[v].append(u)
            out_deg[u] += 1

        vis = [0] * n
        cur_deg = [0] * n

        vis[n - 1] = 1

        stk = [n - 1]

        while stk:
            u = stk.pop()

            for v in rev_path[u]:
                cur_deg[v] += 1

                if 2 * cur_deg[v] > out_deg[v] and not vis[v]:
                    vis[v] = 1
                    stk.append(v)

        if vis[0]: outs.append('-1')
        else:
            edges = []

            for u in range(n):
                for v in rev_path[u]:
                    if not vis[v] and vis[u]:
                        edges.append(f'{v + 1} {u + 1}')

            outs.append(f'{len(edges)}')

            for e in edges: outs.append(e)

    print('\n'.join(outs))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int n, m;
		cin >> n >> m;

		vector<int> out_deg(n, 0);
		vector<vector<int>> rev_path(n);

		while (m --) {
			int u, v;
			cin >> u >> v;
			u --, v --;

			out_deg[u] ++;
			rev_path[v].emplace_back(u);
		}

		vector<int> vis(n, 0), cur_deg(n, 0);
		vis[n - 1] = 1;

		auto dfs = [&] (auto &self, int u) -> void {
			for (auto &v: rev_path[u]) {
				cur_deg[v] ++;
				if (cur_deg[v] * 2 > out_deg[v] && !vis[v]) {
					vis[v] = 1;
					self(self, v);
				}
			}
		};

		dfs(dfs, n - 1);

		if (vis[0]) cout << "-1\n";
		else {
			vector<pair<int, int>> edges;

			for (int u = 0; u < n; u ++) {
				for (auto &v: rev_path[u]) {
					if (!vis[v] && vis[u]) {
						edges.emplace_back(v, u);
					}
				}
			}

			cout << edges.size() << '\n';
			for (auto &[u, v]: edges) cout << u + 1 << ' ' << v + 1 << '\n';
		}
	}

	return 0;
}
```

**提示 1：** 依次确定每个元素是否要选。

首先 $1$ 或者 $-1$ 要不要选呢？直接只看 $k$ 是否是奇数就行。如果取了，从 $k$ 中去掉这个元素。

此时 $k$ 和剩余元素都是 $2$ 的倍数，同时除以 $2$ 不影响答案。

此时就可以判断原本是 $2$ 或者 $-2$ 的这个数要不要选了，只需看此时的 $k$ 是否是 $2$ 的倍数。

以此类推可以确定每一位要不要。最后所有元素遍历完了，只要 $k$ 仍然不是 $0$ 就输出 $-1$ ，否则输出方案即可。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    for _ in range(t):
        n, k = MII()
        nums = [1 if c == '+' else -1 for c in I()]

        ans = []

        for i in range(n):
            if k % 2: k -= nums[i]; ans.append('#')
            else: ans.append('.')
            k //= 2

        outs.append(''.join(ans) if k == 0 else '-1')

    print('\n'.join(outs))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int n, k;
		cin >> n >> k;

		string s;
		cin >> s;

		string ans;
		for (auto &c: s) {
			if (k & 1) k -= (c == '+' ? 1 : -1), ans += '#';
			else ans += '.';
			k >>= 1;
		}

		cout << (k == 0 ? ans : "-1") << '\n';
	}

	return 0;
}
```

**提示 1：** 考虑必须填入的是哪些数，填入他们，剩余部分再任意填。

首先，我们考虑每一列。

对于那些恰好只缺一个数的列，都可能作为产生答案的备选。统计这些元素的出现频率。

因为每个这样的数字都在不同的列，所以互不影响。

因此，分别给这些数分配一个位置，对于剩下的数，再进行任意排列即可。

时间复杂度为 $\mathcal{O}(n^2)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    grid = [LII() for _ in range(n - 1)]

    vis = [0] * (n + 1)
    cnt = [0] * (n + 1)

    for i in range(n):
        for j in range(n - 1):
            vis[grid[j][i]] = 1

        c = 0
        target = 0

        for j in range(1, n + 1):
            if vis[j] == 0:
                c += 1
                target = j

        if c == 1: cnt[target] += 1

        for j in range(n - 1):
            vis[grid[j][i]] = 0

    ans0 = 0
    ans1 = 1

    resid = n
    mod = 10 ** 9 + 7

    for i in range(n + 1):
        if cnt[i]:
            ans0 += 1
            ans1 = ans1 * cnt[i] % mod
            resid -= 1

    for i in range(1, resid + 1):
        ans1 = ans1 * i % mod

    print(ans0, ans1)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	vector<vector<int>> grid(n - 1, vector<int>(n));
	for (auto &x: grid) for (auto &y: x) cin >> y;

	vector<int> vis(n + 1, 0), cnt(n + 1, 0);

	for (int i = 0; i < n; i ++) {
		for (int j = 0; j < n - 1; j ++) {
			vis[grid[j][i]] = 1;
		}

		int c = 0, target = 0;
		for (int i = 1; i <= n; i ++) {
			if (!vis[i]) {
				c ++;
				target = i;
			}
		}

		if (c == 1) cnt[target] ++;

		for (int j = 0; j < n - 1; j ++) {
			vis[grid[j][i]] = 0;
		}
	}

	int ans0 = 0, ans1 = 1, mod = 1e9 + 7;

	for (auto &x: cnt) {
		if (x) {
			ans0 ++;
			ans1 = 1ll * ans1 * x % mod;
		}
	}

	for (int i = 1; i <= n - ans0; i ++) {
		ans1 = 1ll * ans1 * i % mod;
	}

	cout << ans0 << ' ' << ans1 << '\n';

	return 0;
}
```

**提示 1：** 考虑 Manacher 算法，能用吗？怎么调整下？复杂度对吗？

这个题整个逻辑很像回文串，于是想到 Manacher 算法。

唯一的差别就是拓展的过程中，需要两个元素不相等。

这个算法的复杂度本质上跟 Manacher 算法的复杂度的证明是等价的，所以也是线性的。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    s = [ord(c) - ord('a') for c in I()]

    manacher = [0] * (n - 1)

    ans = 0
    chosen_idx = 0

    for i in range(n - 1):
        if chosen_idx + manacher[chosen_idx] >= i and 2 * chosen_idx >= i:
            manacher[i] = fmin(manacher[2 * chosen_idx - i], chosen_idx + manacher[chosen_idx] - i)

        l = i - manacher[i] + 1
        r = i + manacher[i]

        while l > 0 and r + 1 < n and s[l - 1] != s[r + 1]:
            l -= 1
            r += 1
            manacher[i] += 1

        if i + manacher[i] > chosen_idx + manacher[chosen_idx]:
            chosen_idx = i

    print(max(manacher) * 2)

```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	string s;
	cin >> n >> s;

	vector<int> manacher(n - 1, 0);
	int chosen_idx = 0;

	for (int i = 0; i < n - 1; i ++) {
		if (chosen_idx + manacher[chosen_idx] >= i && 2 * chosen_idx >= i) {
			manacher[i] = min(manacher[2 * chosen_idx - i], chosen_idx + manacher[chosen_idx] - i);
		}

		int l = i - manacher[i] + 1, r = i + manacher[i];

		while (l && r + 1 < n && s[l - 1] != s[r + 1]) {
			l --, r ++;
			manacher[i] ++;
		}

		if (i + manacher[i] > chosen_idx + manacher[chosen_idx]) {
			chosen_idx = i;
		}
	}

	cout << *max_element(manacher.begin(), manacher.end()) * 2;

	return 0;
}
```

**提示 1：** DP ，想想状态和状态转移。

很明显，我们令前 $i$ 天的旅行计划的最小成本是 $dp[i]$ 。接下来会发生什么转移呢？

- 直接购入新的一天的单天票，即 $dp[i]+f\to dp[i+1]$ 。

- 选择套票。对于起点 $i+1$ ，我们使用套票最多能到第几天呢？只需判两件事——之间的总天数是否不超过 $p$ ，之间的旅行天数是否不超过 $d$ 。可以二分找对应位置，也可以选择用指针维护，不断右移即可。

每个状态有 $\mathcal{O}(k)$ 转移。

时间复杂度为 $\mathcal{O}(nk)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, k = MII()

    ts = []
    fs = []

    for _ in range(n):
        t, f = MII()
        ts.append(t)
        fs.append(f)

    ps = []
    ds = []
    cs = []

    for _ in range(k):
        p, d, c = MII()
        ps.append(p)
        ds.append(d)
        cs.append(c)

    dp = [inf] * (n + 1)
    dp[0] = 0

    pts = [0] * k

    for i in range(n):
        dp[i + 1] = dp[i] + fs[i]

        for j in range(k):
            while ts[i] - ts[pts[j]] + 1 > ps[j] or i - pts[j] + 1 > ds[j]:
                pts[j] += 1

            dp[i + 1] = fmin(dp[i + 1], dp[pts[j]] + cs[j])

    print(dp[n])
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, k;
	cin >> n >> k;

	vector<pair<int, int>> days(n);
	for (auto &[t, f]: days) cin >> t >> f;

	vector<array<int, 3>> tickets(k);
	for (auto &[p, d, c]: tickets) cin >> p >> d >> c;

	vector<int> dp(n + 1, 1e9);
	dp[0] = 0;

	vector<int> pts(k, 0);

	for (int i = 0; i < n; i ++) {
		auto [t, f] = days[i];
		dp[i + 1] = dp[i] + f;

		for (int j = 0; j < k; j ++) {
			auto [p, d, c] = tickets[j];
			while (t - days[pts[j]].first + 1 > p || i - pts[j] + 1 > d) pts[j] ++;
			dp[i + 1] = min(dp[i + 1], dp[pts[j]] + c);
		}
	}

	cout << dp[n];

	return 0;
}
```

**提示 1：** 可以从后往前推，一步步剥离开。

这题这个立方体不知道是何意味，明明只有 $x,y$ 轴两个操作。

就看成一个 $n\times n$ 的正方形就行。接下来咋办呢？

最开头的操作对最后结果的影响不明确，但是最靠后的操作是明确的。

假设最后进行了一行的操作，则这行就可以删掉了，把问题转化为了行数更小的问题；否则把问题转化为了列数更小的问题——这都能推出一个 DP 的结构。

而如果进行了连续的行操作，那么这几次行操作是可以交换顺序的，所以只能一起考虑。

因此考虑最后一步是行 / 列操作的 $i$ 行 $j$ 列的矩形有 $dp_1[i][j],dp_2[i][j]$ 种方案。

则对于前者的转移，考虑最后一批操作的行的数量，不妨设为 $x$ ，则相当于要从 $i$ 行里选 $x$ 行作为最后操作的行，将这些行去掉后，剩下 $i-x$ 行 $j$ 列的矩形，且这个矩形的最后一次操作是列操作。

因此 $dp_1[i][j]=\sum\limits_{x=1}^i C_i^x dp_2[i-x][j]$ 。

另一侧也是类似的。

时间复杂度为 $\mathcal{O}(n^3)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    mod = 10 ** 9 + 7

    combs = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        combs[i][0] = 1
        combs[i][i] = 1

        for j in range(1, i):
            combs[i][j] = (combs[i - 1][j] + combs[i - 1][j - 1]) % mod

    ans = 0

    dp1 = [[0] * (n + 1) for _ in range(n + 1)]
    dp2 = [[0] * (n + 1) for _ in range(n + 1)]

    dp1[0][0] = 1
    dp2[0][0] = 1

    for i in range(n + 1):
        for j in range(n + 1):
            for k in range(i + 1, n + 1):
                dp2[k][j] += dp1[i][j] * combs[k][i]
                dp2[k][j] %= mod

            for k in range(j + 1, n + 1):
                dp1[i][k] += dp2[i][j] * combs[k][j]
                dp1[i][k] %= mod

    print((dp1[n][n] + dp2[n][n]) % mod)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, mod = 1e9 + 7;
	cin >> n;

	vector<vector<int>> combs(n + 1, vector<int>(n + 1, 0));

	for (int i = 0; i <= n; i ++) {
		combs[i][0] = 1, combs[i][i] = 1;
		for (int j = 1; j < i; j ++) {
			combs[i][j] = (combs[i - 1][j] + combs[i - 1][j - 1]) % mod;
		}
	}

	vector<vector<int>> dp1(n + 1, vector<int>(n + 1, 0));
	vector<vector<int>> dp2(n + 1, vector<int>(n + 1, 0));

	dp1[0][0] = 1, dp2[0][0] = 1;

	for (int i = 0; i <= n; i ++) {
		for (int j = 0; j <= n; j ++) {
			for (int k = i + 1; k <= n; k ++) {
				dp2[k][j] = (dp2[k][j] + 1ll * dp1[i][j] * combs[k][i]) % mod;
			}
			for (int k = j + 1; k <= n; k ++) {
				dp1[i][k] = (dp1[i][k] + 1ll * dp2[i][j] * combs[k][j]) % mod;
			}
		}
	}

	cout << (dp1[n][n] + dp2[n][n]) % mod;

	return 0;
}
```

**提示 1：** 想想各种操作对取模结果的影响。

如果数字长度是奇数，在前后缀新增元素的可能结果包括是：

把 $0$ 变成 $0,1,2$ 。

把 $1$ 变成 $0,1,2$ 。

把 $2$ 变成 $1,2$ 。

如果数字长度是偶数，在前后缀新增元素的可能结果包括是：

把 $0$ 变成 $0,1$ 。

把 $1$ 变成 $0,1,2$ 。

把 $2$ 变成 $0,1,2$ 。

所以后手一旦操作时数字长度是偶数（也就是初始长度是奇数），则必胜；因此 $n$ 为奇数时，后手必胜。

否则，数字初始长度是偶数，如果先手可以让结果变成 $2$ ，则后手毫无操作，无法让结果是 $3$ 的倍数；所以数字原本不是 $3$ 的倍数时，先手必胜。

对于剩下情况，后手总能让每次操作后刚好是 $3$ 的倍数，后手必胜。

时间复杂度为 $\mathcal{O}(n)$ 。

