	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int n;
		cin >> n;

		vector<long long> v1(n), v2(n);
		long long w1 = 0, w2 = 0;

		for (auto &x: v1) cin >> x, w1 += x;
		for (auto &x: v2) cin >> x, w2 += x;

