**提示 1：** 我们可以得到使用 $1$ 次 ski 的最大总步长吗？多次呢？

首先，如果我们完全不使用 ski ，此时最大能走的长度就是从 $y$ 点开始的最长路径。因为图是无环的，所以可以用 DP 求出这个长度。

如果这个长度大于等于 $x$ 了直接输出 $0$ 。

否则，我们的流程大概是：从起点出发，走到一个 ski ，接下来不断沿着最长路走下一个要到达的 ski，直到最后一个 ski，再走对应的最长路。

发现这里的最长路都是跟 ski 的起点终点有关的，所以预处理这些东西。

首先，我们先得到从起点出发，到每个 ski 的起点的最长路，以及从每个 ski 的终点出发的最长路。

中间的部分如何简化呢？我们可以预处理每个 ski 的终点到某个 ski 起点的最长路，这样需要用 $k$ 次 DP 完成。

接下来中间的每一步实际上都是很相近的——从一个 ski 的起点走到另一个 ski 的起点。单次这种操作的最长路是很容易维护的。

而多次操作呢？可以考虑倍增，维护 $2^k$ 这样的操作的最长路。

最后如何确定答案呢？可以从大到小枚举 $2^{29},2^{28},\dots,2^0$ 的额外步长，看是否最长路已经超过 $x$ 了，如果没超过加上它，这样最后就得到了小于答案的最大整数，也就确定了答案。跟倍增找 LCA 之类的问题是一回事。

时间复杂度为 $\mathcal{O}(k(n+m)+k^3\log x)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    for _ in range(t):
        n, m, k = MII()

        path = [[] for _ in range(n)]
        indeg = [0] * n

        for _ in range(m):
            u, v = GMI()
            path[u].append(v)
            indeg[v] += 1

        starts = []
        ends = []

        for _ in range(k):
            s, e = GMI()
            starts.append(s)
            ends.append(e)

        target, start = MII()
        start -= 1

        stk = [i for i in range(n) if indeg[i] == 0]
        topo = []

        while stk:
            u = stk.pop()
            topo.append(u)

            for v in path[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    stk.append(v)

        from_start = [-inf] * n
        from_start[start] = 0

        for i in topo:
            for j in path[i]:
                from_start[j] = fmax(from_start[j], from_start[i] + 1)

        if max(from_start) >= target:
            outs.append(0)
            continue

        to_end = [0] * n

        for i in reversed(topo):
            for j in path[i]:
                to_end[i] = fmax(to_end[i], to_end[j] + 1)

        v0 = [from_start[x] + 1 for x in starts]
        v1 = [to_end[x] for x in ends]

        if max(v0[i] + v1[i] for i in range(k)) >= target:
            outs.append(1)
            continue

        tmp = [-inf] * n
        transition = [[-inf] * k for _ in range(k)]

        for i in range(k):
            tmp[ends[i]] = 0

            for u in topo:
                for v in path[u]:
                    tmp[v] = fmax(tmp[v], tmp[u] + 1)

            for j in range(k):
                transition[i][j] = tmp[starts[j]] + 1

            for u in range(n):
                tmp[u] = -inf

        def f(i, j): return i * k + j

        nth_transition = [[-inf] * (k * k) for _ in range(30)]

        for i in range(k):
            for j in range(k):
                nth_transition[0][f(i, j)] = transition[i][j]

        for i in range(29):
            for u in range(k):
                for v in range(k):
                    for w in range(k):
                        nth_transition[i + 1][f(u, w)] = fmax(nth_transition[i + 1][f(u, w)], nth_transition[i][f(u, v)] + nth_transition[i][f(v, w)])

        ans = 2

        for i in range(29, -1, -1):
            flg = True
            for u in range(k):
                for v in range(k):
                    if v0[u] + nth_transition[i][f(u, v)] + v1[v] >= target:
                        flg = False

            if flg:
                ans += 1 << i
                nv0 = [-inf] * k
                for u in range(k):
                    for v in range(k):
                        nv0[v] = fmax(nv0[v], v0[u] + nth_transition[i][f(u, v)])
                v0 = nv0

        outs.append(ans)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	long long inf = 1e18;

	while (t --) {
		int n, m, k;
		cin >> n >> m >> k;

		vector<vector<int>> path(n);
		vector<int> indeg(n, 0);

		while (m --) {
			int u, v;
			cin >> u >> v;
			u --, v --;

			path[u].emplace_back(v);
			indeg[v] ++;
		}

		vector<pair<int, int>> skis(k);

		for (auto &[u, v]: skis) {
			cin >> u >> v;
			u --, v --;
		}

		int target, start;
		cin >> target >> start;
		start --;

		vector<int> stk, topo;
		for (int i = 0; i < n; i ++) {
			if (indeg[i] == 0) {
				stk.emplace_back(i);
			}
		}

		while (!stk.empty()) {
			int u = stk.back(); stk.pop_back();
			topo.emplace_back(u);

			for (auto &v: path[u]) {
				indeg[v] --;
				if (!indeg[v]) stk.emplace_back(v);
			}
		}

		vector<long long> from_start(n, -inf);
		from_start[start] = 0;

		for (auto &i: topo) {
			for (auto &j: path[i]) {
				from_start[j] = max(from_start[j], from_start[i] + 1);
			}
		}

		if (*max_element(from_start.begin(), from_start.end()) >= target) {
			cout << 0 << '\n';
			continue;
		}

		vector<int> to_end(n, 0);

		reverse(topo.begin(), topo.end());

		for (auto &i: topo) {
			for (auto &j: path[i]) {
				to_end[i] = max(to_end[i], to_end[j] + 1);
			}
		}

		reverse(topo.begin(), topo.end());

		vector<long long> v0, v1;
		bool flg = false;

		for (auto &[s, e]: skis) {
			if (from_start[s] + to_end[e] + 1 >= target) flg = true;
			v0.emplace_back(from_start[s] + 1);
			v1.emplace_back(to_end[e]);
		}

		if (flg) cout << 1 << '\n';
		else {
			vector<long long> tmp(n, -inf);
			vector<vector<long long>> transition(k, vector<long long>(k, -inf));

			for (int i = 0; i < k; i ++) {
				auto [s, e] = skis[i];
				tmp[e] = 0;

				for (auto &u: topo) {
					for (auto &v: path[u]) {
						tmp[v] = max(tmp[v], tmp[u] + 1);
					}
				}

				for (int j = 0; j < k; j ++)
					transition[i][j] = tmp[skis[j].first] + 1;

				for (int u = 0; u < n; u ++) tmp[u] = -inf;
			}

			auto f = [&] (int i, int j) -> int {return i * k + j;};

			vector<vector<long long>> nth_transition(30, vector<long long>(k * k, -inf));

			for (int i = 0; i < k; i ++) {
				for (int j = 0; j < k; j ++) {
					nth_transition[0][f(i, j)] = transition[i][j];
				}
			}

			for (int i = 0; i < 29; i ++) {
				for (int u = 0; u < k; u ++) {
					for (int v = 0; v < k; v ++) {
						for (int w = 0; w < k; w ++) {
							nth_transition[i + 1][f(u, w)] = max(nth_transition[i + 1][f(u, w)], nth_transition[i][f(u, v)] + nth_transition[i][f(v, w)]);
						}
					}
				}
			}

			int ans = 2;

			for (int i = 29; i >= 0; i --) {
				bool flg = true;

				for (int u = 0; u < k; u ++) {
					for (int v = 0; v < k; v ++) {
						if (v0[u] + nth_transition[i][f(u, v)] + v1[v] >= target) {
							flg = false;
						}
					}
				}

				if (flg) {
					ans += 1 << i;
					vector<long long> nv0(k, -inf);

					for (int u = 0; u < k; u ++) {
						for (int v = 0; v < k; v ++) {
							nv0[v] = max(nv0[v], v0[u] + nth_transition[i][f(u, v)]);
						}
					}

					v0.swap(nv0);
				}
			}

			cout << ans << '\n';
		}
	}

	return 0;
}
```

**提示 1：** 如果我们可以拆成若干直着的段，则答案需要满足什么要求？

**提示 2：** 拆法有限。

如果给定的是一系列的线段，则我们的答案就是这些线段的长度的最大公约数的因子。

但这里不是一堆线段，怎么办？

只需考虑四个角落分别属于哪一段即可。枚举 $2^4$ 的情况是最稳妥的选择，否则你最好分类讨论完整（不然容易漏掉 $2$ 是必然可行的）。

时间复杂度为 $\mathcal{O}(\sqrt{M})$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    def factors(x):
        for i in range(1, 100000):
            if i * i > x: break
            if x % i == 0:
                yield i
                if x // i != i:
                    yield x // i

    for _ in range(t):
        w, l = MII()

        ans = {2}

        for x in factors(math.gcd(w - 1, l - 1)): ans.add(x)
        for x in factors(math.gcd(w - 2, l)): ans.add(x)
        for x in factors(math.gcd(w, l - 2)): ans.add(x)

        ans = sorted(ans)

        outs.append(f'{len(ans)} {" ".join(map(str, ans))}')

    print('\n'.join(outs))
