	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	vector<int> nums(n);
	for (auto &x: nums) cin >> x;

	auto z = z_algorithm(nums);

	int cur = -1;
	for (int i = 1; i < n; i ++) {
		if (z[i] != n - i) cur = i;
		cout << cur << " \n"[i == n - 1];
	}

	return 0;
}
