int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, m;
	cin >> n >> m;

	vector<vector<int>> path(n);
	atcoder::dsu uf1(n), uf2(n);

	while (m --){
		int u, v;
		cin >> u >> v;
		u --, v --;
		uf1.merge(u, v);
		path[u].emplace_back(v);
		path[v].emplace_back(u);
	}

	vector<int> diff(n);

	for (int i = 0; i < n; i ++) {
		sort(path[i].begin(), path[i].end());
		path[i].emplace_back(n);

		int l = 0;

		for (auto &j: path[i]) {
			int r = j;

			if (l < r) {
				diff[l] ++;
				diff[r - 1] --;
				uf2.merge(i, l);
			}

			l = r + 1;
		}
	}

	for (int i = 1; i < n; i ++) diff[i] += diff[i - 1];

	for (int i = 0; i < n; i ++) {
		if (diff[i]) {
			uf2.merge(i, i + 1);
		}
	}


	long long ans = 0;
	map<pair<int, int>, int> cnt;

	for (int i = 0; i < n; i ++) {
		int u = uf1.leader(i);
		int v = uf2.leader(i);

		ans += cnt[{u, v}];
		cnt[{u, v}] ++;
	}

	cout << ans;

	return 0;
}
