**提示 1：** 考虑什么状态是重要的？中间的字符串是可以一起考虑的，如何合并这些考虑？

首先，这题定义的状态之一可以是目前匹配 $p$ 前缀的最大长度，这样新来一个字符的时候，我们可以快速得到新的匹配长度（这件事可以直接暴力预处理），进而帮助判断目前子串出现了多少次。

在旋转子串的过程中，只有那个被断开的字符串是特殊的。中间的那些串都是顺次连接起来的。

这些串的起点（也就是匹配到了 $p$ 的多长的前缀）是重要的，因为决定了这些串匹配的起点。

而终点也需要记录（也就是这一长段结束后最后匹配的 $p$ 的多长前缀），因为这个不一定越长越好。

所以设 $dp[i][j][msk]$ 表示从匹配长度 $i$ 开始，选取了 $msk$ 子集后匹配长度变为 $j$ 的情况下，子串匹配 $p$ 的最大次数。

这个状态转移枚举新加入子集的元素即可。但这里可以有个优化，就是从匹配长度为 $j$ 的状态，经过字符串 $s[idx]$ 后的新匹配长度以及这一段的总匹配次数是可以预处理的，这样可以避免重复计算。

最后再把开头和结尾拼接进去。就枚举分割的字符串 $s_0$ 的分割位置，先跑后缀的部分，再看中间的 DP 可能转移到的状态，再从对应状态开始跑 $s_0$ 的前缀部分。

时间复杂度为 $\mathcal{O}(n|p|^22^n+\sum|s_i||p|)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    strs = [[ord(c) - ord('a') for c in I()] for _ in range(n)]
    pattern = [ord(c) - ord('a') for c in I()]

    k = len(pattern)
    transition = [[0] * 26 for _ in range(k + 1)]

    for i in range(k + 1):
        for j in range(26):
            tmp = []
            for idx in range(i):
                tmp.append(pattern[idx])
            tmp.append(j)

            l = len(tmp)
            for cur_len in range(fmin(l, k), -1, -1):
                flg = True

                for idx in range(cur_len):
                    if pattern[idx] != tmp[l - cur_len + idx]:
                        flg = False

                if flg:
                    transition[i][j] = cur_len
                    break

    transition_string = [[None] * (k + 1) for _ in range(n)]

    for i in range(n):
        for j in range(k + 1):
            cur = j
            cnt = 0

            for c in strs[i]:
                cur = transition[cur][c]
                if cur == k: cnt += 1

            transition_string[i][j] = (cur, cnt)

    def f(x, y):
        return x * (k + 1) + y

    dp = [[-1] * (1 << n) for _ in range((k + 1) * (k + 1))]

    for i in range(k + 1): dp[f(i, i)][0] = 0

    for msk in range(1 << n):
        for i in range(k + 1):
            for j in range(k + 1):
                if dp[f(i, j)][msk] != -1:
                    for bit in range(n):
                        if msk >> bit & 1: continue
                        nmsk = msk | (1 << bit)
                        nj, ncnt = transition_string[bit][j]
                        dp[f(i, nj)][nmsk] = fmax(dp[f(i, nj)][nmsk], dp[f(i, j)][msk] + ncnt)

    ans = 0

    for i in range(n):
        l = len(strs[i])

        for j in range(l):
            cur, cnt = 0, 0

            for idx in range(j, l):
                cur = transition[cur][strs[i][idx]]
                if cur == k: cnt += 1

            msk = (1 << n) - 1 - (1 << i)
            for ncur in range(k + 1):
                if dp[f(cur, ncur)][msk] != -1:
                    ncnt = cnt + dp[f(cur, ncur)][msk]

                    for idx in range(j):
                        ncur = transition[ncur][strs[i][idx]]
                        if ncur == k: ncnt += 1

                    ans = fmax(ans, ncnt)

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	vector<string> strs(n);
	for (auto &s: strs) cin >> s;

	string pattern;
	cin >> pattern;

	int k = pattern.size();

	vector<vector<int>> transition(k + 1, vector<int>(26, 0));

	for (int i = 0; i <= k; i ++) {
		for (int j = 0; j < 26; j ++) {
			string tmp = pattern.substr(0, i);
			tmp += (char)('a' + j);

			int l = tmp.size();
			for (int cur_len = min(l, k); cur_len >= 0; cur_len --) {
				bool flg = true;

				for (int idx = 0; idx < cur_len; idx ++) {
					if (pattern[idx] != tmp[l - cur_len + idx]) {
						flg = false;
					}
				}

				if (flg) {
					transition[i][j] = cur_len;
					break;
				}
			}
		}
	}

	vector<vector<pair<int, int>>> transition_string(n, vector<pair<int, int>>(k + 1));

	for (int i = 0; i < n; i ++) {
		for (int j = 0; j <= k; j ++) {
			int cur = j, cnt = 0;

			for (auto &c: strs[i]) {
				cur = transition[cur][c - 'a'];
				if (cur == k) cnt ++;
			}

			transition_string[i][j] = {cur, cnt};
		}
	}

	auto f = [&] (int x, int y) -> int {return x * (k + 1) + y;};

	vector<vector<int>> dp((k + 1) * (k + 1), vector<int>(1 << n, -1));

	for (int i = 0; i <= k; i ++) dp[f(i, i)][0] = 0;

	for (int msk = 0; msk < (1 << n); msk ++) {
		for (int i = 0; i <= k; i ++) {
			for (int j = 0; j <= k; j ++) {
				if (dp[f(i, j)][msk] != -1) {
					for (int bit = 0; bit < n; bit ++) {
						if (msk >> bit & 1) continue;
						int nmsk = msk | (1 << bit);
						auto [nj, ncnt] = transition_string[bit][j];
						dp[f(i, nj)][nmsk] = max(dp[f(i, nj)][nmsk], dp[f(i, j)][msk] + ncnt);
					}
				}
			}
		}
	}

	int ans = 0;

	for (int i = 0; i < n; i ++) {
		int l = strs[i].size();

		for (int j = 0; j < l; j ++) {
			int cur = 0, cnt = 0;

			for (int idx = j; idx < l; idx ++) {
				cur = transition[cur][strs[i][idx] - 'a'];
				if (cur == k) cnt ++;
			}

			int msk = (1 << n) - 1 - (1 << i);

			for (int ncur = 0; ncur <= k; ncur ++) {
				if (dp[f(cur, ncur)][msk] != -1) {
					int vcur = ncur, vcnt = cnt + dp[f(cur, ncur)][msk];

					for (int idx = 0; idx < j; idx ++) {
						vcur = transition[vcur][strs[i][idx] - 'a'];
						if (vcur == k) vcnt ++;
					}

					ans = max(ans, vcnt);
				}
			}
		}
	}

	cout << ans;

	return 0;
}
```

