int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int r, c, m, k;
		cin >> r >> c >> m >> k;

		if (k > min(r, c)) cout << "NO\n";
		else if (m < k || m > 1ll * max(r, c) * k) cout << "NO\n";
		else {
			vector<string> grid(r, string(c, '.'));
			for (int i = 0; i < k; i ++) grid[i][i] = '#', m --;

			for (int i = 0; i < (r < c ? k : r); i ++) {
				for (int j = 0; j < (c < r ? k : c); j ++) {
					if (m && grid[i][j] == '.') {
						grid[i][j] = '#';
						m --;
					}
				}
			}

			cout << "YES\n";
			for (auto &x: grid) cout << x << '\n';
		}
	}

	return 0;
}
```

**提示 1：** 注意 edge case 。从明显的情况开始调整。

可以想下 / 看看样例，容易发现 $k=nm-1$ 的情况似乎不太可能发生。因为这种情况下，只能有 $nm-2$ 个大小为 $1$ 的连通块和 $1$ 个大小为 $2$ 的连通块。而 $\min(n,m)\gt 1$ 时， $1\times 2$ 的那个连通块周围肯定有和它同色的连通块，矛盾，此时输出无解。当然 $\min(n,m)=1$ 需要特判。

接下来咋办呢？

我们难以处理的是连通块较多的情况。首先 $k=nm$ 的时候直接间隔染色就好。

$k=nm-2$ 呢？基于 $k=nm$ 的微调即可。

```
01010
10101
01010
10101
01011
```

$k=nm-3$ 呢？基于 $k=nm-2$ 微调即可。

```
01010
10101
01010
10101
01001
```

这种调整什么时候会失效呢？你改到开头的时候，这个连通块的数量就突然不变了：

```
从：
01010
10101
01010
10101
00101

变成：
01010
10101
01010
10101
10101
```

但此时你可以再多修改一个位置把两个连通块连起来，这也是所有其它的 $tm+(m-1)$ 类型的 $k$ 的构造方法：

```
01010
10101
01010
10100 (这一行的最末尾)
10101
```

而对于剩余的情况，往往可以通过先将 $n$ 减小，构造出答案，再在末尾加上相同的行完成。

时间复杂度为 $\mathcal{O}(nm)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m, k = MII()

    if n == 1:
        print('YES')
        print(''.join(str(fmin(i, k - 1) % 2) for i in range(m)))
    elif m == 1:
        print('YES')
        print('\n'.join(str(fmin(i, k - 1) % 2) for i in range(n)))
    elif k == n * m - 1:
        print('NO')
    else:
        grid = [[-1] * m for _ in range(n)]

        if k <= m:
            for i in range(n):
                for j in range(m):
                    grid[i][j] = fmin(j, k - 1) % 2
        else:
            first = (k - 1) // m + 1
            for i in range(first):
                for j in range(m):
                    if i * m + j <= k:
                        grid[i][j] = (i + j) % 2
                    else:
                        grid[i][j] = 1 - (i + j) % 2

            for i in range(first, n):
                for j in range(m):
                    grid[i][j] = grid[i - 1][j]

            if k % m == m - 1:
                grid[first - 1][m - 1] = grid[first - 2][m - 1]

        print('YES')
        print('\n'.join(''.join(map(str, x)) for x in grid))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, m, k;
	cin >> n >> m >> k;

	if (n == 1) {
		cout << "YES\n";
		for (int i = 0; i < m; i ++) cout << min(i, k - 1) % 2;
		cout << '\n';
	}
	else if (m == 1) {
		cout << "YES\n";
		for (int i = 0; i < n; i ++) cout << min(i, k - 1) % 2 << '\n';
	}
	else if (k == n * m - 1) cout << "NO\n";
	else {
		vector<vector<int>> grid(n, vector<int>(m));

		if (k <= m) {
			for (int i = 0; i < n; i ++) {
				for (int j = 0; j < m; j ++) {
					grid[i][j] = min(j, k - 1) % 2;
				}
			}
		}
		else {
			int first = (k - 1) / m + 1;

			for (int i = 0; i < first; i ++) {
				for (int j = 0; j < m; j ++) {
					if (i * m + j <= k) grid[i][j] = (i + j) % 2;
					else grid[i][j] = 1 - (i + j) % 2;
				}
			}

			for (int i = first; i < n; i ++) {
				for (int j = 0; j < m; j ++) {
					grid[i][j] = grid[i - 1][j];
				}
			}

			if (k % m == m - 1) grid[first - 1][m - 1] = grid[first - 2][m - 1];
		}

		cout << "YES\n";
		for (auto &x: grid) {
			for (auto &y: x) cout << y;
			cout << '\n';
		}
	}

	return 0;
}
