**提示 1：** 枚举 $r_1$ 。

考虑将整体式子整理成 $(r_1-l_1+1)x+(r_2-l_2+1)y+(l_2-r_1-1)z$ ，也就是匹配前前缀、中间、匹配后缀三段的单位长度权值分别是 $x,z,y$ ，其中前后缀非空。

接下来考虑枚举 $r_1$ ，此时其对应的最优的 $l_1$ 就是这个位置结尾的最长匹配真前缀，可以用 KMP 解决。

如果 $l_2$ 确定了， $r_2$ 显然也取最长的，即从这个位置开始的字符串能匹配的最长的真后缀。

而从大到小枚举 $r_1$ 的过程中，我们可以顺便把大于 $l_2$ 的后缀的左端点也考虑进来。具体而言，假设我们已经考虑了 $l_2\geq L$ 的情况，则 $l_2=L-1$ 时，首先可以由 $l_2\geq L$ 的情况 $+z$ 得到权值，再多考虑上 $L-1$ 的最长匹配长度乘以 $y$ 两者取最大值即可。 

注意前后缀的段需要非空，因此只有匹配长度大于 $0$ 时，才更新最值。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    def prep(p):
        pi = [0] * len(p)
        j = 0
        for i in range(1, len(p)):
            while j != 0 and p[j] != p[i]:
                j = pi[j - 1]
            if p[j] == p[i]:
                j += 1
            pi[i] = j
        return pi

    n, x, y, z = MII()
    s = [ord(c) for c in I()]

    v1 = prep(s)

    s.reverse()
    v2 = prep(s)
    v2.reverse()

    ans = 0
    cur = -inf

    for i in range(n - 2, -1, -1):
        cur += z
        if v2[i + 1] > 0:
            cur = fmax(cur, y * v2[i + 1])
        if v1[i] > 0:
            ans = fmax(ans, cur + x * v1[i])

    print(ans)
```

C++ 做法如下——

```cpp []
template <typename T>
std::vector<int> prep(const T& p) {
	int n = static_cast<int>(p.size());
	std::vector<int> pi(n, 0);
	int j = 0;
	for (int i = 1; i < n; ++i) {
		while (j != 0 && p[j] != p[i]) {
			j = pi[j - 1];
		}
		if (p[j] == p[i]) {
			++j;
		}
		pi[i] = j;
	}
	return pi;
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, x, y, z;
	cin >> n >> x >> y >> z;

	string s;
	cin >> s;

	auto v1 = prep(s);

	reverse(s.begin(), s.end());
	auto v2 = prep(s);
	reverse(v2.begin(), v2.end());

	long long ans = 0, cur = -3e18;

	for (int i = n - 2; i >= 0; i --) {
		cur += z;
		if (v2[i + 1] > 0) cur = max(cur, 1ll * y * v2[i + 1]);
		if (v1[i] > 0) ans = max(ans, cur + 1ll * x * v1[i]);
	}

	cout << ans;

	return 0;
}
```

**提示 1：** 考虑状态转移与统计的变量的转移。

显然我们关心第 $i$ 步是赢了的概率，输了的概率以及总期望的赢的次数。（前两者关系到后面的状态，所以重要）

分别设为 $a_n,b_n,c_n$ ，则：

$$
a_n=(p_1/q_1)a_{n-1}+(p_2/q_2)b_{n-1}
$$

$$
b_n=(1-p_1/q_1)a_{n-1}+(1-p_2/q_2)b_{n-1}
$$

$$
c_n=[(p_1/q_1)a_{n-1}+(p_2/q_2)b_{n-1}]+c_{n-1}
$$

于是可以用矩阵快速幂维护转移关系。注意初始状态下 $a_1=p_0/q_0, b_1=1-p_0/q_0, c_1=p_0/q_0$ 。用上面的转移矩阵乘以这个向量就能得到 $n$ 步后的状态了。

时间复杂度为 $\mathcal{O}(\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    mod = 998244353

    def matrix_mul(A, B):
        n, m = len(A), len(A[0])
        p = len(B[0])
        ans = [[0] * p for _ in range(n)]
        for i in range(n):
            for j in range(m):
                for k in range(p):
                    ans[i][k] += A[i][j] * B[j][k]
        for i in range(n):
            for j in range(m):
                ans[i][j] %= mod
        return ans

    def matrix_pow(x, n):
        if n == 0:
            k = len(x)
            grid = [[0] * k for _ in range(k)]
            for i in range(k):
                grid[i][i] = 1
            return grid
        if n == 1: return x
        if n == 2: return matrix_mul(x, x)
        v = matrix_pow(x, n // 2)
        ans = matrix_mul(v, v)
        if n % 2 == 0:
            return ans
        return matrix_mul(ans, x)

    for _ in range(t):
        n = II()
        p0, q0, p1, q1, p2, q2 = MII()

        x0 = p0 * pow(q0, -1, mod) % mod
        y0 = (mod + 1 - x0) % mod

        x1 = p1 * pow(q1, -1, mod) % mod
        y1 = (mod + 1 - x1) % mod

        x2 = p2 * pow(q2, -1, mod) % mod
        y2 = (mod + 1 - x2) % mod

        grid = [[x1, x2, 0],
                [y1, y2, 0],
                [x1, x2, 1]]

        res = matrix_pow(grid, n - 1)

        ans = 0
        ans += res[2][0] * x0 % mod
        ans += res[2][1] * y0 % mod
        ans += res[2][2] * x0 % mod

        outs.append(ans % mod)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
typedef __int128 lll;

const int MAXN = 5;
static lll tmp[MAXN][MAXN];

long long quickPow(long long base, long long power, long long mod) {
	if (power == 0) return 1 % mod;
	long long cur = quickPow(base, power / 2, mod);
	return power & 1 ? base * cur % mod * cur % mod : cur * cur % mod; 
}

vector<vector<int>> matrix_mul(const vector<vector<int>>& A,
								const vector<vector<int>>& B, int mod) {
	int n = A.size(), m = A[0].size(), x = B[0].size();

	for (int i = 0; i < n; i++)
		for (int j = 0; j < x; j++)
			tmp[i][j] = 0;

	for (int i = 0; i < n; i++) {
		for (int k = 0; k < m; k++) {
			lll aik = A[i][k];
			for (int j = 0; j < x; j++)
				tmp[i][j] += aik * B[k][j];
		}
	}

	vector<vector<int>> ans(n, vector<int>(x));
	for (int i = 0; i < n; i++)
		for (int j = 0; j < x; j++)
			ans[i][j] = (int)(tmp[i][j] % mod);
	return ans;
}

vector<vector<int>> matrix_pow(vector<vector<int>> grid, long long power, int mod) {
	int n = grid.size();
	vector<vector<int>> ans(n, vector<int>(n, 0));
	for (int i = 0; i < n; i++) ans[i][i] = 1;
	while (power > 0) {
		if (power & 1) ans = matrix_mul(ans, grid, mod);
		grid = matrix_mul(grid, grid, mod);
		power >>= 1;
	}
	return ans;
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t, mod = 998244353;
	cin >> t;

	while (t --) {
		long long n;
		cin >> n;

		int p0, q0, p1, q1, p2, q2;
		cin >> p0 >> q0 >> p1 >> q1 >> p2 >> q2;

		int x0 = p0 * quickPow(q0, mod - 2, mod) % mod;
		int y0 = (mod + 1 - x0) % mod;

		int x1 = p1 * quickPow(q1, mod - 2, mod) % mod;
		int y1 = (mod + 1 - x1) % mod;

		int x2 = p2 * quickPow(q2, mod - 2, mod) % mod;
		int y2 = (mod + 1 - x2) % mod;

		vector<vector<int>> grid = {
			{x1, x2, 0},
			{y1, y2, 0},
			{x1, x2, 1}
		};

		auto res = matrix_pow(grid, n - 1, mod)[2];

		int ans = 0;
		ans = (ans + 1ll * res[0] * x0) % mod;
		ans = (ans + 1ll * res[1] * y0) % mod;
		ans = (ans + 1ll * res[2] * x0) % mod;

		cout << ans << '\n';
	}

	return 0;
}
```

**提示 1：** 考虑 Manacher 的过程。有些端点的合并。

**提示 2：** 这些端点的合并是充分的吗？

一个字符串的回文串问题，先考虑 Manacher 算法（当然为了考虑长度为偶数的回文串，你需要在相邻字符之间插入相同的无关字符）。

则每当 Manacher 扩展中心长度的时候，我们在其端点之间连一条边（因为对应的都是回文串，当然建立在端点都是字符的基础上）。

每次这样扩展的时候，新增的边都会遍历到一个尚未经过的下标，所以必然不可能成环。

同时，每个回文串的端点要么是加边的时候出现的，此时已经连通；要么是根据前面对称而来的，因此只要前面的时候那两点连通，则新的两点也已经连通。也就可以归纳法证明，任意一个回文串的端点都已经在同一个连通块内。（因为更短的前缀满足条件可以推出当前前缀满足条件）

综上我们连接的结构是个森林。连通块数量就等于点数减去边数。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    s = [ord(c) for c in I()]
    n = len(s)

    tmp = []
    for i in range(n):
        if i: tmp.append(-1)
        tmp.append(s[i])

    ans = n
    wing = [0] * (2 * n - 1)
    j = 0

    for i in range(2 * n - 1):
        if j + wing[j] >= i:
            wing[i] = fmin(j + wing[j] - i, wing[2 * j - i])

        while i - wing[i] - 1 >= 0 and i + wing[i] + 1 < 2 * n - 1 and tmp[i - wing[i] - 1] == tmp[i + wing[i] + 1]:
            wing[i] += 1
            if (i - wing[i]) % 2 == 0:
                ans -= 1

        if i + wing[i] > j + wing[j]:
            j = i

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	string s;
	cin >> s;

	int n = s.size();

	string tmp;
	for (int i = 0; i < n; i ++) {
		if (i) tmp += '|';
		tmp += s[i];
	}

	int ans = n, j = 0;
	vector<int> wing(2 * n - 1, 0);

	for (int i = 0; i < 2 * n - 1; i ++) {
		if (j + wing[j] >= i) wing[i] = min(j + wing[j] - i, wing[2 * j - i]);
		while (i - wing[i] - 1 >= 0 && i + wing[i] + 1 < 2 * n - 1 && tmp[i - wing[i] - 1] == tmp[i + wing[i] + 1]) {
			wing[i] ++;
			if ((i - wing[i]) % 2 == 0) ans --;
		}
		if (i + wing[i] > j + wing[j]) j = i;
	}

	cout << ans;

