		for (auto &x: v1) cin >> x;
		for (auto &x: v2) cin >> x;

		vector<int> cnt(n, 0);
		for (auto &x: v1) if (x <= n) cnt[x - 1] ++;

		int to_fill = 0;
		long long total = 0;
		priority_queue<int, vector<int>, greater<int>> pq;

		for (int i = 0; i < n; i ++) {
			if (cnt[i]) {
				to_fill += cnt[i] - 1;
				total += v2[i];
				pq.push(v2[i]);
