	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int n; string s;
		cin >> n >> s;

		bool flg = true;
		for (int i = 0; i < n - 1; i ++) {
			if (s[i] != s[0]) {
				flg = false;
			}
		}

