**提示 2：** 从第 $i$ 个答案推到第 $i+1$ 个答案。

首先，如果只需求最终的答案，怎么做呢？

先考虑将对应的数字连边，则每条边需要钦定一个互不相同的端点。

每个连通块的方案相乘即可。

如果边数大于点数，则至少有一点分配给两边（抽屉原理），矛盾。

如果边数等于点数，则恰好有一个环，且环上的点只能分给环上的边，不然的话外侧的边数就大于点数了。而环的分配方式有两种。

如果边数等于点数减一，则整个形成一棵树，钦定树上任意一点不被选都对应了一种方案，因此答案是点的个数。

而在连边的过程中只需维护当前两个点连边造成的影响，即可通过前一轮的答案计算下一轮的答案：

- 将两棵树相连：除以它们原本的大小，乘以后来的大小。

- 有环的连通块和树相连：除以树的原先的大小。

- 将两个有环的连通块相连：答案变为 $0$ 。

- 在一个连通块内连边：

	- 如果本身是树，则除以树的大小，乘以 $2$ 。

	- 如果本身有环，则答案变为 $0$ 。

这里预处理逆元就可以快速完成这件事。

是否有环可以在并查集的维护过程中，在对应连通块的结点打标记实现。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    mod = 998244353

    M = 3 * 10 ** 5 + 5
    invs = [0] * M

    invs[1] = 1

    for i in range(2, M):
        invs[i] = (mod - mod // i) * invs[mod % i] % mod

    for _ in range(t):
        n = II()
        us = []
        vs = []

        for _ in range(n):
            u, v = MII()
            us.append(u)
            vs.append(v)

        nodes = sorted(us + vs)

        for i in range(n):
            us[i] = bisect.bisect_left(nodes, us[i])
            vs[i] = bisect.bisect_left(nodes, vs[i])

        res = []
        ans = 1

        tag = [0] * (n * 2)
        uf = UnionFind(n * 2)

        for i in range(n):
            u = uf.find(us[i])
            v = uf.find(vs[i])
            szu = uf.getSize(u)
            szv = uf.getSize(v)

            uf.merge(u, v)
            p = uf.find(u)

            if u != v:
                if tag[u] and tag[v]:
                    ans = 0
                elif tag[u]:
                    ans = ans * invs[szv] % mod
                    tag[p] = 1
                elif tag[v]:
                    ans = ans * invs[szu] % mod
                    tag[p] = 1
                else:
                    ans = ans * invs[szu] % mod * invs[szv] % mod * (szu + szv) % mod
            else:
                if tag[u]:
                    ans = 0
                else:
                    ans = ans * invs[szu] % mod * 2 % mod
                    tag[u] = 1

            res.append(ans)

        outs.append(' '.join(map(str, res)))

    print('\n'.join(outs))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int M = 3e5 + 5, mod = 998244353;
	vector<int> invs(M);

	invs[1] = 1;
	for (int i = 2; i < M; i ++)
		invs[i] = 1ll * (mod - mod / i) * invs[mod % i] % mod;

	int t;
	cin >> t;

	while (t --) {
		int n;
		cin >> n;

		vector<pair<int, int>> edges(n);
		vector<int> nodes;

		for (auto &[u, v]: edges) {
			cin >> u >> v;
			nodes.emplace_back(u);
			nodes.emplace_back(v);
		}

		sort(nodes.begin(), nodes.end());

		atcoder::dsu uf(2 * n);
		vector<int> tag(2 * n, 0);

		int ans = 1;

		for (int i = 0; i < n; i ++) {
			int u = lower_bound(nodes.begin(), nodes.end(), edges[i].first) - nodes.begin();
			int v = lower_bound(nodes.begin(), nodes.end(), edges[i].second) - nodes.begin();

			u = uf.leader(u), v = uf.leader(v);
			int szu = uf.size(u), szv = uf.size(v);

			uf.merge(u, v);
			int p = uf.leader(u);

			if (u != v) {
				if (tag[u] && tag[v]) ans = 0;
				else if (tag[u]) {
					ans = 1ll * ans * invs[szv] % mod;
					tag[p] = 1;
				}
				else if (tag[v]) {
					ans = 1ll * ans * invs[szu] % mod;
					tag[p] = 1;
				}
				else {
					ans = 1ll * ans * invs[szu] % mod * invs[szv] % mod * (szu + szv) % mod;
				}
			}
			else {
				if (tag[u]) ans = 0;
				else {
					ans = 2ll * ans * invs[szu] % mod;
					tag[u] = 1;
				}
			}

			cout << ans << " \n"[i == n - 1];
		}
	}

	return 0;
}
```

**提示 1：** 数分为两类。怎么选才能保证之后不会出问题？

考虑当前的数字按照下标奇偶性分为两类 $V_1,V_2$ ，前者是奇数，后者是偶数。将其排序。

如果查询的是 $2$ ，则显然从后者中选取最大的输出即可。

否则，假设此时有 $k$ 个要选。

直观上来说，一般而言我们应该选那些之后可能没机会选的 $V_1$ 集合中的数，但这个数可能太小了，甚至还不如在 $V_2$ 中选。我们就是要判断何时选前者，何时选后者。

也就是说，如果前 $k$ 大的 $V_2$ 中的元素都超过了 $V_1$ 中的最大元素，此时显然应该之间选 $V_2$ 中的元素。

不然我们可能错过选 $V_1$ 中元素的最后机会，因此我们选 $V_1$ 中的元素。

可以尝试写下更严谨的说法。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, k = MII()
    nums = LII()

    idxs1 = list(range(0, n, 2))
    idxs2 = list(range(1, n, 2))

    idxs1.sort(key=lambda x: nums[x])
    idxs2.sort(key=lambda x: nums[x])

    def output(x):
        print(x + 1, flush=True)
        II()

    for i in range(k):
        v = II()

        if v == 1:
            resid = k - i
            if nums[idxs1[-1]] >= nums[idxs2[-resid]]:
                output(idxs1.pop())
            else:
                output(idxs2.pop())
        else:
            output(idxs2.pop())
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, k;
	cin >> n >> k;

	vector<int> nums(n + 1);
	for (int i = 1; i <= n; i ++) cin >> nums[i];

	vector<int> idxs1, idxs2;
	for (int i = 1; i <= n; i ++) {
		if (i & 1) idxs1.emplace_back(i);
		else idxs2.emplace_back(i);
	}

	sort(idxs1.begin(), idxs1.end(), [&] (int i, int j) {return nums[i] < nums[j];});
	sort(idxs2.begin(), idxs2.end(), [&] (int i, int j) {return nums[i] < nums[j];});

	auto output = [&] (int x) -> void {
		cout << x << endl;
		int v; cin >> v;
	};

	for (int i = 0; i < k; i ++) {
		int v;
		cin >> v;

		if (v == 1) {
			int resid = k - i;
			if (nums[idxs1.back()] >= nums[idxs2.end()[-resid]]) {
				int idx = idxs1.back(); idxs1.pop_back();
				output(idx);
			}
			else {
				int idx = idxs2.back(); idxs2.pop_back();
				output(idx);
			}
		}
		else {
			int idx = idxs2.back(); idxs2.pop_back();
			output(idx);
		}
	}

	return 0;
}
```

**提示 1：** 维护什么？计数什么？

对于查询 $idx, val$ ，首先如果 $val$ 不是 $nums[idx]$ 的因子，则直接返回 $0$ 即可，因为显然不可能是最大公约数。

否则，我们就要看有多少数是 $val$ 的倍数，且对于 $2val, 3val,\dots$ 中 $nums[idx]$ 的约数，我们求的数不能是它的倍数。

所以我们只关心有多少元素是这些数的倍数，数量共有 $nums[idx]/val$ 的因子个。我们获取以这些数为因子的数的个数，在这些计数结果中进行容斥（也可以理解为莫比乌斯反演），即可球的答案。当然，如果 $nums[idx]=val$ 记得排除掉自己。

然后修改的时候直接对其因子进行计数的修改即可。

时间复杂度为 $\mathcal{O}(nd(M)+M)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    M = 10 ** 6 + 5
    pr = list(range(M))

    mu = [0] * M
    mu[1] = 1

    for i in range(2, M):
        if pr[i] == i:
            for j in range((M - 1) // i * i, 0, -i):
                pr[j] = i
                mu[j] = -mu[j // i]

    def factors(x):
        v = [1]
        while x > 1:
            p = pr[x]
            c = 0

            while x % p == 0:
                x //= p
                c += 1

            l = len(v)
            for _ in range(c * l):
                v.append(v[-l] * p)

        return v

    t = II()
    outs = []

    cnt = [0] * M

    for _ in range(t):
        n, q = MII()
        nums = LII()

        for x in nums:
            for f in factors(x):
                cnt[f] += 1

        for _ in range(q):
            ty, idx, val = MII()
            idx -= 1

            if ty == 1:
                if nums[idx] % val: outs.append(0)
                else:
                    ans = 0
                    for f in factors(nums[idx] // val):
                        ans += mu[f] * cnt[f * val]
                    if val == nums[idx]: ans -= 1
                    outs.append(ans)
            else:
                for f in factors(nums[idx]):
                    cnt[f] -= 1
                nums[idx] = val
                for f in factors(nums[idx]):
                    cnt[f] += 1

        for x in nums:
            for f in factors(x):
                cnt[f] -= 1

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int M = 1e6;

	vector<int> pr(M + 1), mu(M + 1, 0);
	iota(pr.begin(), pr.end(), 0);
	mu[1] = 1;

	for (int i = 2; i <= M; i ++) {
		if (pr[i] == i) {
			for (int j = M / i * i; j >= i; j -= i) {
				pr[j] = i;
				mu[j] = -mu[j / i];
			}
		}
	}

	auto factors = [&] (int x) -> vector<int> {
		vector<int> res = {1};
		while (x > 1) {
			int p = pr[x], c = 0;
			while (x % p == 0) x /= p, c ++;
			int l = res.size();
			for (int i = 0; i < l * c; i ++) res.emplace_back(res.end()[-l] * p);
		}
		return res;
	};

	vector<int> cnt(M + 1, 0);

	int t;
	cin >> t;

	while (t --) {
		int n, q;
		cin >> n >> q;

		vector<int> nums(n);
		for (auto &v: nums) cin >> v;

		for (auto &v: nums) for (auto &x: factors(v)) cnt[x] ++;

		while (q --) {
			int ty, idx, val;
			cin >> ty >> idx >> val; idx --;

			if (ty == 1) {
				if (nums[idx] % val) cout << 0 << '\n';
				else {
					int ans = 0;
					for (auto &v: factors(nums[idx] / val))
						ans += mu[v] * cnt[v * val];
					if (nums[idx] == val) ans --;
					cout << ans << '\n';
				}
			}
			else {
				for (auto &v: factors(nums[idx])) cnt[v] --;
				nums[idx] = val;
				for (auto &v: factors(nums[idx])) cnt[v] ++;
			}
		}

		for (auto &v: nums) for (auto &x: factors(v)) cnt[x] --;
	}

	return 0;
}
```

**提示 1：** 每个环是独立决策的，分别有何特点？

**提示 2：** 找到合适的策略。

首先，将 $i$ 向 $p_i$ 连边，每个点一个入度一个出度，是一系列的环。而每次选了一个点后，这个环上的点都得被选。

在选择某个环的情况下，我们肯定选择权值最大的那个点当开头。而如果选择的环长度是偶数，则先后手不变；否则下个环先后手关系转变。

而对于长度为偶数的环，总能找到起点，使得这个环结束后分值朝自己想要的方向变动，所以先手可以先挑选所有偶数的环，把这些分拿到。

接下来每个奇数环，先预处理其最优起点及对应的得分。接下来的问题，就是两个人轮流选环，因此按照得分逆序排序，依次分配给先后手即可。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    for _ in range(t):
        n = II()
        p = [0] + LII()

        ans = 0
        vis = [0] * (n + 1)

        tmp = []

        for i in range(1, n + 1):
            if vis[i] == 0:
                cur = [i]
                while p[cur[-1]] != i:
                    cur.append(p[cur[-1]])

                for x in cur:
                    vis[x] = 1

                l = len(cur)
                if l % 2 == 0:
                    v = 0
                    for j in range(l):
                        if j % 2: v += cur[j]
                        else: v -= cur[j]
                    ans += abs(v)
                else:
                    v = 0
                    for j in range(1, l):
                        if j % 2: v += cur[j]
                        else: v -= cur[j]

                    res = 0
                    for j in range(l):
                        if j % 2:
                            res = fmax(res, cur[j] + v)
                            v += cur[(j + 1) % l]
                            v -= cur[j]
                        else:
                            res = fmax(res, cur[j] - v)
                            v -= cur[(j + 1) % l]
                            v += cur[j]

                    tmp.append(res)

        tmp.sort(reverse=True)

        for i in range(len(tmp)):
            if i % 2 == 0: ans += tmp[i]
            else: ans -= tmp[i]

        outs.append(ans)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int n;
		cin >> n;

		vector<int> p(n + 1);
		for (int i = 1; i <= n; i ++) cin >> p[i];

		long long ans = 0;
		vector<int> vis(n + 1, 0);
		vector<long long> tmp;

		for (int i = 1; i <= n; i ++) {
			if (!vis[i]) {
				vector<int> cur = {i};
				while (p[cur.back()] != i) cur.emplace_back(p[cur.back()]);

				for (auto &x: cur) vis[x] = 1;

				int l = cur.size();

				if (l % 2 == 0) {
					long long v = 0;
					for (int j = 0; j < l; j ++) {
						if (j & 1) v += cur[j];
						else v -= cur[j];
					}
					ans += abs(v);
				}
				else {
					long long v = 0;
					for (int j = 1; j < l; j ++) {
						if (j & 1) v += cur[j];
						else v -= cur[j];
					}

					long long res = 0;
					for (int j = 0; j < l; j ++) {
						if (j & 1) {
							res = max(res, cur[j] + v);
							v += cur[(j + 1) % l];
							v -= cur[j];
						}
						else {
							res = max(res, cur[j] - v);
							v -= cur[(j + 1) % l];
							v += cur[j];
						}
					}

					tmp.emplace_back(res);
				}
			}
		}

		sort(tmp.rbegin(), tmp.rend());

		for (int i = 0; i < tmp.size(); i ++) {
			if (i % 2 == 0) ans += tmp[i];
			else ans -= tmp[i];
		}

		cout << ans << '\n';
	}

	return 0;
}
