	dp[0][0] = 1;

	for (int i = 1; i < 20; i ++) dp[0][i] = i * dp[0][i - 1];

	for (int i = 1; i < 20; i ++) {
		for (int j = 0; j < 20; j ++) {
			if (i + j < 20) {
				dp[i][j] = dp[i - 1][j] * j;
