C++ 做法如下——

```cpp []
long long op(long long x, long long y) {return gcd(x, y);}

long long e() {return 0;}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	vector<long long> nums(n);
	for (auto &x: nums) cin >> x;

	vector<int> deg(n, 0);
	for (int i = 0; i < n - 1; i ++) {
		int u, v;
		cin >> u >> v;
		u --, v --;
		deg[u] ++, deg[v] ++;
	}

	vector<int> tmp;
	for (int i = 0; i < n; i ++) if (deg[i] == 1) tmp.emplace_back(i);
	for (int i = 0; i < n; i ++) if (deg[i] > 1) tmp.emplace_back(i);

	vector<long long> vals(n, 0);
	vector<int> pos(n, 0);

	for (int i = 0; i < n; i ++) {
		vals[i] = nums[tmp[i]];
		pos[tmp[i]] = i;
	}

	atcoder::segtree<long long, op, e> seg(vals);

	int q;
	cin >> q;

	while (q --) {
		int idx;
		long long val;
		cin >> idx >> val; idx --;

		vals[pos[idx]] = val;
		seg.set(pos[idx], val);

		int k = min(16, n);
		long long cur = seg.prod(k, n);

		vector<long long> pref = {0};
		for (int i = 0; i < k - 1; i ++) pref.emplace_back(gcd(pref.back(), vals[i]));

		bool flg = false;
		for (int i = k - 1; i >= 0; i --) {
			if (deg[tmp[i]] == 1 && gcd(pref[i], cur) == 1) flg = true;
			cur = gcd(cur, vals[i]);
		}

		cout << (flg ? "Yes" : "No") << '\n';
	}

	return 0;
}
```

**提示 1：** 这个子数组需要满足什么条件？

MEX 可能是 $0$ 或者 $1$ 吗？不可能。

MEX 可能是 $2$ 吗？可能，且只可能是 $2$ 个 $1$ 和不小于 $1$ 个的 $0$ 。

MEX 可能是 $3$ 吗？可能，且只可能是 $1$ 个 $2$ ， $1$ 个 $1$ 和不小于 $1$ 个的 $0$ 。

MEX 可能更大吗？不可能了。因为至少就要出现 $1\sim x-1$ 中的所有数了，它们的和就超过了 $x$ 。

所以数组中恰好有俩非 $0$ 数且满足上面的条件。

数量求法有很多，下面给出一种。我们先提取所有非 $0$ 元素的下标，再考虑相邻的两个元素出现在多少个子数组中，其实本质上就看前一个元素的左侧和后一个元素的右侧有多少个 $0$ ，不妨设分别有 $x,y$ 个，则答案为 $(x+1)(y+1)$ 。当然如果这两个元素相邻，那得排除下子数组长度为 $2$ 的情况，减去 $1$ 即可。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    nums = LII()

    ans = 0
    idxs = [i for i in range(n) if nums[i]]

    for i in range(1, len(idxs)):
        x = idxs[i - 1]
        y = idxs[i]
        if fmin(nums[x], nums[y]) == 1 and fmax(nums[x], nums[y]) <= 2:
            lx = idxs[i - 2] if i - 2 >= 0 else -1
            ry = idxs[i + 1] if i + 1 < len(idxs) else n

            ans += (x - lx) * (ry - y)
            if y - x == 1: ans -= 1

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	vector<int> nums(n);
	for (auto &x: nums) cin >> x;

	vector<int> idxs;
	for (int i = 0; i < n; i ++) if (nums[i]) idxs.emplace_back(i);

	long long ans = 0;
	for (int i = 1; i < idxs.size(); i ++) {
		int x = idxs[i - 1], y = idxs[i];
		if (min(nums[x], nums[y]) == 1 && max(nums[x], nums[y]) <= 2) {
			int lx = (i >= 2 ? idxs[i - 2] : -1);
			int ry = (i + 1 < idxs.size() ? idxs[i + 1] : n);

			ans += 1ll * (x - lx) * (ry - y);
			if (y - x == 1) ans --;
		}
	}

	cout << ans;

	return 0;
}
```

**提示 1：** 最多留下来多少牌？满足什么性质？

**提示 2：** DP 状态？

先看提示 1 。

首先，我们最多选择两个奇数，因为任意两个奇数异或结果只能是偶数，而偶质数只有 $2$ ，所以要让奇数之间的异或和两两为 $2$ ，最多只能选两个。

同理也至多选两个偶数。

这样我们总共最多选 $4$ 个数。

但似乎状态还是太多了，但是刚刚我们也提到了，选两个奇数的时候，我们只可能让它们异或和是 $2$ ，所以只可能是不选或者 $x$ 或者 $x,x+2$ 的形式，偶数也是一样。

于是对于一个固定的前缀，可行的奇数选取方案是 $\mathcal{O}(n)$ 的，偶数选取方案是 $\mathcal{O}(n)$ 的，因此总的选取方案数是 $\mathcal{O}(n^2)$ 。

接下来考虑 DP ，在最开头的时候，是空集，答案为 $0$ 。

而新增一个元素后，选取的子集，复杂度是 $\mathcal{O}(2^k)$ 的（ $k$ 是选取的卡片数量），选取子集判定合法后发生状态转移，更新状态转移后的结果即可。

这里为了减少状态，可以直接对选取的元素排序。

时间复杂度为 $\mathcal{O}(n^3)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    M = 1 << 20
    pr = [1] * M

    pr[0] = 0
    pr[1] = 0

    for i in range(2, M):
        if pr[i]:
            for j in range(2 * i, M, i):
                pr[j] = 0

    inf = 10 ** 18

    t = II()
    outs = []

    for _ in range(t):
        n = II()
        nums = LII()

        dp = Counter()
        dp[tuple()] = 0

        for value in nums:
            ndp = Counter()

            for v in dp:
                ndp[v] = fmax(ndp[v], dp[v])

                vals = list(v)
                k = len(vals)

                for i in range(1 << k):
                    tmp = [vals[j] for j in range(k) if i >> j & 1]
                    tmp.append(value)

                    l = len(tmp)
                    flg = True

                    for x in range(l):
                        for y in range(x):
                            if not pr[tmp[x] ^ tmp[y]]:
                                flg = False

                    if flg:
                        tmp.sort()
                        tmp = tuple(tmp)
                        ndp[tmp] = fmax(ndp[tmp], dp[v])

            dp = ndp

            for x in dp:
                dp[x] += sum(x)

        outs.append(max(dp.values()))

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int M = 1 << 20;

	vector<int> is_prime(M, 1);
	is_prime[0] = 0, is_prime[1] = 0;

	for (int i = 2; i < M; i ++) {
		if (is_prime[i]) {
			for (int j = i * 2; j < M; j += i) {
				is_prime[j] = 0;
			}
		}
	}

	int t;
	cin >> t;

	while (t --) {
		int n;
		cin >> n;

		map<vector<int>, long long> dp;
		dp[vector<int>()] = 0;

		while (n --) {
			int x;
			cin >> x;

			map<vector<int>, long long> ndp = dp;

			for (auto [nums, val]: dp) {
				int k = nums.size();

				for (int i = 0; i < 1 << k; i ++) {
					vector<int> tmp;

					for (int j = 0; j < k; j ++) {
						if (i >> j & 1) {
							tmp.emplace_back(nums[j]);
						}
					}

					tmp.emplace_back(x);

					bool flg = true;
					for (int a = 0; a < tmp.size(); a ++) {
						for (int b = 0; b < a; b ++) {
							if (!is_prime[tmp[a] ^ tmp[b]]) {
								flg = false;
							}
						}
					}

					if (flg) {
						sort(tmp.begin(), tmp.end());
						ndp[tmp] = max(ndp[tmp], val);
					}
				}
			}

			for (auto &[k, val]: ndp) {
				for (auto &v: k) {
					val += v;
				}
			}

			dp = ndp;
		}

		long long ans = 0;
		for (auto &[x, y]: dp) ans = max(ans, y);

		cout << ans << '\n';
	}

	return 0;
}
```

**提示 1：** 我们要求的是啥？每次更新会如何修改答案？

这题要求的是啥呢？

就是我们先统计每个元素出现的频率，再看频率中出现了多少个 $x$ 的倍数。

为此我们可以统计各个频率出现的频率，再对 $x$ 的倍数做统计，就可以得到初始的答案。初始答案可以对于 $x$ 枚举 $x,2x,\dots$ 等 $x$ 的倍数出现的总次数来得到。

而修改的时候，只有两个元素的频率被修改： $i$ 为止本来的数值和之后的数值。

所以频率修改时，哪些位置的答案改变了呢？

如果某个位置频率不再是 $v$ ，则所有 $v$ 的因子答案减去 $1$ ，而如果频率变成了 $v$ ，则所有 $v$ 的因子答案加上 $1$ 。

整体将频率的修改视为删去一个频率加上一个频率，因此只要求出所有改前和改后的频率的因子即可。

这件事在质因数分解后，可以以因子个数的复杂度完成。当然你也可以选择 $\mathcal{O}(\sqrt{n})$ 求。

时间复杂度为 $\mathcal{O}(n\log n+q\times d(n))$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, q = MII()
    nums = LII()

    pr = list(range(n + 1))

    for i in range(2, n + 1):
        if pr[i] == i:
            for j in range(i, n + 1, i):
                pr[j] = i

    M = 10 ** 6 + 5

    cnt = [0] * M

    for x in nums:
        cnt[x] += 1

    ans = [0] * M

    for x in cnt:
        ans[x] += 1

    for i in range(1, n + 1):
        for j in range(i * 2, n + 1, i):
            ans[i] += ans[j]

    def factors(x):
        if x == 0: return []

        res = [1]

        while x > 1:
            p = pr[x]
            c = 0
            while x % p == 0:
                x //= p
                c += 1

            l = len(res)
            for _ in range(c * l):
                res.append(res[-l] * p)

        return res

    outs = []

    for _ in range(q):
        query = LII()

        if query[0] == 1:
            idx = query[1] - 1
            val = query[2]

            for x in factors(cnt[nums[idx]]):
                ans[x] -= 1

            cnt[nums[idx]] -= 1

            for x in factors(cnt[nums[idx]]):
                ans[x] += 1

            nums[idx] = val

            for x in factors(cnt[nums[idx]]):
                ans[x] -= 1

            cnt[nums[idx]] += 1

            for x in factors(cnt[nums[idx]]):
                ans[x] += 1

        else:
            outs.append(ans[query[1]])

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, q;
	cin >> n >> q;

	vector<int> pr(n + 1);
	iota(pr.begin(), pr.end(), 0);

	for (int i = 2; i <= n; i ++) {
		if (pr[i] == i) {
			for (int j = i; j <= n; j += i) {
				pr[j] = i;
			}
		}
	}

	int M = 1e6 + 5;
	vector<int> nums(n), cnt(M, 0), ans(M, 0);
	for (auto &x: nums) cin >> x, cnt[x] ++;

	for (auto &v: cnt) ans[v] ++;

	for (int i = 1; i <= n; i ++) {
		for (int j = i * 2; j <= n; j += i) {
			ans[i] += ans[j];
		}
	}

	auto factors = [&] (int x) -> vector<int> {
		if (!x) return vector<int>();

		vector<int> res = {1};

		while (x > 1) {
			int p = pr[x], c = 0;
			while (x % p == 0)
				x /= p, c ++;

			int l = res.size();
			for (int i = 0; i < c * l; i ++)
				res.emplace_back(res.end()[-l] * p);
		}

		return res;
	};

	while (q --) {
		int t;
		cin >> t;

		if (t == 1) {
			int idx, val;
			cin >> idx >> val, idx --;

			for (auto &x: factors(cnt[nums[idx]])) ans[x] --;
			cnt[nums[idx]] --;
			for (auto &x: factors(cnt[nums[idx]])) ans[x] ++;

			nums[idx] = val;

			for (auto &x: factors(cnt[nums[idx]])) ans[x] --;
			cnt[nums[idx]] ++;
			for (auto &x: factors(cnt[nums[idx]])) ans[x] ++;
		}
		else {
			int x;
			cin >> x;
			cout << ans[x] << '\n';
		}
	}

	return 0;
}
```

**提示 1：** 数字要满足什么条件？

**提示 2：** 如何找？

首先，这个博弈过于简单了，就是要求每个数位的异或和为 $0$ 。

而如果数位的数量大于等于 $3$ ，那么 $B^2\leq N\leq 10^{12}$ ，所以 $B\leq 10^6$ ，可以直接枚举判断。

否则，数位如果恰好为 $1$ ，则要求两个数位完全一致，不妨设为 $x$ ，则 $x\times B+x=x\times (B+1)$ ，而 $x\leq B-1$ ，所以我们只需将 $n$ 拆分为两个数的乘积，且这两个数差至少为 $2$ ，其一分配给 $x$ ，其二分配给 $B+1$ 即可。这一部分是可以枚举 $x$ 的，因为 $x$ 也不可能超过 $10^6$ 。

时间复杂度为 $\mathcal{O}(\sqrt{X\log X})$ ，如果你选择合适的分块位置。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    x = II()
    ans = 0

    for i in range(2, 10 ** 6 + 5):
        cnt = 0
        xor_val = 0
        cur = x

        while cur:
            cnt += 1
            xor_val ^= cur % i
            cur //= i

        if cnt <= 2: break

        if xor_val == 0:
            ans += 1

    for i in range(1, 10 ** 6 + 5):
        if i * (i + 2) > x: break
        if x % i == 0:
            ans += 1

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	long long n;
	cin >> n;

	int ans = 0;

	for (int i = 2; i <= 1'000'000; i ++) {
		int xor_val = 0, cnt = 0;
		long long cur = n;

		while (cur) {
			xor_val ^= cur % i;
			cnt ++;
			cur /= i;
		}

		if (cnt <= 2) break;
		if (xor_val == 0) ans ++;
	}

	for (int i = 1; i <= 1'000'000; i ++) {
		if (1ll * i * (i + 2) > n) break;
		if (n % i == 0) ans ++;
	}

	cout << ans;

	return 0;
}
```

**提示 1：** 第一个元素一定不同。不如先确定其中一个，另一个怎么选？

首先，每个元素两两不同，所以相当于字典序的比较只需比较第一个元素。

于是，考虑枚举第二个序列的第一个元素 $x$ ，这个元素的交换次数也就此确定。接下来，第一个序列的第一个元素的所有选择就是所有小于 $x$ 的元素，我们只需找这些元素的最小下标，将对应元素操作到开头即可。

而这对应于关于元素升序排序后的一个前缀，我们取排序后的前缀原下标最小值即可。这里值域很小，不需要真的排序，开数组记录元素下标即可。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    for _ in range(t):
        n, ca, cb = MII()
        v1 = LII()
        v2 = LII()

        p1 = [0] * n
        p2 = [0] * n

        for i in range(n):
            p1[(v1[i] - 1) // 2] = i
            p2[(v2[i] - 1) // 2] = i

        ans = 10 ** 18
        cur = n

        for i in range(n):
            cur = fmin(cur, p1[i])
            ans = fmin(ans, cur * ca + p2[i] * cb)

        outs.append(ans)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

