**提示 1：** 不考虑复杂度，你应该怎么维护？

**提示 2：** 如何利用 $K$ 对距离的要求没那么紧？

如果我们不在意复杂度，我们可以维护每个点往子树里的各个点的距离。然后从上面来的路径可以用换根 DP 来做。这样我们就得到任意两个点之间的距离了，最后再在所有结果上二分即可。

而这里直接这么做复杂度是 $\mathcal{O}(n^2)$ 的，怎么办呢？

实际上我们不需要所有的距离，因为我们给的范围 $[K,2K]$ 还是比较宽松的。

所以我们只需维护一些区间。如果有三个数满足 $x\lt y\lt z$ 且 $y\leq 2x, z\leq 2y$ ，我们就可以用 $[x,z]$ 来替代这三个数，因为中间的数都凑得出来。

而我们最多需要维护多少个区间呢？对于某个区间的右端点 $V$ ，下一个区间左端点至少得是 $2V+1$ ，因此最多 $\mathcal{O}(\log M)$ 次，区间左端点就要超过最大值域了。

因此只需维护少量的区间。

这个信息可合并吗？也就是各个子树的结果可以放到一起去吗？答案是肯定的。直接双指针即可归并，最后再缩减成满足上述条件的区间组。

这个换根 DP 的时候就需要用到其他子树的区间合并的结果。相当于一个区间组序列的去掉一个的合并结果，可以用前后缀分解解决。

时间复杂度为 $\mathcal{O}(n\log M)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    def simplify(tmp):
        ans = []

        for l, r in tmp:
            if len(ans) == 0:
                ans.append((l, r))
            else:
                if ans[-1][1] * 2 >= l:
                    vl, vr = ans.pop()
                    ans.append((fmin(l, vl), fmax(r, vr)))
                else:
                    ans.append((l, r))

        return ans

    def merge(intervals1, intervals2):
        tmp = []
        p1, p2 = 0, 0

        while p1 < len(intervals1) and p2 < len(intervals2):
            if intervals1[p1] < intervals2[p2]:
                tmp.append(intervals1[p1])
                p1 += 1
            else:
                tmp.append(intervals2[p2])
                p2 += 1

        while p1 < len(intervals1):
            tmp.append(intervals1[p1])
            p1 += 1

        while p2 < len(intervals2):
            tmp.append(intervals2[p2])
            p2 += 1

        return simplify(tmp)

    t = II()
    outs = []

    for _ in range(t):
        n, q = MII()
        path = [[] for _ in range(n)]

        for _ in range(n - 1):
            u, v, w = MII()
            u -= 1
            v -= 1
            path[u].append(w * n + v)
            path[v].append(w * n + u)

        parent = [-1] * n
        que = [0]

        for u in que:
            for msk in path[u]:
                v = msk % n
                if parent[u] != v:
                    parent[v] = u
                    que.append(v)

        dp = [[(0, 0)] for _ in range(n)]

        for u in reversed(que):
            for msk in path[u]:
                w, v = divmod(msk, n)
                if parent[v] == u:
                    dp[u] = merge(dp[u], [(l + w, r + w) for l, r in dp[v]])

        rev_dp = [[] for _ in range(n)]

        for u in que:
            pre = [[]]
            for msk in path[u]:
                w, v = divmod(msk, n)
                if parent[v] == u:
                    pre.append(merge(pre[-1], [(l + w, r + w) for l, r in dp[v]]))

            suf = [[]]
            for msk in reversed(path[u]):
                w, v = divmod(msk, n)
                if parent[v] == u:
                    suf.append(merge(suf[-1], [(l + w, r + w) for l, r in dp[v]]))

            pre.reverse()
            suf.pop()

            for msk in path[u]:
                w, v = divmod(msk, n)
                if parent[v] == u:
                    rev_dp[v] = merge([(l + w, r + w) for l, r in rev_dp[u]], [(l + w, r + w) for l, r in merge(suf.pop(), pre.pop())])

        total_merge = []
        while dp: total_merge = merge(total_merge, dp.pop())
        while rev_dp: total_merge = merge(total_merge, rev_dp.pop())

        ans = []

        for _ in range(q):
            val = II()
            flg = False

            for l, r in total_merge:
                if (l + 1) // 2 <= val <= r:
                    flg = True

            ans.append(1 if flg else 0)

        outs.append(''.join(map(str, ans)))

    print('\n'.join(outs))
```

C++ 做法如下——

```cpp []
vector<pair<long long, long long>> simplify(vector<pair<long long, long long>> &tmp) {
	vector<pair<long long, long long>> ans;

	for (auto &[l, r]: tmp) {
		if (ans.empty()) ans.emplace_back(l, r);
		else {
			if (ans.back().second * 2 >= l) {
				auto [vl, vr] = ans.back(); ans.pop_back();
				ans.emplace_back(min(l, vl), max(r, vr));
			}
			else ans.emplace_back(l, r);
		}
	}

	return ans;
}

vector<pair<long long, long long>> merge(vector<pair<long long, long long>> intervals1, vector<pair<long long, long long>> intervals2) {
	vector<pair<long long, long long>> tmp;
	int p1 = 0, p2 = 0;

	while (p1 < intervals1.size() && p2 < intervals2.size()) {
		if (intervals1[p1] < intervals2[p2])
			tmp.emplace_back(intervals1[p1 ++]);
		else
			tmp.emplace_back(intervals2[p2 ++]);
	}

	while (p1 < intervals1.size())
		tmp.emplace_back(intervals1[p1 ++]);

	while (p2 < intervals2.size())
		tmp.emplace_back(intervals2[p2 ++]);

	return simplify(tmp);
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int n, q;
		cin >> n >> q;

		vector<vector<pair<int, long long>>> path(n);

		for (int i = 0; i < n - 1; i ++) {
			int u, v;
			long long w;
			cin >> u >> v >> w;
			u --, v --;
			path[u].emplace_back(v, w);
			path[v].emplace_back(u, w);
		}

		vector<vector<pair<long long, long long>>> dp(n);

		auto dfs1 = [&] (auto &self, int u, int p) -> void {
			dp[u].emplace_back(0, 0);

			for (auto &[v, w]: path[u]) {
				if (v != p) {
					self(self, v, u);
					vector<pair<long long, long long>> tmp;
					for (auto &[l, r]: dp[v])
						tmp.emplace_back(l + w, r + w);
					dp[u] = merge(dp[u], tmp);
				}
			}
		};

		dfs1(dfs1, 0, -1);

		vector<vector<pair<long long, long long>>> rev_dp(n);

		auto dfs2 = [&] (auto &self, int u, int p) -> void {
			vector<vector<pair<long long, long long>>> pre; 
			vector<vector<pair<long long, long long>>> suf;
			pre.emplace_back(vector<pair<long long, long long>>());
			suf.emplace_back(vector<pair<long long, long long>>());

			for (auto &[v, w]: path[u]) {
				if (v != p) {
					vector<pair<long long, long long>> tmp;
					for (auto &[l, r]: dp[v])
						tmp.emplace_back(l + w, r + w);
					pre.emplace_back(merge(pre.back(), tmp));
				}
			}

			reverse(path[u].begin(), path[u].end());

			for (auto &[v, w]: path[u]) {
				if (v != p) {
					vector<pair<long long, long long>> tmp;
					for (auto &[l, r]: dp[v])
						tmp.emplace_back(l + w, r + w);
					suf.emplace_back(merge(suf.back(), tmp));
				}
			}

			reverse(pre.begin(), pre.end());
			suf.pop_back();

			reverse(path[u].begin(), path[u].end());

			for (auto &[v, w]: path[u]) {
				if (v != p) {
					auto res = merge(suf.back(), pre.back());
					suf.pop_back(); pre.pop_back();
					vector<pair<long long, long long>> x1, x2;
					for (auto &[l, r]: rev_dp[u]) x1.emplace_back(l + w, r + w);
					for (auto &[l, r]: res) x2.emplace_back(l + w, r + w);
					rev_dp[v] = merge(x1, x2);
					self(self, v, u);
				}
			}
		};

		dfs2(dfs2, 0, -1);

		vector<pair<long long, long long>> ans;
		for (auto &x: dp) ans = merge(ans, x);
		for (auto &x: rev_dp) ans = merge(ans, x);

		while (q --) {
			long long val;
			cin >> val;

			bool flg = false;
			for (auto &[l, r]: ans) {
				if (val >= (l + 1) / 2 && val <= r) {
					flg = true;
				}
			}

			cout << flg;
		}
		cout << '\n';
	}

	return 0;
}
```

**提示 1：** 进位以下的部分肯定都得调整。

**提示 2：** 最小的调整成本？

首先，如果从低到高的第 $i$ 位发生了进位，则至少第 $i$ 位得调整。

而从 $(x,y)$ 开始调整，如果 $x$ 是增加的那个，则最小要增加到 $10$ 。而增加到 $10$ 并不会导致更高位的进位。

所以我们就直接求 $10^i$ 减去两个数字的最低的 $i$ 位，最后取结果的最小值即可。

当然你可能得特判下 $0$ 之类的情况。都是经典的高精度的模拟的问题。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    x = [int(c) for c in I()]
    y = [int(c) for c in I()]

    x.reverse()
    y.reverse()

    while len(x) < len(y): x.append(0)
    while len(y) < len(x): y.append(0)

    x.append(0)
    y.append(0)

    x.reverse()
    y.reverse()

    k = len(x)

    total = [0] * k
    chosen = k

    for i in range(k - 1, 0, -1):
        if x[i] + y[i] + total[i] >= 10:
            chosen = i

        total[i] += x[i] + y[i]
        total[i - 1] += total[i] // 10
        total[i] %= 10

    x = x[chosen:]
    y = y[chosen:]

    tmp = max(x, y)

    k = len(tmp)

    ans = []

    for i in range(k):
        if i < k - 1: ans.append(9 - tmp[i])
        else: ans.append(10 - tmp[i])

    if ans and ans[-1] == 10:
        ans[-1] = 0
        ans[-2] += 1

    ans.reverse()
    while ans and ans[-1] == 0:
        ans.pop()
    ans.reverse()

    if ans: print(''.join(map(str, ans)))
    else: print(0)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	string s1, s2;
	cin >> s1 >> s2;

	vector<int> v1, v2;
	for (auto &c: s1) v1.emplace_back(c - '0');
	for (auto &c: s2) v2.emplace_back(c - '0');

	reverse(v1.begin(), v1.end());
	reverse(v2.begin(), v2.end());

	while (v1.size() < v2.size()) v1.emplace_back(0);
	while (v2.size() < v1.size()) v2.emplace_back(0);

	v1.emplace_back(0);
	v2.emplace_back(0);

	int k = v1.size();

	vector<int> total(k, 0);
	int chosen = -1;

	for (int i = 0; i < k - 1; i ++) {
		if (v1[i] + v2[i] + total[i] >= 10) chosen = i;

		total[i] += v1[i] + v2[i];
		total[i + 1] += total[i] / 10;
		total[i] %= 10;
	}

	while (v1.size() > chosen + 1) v1.pop_back();
	while (v2.size() > chosen + 1) v2.pop_back();

	reverse(v1.begin(), v1.end());
	reverse(v2.begin(), v2.end());

	auto res = max(v1, v2);

	vector<int> ans;

	for (int i = 0; i < res.size(); i ++) {
		if (i + 1 < res.size()) ans.emplace_back(9 - res[i]);
		else ans.emplace_back(10 - res[i]);
	}

	if (ans.size() && ans.back() == 10) {
		ans.back() = 0;
		ans.end()[-2] ++;
	}

	reverse(ans.begin(), ans.end());
	while (!ans.empty() && ans.back() == 0) ans.pop_back();
	reverse(ans.begin(), ans.end());

	if (ans.empty()) cout << 0;
	else for (auto &x: ans) cout << x;

	return 0;
}
