**提示 1：** 哪个矩形最好找？

**提示 2：** 一层一层剥开来。

最外侧的矩形是最容易确定的。于是不断剥开最外侧的矩形，最后剩下的四个点就是最开始的矩形了。

怎么找到最外侧的四个点呢？分别取最靠右侧，最靠左侧，最靠上侧，最靠下侧的四个点即可。如果斜着的话，这四个点唯一确定，否则你要么特判一下，要么对同一条横线 / 竖线上的点给个排序关系。

如何在删点的过程中还能维护上述关系呢？

一种方式是直接使用有序集合 set 之类的。

另一种方式是，你直接一开始关于四个关键字排序，然后删除的过程中只需用指针的移动寻找下一个还没删除的点。

最后剩下四个点求面积，可以任取三点算三角形面积再乘以 $2$ ，而这件事可以用叉乘。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    xs = []
    ys = []

    for _ in range(n):
        x, y = MII()
        xs.append(x)
        ys.append(y)

    o1 = sorted(range(n), key=lambda x: (xs[x], ys[x]))
    o2 = sorted(range(n), key=lambda x: (ys[x], -xs[x]))
    o3 = sorted(range(n), key=lambda x: (-xs[x], -ys[x]))
    o4 = sorted(range(n), key=lambda x: (-ys[x], xs[x]))

    p1 = 0
    p2 = 0
    p3 = 0
    p4 = 0

    vis = [0] * n

    for _ in range(n // 4 - 1):
        while vis[o1[p1]]: p1 += 1
        vis[o1[p1]] = 1

        while vis[o2[p2]]: p2 += 1
        vis[o2[p2]] = 1

        while vis[o3[p3]]: p3 += 1
        vis[o3[p3]] = 1

        while vis[o4[p4]]: p4 += 1
        vis[o4[p4]] = 1

    pts = []

    for i in range(n):
        if not vis[i]:
            pts.append((xs[i], ys[i]))

    x1, y1 = pts[0]
    x2, y2 = pts[1]
    x3, y3 = pts[2]

    dx1, dy1 = x2 - x1, y2 - y1
    dx2, dy2 = x3 - x1, y3 - y1

    print(abs(dx1 * dy2 - dy1 * dx2))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	vector<pair<int, int>> pts(n);
	for (auto &[x, y]: pts) cin >> x >> y;

	vector<int> o1(n), o2(n), o3(n), o4(n);

	iota(o1.begin(), o1.end(), 0);
	iota(o2.begin(), o2.end(), 0);
	iota(o3.begin(), o3.end(), 0);
	iota(o4.begin(), o4.end(), 0);

	sort(o1.begin(), o1.end(), [&] (int i, int j) {
		pair<int, int> pt1 = {pts[i].first, pts[i].second};
		pair<int, int> pt2 = {pts[j].first, pts[j].second};
		return pt1 < pt2;
	});

	sort(o2.begin(), o2.end(), [&] (int i, int j) {
		pair<int, int> pt1 = {pts[i].second, -pts[i].first};
		pair<int, int> pt2 = {pts[j].second, -pts[j].first};
		return pt1 < pt2;
	});

	sort(o3.begin(), o3.end(), [&] (int i, int j) {
		pair<int, int> pt1 = {-pts[i].first, -pts[i].second};
		pair<int, int> pt2 = {-pts[j].first, -pts[j].second};
		return pt1 < pt2;
	});

	sort(o4.begin(), o4.end(), [&] (int i, int j) {
		pair<int, int> pt1 = {-pts[i].second, pts[i].first};
		pair<int, int> pt2 = {-pts[j].second, pts[j].first};
		return pt1 < pt2;
	});

	vector<int> vis(n, 0);
	int p1 = 0, p2 = 0, p3 = 0, p4 = 0;

	for (int i = 0; i < n / 4 - 1; i ++) {
		while (vis[o1[p1]]) p1 ++; vis[o1[p1]] = 1;
		while (vis[o2[p2]]) p2 ++; vis[o2[p2]] = 1;
		while (vis[o3[p3]]) p3 ++; vis[o3[p3]] = 1;
		while (vis[o4[p4]]) p4 ++; vis[o4[p4]] = 1;
	}

	vector<pair<int, int>> chosen;

	for (int i = 0; i < n; i ++) {
		if (!vis[i]) {
			chosen.emplace_back(pts[i]);
		}
	}

	auto [x1, y1] = chosen[0];
	auto [x2, y2] = chosen[1];
	auto [x3, y3] = chosen[2];

	int dx1 = x2 - x1, dy1 = y2 - y1;
	int dx2 = x3 - x1, dy2 = y3 - y1;

	cout << abs(1ll * dx1 * dy2 - 1ll * dy1 * dx2);

	return 0;
}
```

**提示 1：** 找到一个关键特征。各个操作如何改变特征？

**提示 2：** 一个经典博弈问题。

操作实在太多了，得想办法减少一些需要考虑的东西。

如果你考虑整体的逆序对，你会发现第一个操作让逆序对减少 $1$ ，后面的操作让逆序对减少 $2$ 。

而一旦逆序对至少有一个，则总能进行第一个操作；一旦逆序对至少有两个，则总能进行第二个操作（可以想下，不可能构造一个不包含第二类子串的至少有两个逆序对的序列）。

所以操作实际上就只是针对逆序对数量操作。而每次操作可以选择减去 $1$ 或者 $2$ ，看谁做最后一次操作。

这就是极其经典的博弈论问题了。在 $3$ 的倍数的情况下，先手选 $x$ 后手就选 $3-x$ ，后手总是必胜；否则，先手总能一次操作达到 $3$ 的倍数，操作后变成后手，于是也必胜了。

于是，只需统计逆序对关于 $3$ 取模的余数即可。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    s = [int(c) for c in I()]
    c1 = 0
    rev = 0

    for x in s:
        if x: c1 = (c1 + 1) % 3
        else: rev = (rev + c1) % 3

    print('Alice' if rev else 'Bob')
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	string s;
	cin >> s;

	int c1 = 0, rev = 0;

	for (auto &c: s) {
		if (c == '1') c1 = (c1 + 1) % 3;
		else rev = (rev + c1) % 3;
	}

	cout << (rev ? "Alice" : "Bob");

	return 0;
}
```

**提示 1：** $1,2$ 随意放，剩余的元素排布有啥要求？

**提示 2：** 如何解决这部分的？

先把问题看成一个环，环上相邻两点满足取模后不超过 $2$ 。

对于序列中大于 $2$ 的元素，其后面的元素只能比它小，不然取模就是它自己了，就矛盾了。

所以如果用 $1,2$ 把整个环分成两段，每一段都是一个递减序列。

所以我们相当于要构造两个递减序列，总共用的元素是 $3,\dots,n$ ，满足前一项关于后一项取模不超过 $2$ 。

把这个序列反过来，然后把相邻的数字看成一段，则段内一定满足要求。而两个段之间的相邻元素 $x,y$ 才是非常需要关心的问题。

因此一段段 DP ，也就是把 $3,4,\dots, n$ 的元素切分成一段一段的，再把相邻的段放到不同的序列中，就是整体拆序列的方案数了。

假设我们现在某一段分段的结尾时是 $i$ （这里令 $i\lt n$ 且 $i+1$ 所在的段跟前面的不产生矛盾），对应方案数有 $dp[i]$ 种，有哪些状态转移呢？

首先，可以让下一段直接走到 $n$ ，一定满足要求。

否则，假设走到了 $j$ ，则 $j+1$ 是跟这个 $i$ 被分到同一个序列的，因此有 $(j+1)\bmod i\leq 2$ 。我们枚举 $ki+b$ ( $b\leq 2$ ) 即可。

对于不同的 $i$ ，枚举的数量是 $\mathcal{O}(n/i)$ 量级的，因此求和后是个 “调和级数” 的复杂度，为 $\mathcal{O}(n\log n)$ 。

段落分完后，可以分别选择放到 $1$ 和 $2$ 后，因此这里方案数得乘 $2$ 。而 $1$ 的位置任选，因此还需要将答案乘 $n$ 。

注意 $n\lt 3$ 的时候上述讨论并不成立，需要特判。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    mod = 10 ** 9 + 7

    if n < 3:
        print(n)
    else:
        dp = [1] * (n + 1)

        for i in range(3, n):
            dp[n] += dp[i]
            dp[n] %= mod

            for j in range(2 * i - 1, n, i):
                dp[j] += dp[i]
                dp[j] %= mod

            for j in range(2 * i, n, i):
                dp[j] += dp[i]
                dp[j] %= mod

            for j in range(i + 1, n, i):
                dp[j] += dp[i]
                dp[j] %= mod

        print(dp[n] * 2 * n % mod)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, mod = 1e9 + 7;
	cin >> n;

	if (n < 3) cout << n;
	else {
		vector<int> dp(n + 1, 1);

		for (int i = 3; i < n; i ++) {
			dp[n] = (dp[n] + dp[i]) % mod;
			for (int j = 2 * i - 1; j < n; j += i)
				dp[j] = (dp[j] + dp[i]) % mod;
			for (int j = 2 * i; j < n; j += i)
				dp[j] = (dp[j] + dp[i]) % mod;
			for (int j = i + 1; j < n; j += i)
				dp[j] = (dp[j] + dp[i]) % mod;
		}

		cout << 2ll * n * dp[n] % mod;
	}

	return 0;
}
```

**提示 1：** 如何用前缀和来算一个子段的取模结果呢？

判断一个子数组是否满足要求有啥快速的方法吗？

我们可以维护前缀 $v_1$ 和以及平方的前缀和 $v_2$ 。则 $(v_1[r+1]-v_1[l])^2-(v_2[r+1]-v_2[l])$ 就是要求的东西的两倍。要判断它是否是 $3$ 的倍数，只需看这四个变量关于 $3$ 的取模的结果。

所以维护前缀中 $v_1[i]\bmod 3=x, v_2[i]\bmod 3=y$ 的个数记录在 $(x,y)$ 位置上。这样我们新遍历一个新的位置的时候，就枚举前面的位置的 $(x,y)$ ，如果满足条件，把对应 $(x,y)$ 的计数加入到答案中即可。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    nums = LII()

    ans = 0

    cnt = [[0] * 3 for _ in range(3)]
    cnt[0][0] = 1

    cur1 = 0
    cur2 = 0

    for x in nums:
        x %= 3
        cur1 = (cur1 + x) % 3
        cur2 = (cur2 + x * x) % 3

        for i in range(3):
            for j in range(3):
                v1 = (cur1 - i) % 3
                v2 = (cur2 - j) % 3

                if v1 * v1 % 3 == v2:
                    ans += cnt[i][j]

        cnt[cur1][cur2] += 1

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	vector<vector<int>> cnt(3, vector<int>(3, 0));
	long long ans = 0;
	int cur1 = 0, cur2 = 0;

	cnt[0][0] = 1;

	while (n --) {
		int x;
		cin >> x;

		x %= 3;
		cur1 = (cur1 + x) % 3;
		cur2 = (cur2 + x * x) % 3;

		for (int i = 0; i < 3; i ++) {
			for (int j = 0; j < 3; j ++) {
				int v1 = (cur1 - i) % 3;
				int v2 = (cur2 - j) % 3;

				if ((v1 * v1 - v2) % 3 == 0) ans += cnt[i][j];
			}
		}

		cnt[cur1][cur2] ++;
	}

	cout << ans;

	return 0;
}
```

**提示 1：** 如果我们知道从 $u$ 到 $v$ 走 $k$ 步最小的路径，怎么往后推？

**提示 2：** $k$ 很大，怎么办？

走的路很长，所以考虑倍增。

假设我们知道走 $2^i$ 步从 $u$ 到 $v$ 的最优路径（ $u,v$ 任意），怎么求 $2^{i+1}$ 的答案呢？

我们枚举中转点 $w$ ，从 $u$ 到 $w$ 选最优，从 $w$ 到 $v$ 选最优。

如何比较不同的 $w$ 的结果呢？我们就要给出任意一对 $(u,v)$ 走 $2^i$ 步的最优路径的大小关系比较（可以根据排名赋值一个 $1,2,\dots,n^2$ 中的数）。这样就可以比较选出最优的 $w$ 。同时 $2^{i+1}$ 步的各个 $(u,v)$ 间的路径也可以互相比较给出排名。

同时我们需要计算的是 $\sum w_{e_i} x^{k-i}$ ，于是我们也要维护这个权重。前半段路径的权重得乘以 $x^{后半段路径的长度}$ 再加上后半段路径的权重才是整段路径的权重。

上述信息可以倍增维护。

接下来考虑 $k$ 。也可以 $2^i$ 一步一步从 $0$ 步开始拼进来，因此问题解决。

几个细节是：算答案的过程中，初始情况是走 $0$ 步，所以只需标记这些位置，所有 $u\neq v$ 是走不到的；走不到的情况用特殊标记可以方便你求解。

时间复杂度为 $\mathcal{O}(n^3\log k)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    mod = 10 ** 9 + 7

    n, m, s, t, x, k = MII()
    s -= 1
    t -= 1

    inf = 10 ** 9

    def f(x, y):
        return x * n + y

    def merge_path(msk1, order1, msk2, order2, len2):
        pw = pow(x, len2, mod)

        msk = [-1] * (n * n)
        notes = [(inf, inf) for _ in range(n * n)]

        for u in range(n):
            for v in range(n):
                for w in range(n):
                    if msk1[f(u, v)] == -1 or msk2[f(v, w)] == -1:
                        continue

                    new_path = (order1[f(u, v)], order2[f(v, w)])
                    if new_path < notes[f(u, w)]:
                        notes[f(u, w)] = new_path
                        msk[f(u, w)] = (msk1[f(u, v)] * pw + msk2[f(v, w)]) % mod

        st_range = sorted(range(n * n), key=lambda x: notes[x])
        order = [0] * (n * n)

        for i in range(1, n * n):
            if notes[st_range[i]] == notes[st_range[i - 1]]:
                order[st_range[i]] = order[st_range[i - 1]]
            else:
                order[st_range[i]] = order[st_range[i - 1]] + 1

        return msk, order

    msk = [-1] * (n * n)
    order = [0] * (n * n)

    msk[f(s, s)] = 0

    tmp_msk = [-1] * (n * n)
    tmp_order = [0] * (n * n)

    edges = []

    for _ in range(m):
        u, v, w = MII()
        u -= 1
        v -= 1
        edges.append((u, v, w))

    edges.sort(key=lambda x: x[2])

    for u, v, w in edges:
        tmp_msk[f(u, v)] = w

    for i in range(1, m):
        u1, v1, w1 = edges[i - 1]
        u2, v2, w2 = edges[i]

        if w1 < w2:
            tmp_order[f(u2, v2)] = tmp_order[f(u1, v1)] + 1
        else:
            tmp_order[f(u2, v2)] = tmp_order[f(u1, v1)]

    for i in range(30):
        if k >> i & 1:
            msk, order = merge_path(msk, order, tmp_msk, tmp_order, 1 << i)
        tmp_msk, tmp_order = merge_path(tmp_msk, tmp_order, tmp_msk, tmp_order, 1 << i)

    print(msk[f(s, t)])
```

C++ 做法如下——

```cpp []
typedef pair<vector<int>, vector<int>> node;

node init(int x) {
	node ans;
	ans.first = vector<int>(x, -1);
	ans.second = vector<int>(x, 0);
	return ans;
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, m, s, t, x, k, mod = 1e9 + 7, inf = 1e9;
	cin >> n >> m >> s >> t >> x >> k;
	s --, t --;

	auto f = [&] (int x, int y) {return x * n + y;};

	auto merge_info = [&] (node info1, node info2, int pw) -> node {
		node ans = init(n * n);
		vector<pair<int, int>> notes(n * n, {inf, inf});

		auto &[msk1, order1] = info1;
		auto &[msk2, order2] = info2;

		for (int u = 0; u < n; u ++) {
			for (int v = 0; v < n; v ++) {
				for (int w = 0; w < n; w ++) {
					if (msk1[f(u, v)] == -1 || msk2[f(v, w)] == -1) continue;

					pair<int, int> new_path = {order1[f(u, v)], order2[f(v, w)]};
					if (new_path < notes[f(u, w)]) {
						notes[f(u, w)] = new_path;
						ans.first[f(u, w)] = (1ll * msk1[f(u, v)] * pw + msk2[f(v, w)]) % mod;
					}
				}
			}
		}

		vector<int> order(n * n);
		iota(order.begin(), order.end(), 0);
		sort(order.begin(), order.end(), [&] (int i, int j) {return notes[i] < notes[j];});

		for (int i = 1; i < n * n; i ++) {
			if (notes[order[i]] == notes[order[i - 1]])
				ans.second[order[i]] = ans.second[order[i - 1]];
			else
				ans.second[order[i]] = ans.second[order[i - 1]] + 1;
		}

		return ans;
	};

	node ans = init(n * n);
	ans.first[f(s, s)] = 0;

	node tmp = init(n * n);

	vector<array<int, 3>> edges(m);
	for (auto &[u, v, w]: edges) {
		cin >> u >> v >> w;
		u --, v --;
	}

	sort(edges.begin(), edges.end(), [&] (array<int, 3> x, array<int, 3> y) {return x[2] < y[2];});

	for (auto &[u, v, w]: edges) tmp.first[f(u, v)] = w;

	for (int i = 1; i < m; i ++) {
		auto [u1, v1, w1] = edges[i - 1];
		auto [u2, v2, w2] = edges[i];

		if (w1 < w2) tmp.second[f(u2, v2)] = tmp.second[f(u1, v1)] + 1;
		else tmp.second[f(u2, v2)] = tmp.second[f(u1, v1)];
	}

	int pw = x;
	for (int i = 0; i < 30; i ++) {
		if (k >> i & 1) ans = merge_info(ans, tmp, pw);
		tmp = merge_info(tmp, tmp, pw);
		pw = 1ll * pw * pw % mod;
	}

	cout << ans.first[f(s, t)];

	return 0;
}
```

**提示 1：** 考虑用数学归纳法证明可行。先凑 $n$ 。

我们相当于首尾元素依次相配，和为质数。

这个题直接考虑构造似乎不太行。考虑用归纳法证明可以构造。

首先 $n=1,2$ 显然可以构造。

而假设 $n\leq M$ 的情况可以构造。考虑 $n=M+1$ 。

此时，考虑跟 $n$ 配凑的元素 $i$ ，则 $n+1\leq n+i\leq 2n-1$ 。

对于任意正整数 $n$ ，这个范围内有至少一个质数（这个东西不是很好证明，但这个数据范围内你很容易确认）。所以考虑用这个质数 $p$ 。

则 $p-n,p-n+1,\dots,n$ 依次和 $n,n-1,\dots, p-n$ 相配。这样问题就转化为 $1\sim p-1$ 的范围内的配对问题了，也就是归纳假设的情况。因此可以用数学归纳法解决证明。

而真正的构造方案也可以从证明看出。先凑出大的 $n$ ，再将问题不断转化为小范围的问题。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    M = 10 ** 6 + 10
    isPrime = [1] * M
    isPrime[0] = 0
    isPrime[1] = 0

    for i in range(2, M):
        if isPrime[i]:
            for j in range(2 * i, M, i):
                isPrime[j] = 0

    t = II()
    outs = []

    for _ in range(t):
        n = II()

        ans = [0] * n
        l, r = 0, n - 1

        while n:
            for x in range(1, n + 1):
                if isPrime[n + x]:

                    for i in range(x, n + 1):
                        if i > n + x - i: break
                        ans[l] = i
                        ans[r] = n + x - i
                        l += 1
                        r -= 1

                    n = x - 1
                    break

        outs.append(' '.join(map(str, ans)))

    print('\n'.join(outs))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int M = 1e6 + 100;

	vector<int> isPrime(M, 1);
	isPrime[0] = 0, isPrime[1] = 0;

	for (int i = 2; i < M; i ++) {
		for (int j = i * 2; j < M; j += i) {
			isPrime[j] = 0;
		}
	}

	int t;
	cin >> t;

	while (t --) {
		int n;
		cin >> n;

		vector<int> ans(n);
		int l = 0, r = n - 1;

		while (n) {
			for (int x = 1; x <= n; x ++) {
				if (isPrime[n + x]) {

					for (int i = x; i <= n; i ++) {
						if (i > n + x - i) break;
						ans[l ++] = i;
						ans[r --] = n + x - i;
					}

					n = x - 1;
					break;
				}
			}
		}

		for (auto &v: ans) cout << v << ' '; cout << '\n';
	}

	return 0;
}
```

**提示 1：** $k\gt 2$ ？ $k=2$ ？

$k$ 大于 $2$ 时，集合中至少有 $3$ 个点，设为 $u,v,w$ ，则三者取二，形成 $3$ 条路径，有且仅有一个点被三条路径同时经过，而只有这个点为 $0$ 时可以取到最大的答案 $1$ 。因此这种情况下答案最大为 $1$ 。

而答案为正的情况最多能取多少个点呢？从 $0$ 开始延申的每个子树最多取一个点，再加上 $0$ 结点本身就是最多的点数了。 $k$ 更大的话答案就是 $0$ 了。

接下来考虑 $k=2$ 。也就是一条路径的 MEX 最大是多少。

为此，我们枚举 $0,1,2,\dots$ ，看当前枚举过的点是否在同一条路径上。

有很多办法，这里给出一种线性的。我们每次遇到一个新的点，不断往 $0$ 结点走，直到走到了走过的点。

如果存在路径，则我们标记过的店就是这条路径上的各个点。如何判定这是一条路径呢？直接查看这条路径上每个点跟多少个标记过的点相邻。如果这个数值的最大值大于 $2$ 则不是路径，否则是路径。而这个信息是可以在遍历的过程中更新的。

因为每条边最多走一遍，因此这个做法是线性的。其实相当于暴力走了一遍虚树上所有的边。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    for _ in range(t):
        n = II()
        path = [[] for _ in range(n)]

        for _ in range(n - 1):
            u, v = MII()
            path[u].append(v)
            path[v].append(u)

        parent = [-1] * n
        que = [0]

        for u in que:
            for v in path[u]:
                if parent[u] != v:
                    parent[v] = u
                    que.append(v)

        vis = [0] * n
        vis[0] = 1

        degs = [0] * n
        ans = 0
        flg = True

        for i in range(1, n):
            cur = i
            while not vis[cur]:
                vis[cur] = 1
                degs[cur] += 1
                degs[parent[cur]] += 1
                cur = parent[cur]
                if degs[cur] > 2:
                    flg = False
            if flg: ans = i

        out = [0] * (n - 1)
        out[0] = ans + 1

        for i in range(1, len(path[0])):
            out[i] = 1

        outs.append(' '.join(map(str, out)))

    print('\n'.join(outs))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int n;
		cin >> n;

		vector<vector<int>> path(n);
		for (int i = 0; i < n - 1; i ++) {
			int u, v;
			cin >> u >> v;
			path[u].emplace_back(v);
			path[v].emplace_back(u);
		}

		vector<int> parent(n);

		auto dfs = [&] (auto &self, int u, int p) -> void {
			parent[u] = p;

			for (auto &v: path[u]) {
				if (v != p) {
					self(self, v, u);
				}
			}
		};

		dfs(dfs, 0, -1);

		vector<int> vis(n, 0), degs(n, 0);
		vis[0] = 1;

		int ans = 0;
		bool flg = true;

		for (int i = 1; i < n; i ++) {
			int cur = i;
			while (!vis[cur]) {
				vis[cur] = 1;
				degs[cur] ++;
				degs[parent[cur]] ++;
				cur = parent[cur];
				if (degs[cur] > 2)
					flg = false;
			}
			if (flg) ans = i;
		}

		cout << ans + 1;
		for (int i = 2; i < n; i ++) cout << ' ' << (i <= path[0].size());
		cout << '\n';
	}

	return 0;
}
