**提示 1：** 走到每个位置有哪些不同的状态？如何让各种不同的状态能遍历的都遍历上。

先看提示 1。

实际上重要的状态是：当前所在位置，此前三次的颜色。

但是我们并不知道颜色，所以我们只能退而求其次，看此前三次选的边。本质上是此前三次选的方向，因此总共只有 $4^3$ 种不同的可能（当然你不能重复选同一条边，实际上是 $4\times 3^2$ ）。

而一个状态一旦遍历过就没必要遍历了。

这里怎么遍历呢？因为每一步都是看前一步的位置，所以用 DFS。每次走到一个状态，枚举下一步的方向，得到下一步的状态，通过查询判断往不往下搜索即可。记得存状态避免重复遍历。

时间复杂度为 $\mathcal{O}(nmd^4)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    sys.setrecursionlimit(300000)

    n, m = MII()
    grid = [[set() for _ in range(2 * m + 1)] for _ in range(2 * n + 1)]

    dirs = [(0, -1), (0, 1), (-1, 0), (1, 0)]
    dir_str = ['LEFT', 'RIGHT', 'UP', 'DOWN']

    cur = [-1, -1, -1]

    def move(idx):
        if idx < 4: print('MOVE', dir_str[idx], flush=True)
        else: print('BACK', flush=True)
        ret = I()
        if ret == 'EXIT': exit()
        if ret == 'FAIL': return False
        return True

    def f(x, y):
        for i in range(4):
            if cur[-1] ^ i == 1: continue

            cur.append(i)
            dx, dy = dirs[i]
            nx = x + dx
            ny = y + dy

            if tuple(cur[-3:]) not in grid[nx][ny] and move(i):
                grid[nx][ny].add(tuple(cur[-3:]))
                f(nx, ny)
                move(4)

            cur.pop()

    f(n, m)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, m;
	cin >> n >> m;

	vector<vector<set<array<int, 3>>>> grid(2 * n + 1, vector<set<array<int, 3>>>(2 * m + 1));

	vector<pair<int, int>> dirs = {{0, -1}, {0, 1}, {-1, 0}, {1, 0}};
	vector<string> dir_str = {"LEFT", "RIGHT", "UP", "DOWN"};
	vector<int> cur = {-1, -1, -1};

	auto move = [&] (int idx) -> bool {
		if (idx < 4) cout << "MOVE " << dir_str[idx] << endl;
		else cout << "BACK" << endl;

		string ret; cin >> ret;
		if (ret == "EXIT") exit(0);
		if (ret == "FAIL") return false;
		return true;
	};

	auto dfs = [&] (auto &self, int x, int y) -> void {
		for (int i = 0; i < 4; i ++) {
			if (cur.back() == (i ^ 1)) continue;

			cur.emplace_back(i);
			auto [dx, dy] = dirs[i];
			int nx = x + dx, ny = y + dy;
			array<int, 3> last_3 = {cur.end()[-3], cur.end()[-2], cur.end()[-1]};

			if (grid[nx][ny].find(last_3) == grid[nx][ny].end() && move(i)) {
				grid[nx][ny].insert(last_3);
				self(self, nx, ny);
				move(4);
			}

			cur.pop_back();
		}
	};

	dfs(dfs, n, m);

	return 0;
}
```

**提示 1：** 枚举 $\max b_{i_j}$ ，前面部分要最大化什么？

看提示。

枚举之后，我们相当于要在选取对应的 $a_{i_j}$ 的基础上，前面 $b_{i_j}$ 更小的元素，我们要选出 $k-1$ 个 $a_{i_j}$ 最大的。

所以可以将元素按照 $b$ 的数值排序，再枚举当前最大的 $b$ 数值，该数值对应的 $a$ 必须选取，而前缀部分选取 $k-1$ 个 $a$ 数值最大的元素。新增元素的过程中，需要维护前 $k-1$ 大，可以使用堆。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    bound = 10 ** 18

    for _ in range(t):
        n, k = MII()
        v1 = []
        v2 = []

        for _ in range(n):
            x, y = MII()
            v1.append(x)
            v2.append(y)

        st_range = sorted(range(n), key=lambda x: v2[x])

        ans = -bound

        cur = 0
        pq = []

        for i in st_range:
            if len(pq) == k - 1:
                ans = fmax(ans, cur + v1[i] - v2[i])

            cur += v1[i]
            heappush(pq, v1[i])

            if len(pq) == k:
                cur -= heappop(pq)

        outs.append(ans)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int n, k;
		cin >> n >> k;

		vector<pair<int, long long>> vals(n);
		for (auto &[a, b]: vals) cin >> a >> b;

		sort(vals.begin(), vals.end(), [&] (pair<int, long long> &x, pair<int, long long> &y) {return x.second < y.second;});

		long long cur = 0, ans = -1e18;
		priority_queue<int, vector<int>, greater<int>> pq;

		for (auto &[x, y]: vals) {
			if (pq.size() == k - 1) {
				ans = max(ans, cur + x - y);
			}

			cur += x;
			pq.push(x);

			if (pq.size() == k) {
				cur -= pq.top();
				pq.pop();
			}
		}

		cout << ans << '\n';
	}

	return 0;
}
```

**提示 1：** 走一条路径的时候如何分解为各个段的权？

**提示 2：** 什么情况是值得合并的。

考虑一段路径的权值从头到尾是 $[w_1,w_2,\dots,w_n]$ 则总权值是 $nw_1+(n-1)w_2+\dots+w_n$ 。

我们没必要走一个结点两次，所以路径长度最多为 $n-1$ 。

我们要考虑从 $1$ 到 $i$ 的路径。但第一条边的权重不好确定，因为不知道要走几步。但最后一条边的权重是 $1$ 。

所以我们只有知道是倒数第几条边，才能知道答案。

所以不妨设当前要走倒数第 $i$ 条边且在第 $u$ 个结点，这样枚举 $u$ 走的边 $(v,w)$ ，就可以走到状态 $(i-1,v)$ ，且权值加上 $i\times w$ 。

因为开头只能在 $0$ 位置，而接下来走几条边都可以，取最优情况即可，所以初值是所有 $(i,0)$ 的位置标记为 $0$ 。而最后我们要走到剩余 $0$ 条边的情况，因此输出 $(0,1),(0,2),\dots,(0, n)$ 位置的数值即可。

时间复杂度为 $\mathcal{O}(n(n+m))$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    inf = 10 ** 9

    for _ in range(t):
        n, m = MII()
        path = [[] for _ in range(n)]

        for _ in range(m):
            u, v, w = MII()
            path[u].append(w * n + v)

        dp = [[inf] * n for _ in range(n)]

        for i in range(n): dp[i][0] = 0

        for i in range(n - 1, 0, -1):
            for j in range(n):
                for msk in path[j]:
                    w, nj = divmod(msk, n)
                    dp[i - 1][nj] = fmin(dp[i - 1][nj], dp[i][j] + i * w)

        outs.append(' '.join(map(str, (x if x < inf else -1 for x in dp[0][1:]))))

    print('\n'.join(outs))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t, inf = 1e9;
	cin >> t;

	while (t --) {
		int n, m;
		cin >> n >> m;

		vector<vector<pair<int, int>>> path(n);

		while (m --) {
			int u, v, w;
			cin >> u >> v >> w;
			path[u].emplace_back(v, w);
		}

		vector<vector<int>> dis(n, vector<int>(n, inf));

		for (int i = 0; i < n; i ++) dis[i][0] = 0;

		for (int i = n - 1; i > 0; i --) {
			for (int u = 0; u < n; u ++) {
				for (auto &[v, w]: path[u]) {
					dis[i - 1][v] = min(dis[i - 1][v], dis[i][u] + i * w);
				}
			}
		}

		for (int i = 1; i < n; i ++) {
			cout << (dis[0][i] < inf ? dis[0][i] : -1) << " \n"[i == n - 1];
		}
	}

	return 0;
}
```

**提示 1：** 到每次检查的时候有什么状态？

到每次检查时，前面分配了 $x$ 次点数，所以我们只要知道有 $y$ 的力量值，则智力值一定是 $x-y$ 。所以维护的时候只需要维护其一即可。考虑到第 $i$ 个位置，力量值为 $y$ 时的最大通过检查次数为 $dp[i][y]$ 。

每次新来一个分配点数时，只需枚举这个点数是分配给哪一个进行暴力状态转移即可。

而如果是检查点，则会给一个区间进行答案的 $+1$ 操作，这很容易差分维护，等到下次新增分配点数 / 最后获取答案时再更新即可。

时间复杂度为 $\mathcal{O}(n+m^2)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m = MII()
    nums = LII()

    cur = 0
    dp = [0]
    diff = [0] * 2

    def update():
        global cur
        cur += 1

        for i in range(cur):
            diff[i + 1] += diff[i]

        for i in range(cur):
            dp[i] += diff[i]
            diff[i] = 0

    for x in nums:
        if x == 0:
            update()

            dp.append(0)
            diff.append(0)

            for i in range(cur, 0, -1):
                dp[i] = fmax(dp[i], dp[i - 1])

        elif x > 0:
            if x <= cur:
                diff[x] += 1
                diff[cur + 1] -= 1

        else:
            if -x <= cur:
                diff[0] += 1
                diff[cur + x + 1] -= 1

    update()
    print(max(dp))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, m;
	cin >> n >> m;

	vector<int> dp = {0}, diff = {0, 0};
	int cur = 0;

	auto update = [&] () -> void {
		cur ++;
		for (int i = 0; i < cur; i ++)
			diff[i + 1] += diff[i];
		for (int i = 0; i < cur; i ++)
			dp[i] += diff[i], diff[i] = 0;
	};

	while (n --) {
		int x;
		cin >> x;

		if (x == 0) {
			update();
			dp.emplace_back(0);
			diff.emplace_back(0);
			for (int i = cur; i > 0; i --)
				dp[i] = max(dp[i], dp[i - 1]);
		}
		else if (x > 0) {
			if (x <= cur) {
				diff[x] ++;
				diff[cur + 1] --;
			}
		}
		else {
			if (-x <= cur) {
				diff[0] ++;
				diff[cur + x + 1] --;
			}
		}
	}

	update();
	cout << *max_element(dp.begin(), dp.end());

	return 0;
}
```

**提示 1：** 前缀和后缀是不变的。所以大量数值不变，考虑中间如何调整。

先看提示。

我们先看完全不操作的情况下的答案。这个直接维护到当前位置为止的最后一个字符及其出现次数就够了。

在交换的时候，我们会断开两段，再重新拼接两段。所以我们减去断开两段带来的成本，加上拼接两段带来的收益即可。

这个成本和收益仅仅取决于是否等于拼接 / 拆开的元素是否相同，以及这一段的长度。所以我们可以预处理顺序到某个位置的连续相同元素个数，以及逆序回来到某个位置的连续相同元素个数。

如果把 $x+y$ 拆成 $x,y$ 两段，那么成本是 $(x+y)^2-x^2-y^2=2xy$ ；拼接也是类似的。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    s = [ord(c) - ord('a') for c in I()]

    pref_ch = [0] * (n + 1)
    pref_cnt = [0] * (n + 1)

    ch = 0
    cnt = 0
    cur = 0

    for i in range(n):
        if s[i] != ch:
            ch = s[i]
            cnt = 0

        cur += 2 * cnt + 1
        cnt += 1

        pref_ch[i + 1] = ch
        pref_cnt[i + 1] = cnt

    suff_ch = [0] * (n + 1)
    suff_cnt = [0] * (n + 1)

    ch = 0
    cnt = 0

    for i in range(n - 1, -1, -1):
        if s[i] != ch:
            ch = s[i]
            cnt = 0

        cnt += 1

        suff_ch[i] = ch
        suff_cnt[i] = cnt

    ans = 0

    for i in range(1, n):
        if s[i] != s[i - 1]:
            val = cur

            val -= (pref_cnt[i - 1] if s[i - 1] == pref_ch[i - 1] else 0) * 2
            val -= (suff_cnt[i + 1] if s[i] == suff_ch[i + 1] else 0) * 2

            val += (pref_cnt[i - 1] if s[i] == pref_ch[i - 1] else 0) * 2
            val += (suff_cnt[i + 1] if s[i - 1] == suff_ch[i + 1] else 0) * 2

            ans = fmax(ans, val)

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	string s;

	cin >> n >> s;

	vector<int> pref_ch(n + 1, 0);
	vector<int> pref_cnt(n + 1, 0);

	vector<int> suff_ch(n + 1, 0);
	vector<int> suff_cnt(n + 1, 0);

	int ch = 0, cnt = 0;
	long long cur = 0;

	for (int i = 0; i < n; i ++) {
		if (s[i] - 'a' != ch) ch = s[i] - 'a', cnt = 0;

		cur += 2 * cnt + 1;
		cnt ++;

		pref_ch[i + 1] = ch;
		pref_cnt[i + 1] = cnt;
	}

	ch = 0, cnt = 0;

	for (int i = n - 1; i >= 0; i --) {
		if (s[i] - 'a' != ch) ch = s[i] - 'a', cnt = 0;

		cnt ++;

		suff_ch[i] = ch;
		suff_cnt[i] = cnt;
	}

	long long ans = 0;

	for (int i = 1; i < n; i ++) {
		if (s[i] != s[i - 1]) {
			long long val = cur;

			val -= 2 * (s[i - 1] - 'a' == pref_ch[i - 1] ? pref_cnt[i - 1] : 0);
			val -= 2 * (s[i] - 'a' == suff_ch[i + 1] ? suff_cnt[i + 1] : 0);

			val += 2 * ((s[i] - 'a' == pref_ch[i - 1]) ? pref_cnt[i - 1] : 0);
			val += 2 * (s[i - 1] - 'a' == suff_ch[i + 1] ? suff_cnt[i + 1] : 0);

			ans = max(ans, val);
		}
	}

	cout << ans;

	return 0;
}
```

