int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t, mod = 998244353;
	cin >> t;

	while (t --) {
		int n, k;
		string s;

		cin >> n >> k >> s;
		auto kmp = prep(s);

		vector<int> dp(k + 1, 0);
		dp[0] = 1;

		for (int i = 0; i < k; i ++) {
			for (int j = 0; j < n; j ++) {
