**提示 1：** 我们只需要考虑若干个质因子的情况。

**提示 2：** 维护质因子的次数。

我们如果是第三类查询，可以将输入的数进行质因数分解，看各个质因子是否达到了数量。

所以对于 $X$ 只需维护其各个质因子的数量。

第一个查询相当于单点加法，第二个查询相当于全局乘法。

一个用数据结构的办法就是用懒更新线段树，不过你不断乘会让数值过大，你可以设置一个上界，超过它就赋值为它，这样就没问题了。

你也可以考虑，每一个位置在变成正数后，进行幂次操作的次数（也就是次数进行乘法）是很少的。因此可以暴力维护那些还可以使用乘法的位置。下面的代码给的是这种做法。

时间复杂度为 $\mathcal{O}(M+q\log M)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    M = 10 ** 5 + 5
    pr = list(range(M))

    for i in range(2, M):
        if pr[i] == i:
            for j in range(i, M, i):
                pr[j] = i

    q = II()

    cur = [0] * M
    to_multiply = []

    outs = []

    for _ in range(q):
        t, x = MII()

        if t == 1:
            while x > 1:
                if cur[pr[x]] == 0:
                    to_multiply.append(pr[x])
                cur[pr[x]] += 1
                x //= pr[x]

        elif t == 2:
            new_to_multipy = []
            for v in to_multiply:
                cur[v] *= x
                if cur[v] < 20:
                    new_to_multipy.append(v)

            to_multiply = new_to_multipy

        else:
            cnt = Counter()
            while x > 1:
                cnt[pr[x]] += 1
                x //= pr[x]

            flg = True

            for x in cnt:
                if cnt[x] > cur[x]:
                    flg = False

            outs.append('Yes' if flg else 'No')

    print('\n'.join(outs))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int M = 1e5 + 5;
	vector<int> pr(M);

	iota(pr.begin(), pr.end(), 0);

	for (int i = 2; i < M; i ++) {
		if (pr[i] == i) {
			for (int j = i; j < M; j += i) {
				pr[j] = i;
			}
		}
	}

	int q;
	cin >> q;

	vector<long long> cur(M, 0);
	vector<int> to_multiply;

	while (q --) {
		int t, x;
		cin >> t >> x;

		if (t == 1) {
			while (x > 1) {
				if (!cur[pr[x]])
					to_multiply.emplace_back(pr[x]);
				cur[pr[x]] ++;
				x /= pr[x];
			}
		}
		else if (t == 2) {
			vector<int> new_to_multiply;

			for (auto &v: to_multiply) {
				cur[v] *= x;
				if (cur[v] < 20) new_to_multiply.emplace_back(v);
			}

			to_multiply.swap(new_to_multiply);
		}
		else {
			int v = x;
			bool flg = true;

			while (v > 1) {
				if (!cur[pr[v]]) flg = false;
				cur[pr[v]] --;
				v /= pr[v];
			}

			v = x;
			while (v > 1) {
				cur[pr[v]] ++;
				v /= pr[v];
			}

			cout << (flg ? "Yes" : "No") << '\n';
		}
	}

	return 0;
}
