**提示 1：** 考虑另一个求和式。

**提示 2：** 另一个求和如何 DP ？

LCA 的深度，等于这组点的 LCA 从该位置的父亲起到根，每个位置贡献一单位的权重。

于是，这么来算每个点的权重等于这个点对应的各个儿子的子树的 $k$ 元子集的个数的和。而 DP 只需求子树内的权重和即可。

对于根节点而言 DP 数值就是答案。

因为要对每个点求答案，涉及到每个点往上的那棵子树，所以用换根 DP 即可。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():  
    n, k = MII()
    path = [[] for _ in range(n)]

    for _ in range(n - 1):
        u, v = GMI()
        path[u].append(v)
        path[v].append(u)

    mod = 10 ** 9 + 7
    f = Factorial(n, mod)

    parent = [-1] * n
    que = [0]

    for u in que:
        for v in path[u]:
            if parent[u] != v:
                parent[v] = u
                que.append(v)

    sz = [1] * n
    dp = [0] * n

    for u in reversed(que):
        if u:
            p = parent[u]
            sz[p] += sz[u]
            dp[p] += dp[u] + f.combi(sz[u], k)
            dp[p] %= mod

    rev_dp = [0] * n

    for u in que:
        for v in path[u]:
            if parent[v] == u:
                cur = (dp[u] - dp[v] - f.combi(sz[v], k)) % mod
                rev_dp[v] = (rev_dp[u] + cur + f.combi(n - sz[v], k)) % mod

    print(' '.join(str((dp[i] + rev_dp[i]) % mod) for i in range(n)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int M = 2e5 + 5, mod = 1e9 + 7;

	vector<int> f(M), g(M);

	f[0] = 1;
	for (int i = 1; i < M; i ++) {
		f[i] = 1ll * i * f[i - 1] % mod;
	}

	g[M - 1] = quickPow(f[M - 1], mod - 2, mod);
	for (int i = M - 1; i > 0; i --) {
		g[i - 1] = 1ll * i * g[i] % mod;
	}

	auto comb = [&] (int x, int y) -> int {
		if (y < 0 || y > x) return 0;
		return 1ll * f[x] * g[y] % mod * g[x - y] % mod;
	};

	int n, k;
	cin >> n >> k;

	vector<vector<int>> path(n);
	for (int i = 0; i < n - 1; i ++) {
		int u, v;
		cin >> u >> v;
		u --, v --;
		path[u].emplace_back(v);
		path[v].emplace_back(u);
	}

	vector<int> dp(n, 0), rev_dp(n, 0), sz(n, 1);

	auto dfs = [&] (auto &self, int u, int p) -> void {
		for (auto &v: path[u]) {
			if (v != p) {
				self(self, v, u);
				dp[u] = (dp[u] + dp[v]) % mod;
				dp[u] = (dp[u] + comb(sz[v], k)) % mod;
				sz[u] += sz[v];
			}
		}
	};

	dfs(dfs, 0, -1);

	auto rev_dfs = [&] (auto &self, int u, int p) -> void {
		for (auto &v: path[u]) {
			if (v != p) {
				int cur = dp[u];
				cur = (cur + mod - dp[v]) % mod;
				cur = (cur + mod - comb(sz[v], k)) % mod;
				rev_dp[v] = rev_dp[u];
				rev_dp[v] = (rev_dp[v] + cur) % mod;
				rev_dp[v] = (rev_dp[v] + comb(n - sz[v], k)) % mod;
				self(self, v, u);
			}
		}
	};

	rev_dfs(rev_dfs, 0, -1);

	for (int i = 0; i < n; i ++)
		cout << (dp[i] + rev_dp[i]) % mod << " \n"[i == n - 1];

	return 0;
}
```

**提示 1：** Hall 定理。考虑清楚所有的条件。

我们要最小化超过 $x$ 题的人数，同时你自己刚好做了 $x$ 个题。

这两件事不太统一 （因为 $x$ 并不超过 $x$ ），我们干脆最大化做了不超过 $x$ 个题的人数。设这个人数是 $v$ 。

考虑使用 Hall 定理。

我们需要考虑的就是每一个子集需要满足的限制，再将这些限制取交集即可。考虑一个 $i$ 元的题目子集，则这个子集最多被做了多少次呢？ $\min(x,i)\times v+i\times(n-v)$ 。于是这个数值不小于 $i$ 元子集的总解决次数。

发现其中只有总解决次数最大的 $i$ 元子集有用，因此对数组排序后取最大的 $i$ 项子集进行讨论即可。最后将不同的 $i$ 给出的限制取交集即可。

因为 $n$ 范围很小，所以可以直接用基数排序等排序方法。

时间复杂度为 $\mathcal{O}(n+p)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():  
    t = II()
    outs = []

    for _ in range(t):
        n, p, x = MII()
        nums = LII()

        x = p - x

        cnt = [0] * (n + 1)
        for v in nums:
            cnt[n - v] += 1

        nums.clear()

        for i in range(n + 1):
            for _ in range(cnt[i]):
                nums.append(i)

        cur = 0
        ans = n

        for i in range(p):
            cur += nums[i]
            if x - (p - i - 1) > 0:
                ans = fmin(ans, cur // (x - (p - i - 1)))

        outs.append(n - ans)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int n, p, x;
		cin >> n >> p >> x;

		x = p - x;

		vector<int> cnt(n + 1, 0);
		for (int i = 0; i < p; i ++) {
			int v;
			cin >> v;
			cnt[n - v] ++;
		}

		vector<int> nums;
		for (int i = 0; i <= n; i ++) {
			while (cnt[i] --) {
				nums.emplace_back(i);
			}
		}

		long long cur = 0, ans = n;
		for (int i = 0; i < p; i ++) {
			cur += nums[i];
			if (x - (p - i - 1) > 0) {
				ans = min(ans, cur / (x - (p - i - 1)));
			}
		}

		cout << n - ans << '\n';
	}

	return 0;
}
