**提示 1：** 考虑 gcd 是 $x$ 的倍数的数对，这个怎么求？

**提示 2：** 如何求 gcd 恰好是 $x$ 的数对个数。

先看提示 1 。我们可以统计每个数组中 $x$ 的倍数的个数（直接枚举 $x,2x,\dots$ 的出现个数，复杂度是 $\mathcal{O}(\sum n/x)=\mathcal{O}(n\log n)$ ），相乘就是 gcd 是 $x$ 的倍数的数对个数。

接下来为了得到 gcd 恰好是 $x$ 的数对的个数，我们可以用 gcd 是 $x$ 的倍数的数对的数量，减去 gcd 恰好是 $2x,3x,\dots$ 的情况的数对的数量。这里的枚举是 $\mathcal{O}(n/x)$ 的，所以整体复杂度是 $\mathcal{O}(n\log n)$ 。

最后对质数的位置的结果求和即可。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():  
    M = 10 ** 5 + 5
    pr = [1] * M
    pr[0] = 0
    pr[1] = 0

    for i in range(2, M):
        if pr[i]:
            for j in range(2 * i, M, i):
                pr[j] = 0

    t = II()
    outs = []

    for _ in range(t):
        n = II()
        v1 = LII()
        v2 = LII()

        c1 = [0] * (n + 1)
        c2 = [0] * (n + 1)

        for x in v1:
            c1[x] += 1

        for x in v2:
            c2[x] += 1

        for i in range(1, n + 1):
            for j in range(2 * i, n + 1, i):
                c1[i] += c1[j]
                c2[i] += c2[j]

        c = [x * y for x, y in zip(c1, c2)]

        for i in range(n, 0, -1):
            for j in range(2 * i, n + 1, i):
                c[i] -= c[j]

        ans = 0
        for i in range(n + 1):
            if pr[i]:
                ans += c[i]

        outs.append(ans)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int M = 1e5 + 5;
	vector<int> pr(M, 1);
	pr[0] = 0, pr[1] = 0;

	for (int i = 2; i < M; i ++) {
		if (pr[i]) {
			for (int j = 2 * i; j < M; j += i) {
				pr[j] = 0;
			}
		}
	}

	int t;
	cin >> t;

	while (t --) {
		int n;
		cin >> n;

		vector<int> c1(n + 1, 0), c2(n + 1, 0);

		for (int i = 0; i < n; i ++) {
			int x; cin >> x;
			c1[x] ++;
		}

		for (int i = 0; i < n; i ++) {
			int x; cin >> x;
			c2[x] ++;
		}

		for (int i = 1; i <= n; i ++) {
			for (int j = 2 * i; j <= n; j += i) {
				c1[i] += c1[j];
				c2[i] += c2[j];
			}
		}

		vector<long long> cnt(n + 1, 0);
		for (int i = 0; i <= n; i ++) {
			cnt[i] = 1ll * c1[i] * c2[i];
		}

		for (int i = n; i >= 1; i --) {
			for (int j = 2 * i; j <= n; j += i) {
				cnt[i] -= cnt[j];
			}
		}

		long long ans = 0;
		for (int i = 0; i <= n; i ++) {
			if (pr[i]) {
				ans += cnt[i];
			}
		}

		cout << ans << '\n';
	}

	return 0;
}
```

**提示 1：** 相当于看哪些质因子同时出现在选的子集里。所以次数不重要，是否出现重要。

**提示 2：** 统计的实际上是啥？

先看提示 1 ，所以我们每个元素实际上只需要关注每个质因数是否出现了，也就是可以用一个 $2^m$ 范围内的数进行表示。

而取了一个子集后，我们关心的是这个子集的与和。

而总共只有 $2^m$ 种不同的与和，因此分别考虑每一种与和分别出现多少次，然后最后乘每种与和对应的数值即可。

与和恰好是 $x$ 的方案数不好直接求。我们可以先求与和包含 $x$ 的方案数。我们先统计包含 $x$ 的元素个数 $k$ ，则对应非空子集个数是 $2^k-1$ ，最后再把不等于 $x$ 的部分去掉就是恰好等于 $x$ 的部分了。

时间复杂度为 $\mathcal{O}(nm+m2^m)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():  
    n, m = MII()
    prs = LII()
    nums = LII()

    cnt = [0] * (1 << m)

    for i in range(n):
        msk = 0
        for j in range(m):
            if nums[i] % prs[j] == 0:
                msk |= 1 << j

        cnt[msk] += 1

    for i in range(m):
        for j in range(1 << m):
            if j >> i & 1:
                cnt[j ^ (1 << i)] += cnt[j]

    mod = 10 ** 9 + 7

    for i in range(1 << m):
        cnt[i] = pow(2, cnt[i], mod) - 1

    for i in range(m):
        for j in range(1 << m):
            if j >> i & 1:
                nj = j ^ (1 << i)
                cnt[nj] = (cnt[nj] - cnt[j]) % mod

    val = [1] * (1 << m)

    for i in range(1, 1 << m):
        x = i & -i
        val[i] = val[i - x] * prs[x.bit_length() - 1] % mod

    print(sum(val[i] * cnt[i] % mod for i in range(1 << m)) % mod)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, m;
	cin >> n >> m;

	vector<int> pr(m), nums(n);
	for (auto &x: pr) cin >> x;
	for (auto &x: nums) cin >> x;

	vector<int> cnt(1 << m, 0);

	for (auto &v: nums) {
		int msk = 0;
		for (int i = 0; i < m; i ++) {
			if (v % pr[i] == 0) {
				msk |= 1 << i;
			}
		}
		cnt[msk] ++;
	}

	for (int i = 0; i < m; i ++) {
		for (int j = 0; j < 1 << m; j ++) {
			if (j >> i & 1) {
				cnt[j ^ (1 << i)] += cnt[j];
			}
		}
	}

	int mod = 1e9 + 7;
	for (int i = 0; i < (1 << m); i ++)
		cnt[i] = quickPow(2, cnt[i], mod) - 1;

	for (int i = 0; i < m; i ++) {
		for (int j = 0; j < 1 << m; j ++) {
			if (j >> i & 1) {
				int nj = j ^ (1 << i);
				cnt[nj] = (cnt[nj] - cnt[j] + mod) % mod;
			}
		}
	}

	vector<int> vals(1 << m, 1);

	for (int i = 1; i < 1 << m; i ++)
		vals[i] = 1ll * vals[i - (i & -i)] * pr[__builtin_ctz(i)] % mod;

	int ans = 0;
	for (int i = 0; i < 1 << m; i ++)
		ans = (ans + 1ll * vals[i] * cnt[i]) % mod;

	cout << ans;

	return 0;
}
```

**提示 1：** 路径拆为两部分拼起来，求的实际上是什么？

显然是一个树上的 DP 问题。

路径相关的问题可以考虑从某个结点往更深的地方连的路径。这样每条路径一定可以拆分成两条这样的路径。

而这题中，如果我们选定了 $u$ 出发的向两个不同的儿子方向的往下的路径，我们要求的东西实际上是什么呢？也就是我们需要维护什么呢？

考虑去绝对值，则发现其中一条路径中，如果端点的 $x,y,z$ 对应的权值是 $v_x,v_y,v_z$ ，则另一条路径的端点的权值是 $-v_x,-v_y,-v_z$ 。

而 $|x_1-x_2|+|y_1-y_2|+|z_1-z_2|$ 等价于 $\max\limits_{w_1,w_2,w_3} w_1(x_1-x_2)+w_2(y_1-y_2)+w_3(z_1-z_2)$ 。

所以我们无需真的知道 $x_1,x_2$ 一类的大小关系，只需枚举其中一端的 $2^3=8$ 种可能的权重，另一端与其相反，最终结果取最大值就跟绝对值是一个效果了。

所以维护从每个结点出发，往更深处的端点且端点权值分别为 $(a,b,c)$ 的最大权值路径，再将不同子树对应的答案合并即可。考虑第 $i$ 棵子树的时候只在意前面的子树的最大权值，因此可以边遍历边维护当前权值组合的最大权。

时间复杂度为 $\mathcal{O}(n2^d)$ ， $d$ 是坐标维数。

### 具体代码如下——

Python 做法如下——

```Python []
def main():  
    n = II()
    path = [[] for _ in range(n)]

    for _ in range(n - 1):
        u, v, w = MII()
        u -= 1
        v -= 1
        path[u].append(w * n + v)
        path[v].append(w * n + u)

    pts = [[] for _ in range(3)]

    for _ in range(n):
        pt = LII()

        for i in range(3):
            pts[i].append(pt[i])

    parent = [-1] * n
    que = [0]

    for u in que:
        for msk in path[u]:
            v = msk % n
            if parent[u] != v:
                parent[v] = u
                que.append(v)

    ans = 0

    ma = [[0] * n for _ in range(8)]

    for i in reversed(que):
        for j in range(8):
            for k in range(3):
                if j >> k & 1:
                    ma[j][i] += pts[k][i]
                else:
                    ma[j][i] -= pts[k][i]

        for msk in path[i]:
            w, v = divmod(msk, n)
            if parent[v] == i:
                for j in range(8):
                    ans = fmax(ans, ma[j][v] + w + ma[7 - j][i])
                for j in range(8):
                    ma[j][i] = fmax(ma[j][i], ma[j][v] + w)

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	vector<vector<pair<int, int>>> path(n);

	for (int i = 0; i < n - 1; i ++) {
		int u, v, w;
		cin >> u >> v >> w;
		u --, v --;
		path[u].emplace_back(v, w);
		path[v].emplace_back(u, w);
	}

	vector<array<long long, 3>> pts(n);
	for (auto &[x, y, z]: pts) cin >> x >> y >> z;

	long long total_ans = 0;

	auto dfs = [&] (auto &self, int u, int p) -> array<long long, 8> {
		array<long long, 8> ans;
		for (int i = 0; i < 8; i ++) {
			ans[i] = 0;
			for (int j = 0; j < 3; j ++) {
				if (i >> j & 1) ans[i] += pts[u][j];
				else ans[i] -= pts[u][j];
			}
		}

		for (auto &[v, w]: path[u]) {
			if (v != p) {
				auto res = self(self, v, u);

				for (int i = 0; i < 8; i ++)
					total_ans = max(total_ans, ans[i] + res[7 ^ i] + w);

				for (int i = 0; i < 8; i ++)
					ans[i] = max(ans[i], res[i] + w);
			}
		}

		return ans;
	};

	dfs(dfs, 0, -1);

	cout << total_ans;

	return 0;
}
```

**提示 1：** 对于每个查询而言，点分为哪几类？

**提示 2：** 如何让这几类点更方便维护？

首先，假设是单次询问。考虑平面直角坐标系中，左上角、右上角、左下角、右下角，四个方向的点对应的结果的求法也这样分为四类。而去掉其中跟查询坐标相关的，也就发现了四个方向我们有四个最小化的目标。

所以我们要对每个查询，分别求四个方向的最小化结果。

那多次查询怎么办呢？

考虑对查询进行排序，接下来使用扫描线。

我们考虑对查询按照 $y$ 轴坐标排序，则扫上去的过程中，我们可以维护每个点作为左上 / 右上 / 左下 / 右下点的对应权值。枚举每一个 $y$ 的过程中，上方的点维护在左上和右上两个数据结构中，下方的点在剩余数据结构中。

当一个点被穿过的时候需要发生上下的状态的转移。

而上述扫描线维护了上下关系，也就将点分为了上下两部分。而左右的关系可以用线段树来做。对于每个查询 $(x,y)$ ，我们找到 $x$ 左侧的所有位置，用维护左上方和左下方权值的线段树解决左侧问题，右侧也类似。

更具体地，上侧的点维护其作为左上角点 / 右上角点的最优权值，将这个结果分别存储在两个线段树中。接下来查询 $(x,y)$ 时，考虑 $x$ 左侧的左上角点最小权值，以及 $x$ 右侧的右上角点最小权值。下侧部分是类似的。而平移 $y$ 的过程中，上下侧的转换是容易的。

两个维度的最优化问题可以通过排序将其中一个维度的最优化简化。

时间复杂度为 $\mathcal{O}(n\log n+q\log n+q\log q)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():  
    n, q, a, b = MII()

    xs = []
    ys = []
    cs = []

    for _ in range(n):
        x, y, c = MII()
        xs.append(x)
        ys.append(y)
        cs.append(c)

    sorted_xs = sorted(xs)
    st_range_x = sorted(range(n), key=lambda x: xs[x])
    st_range_y = sorted(range(n), key=lambda x: ys[x])

    pos = [0] * n

    for i in range(n):
        pos[st_range_x[i]] = i

    qxs = []
    qys = []

    for _ in range(q):
        x, y = MII()
        qxs.append(x)
        qys.append(y)

    st_range_q = sorted(range(q), key=lambda x: qys[x])

    inf = 7 * 10 ** 18

    seg_up_left = SegTree(fmin, inf, [-a * xs[i] + b * ys[i] + cs[i] for i in st_range_x])
    seg_up_right = SegTree(fmin, inf, [a * xs[i] + b * ys[i] + cs[i] for i in st_range_x])
    seg_down_left = SegTree(fmin, inf, n)
    seg_down_right = SegTree(fmin, inf, n)

    outs = [0] * q
    pt = 0

    for i in st_range_q:
        while pt < n and ys[st_range_y[pt]] < qys[i]:
            idx = st_range_y[pt]
            seg_up_left.set(pos[idx], inf)
            seg_up_right.set(pos[idx], inf)
            seg_down_left.set(pos[idx], -a * xs[idx] - b * ys[idx] + cs[idx])
            seg_down_right.set(pos[idx], a * xs[idx] - b * ys[idx] + cs[idx])
            pt += 1

        p = bisect.bisect_left(sorted_xs, qxs[i])

        ans = inf
        ans = fmin(ans, seg_up_left.prod(0, p) + a * qxs[i] - b * qys[i])
        ans = fmin(ans, seg_up_right.prod(p, n) - a * qxs[i] - b * qys[i])
        ans = fmin(ans, seg_down_left.prod(0, p) + a * qxs[i] + b * qys[i])
        ans = fmin(ans, seg_down_right.prod(p, n) - a * qxs[i] + b * qys[i])

        outs[i] = ans

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
const long long inf = 7e18;

long long op(long long x, long long y) {return min(x, y);}

long long e() {return inf;}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, q;
	long long a, b;
	cin >> n >> q >> a >> b;

	vector<array<long long, 3>> pts(n);
	for (auto &[x, y, c]: pts) cin >> x >> y >> c;

	sort(pts.begin(), pts.end());

	vector<int> order(n);
	iota(order.begin(), order.end(), 0);
	sort(order.begin(), order.end(), [&] (int i, int j) {return pts[i][1] < pts[j][1];});

	vector<pair<int, int>> queries(q);
	for (auto &[x, y]: queries) cin >> x >> y;

	vector<int> solve_order(q);
	iota(solve_order.begin(), solve_order.end(), 0);
	sort(solve_order.begin(), solve_order.end(), [&] (int i, int j) {return queries[i].second < queries[j].second;});

	vector<long long> up_left(n), up_right(n);

	for (int i = 0; i < n; i ++) {
		up_left[i] = -a * pts[i][0] + b * pts[i][1] + pts[i][2];
		up_right[i] = a * pts[i][0] + b * pts[i][1] + pts[i][2];
	}

	atcoder::segtree<long long, op, e> seg_up_left(up_left), seg_up_right(up_right), seg_down_left(n), seg_down_right(n);

	vector<long long> outs(q);
	int pt = 0;

	for (auto &i: solve_order) {
		while (pt < n && pts[order[pt]][1] < queries[i].second) {
			int idx = order[pt];
			seg_up_left.set(idx, inf);
			seg_up_right.set(idx, inf);
			seg_down_left.set(idx, -a * pts[idx][0] - b * pts[idx][1] + pts[idx][2]);
			seg_down_right.set(idx, a * pts[idx][0] - b * pts[idx][1] + pts[idx][2]);
			pt ++;
		}

		int l = 0, r = n - 1;

		while (l <= r) {
			int mid = (l + r) / 2;
			if (pts[mid][0] <= queries[i].first) l = mid + 1;
			else r = mid - 1;
		}

		long long ans = inf;
		ans = min(ans, seg_up_left.prod(0, l) + a * queries[i].first - b * queries[i].second);
		ans = min(ans, seg_up_right.prod(l, n) - a * queries[i].first - b * queries[i].second);
		ans = min(ans, seg_down_left.prod(0, l) + a * queries[i].first + b * queries[i].second);
		ans = min(ans, seg_down_right.prod(l, n) - a * queries[i].first + b * queries[i].second);

		outs[i] = ans;
	}

	for (auto &x: outs) cout << x << '\n';

	return 0;
}
```

**提示 1：** 先探讨先手必胜的条件。

**提示 2：** 如何计算必胜元素对数量。

什么情况下必胜呢？

如果开局两个元素相同，则必胜。接下来认为 $x,y$ 不相等。

否则 $x,y$ 不断操作，只能得到 $\mathrm{gcd}(x,y)$ 的倍数。且一旦有一个倍数没有出现，总能进行操作。

因此最后数的数量就是 $\frac{\max(x,y)}{\mathrm{gcd}(x,y)}$ ，而先手必胜就要求这个数是奇数。

考虑枚举 $\mathrm{gcd}(x,y)=g$ ，则 $x=x_0g,y=y_0g$ ，我们再枚举 $\max(x_0,y_0)=M\gt 1$ ，则要求 $M$ 是奇数，且另一个数的取法有欧拉函数 $\phi(M)$ 种。而两个数可以交换顺序，所以方案数乘 $2$ 。

所以对于每个 $g$ 而言，我们要求的就是不超过 $\frac{n}{g}$ 的奇数的 $\phi(x)$ 之和的两倍再加上 $1$ 。

因此只需我们通过素数筛预处理欧拉函数，再取前缀和就可以 $\mathcal{O}(1)$ 快速得到每个 $g$ 对应的答案，相加即可。也可以通过整除分块进一步得到更优的复杂度。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():  
    M = 10 ** 6 + 5
    phi = list(range(M))

    for i in range(2, M):
        if phi[i] == i:
            for j in range(i, M, i):
                phi[j] = phi[j] // i * (i - 1)

    for i in range(2, M):
        if i % 2 == 0:
            phi[i] = 0
        else:
            phi[i] = 2 * phi[i]

    for i in range(1, M):
        phi[i] += phi[i - 1]

    t = II()
    outs = []

    for _ in range(t):
        n = II()
        ans = 0

        for i in range(1, n + 1):
            ans += phi[n // i]

        outs.append(ans)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int M = 1e6 + 5;

	vector<long long> phi(M);
	iota(phi.begin(), phi.end(), 0);

	for (int i = 2; i < M; i ++) {
		if (phi[i] == i) {
			for (int j = i; j < M; j += i) {
				phi[j] = phi[j] / i * (i - 1);
			}
		}
	}

	for (int i = 2; i < M; i ++) {
		if (i & 1) phi[i] = 2 * phi[i];
		else phi[i] = 0;
	}

	for (int i = 1; i < M; i ++) {
		phi[i] += phi[i - 1];
	}

	int t;
	cin >> t;

	while (t --) {
		int n;
		cin >> n;

		long long ans = 0;

		for (int i = 1; i <= n; i ++) {
			ans += phi[n / i];
		}

		cout << ans << '\n';
	}

	return 0;
}
```

**提示 1：** 首先，先求出单个元素博弈情况下的 SG 函数。

**提示 2：** 我们最后求的跟这个 SG 函数有什么关系？

如果你不熟悉博弈论的 SG 函数，请查阅 OI-wiki 的相关资料，这里不做过多解释。

这题里，我们先求单个元素博弈的 SG 函数。设 $x$ 大小对应的 SG 函数数值是 $sg(x)$ 。则我们要求的就是 $[x-nums[x],x-1]$ 的位置对应的 MEX 数值。

从小到大考虑各个 SG 函数。因为这里转移的区间是连续且靠近要求的那个 $x$ 的，所以我们只在乎每个 SG 数值对应的最靠后的位置。我们可以用线段树维护它，这样我们只需二分找到第一个不在 $[x-nums[x],x-1]$ 区间内的元素的数值即可。我们线段树维护前缀最小出现位置。（用树状数组也可以）

接下来我们最终的数组需要满足什么条件呢？

首先，其本身 SG 函数的数值的异或和得等于 $0$ （如果这个不知道你也需要在 OI-wiki 中重新学习 SG 函数）。这个怎么求呢？我们相当于有一个序列，反复取 $r$ 轮，要求最后异或和等于 $0$ 的方案数。这件事我们可以用 FWT，快速幂后再 IFWT 即可。这个不会的话可以去学习快速沃尔什变换。

那么我们多算了哪些情况呢？多算了那些 “不存在异或值不等于 $0$ 的状态，使得将其中一个元素减去 $K$ 后等于当前状态”。

所以结果数组中的每个元素，要么不可能是由减 $K$ 得到的，要么减去 $K$ 前和当前状态的 SG 函数结果一致。否则将该位置 $+K$ 就是一个合法的异或值不等于 $0$ 的初始状态，不应排除。

于是取出这个子集再进行上述的 FWT 过程即可。

时间复杂度为 $\mathcal{O}(n\log n+n\log r)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():  
    mod = 998244353
    rev2 = (mod + 1) // 2

    def fwt_xor(nums, bit, type):
        for i in range(bit):
            mask = 1 << i
            for j in range(0, 1 << bit, 2 * mask):
                for k in range(mask):
                    x, y = nums[j + k], nums[j + mask + k]
                    nums[j + k] = x + y
                    nums[j + mask + k] = x - y
                    if type == -1:
                        nums[j + k] = nums[j + k] * rev2 % mod
                        nums[j + mask + k] = nums[j + mask + k] * rev2 % mod

    n, k, r = MII()
    nums = LII()

    sg = [0] * (n + 1)
    seg = SegTree(fmin, n + 1, [-1] * (n + 1))

    seg.set(0, 0)

    for i in range(1, n + 1):
        sg[i] = seg.max_right(0, lambda x: x >= i - nums[i - 1])
        seg.set(sg[i], i)

    ans = 0

    cnt = [0] * (1 << 19)

    for x in sg:
        cnt[x] += 1

    fwt_xor(cnt, 19, 1)

    for i in range(1 << 19):
        cnt[i] = pow(cnt[i], r, mod)

    fwt_xor(cnt, 19, -1)

    ans += cnt[0]

    cnt = [0] * (1 << 19)

    for i in range(n + 1):
        if i + k > n or sg[i] == sg[i + k]:
            cnt[sg[i]] += 1

    fwt_xor(cnt, 19, 1)

    for i in range(1 << 19):
        cnt[i] = pow(cnt[i], r, mod)

    fwt_xor(cnt, 19, -1)

    ans -= cnt[0]

    print(ans % mod)
```

C++ 做法如下——

```cpp []
const int mod = 998244353, rev2 = (mod + 1) / 2;

int op(int x, int y) {return min(x, y);}

int e() {return 1'000'000;}

long long quickPow(long long base, long long power, long long mod) {
	if (power == 0) return 1 % mod;
	long long cur = quickPow(base, power / 2, mod);
	return power & 1 ? base * cur % mod * cur % mod : cur * cur % mod; 
}

void fwt_xor(vector<int>& nums, int bit, int type) {
	for (int i = 0; i < bit; i++) {
		int mask = 1 << i;
		for (int j = 0; j < (1 << bit); j += 2 * mask) {
			for (int k = 0; k < mask; k ++) {
				int x = nums[j + k], y = nums[j + mask + k];
				nums[j + k] = (x + y) % mod;
				nums[j + mask + k] = (x - y + mod) % mod;
				if (type == -1) {
					nums[j + k] = 1ll * nums[j + k] * rev2 % mod;
					nums[j + mask + k] = 1ll * nums[j + mask + k] * rev2 % mod;
				}
			}
		}
	}
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, k, r;
	cin >> n >> k >> r;

	vector<int> sg(n + 1, -1);
	atcoder::segtree<int, op, e> seg(sg);

	sg[0] = 0; seg.set(0, 0);

	for (int i = 1; i <= n; i ++) {
		int v;
		cin >> v;
		sg[i] = seg.max_right(0, [&] (int x) {return x >= i - v;});
		seg.set(sg[i], i);
	}

	int ans = 0;

	vector<int> cnt(1 << 19, 0);

	for (auto &x: sg) cnt[x] ++;

	fwt_xor(cnt, 19, 1);

	for (int i = 0; i < 1 << 19; i ++) cnt[i] = quickPow(cnt[i], r, mod);

	fwt_xor(cnt, 19, -1);

	ans += cnt[0];

	fill(cnt.begin(), cnt.end(), 0);

	for (int i = 0; i <= n; i ++) {
		if (i + k > n || sg[i] == sg[i + k]) {
			cnt[sg[i]] ++;
		}
	}

	fwt_xor(cnt, 19, 1);

	for (int i = 0; i < 1 << 19; i ++) cnt[i] = quickPow(cnt[i], r, mod);

	fwt_xor(cnt, 19, -1);

	ans -= cnt[0];

	cout << (ans + mod) % mod;

	return 0;
}
```

**提示 1：** 先找到最小的 $i$ 。怎么构造可以避开分类讨论？

首先，用 $1,2,\dots,N$ 能凑出来的数的数据范围的最小值是 $1-2-3-\dots N$ ，最大值是 $1+2+\dots+N$ ，所以范围是 $[2-\frac{N(N+1)}{2},\frac{N(N+1)}{2}]$ 。

同时设取负数的集合的和是 $X$ ，则整体的和是 $\frac{N(N+1)}{2}-2X$ ，所以 $X$ 只能跟 $\frac{N(N+1)}{2}$ 奇偶性相同。

除此之外，我们选取的子集不能包含 $1$ ，所以子集和不能是 $1$ 。类似地， $2+3+\dots+N-1$ 的这个子集和也是凑不出来的。

于是我们枚举 $N$ ，直到上述条件不会被判为非法，并确定我们需要凑的要取负数的子集和。

因为整体构造的发挥空间很大，可以自行尝试可行的做法。下面给出一种。

因为我们要留着小数给最后调整，所以我们从大到小遍历 $N$ 到 $2$ 的数，能放到要选的集合中就放进去。

但这样可能导致非法，因为可能出现最后剩下一个 $1$ 。在这种情况下，我们选取的数一定形成一个后缀（不然我们可以将其中某个数 $x$ 增大 $1$ 且 $x+1$ 没有被选到，而这就意味着我们到 $x+1$ 时本应选上  $x+1$ 却没选），且最小数不小于 $4$ 。于是删去我们选的最小的数 $y$ ，改选 $y-1$ 和 $2$ 即可。

时间复杂度为 $\mathcal{O}(\sqrt{X})$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():  
    t = II()
    outs = []

    for _ in range(t):
        n = II()

        for i in range(1, 1000):
            v = i * (i + 1) // 2

            if 2 - v <= n <= v and (v - n) % 2 == 0 and n != v - 2 and n != 4 - v:
                outs.append(str(i))

                chosen = [0] * (i + 1)
                target = (v - n) // 2

                for x in range(i, 1, -1):
                    if target >= x and target - x != 1:
                        target -= x
                        chosen[x] = 1

                outs.append('1' + ''.join("+-"[chosen[j]] + str(j) for j in range(2, i + 1)))
                break

    print('\n'.join(outs))
```

