	else {
		while (t --) {
			int n, m, k;
			cin >> n >> m >> k;

			vector<int> nums(k);
			for (auto &x: nums) cin >> x;

			vector<vector<int>> path(n);

			while (m --) {
				int u, v;
				cin >> u >> v;
				u --, v --;
				path[u].emplace_back(v);
				path[v].emplace_back(u);
			}

			vector<int> cols(n, 0);

			auto dfs = [&] (auto &self, int u) -> void {
				for (auto &v: path[u]) {
					if (!cols[v]) {
						cols[v] = cols[u] ^ 3;
						self(self, v);
					}
				}
			};

			for (int i = 0; i < n; i ++) {
				if (!cols[i]) {
					cols[i] = 1;
					dfs(dfs, i);
				}
			}

			int c1 = 0, c2 = 0;
			for (auto &x: cols) {
				if (x == 1) c1 ++;
				else c2 ++;
			}

			vector<int> ans(n, 0);
