	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int n, k;
		cin >> n >> k;

		vector<int> nums(n);
		for (auto &x: nums) cin >> x;

		swap(nums[k - 1], nums[n - 1]);

		vector<int> vis(n + 1, 0);
		for (int i = 0; i < n - 1; i ++)
			vis[nums[i]] = 1;

		int mex = 0;
