**提示 1：** 考虑中间的分割点，前面选一个数，后一部分选另一个数。

**提示 2：** 存哪些备选。

因为整体有两段，一段是一个数值，所以考虑枚举中间的分割位置。也就是拆分为前缀和后缀，分别选取一个相同的数。

我们可以统计每个前缀 / 后缀中每个元素的出现频率。

首先第一直觉是直接选择出现频率最高的数出现的次数。

但左右两端对应数可能数值相同，这在本题中是不允许的，所以考虑维护前两名。这样就一定能找到最优组合了。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    rnd = random.getrandbits(30)

    for _ in range(t):
        n = II()
        nums = LII()

        for i in range(n):
            nums[i] ^= rnd

        pref = [[] for _ in range(n + 1)]

        top1 = (0, 0)
        top2 = (1, 0)
        pref[0] = [top1, top2]

        cnt = Counter()

        for i in range(n):
            cnt[nums[i]] += 1
            cur_freq = cnt[nums[i]]

            if nums[i] == top1[0]:
                top1 = (nums[i], cur_freq)
            elif cur_freq > top1[1]:
                top2 = top1
                top1 = (nums[i], cur_freq)
            elif nums[i] == top2[0] or cur_freq > top2[1]:
                top2 = (nums[i], cur_freq)

            pref[i + 1] = [top1, top2]

        suff = [[] for _ in range(n + 1)]

        top1 = (0, 0)
        top2 = (1, 0)
        suff[n] = [top1, top2]

        cnt = Counter()

        for i in range(n - 1, -1, -1):
            cnt[nums[i]] += 1
            cur_freq = cnt[nums[i]]

            if nums[i] == top1[0]:
                top1 = (nums[i], cur_freq)
            elif cur_freq > top1[1]:
                top2 = top1
                top1 = (nums[i], cur_freq)
            elif nums[i] == top2[0] or cur_freq > top2[1]:
                top2 = (nums[i], cur_freq)

            suff[i] = [top1, top2]

        ans = 0
        for i in range(n + 1):
            for x1, y1 in pref[i]:
                for x2, y2 in suff[i]:
                    if y1 and y2 and x1 != x2:
                        ans = fmax(ans, y1 + y2)

        outs.append(ans)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int n;
		cin >> n;

		vector<int> nums(n);
		for (auto &x: nums) cin >> x;

		vector<array<pair<int, int>, 2>> pref(n + 1), suff(n + 1);
		pair<int, int> top1, top2;
		map<int, int> cnt;

		top1 = {0, 0}, top2 = {1, 0};
		pref[0] = {top1, top2};

		for (int i = 0; i < n; i ++) {
			cnt[nums[i]] ++;
			int cur_freq = cnt[nums[i]];

			if (nums[i] == top1.first)
				top1 = {nums[i], cur_freq};
			else if (cur_freq > top1.second) {
				top2 = top1;
				top1 = {nums[i], cur_freq};
			}
			else if (nums[i] == top2.first || cur_freq > top2.second)
				top2 = {nums[i], cur_freq};

			pref[i + 1] = {top1, top2};
		}

		cnt.clear();

		top1 = {0, 0}, top2 = {1, 0};
		suff[n] = {top1, top2};

		for (int i = n - 1; i >= 0; i --) {
			cnt[nums[i]] ++;
			int cur_freq = cnt[nums[i]];

			if (nums[i] == top1.first)
				top1 = {nums[i], cur_freq};
			else if (cur_freq > top1.second) {
				top2 = top1;
				top1 = {nums[i], cur_freq};
			}
			else if (nums[i] == top2.first || cur_freq > top2.second)
				top2 = {nums[i], cur_freq};

			suff[i] = {top1, top2};
		}

		int ans = 0;
		for (int i = 0; i <= n; i ++) {
			for (auto &[x1, y1]: pref[i]) {
				for (auto &[x2, y2]: suff[i]) {
					if (y1 && y2 && x1 != x2) {
						ans = max(ans, y1 + y2);
					}
				}
			}
		}

		cout << ans << '\n';
	}

	return 0;
}
