**提示 1：** 先求最优化问题，哪些变量是重要的？

怎么求最优的 $K,B$ 呢？分别求偏导，根据偏导为 $0$ 列方程即可。这是个经典的岭回归。

接下来再代入 $x$ 即可得到预测值。

前面的 $K,B$ 只跟 $\sum x,\sum y, \sum xy,\sum x^2,\lambda$ 有关，前面的都是区间和，因此可以前缀和维护。

时间复杂度为 $\mathcal{O}(\log\epsilon^{-1})$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()

    acc_x = [0] * (n + 1)
    acc_y = [0] * (n + 1)
    acc_x2 = [0] * (n + 1)
    acc_xy = [0] * (n + 1)

    for i in range(n):
        x, y = LFI()
        acc_x[i + 1] = acc_x[i] + x
        acc_y[i + 1] = acc_y[i] + y
        acc_x2[i + 1] = acc_x2[i] + x * x
        acc_xy[i + 1] = acc_xy[i] + x * y

    q = II()
    outs = []

    for _ in range(q):
        l, r, lamb, x = LI()
        l = int(l) - 1
        r = int(r)
        lamb = float(lamb)
        x = float(x)

        vx = acc_x[r] - acc_x[l]
        vy = acc_y[r] - acc_y[l]
        vx2 = acc_x2[r] - acc_x2[l]
        vxy = acc_xy[r] - acc_xy[l]

        delta = (vx2 + lamb) * (r - l + lamb) - vx * vx
        k = ((r - l + lamb) * vxy - vx * vy) / delta
        b = ((vx2 + lamb) * vy - vx * vxy) / delta

        outs.append(k * x + b)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	vector<double> acc_x(n + 1, 0), acc_y(n + 1, 0), acc_xy(n + 1, 0), acc_x2(n + 1, 0);

	for (int i = 0; i < n; i ++) {
		string sx, sy;
		cin >> sx >> sy;
		double x = stod(sx), y = stod(sy);

		acc_x[i + 1] = acc_x[i] + x;
		acc_y[i + 1] = acc_y[i] + y;
		acc_xy[i + 1] = acc_xy[i] + x * y;
		acc_x2[i + 1] = acc_x2[i] + x * x;
	}

	int q;
	cin >> q;

	cout << fixed << setprecision(10);

	while (q --) {
		int l, r;
		string s_lambda, s_x;
		cin >> l >> r >> s_lambda >> s_x; l --;
		double lambda = stod(s_lambda), x = stod(s_x);

		double vx = acc_x[r] - acc_x[l];
		double vy = acc_y[r] - acc_y[l];
		double vxy = acc_xy[r] - acc_xy[l];
		double vx2 = acc_x2[r] - acc_x2[l];

		double delta = (vx2 + lambda) * (r - l + lambda) - vx * vx;
		double k = ((r - l + lambda) * vxy - vx * vy) / delta;
		double b = ((vx2 + lambda) * vy - vx * vxy) / delta;

		cout << k * x + b << '\n';
	}

	return 0;
}
```

**提示 1：** 考虑将数字从小到大插入数组。

看提示。

最小的元素安排完了之后，中间有 $x$ 个位置需要填入比它大 $1$ 的元素，设有 $y$ 个，则填入的方案数等于将 $y$ 分为 $x$ 个非空组的方案数，乘以 $y$ 个元素的排列。前者可以用隔板法算出来方案数。

而此时，新的需要填入元素的位置变为 $y-x$ ，我们再填入比这个元素大 $1$ 的元素即可。

最后，遍历完全部元素时，需要剩余的填入位置的数量为 $0$ ，否则一定无法构造。

最后，我们可以旋转整个数组得到新的数组，因此方案数除以最小值数量再乘以 $n$ 。因为我们一开始的计算方式只考虑了最小值得是第一项，所以剩余的非最小值开头的还得算进来，总数量和最小值在开头的数组的比例为 $n:x$ 。

时间复杂度为 $\mathcal{O}(n+M)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    nums = LII()

    M = 10 ** 6 + 5
    mod = 998244353

    f = Factorial(n, mod)

    cnt = [0] * M
    for x in nums:
        cnt[x] += 1

    mi = min(nums)
    ma = max(nums)

    ans = f.fac(cnt[mi])
    neighbors = cnt[mi]

    for i in range(mi + 1, ma + 1):
        if cnt[i] < neighbors:
            ans = 0
            break

        ans = ans * f.fac(cnt[i]) % mod
        ans = ans * f.combi(cnt[i] - 1, neighbors - 1) % mod

        neighbors = cnt[i] - neighbors

    if neighbors == 0: print(ans * n % mod * f.inv(cnt[mi]) % mod)
    else: print(0)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	int M = 1e6 + 5, mod = 998244353;

	vector<int> f(n + 1), g(n + 1);
	f[0] = 1;
	for (int i = 1; i <= n; i ++) f[i] = 1ll * i * f[i - 1] % mod;
	g[n] = quickPow(f[n], mod - 2, mod);
	for (int i = n; i >= 1; i --) g[i - 1] = 1ll * i * g[i] % mod;

	vector<int> cnt(M, 0);
	int mi = M, ma = 0;

	for (int i = 0; i < n; i ++) {
		int x;
		cin >> x;
		mi = min(x, mi);
		ma = max(x, ma);
		cnt[x] ++;
	}

	int ans = f[cnt[mi]], neighbors = cnt[mi];

	for (int i = mi + 1; i <= ma; i ++) {
		if (cnt[i] < neighbors) {
			ans = 0;
			break;
		}

		ans = 1ll * ans * f[cnt[i]] % mod * f[cnt[i] - 1] % mod * g[neighbors - 1] % mod * g[cnt[i] - neighbors] % mod;

		neighbors = cnt[i] - neighbors;
	}

	if (!neighbors) cout << 1ll * ans * n % mod * f[cnt[mi] - 1] % mod * g[cnt[mi]] % mod;
	else cout << 0;

	return 0;
}
```

**提示 1：** 将求和式拆分为若干部分。

因为不同的 $p_i$ 的数值之间关系太小了，所以不如单独考虑每个 $p_i$ 。

我们求所有 $p_i=k$ 的部分对答案的贡献，则贡献数值是 $k^2$ 乘 $p_i=V$ 的出现次数之和。

出现次数之和也不好求，我们可以转而求出现次数大于等于 $1,2,\dots,k$ 的方案数之和。

为此，对于出现次数大于等于 $i$ 的方案数，我们只需求和为 $n-iV$ 的 $k-i$ 个元素的方案数。

这件事可以 DP 来求，设 $x$ 个元素和为 $y$ 的方案数为 $dp[x][y]$ ，其中各个元素不记顺序。

则我们考虑集合的构造方式是通过两个步骤进行的 —— 所有元素 $+1$ ，新增元素 $1$ 。容易发现，每个多元集合一一对应于一个操作序列。

所以 $dp[x][y]=dp[x][y-x]+dp[x-1][y-1]$ ，于是可以平方量级解决。

同时这题给的空间不大，可以滚动数组优化空间。

时间复杂度为 $\mathcal{O}(nk)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, k = MII()
    mod = 10 ** 9 + 7

    ans = 0
    dp = [0] * (n + 1)
    dp[0] = 1

    for i in range(k):
        ndp = [0] * (n + 1)

        for j in range(n + 1):
            if i and i + j <= n:
                dp[i + j] += dp[j]
                dp[i + j] %= mod
            if i + 1 <= n and j + 1 <= n:
                ndp[j + 1] += dp[j]
                ndp[j + 1] %= mod

        y = k - i
        for x in range(1, n // y + 1):
            ans += x * x * dp[n - y * x] % mod
            ans %= mod

        dp = ndp

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, k, mod = 1e9 + 7;
	cin >> n >> k;

	int ans = 0;

	vector<int> dp(n + 1, 0);
	dp[0] = 1;

	for (int i = 0; i < k; i ++) {
		vector<int> ndp(n + 1, 0);

		for (int j = 0; j <= n; j ++) {
			if (i && i + j <= n) dp[i + j] = (dp[i + j] + dp[j]) % mod;
			if (i + 1 <= n && j + 1 <= n) ndp[j + 1] = (ndp[j + 1] + dp[j]) % mod;
		}

		int y = k - i;
		for (int x = 1; x <= n / y; x ++) ans = (ans + 1ll * x * x * dp[n - y * x]) % mod;

		dp.swap(ndp);
	}

	cout << ans;

	return 0;
}
```

**提示 1：** 这是个字符串题。

我们只需判断是否下面的字符串 $T$ 的旋转字符串是否是已知字符串 $S$ 。

为此，只需判断 $T$ 是否是 $S+S$ 的子串即可。这相当于是把原本旋转字符串的环断为一条链来方便判断。

这件事用 KMP 等方式都能快速解决。

你也可以开头将 $n$ 个旋转字符串插入到一个字典树中，后面判断，从正确性上来说也是可行的，虽然可能时间空间上会不太好。

时间复杂度为 $\mathcal{O}(nm)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    def prep(p):
        pi = [0] * len(p)
        j = 0
        for i in range(1, len(p)):
            while j != 0 and p[j] != p[i]:
                j = pi[j - 1]
            if p[j] == p[i]:
                j += 1
            pi[i] = j
        return pi

    n, m = MII()
    nums = LII()

    for i in range(1, n + 1):
        if m in prep(LII() + [-1] + nums + nums):
            print(i)
            break
    else:
        print(-1)
```

C++ 做法如下——

```cpp []
vector<int> prep(const vector<int> &p) {
    vector<int> pi(p.size(), 0);
    int j = 0;
    for (int i = 1; i < (int)p.size(); i++) {
        while (j != 0 && p[j] != p[i])
            j = pi[j - 1];
        if (p[j] == p[i])
            j ++;
        pi[i] = j;
    }
    return pi;
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, m;
	cin >> n >> m;

	vector<int> nums(m);
	for (auto &x: nums) cin >> x;

	for (int i = 1; i <= n; i ++) {
		vector<int> vals(m);
		for (auto &x: vals) cin >> x;
		vals.emplace_back(-1);
		vals.insert(vals.end(), nums.begin(), nums.end());
		vals.insert(vals.end(), nums.begin(), nums.end());

		auto kmp = prep(vals);
		for (auto &v: kmp) if (v == m) return cout << i, 0;
	}

	cout << -1;

	return 0;
}
