**提示 1：** 先看存活下来的人需要满足什么条件。

**提示 2：** 最大化存活的人。应该按照什么步骤进行？

先看提示 1 。将图中的刺杀关系看成一系列边。需要满足条件的是，边上两点不能同时存活。

而我们可以先让所有最终准备存活的人先操作，这样就构造出了合法的顺序。

接下来，我们将上述边画在一个图上，这个基环树问题如何最优化呢？

对于环上每个点连出来的一棵树，我们可以用树 DP 得到这棵树根节点存活 / 不存活的情况下，这棵子树最多存活多少人。

接下来，环上也不能有相邻结点存活，因此假设环上有 $k$ 个结点，第一个和最后一个中总有一个是不存活的，枚举这个元素，剩余部分就是可以线性 DP 解决的问题了，状态是到第 $i$ 个位置，最后一个位置存活 / 不存活的情况下最大总存活人数。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    graph = LGMI()

    rev_graph = [[] for _ in range(n)]
    for i in range(n):
        rev_graph[graph[i]].append(i)

    indeg = [0] * n
    for x in graph:
        indeg[x] += 1

    stk = [i for i in range(n) if indeg[i] == 0]
    while stk:
        u = stk.pop()
        indeg[graph[u]] -= 1
        if indeg[graph[u]] == 0:
            stk.append(graph[u])

    vis = [0] * n

    dp0 = [0] * n
    dp1 = [0] * n

    ans = 0

    for i in range(n):
        if indeg[i] and not vis[i]:
            cycle = [i]
            vis[i] = 1

            while graph[cycle[-1]] != i:
                cycle.append(graph[cycle[-1]])
                vis[cycle[-1]] = 1

            v0s = []
            v1s = []

            for u in cycle:
                que = [u]
                for x in que:
                    for y in rev_graph[x]:
                        if not vis[y]:
                            vis[y] = 1
                            que.append(y)

                for x in reversed(que):
                    dp1[x] = 1
                    for y in rev_graph[x]:
                        if indeg[y] == 0:
                            dp0[x] += fmax(dp0[y], dp1[y])
                            dp1[x] += dp0[y]

                v0s.append(dp0[u])
                v1s.append(dp1[u])

            k = len(v0s)
            res = 0

            val0 = 0
            val1 = 0

            for i in range(1, k):
                val0, val1 = fmax(val0, val1) + v0s[i], val0 + v1s[i]

            res = fmax(res, v0s[0] + fmax(val0, val1))

            val0 = 0
            val1 = 0

            for i in range(k - 1):
                val0, val1 = fmax(val0, val1) + v0s[i], val0 + v1s[i]

            res = fmax(res, v0s[-1] + fmax(val0, val1))

            ans += res

    print(n - ans)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	vector<int> graph(n);
	for (auto &x: graph) {
		cin >> x;
		x --;
	}

	vector<vector<int>> rev_graph(n);
	for (int i = 0; i < n; i ++)
		rev_graph[graph[i]].emplace_back(i);

	vector<int> indeg(n, 0);
	for (int x : graph)
		indeg[x] ++;

	vector<int> stk;
	for (int i = 0; i < n; i ++)
		if (indeg[i] == 0) stk.emplace_back(i);

	while (!stk.empty()) {
		int u = stk.back(); stk.pop_back();
		indeg[graph[u]] --;
		if (indeg[graph[u]] == 0)
			stk.emplace_back(graph[u]);
	}

	vector<int> vis(n, 0);
	int ans = 0;

	auto dfs = [&] (auto &self, int u) -> pair<int, int> {
		int v0 = 0, v1 = 1;
		for (auto &v: rev_graph[u]) {
			if (!vis[v]) {
				auto [x0, x1] = self(self, v);
				v0 += max(x0, x1);
				v1 += x0;
			}
		}
		return {v0, v1};
	};

	for (int i = 0; i < n; i ++) {
		if (indeg[i] && !vis[i]) {
			vector<int> cycle = {i};
			vis[i] = 1;
			while (graph[cycle.back()] != i) {
				cycle.emplace_back(graph[cycle.back()]);
				vis[cycle.back()] = 1;
			}

			vector<int> v0s, v1s;

			for (auto &u: cycle) {
				auto [v0, v1] = dfs(dfs, u);
				v0s.emplace_back(v0);
				v1s.emplace_back(v1);
			}

			int k = v0s.size();
			int res = 0;

			int val0 = 0, val1 = 0;
			for (int j = 1; j < k; j ++) {
				int nv0 = max(val0, val1) + v0s[j];
				int nv1 = val0 + v1s[j];
				val0 = nv0; val1 = nv1;
			}
			res = max(res, v0s[0] + max(val0, val1));

			val0 = 0; val1 = 0;
			for (int j = 0; j < k - 1; j ++) {
				int nv0 = max(val0, val1) + v0s[j];
				int nv1 = val0 + v1s[j];
				val0 = nv0; val1 = nv1;
			}
			res = max(res, v0s[k - 1] + max(val0, val1));

			ans += res;
		}
	}

	cout << n - ans;

	return 0;
}
```

**提示 1：** 最小的边数如何？所以实际求的是什么？

最少边数是 $n$ ，因为直接构造一个环就好。

所以我们要找最小权值的遍历 $n$ 个点的环，这是典型的旅行商问题，可以用 bitmask DP 解决。

时间复杂度为 $\mathcal{O}(n^2 2^n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():  
    n = II()
    grid = [LII() for _ in range(n)]

    if n == 1:
        print(0)
    else:
        inf = 10 ** 9
        dp = [[inf] * (1 << n) for _ in range(n)]
        dp[0][1] = 0

        for i in range(1 << n):
            for j in range(n):
                if dp[j][i] < inf:
                    for nj in range(n):
                        if i >> nj & 1: continue
                        ni = i | (1 << nj)
                        dp[nj][ni] = fmin(dp[nj][ni], dp[j][i] + grid[j][nj])

        print(min(dp[i][(1 << n) - 1] + grid[i][0] for i in range(n)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	vector<vector<int>> grid(n, vector<int>(n));
	for (auto &x: grid) for (auto &y: x) cin >> y;

	if (n == 1) return cout << 0, 0;

	int inf = 1e9;
	vector<vector<int>> dp(n, vector<int>(1 << n, inf));

	dp[0][1] = 0;

	for (int i = 0; i < (1 << n); i ++) {
		for (int j = 0; j < n; j ++) {
			if (dp[j][i] < inf) {
				for (int nj = 0; nj < n; nj ++) {
					if (i >> nj & 1) continue;
					int ni = i | (1 << nj);
					dp[nj][ni] = min(dp[nj][ni], dp[j][i] + grid[j][nj]);
				}
			}
		}
	}

	int ans = inf;
	for (int i = 1; i < n; i ++) ans = min(ans, dp[i][(1 << n) - 1] + grid[i][0]);

	cout << ans;

	return 0;
}
```

**提示 1：** 需要维护什么？

我们要查询的是区间中的概率乘积，以及选其中一个为 $1-p$ 的概率的乘积之和。

我们可以使用线段树，分别维护两者。设两者为 $x,y$ ，则 $(x_1,y_1),(x_2,y_2)$ 合并的结果是 $(x_1x_2,x_1y_2+x_2y_1)$ 。

也可以考虑先求概率乘积，则将上述求的结果除以概率乘积，发现求的实际上是 $\frac{1-p}{p}$ 的区间和，这件事很明显也可以树状数组维护。

上面两个做法都比较容易。

时间复杂度为 $\mathcal{O}(n+q\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, q = MII()
    nums = LII()

    mod = 10 ** 9 + 7
    revs = [0] + [pow(i, -1, mod) for i in range(1, 101)]

    probs = [0] * n
    vals = [0] * n

    for i in range(n):
        probs[i] = (100 - nums[i]) * revs[100] % mod
        vals[i] = nums[i] * revs[100 - nums[i]] % mod

    seg = SegTree(lambda x, y: x * y % mod, 1, probs)
    fen = FenwickTree(n)

    for i in range(n):
        fen.add(i, vals[i])

    outs = []
    for _ in range(q):
        query = LII()

        if query[0] == 1:
            idx = query[1] - 1
            val = query[2]

            seg.set(idx, (100 - val) * revs[100] % mod)
            fen.add(idx, val * revs[100 - val] % mod - nums[idx] * revs[100 - nums[idx]] % mod)

            nums[idx] = val

        else:
            outs.append((1 + fen.rsum(query[1], n - 1) % mod) * seg.prod(query[1], n) % mod)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, q;
	cin >> n >> q;

	vector<int> revs(101);
	for (int i = 1; i <= 100; i ++)
		revs[i] = quickPow(i, mod - 2, mod);

	vector<int> nums(n), probs(n);
	atcoder::fenwick_tree<long long> vals(n);

	for (int i = 0; i < n; i ++) {
		cin >> nums[i];
		probs[i] = 1ll * (100 - nums[i]) * revs[100] % mod;
		vals.add(i, 1ll * nums[i] * revs[100 - nums[i]] % mod);
	}

	atcoder::segtree<int, op, e> seg(probs);

	while (q --) {
		int t;
		cin >> t;

		if (t == 1) {
			int idx, val;
			cin >> idx >> val;
			idx --;

			seg.set(idx, 1ll * (100 - val) * revs[100] % mod);
			vals.add(idx, 1ll * val * revs[100 - val] % mod - 1ll * nums[idx] * revs[100 - nums[idx]] % mod);

			nums[idx] = val;
		}
		else {
			int idx;
			cin >> idx;
			cout << (vals.sum(idx, n) + 1) % mod * seg.prod(idx, n) % mod << '\n';
		}
	}

	return 0;
}
