**提示 1：** 解决其中一个类型，同时让另一个类型受的影响尽可能小。

我们先解决第一类型的对手的怪物。

此时，我们从大到小一一消灭。我们先得到所有能干掉它的我们自己的怪物，此时，我们应该用哪个消灭它呢？

我们应该用对第二类型怪物的伤害最小的怪物去消灭它。

以此类推，我们分别拿剩余的对第二类型怪物的伤害最小的怪物去分别消灭各个对手。如果某一次我们已经派不出怪物了，则无法构造。

这件事可以根据第一个伤害从大到小排序，然后用一个可以提取最小值的数据结构进行增删（堆即可）。最后堆中剩下的就是处理第二个类型怪物的那些了。

再从小到大一一匹配即可。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    t = II()
    outs = []

    for _ in range(t):
        n = II()
        v1 = []
        v2 = []

        for _ in range(n):
            p, s = MII()
            if s == 0:
                v1.append(2 * p)
                v2.append(p)
            else:
                v1.append(p)
                v2.append(2 * p)

        x1 = []
        x2 = []

        for _ in range(n):
            p, s = MII()
            if s == 0: x1.append(p)
            else: x2.append(p)

        x1.sort()

        flg = True
        pq = []

        for i in sorted(range(n), key=lambda x: -v1[x]):
            while x1 and x1[-1] > v1[i]:
                if len(pq) == 0:
                    flg = False
                    break
                x1.pop()
                heappop(pq)
            heappush(pq, v2[i])

        while x1:
            x1.pop()
            heappop(pq)

        if not flg: outs.append('NO')
        else:
            x2.sort()

            for x in x2:
                if heappop(pq) < x:
                    flg = False

            outs.append('YES' if flg else 'NO')

    print('\n'.join(outs))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int n;
		cin >> n;

		vector<pair<int, int>> monsters;

		for (int i = 0; i < n; i ++) {
			int p, s;
			cin >> p >> s;

			if (!s) monsters.emplace_back(2 * p, p);
			else monsters.emplace_back(p, 2 * p);
		}

		vector<int> x1, x2;

		for (int i = 0; i < n; i ++) {
			int p, s;
			cin >> p >> s;

			if (!s) x1.emplace_back(p);
			else x2.emplace_back(p);
		}

		sort(x1.begin(), x1.end());

		bool flg = true;
		priority_queue<int, vector<int>, greater<int>> pq;

		sort(monsters.begin(), monsters.end(), [&] (pair<int, int> &x, pair<int, int> &y) {return x.first > y.first;});

		for (auto &[x, y]: monsters) {
			while (!x1.empty() && x1.back() > x) {
				if (pq.empty()) {
					flg = false;
					break;
				}
				x1.pop_back();
				pq.pop();
			}
			pq.push(y);
		}

		while (!x1.empty()) {
			x1.pop_back();
			pq.pop();
		}

		if (!flg) cout << "NO\n";
		else {
			sort(x2.begin(), x2.end());

			for (auto &x: x2) {
				if (pq.top() < x) flg = false;
				pq.pop();
			}

			cout << (flg ? "YES" : "NO") << '\n';
		}
	}

	return 0;
}
