C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	auto query = [&] (int i, int j) -> int {
		cout << "? " << i << ' ' << j << endl;
		char c;
		cin >> c;
		if (c == 'X') return 0;
		if (c == 'P') return 1;
		return 2;
	};

	int n, t, b;
	cin >> n >> t >> b;

	vector<vector<int>> ans(n + 1, vector<int>(n + 1, 0));
	int l = t, r = t;

	for (int i = 1; i <= n; i ++) {
		ans[1][i] = query(1, i);
		ans[n][i] = query(n, i);

		if (ans[1][i]) {
			l = min(l, i);
			r = max(r, i);
		}
	}

	for (int i = 2; i < n; i ++) {
		int l_bound = floor_div((t - b) * (i - 1), (n - 1)) + b;
		int r_bound = floor_div((t - b) * (i - 1) - 1, (n - 1)) + b;

		ans[i][l] = query(i, l);

		if (ans[i][l]) {
			while (l > 1) {
				l --;
				ans[i][l] = query(i, l);
				if (!ans[i][l]) {
					l ++;
					break;
				}
			}
		}
		else {
			while (l < lbound) {
				l ++;
				ans[i][l] = query(i, l);
				if (ans[i][l]) break;
			}
		}

		ans[i][r] = query(i, r);

		if (ans[i][r]) {
			while (r < n) {
				r ++;
				ans[i][r] = query(i, r);
				if (!ans[i][r]) {
					r --;
					break;
				}
			}
		}
		else {
			while (r > rbound) {
				r --;
				ans[i][r] = query(i, r);
				if (ans[i][r]) break;
			}
		}

		for (int j = l + 1; j < r; j ++) ans[i][j] = 2;
	}

	int area = 0;
	for (auto &x: ans) for (auto &y: x) area += y;

	cout << "! " << area - 2;

	return 0;
}
```

**提示 1：** 我们考虑第 $i$ 项时，相当于前面每个元素的出现都被算进来了。如何快速算 $x$ 前面的数的频率和？

**提示 2：** 基于预处理，怎么求答案？

先看提示 1 。

首先看每个元素的频率怎么求。发现每次相当于区间频率加一，因此可以用差分快速维护。

而利用频率再求个前缀和就是前缀频率和了。（频率的数值是一段一段的，每一段数值相同）

最后，对于每个查询，我们相当于要找到答案位于哪一段，因此前面有一些整段需要跳过。为此，找到前缀频率和中比当前查询更小的位置，则答案就是这一段中的了。是这一段中的哪一个呢？只与多出来的数以及这一段的频率有关。

时间复杂度为 $\mathcal{O}(n\log n+q\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n, q = MII()

    ls = []
    rs = []
    seps = []

    for _ in range(n):
        l, r = MII()
        ls.append(l)
        rs.append(r)
        seps.append(l)
        seps.append(r + 1)

    seps.sort()

    k = len(seps)
    diff = [0] * k

    for i in range(n):
        diff[bisect.bisect_left(seps, ls[i])] += 1
        diff[bisect.bisect_left(seps, rs[i] + 1)] -= 1

    for i in range(1, k):
        diff[i] += diff[i - 1]

    acc = [0] * k
    for i in range(k - 1):
        acc[i + 1] = acc[i] + diff[i] * (seps[i + 1] - seps[i])

    queries = LII()
    outs = []

    for x in queries:
        x -= 1
        p = bisect.bisect_right(acc, x) - 1
        outs.append(seps[p] + (x - acc[p]) // diff[p])

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, q;
	cin >> n >> q;

	vector<pair<int, int>> intervals(n);
	vector<int> seps;

	for (auto &[l, r]: intervals) {
		cin >> l >> r;
		seps.emplace_back(l);
		seps.emplace_back(r + 1);
	}

	sort(seps.begin(), seps.end());

	int k = seps.size();
	vector<int> diff(k, 0);

	for (auto [l, r]: intervals) {
		diff[lower_bound(seps.begin(), seps.end(), l) - seps.begin()] ++;
		diff[lower_bound(seps.begin(), seps.end(), r + 1) - seps.begin()] --;
	}

	for (int i = 1; i < k; i ++) diff[i] += diff[i - 1];

	vector<long long> acc(k, 0);
	for (int i = 0; i < k - 1; i ++)
		acc[i + 1] = acc[i] + 1ll * diff[i] * (seps[i + 1] - seps[i]);

	while (q --) {
		long long x;
		cin >> x; x --;

		int p = upper_bound(acc.begin(), acc.end(), x) - acc.begin() - 1;
		cout << seps[p] + (x - acc[p]) / diff[p] << '\n';
	}

	return 0;
}
```

**提示 1：** $k$ 个一循环，所以考虑 $k$ 步后到哪里。

**提示 2：** 不同情况，如何理解？

首先看提示 1，我们对每个格子先进行模拟。

如果在模拟的过程中已经到了 $S$ ，则标记。否则假设从 $x$ 格子到了 $y$ 。

接下来对这些位置连从 $x$ 到 $y$ 的有向边，也就是我们要看每个点能否到达 $S$ 。

一种直接的方式是建反图，看 $S$ 出发能到达哪些位置。

但实际上这个图中不存在环，所以可以直接将图视为无向图，看每个连通部分里是否有 $S$ 。这件事也有更快的办法——把所有 $S$ 连向一个虚拟结点，这样只需判是否跟虚拟节点在同一个连通块即可。

时间复杂度为 $\mathcal{O}(n^2m)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    d = {'.': 0, 'S': 1, '#': 2}
    dir = {
        'N': (-1, 0),
        'S': (1, 0),
        'W': (0, -1),
        'E': (0, 1)
    }

    n, m = MII()
    grid = [[d[c] for c in I()] for _ in range(n)]
    s = [dir[c] for c in I()]

    uf = UnionFind(n * n + 1)

    def f(i, j): return i * n + j

    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                uf.merge(f(i, j), n * n)

            elif grid[i][j] == 0:
                x, y = i, j

                for dx, dy in s:
                    nx = x + dx
                    ny = y + dy
                    if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] != 2:
                        x = nx
                        y = ny
                        if grid[nx][ny] == 1:
                            break

                uf.merge(f(i, j), f(x, y))

    ans = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if uf.find(f(i, j)) == uf.find(n * n):
                ans[i][j] = 1

    print('\n'.join(''.join(map(str, x)) for x in ans))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	vector<pair<int, int>> dirs(300);
	dirs['N'] = {-1, 0};
	dirs['S'] = {1, 0};
	dirs['W'] = {0, -1};
	dirs['E'] = {0, 1};

	int n, m;
	cin >> n >> m;

	vector<string> grid(n);
	for (auto &s: grid) cin >> s;

	string op;
	cin >> op;

	atcoder::dsu uf(n * n + 1);
	auto f = [&] (int i, int j) {return i * n + j;};

	for (int i = 0; i < n; i ++) {
		for (int j = 0; j < n; j ++) {
			if (grid[i][j] == 'S') uf.merge(f(i, j), n * n);
			else if (grid[i][j] == '.') {
				int x = i, y = j;

				for (auto &ch: op) {
					auto [dx, dy] = dirs[ch];
					int nx = x + dx, ny = y + dy;

					if (nx >= 0 && nx < n && ny >= 0 && ny < n && grid[nx][ny] != '#') {
						x = nx, y = ny;
						if (grid[x][y] == 'S') break;
					}
				}

				uf.merge(f(i, j), f(x, y));
			}
		}
	}

	vector<string> ans(n, string(n, '0'));

	for (int i = 0; i < n; i ++) {
		for (int j = 0; j < n; j ++) {
			if (uf.leader(f(i, j)) == uf.leader(n * n)) {
				ans[i][j] = '1';
			}
		}
	}

	for (auto &x: ans) cout << x << '\n';

	return 0;
}
