**提示 1：** 每一个空缺步骤的可选集很小。

**提示 2：** 考虑成图论问题的话，是什么问题？

首先，给出的步骤之间只隔了两步，同时不会有重复，所以曼哈顿距离一定是 $2$ 。一旦有不满足的直接就输出 $0$ 。

否则，可选点集大小不超过 $2$ 。我们将两个点相连形成一条边（如果只有一个点就连自环）。

我们在这个图中，每条边钦定一个端点，使得端点的选择不重合。

考虑每个连通块。最后答案方案数就是每个连通块的答案的乘积。

如果连通块中不止包含一个环，则边数大于点数，直接点不够用了，矛盾。

如果只有一个环——如果是自环，则这个环只有一种选法，剩余的点都确定了，所以只有一种方案；否则，环大小不小于 $2$ ，环上的分配点方案有 $2$ 种，外侧的边只有一种分配方式。

如果没有环，也就是是一棵树，此时可以任选一点为空，其余的分配也就确定了。所以方案数等于点数。

时间复杂度为 $\mathcal{O}(nm+k)$ ，如果你用 BFS / DFS 来处理中间的部分，当然用并查集实现似乎更好写。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    t = II()
    outs = []

    mod = 10 ** 9 + 7

    for _ in range(t):
        n, m, k = MII()
        xs = []
        ys = []

        for _ in range(k + 1):
            x, y = GMI()
            xs.append(x)
            ys.append(y)

        flg = True
        for i in range(k):
            if abs(xs[i + 1] - xs[i]) + abs(ys[i + 1] - ys[i]) != 2:
                flg = False

        if not flg: outs.append(0)
        else:
            uf = UnionFind(n * m)
            edge_cnt = [0] * (n * m)
            self_cycle = [0] * (n * m)

            def f(x, y):
                return x * m + y

            for i in range(k):
                x1, y1 = xs[i], ys[i]
                x2, y2 = xs[i + 1], ys[i + 1]

                if x1 == x2 or y1 == y2:
                    msk = f((x1 + x2) // 2, (y1 + y2) // 2)
                    edge_cnt[msk] += 1
                    self_cycle[msk] = 1
                else:
                    msk1 = f(x1, y2)
                    msk2 = f(x2, y1)
                    uf.merge(msk1, msk2)
                    edge_cnt[msk1] += 1

            for i in range(n * m):
                if uf.find(i) != i:
                    edge_cnt[uf.find(i)] += edge_cnt[i]
                    self_cycle[uf.find(i)] |= self_cycle[i]

            ans = 1
            for i in range(n * m):
                if uf.find(i) == i:
                    if edge_cnt[i] > uf.getSize(i):
                        ans = 0
                    elif edge_cnt[i] == uf.getSize(i):
                        if not self_cycle[i]:
                            ans = ans * 2 % mod
                    else:
                        ans = ans * uf.getSize(i) % mod

            outs.append(ans)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t, mod = 1e9 + 7;
	cin >> t;

	while (t --) {
		int n, m, k;
		cin >> n >> m >> k;

		vector<pair<int, int>> pts(k + 1);
		for (auto &[x, y]: pts) {
			cin >> x >> y;
			x --, y --;
		}

		bool flg = true;
		for (int i = 0; i < k; i ++) {
			auto [x1, y1] = pts[i];
			auto [x2, y2] = pts[i + 1];
			if (abs(x1 - x2) + abs(y1 - y2) != 2) flg = false;
		}

		if (!flg) cout << 0 << '\n';
		else {
			atcoder::dsu uf(n * m);
			vector<int> edge_cnt(n * m, 0), self_cycle(n * m, 0);

			auto f = [&] (int x, int y) -> int {return x * m + y;};

			for (int i = 0; i < k; i ++) {
				auto [x1, y1] = pts[i];
				auto [x2, y2] = pts[i + 1];

				if (x1 == x2 || y1 == y2) {
					int msk = f((x1 + x2) / 2, (y1 + y2) / 2);
					edge_cnt[msk] ++;
					self_cycle[msk] = 1;
				}
				else {
					int msk1 = f(x1, y2);
					int msk2 = f(x2, y1);
					uf.merge(msk1, msk2);
					edge_cnt[msk1] ++;
				}
			}

			for (int i = 0; i < n * m; i ++) {
				if (uf.leader(i) != i) {
					edge_cnt[uf.leader(i)] += edge_cnt[i];
					self_cycle[uf.leader(i)] |= self_cycle[i];
				}
			}

			int ans = 1;
			for (int i = 0; i < n * m; i ++) {
				if (uf.leader(i) == i) {
					if (edge_cnt[i] > uf.size(i)) ans = 0;
					else if (edge_cnt[i] == uf.size(i)) {
						if (!self_cycle[i]) ans = 2 * ans % mod;
					}
					else ans = 1ll * uf.size(i) * ans % mod;
				}
			}

			cout << ans << '\n';
		}
	}

	return 0;
}
```

**提示 1：** 考虑 SG 函数。 Bob 什么情况下胜利？

**提示 2：** SG 函数数值不大，如何借此优化？

考虑博弈论的 SG 函数，Bob 胜利当且仅当两个数的 SG 函数结果相同。

所以我们如果能够预处理 $1\sim 5\times 10^6$ 的 SG 函数，则我们只需统计 SG 函数不同的元素对个数即可，可以用整体的数量减去相等的元素对个数。而后者就方便多了，直接统计每个元素的出现频率即可。

先给出一个相对慢的做法。我们直接枚举这个数的因子，取其 SG 函数的 MEX 来直接暴力计算。我们发现，SG 函数最大值并不大。

因此集合的操作可以用整数表示。我们可以用 $i$ 直接整数操作更新 $2i,3i,\dots$ ，这样就是小常数的 $\mathcal{O}(M\log M)$ 的复杂度了。

还可以进一步优化理论复杂度。我们可以对一个 $i$ 枚举质因子 $p$ ，则 $i/p$ 用于计算 MEX 的集合在 $i$ 的结果计算中也可以用到——所以我们将每个质数对应的 $i/p$ 的集合取或，再加上所有形如 $i/p$ 的因子，也就考虑完了所有的因子的 SG 函数，就是整体需要考虑的集合了。

时间复杂度为 $\mathcal{O}(M\log\log M)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    M = 5 * 10 ** 6 + 1
    pr = list(range(M))

    for i in range(2, M):
        if pr[i] == i:
            for j in range(i, M, i):
                pr[j] = i

    sg_vis = [0] * M
    sg = [0] * M

    for i in range(1, M):
        cur = i

        while cur > 1:
            sg_vis[i] |= sg_vis[i // pr[cur]] | (1 << sg[i // pr[cur]])
            cur //= pr[cur]

        x = ~sg_vis[i]
        x &= -x

        sg[i] = x.bit_length() - 1

    m, n, x, y = MII()

    c1 = [0] * 30
    c2 = [0] * 30

    for i in range(x + 1):
        c1[sg[m - i]] += 1

    for i in range(y + 1):
        c2[sg[n - i]] += 1

    ans = (x + 1) * (y + 1)
    for i in range(30):
        ans -= c1[i] * c2[i]

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t, mod = 1e9 + 7;
	cin >> t;

	while (t --) {
		int n, m, k;
		cin >> n >> m >> k;

		vector<pair<int, int>> pts(k + 1);
		for (auto &[x, y]: pts) {
			cin >> x >> y;
			x --, y --;
		}

		bool flg = true;
		for (int i = 0; i < k; i ++) {
			auto [x1, y1] = pts[i];
			auto [x2, y2] = pts[i + 1];
			if (abs(x1 - x2) + abs(y1 - y2) != 2) flg = false;
		}

		if (!flg) cout << 0 << '\n';
		else {
			atcoder::dsu uf(n * m);
			vector<int> edge_cnt(n * m, 0), self_cycle(n * m, 0);

			auto f = [&] (int x, int y) -> int {return x * m + y;};

			for (int i = 0; i < k; i ++) {
				auto [x1, y1] = pts[i];
				auto [x2, y2] = pts[i + 1];

				if (x1 == x2 || y1 == y2) {
					int msk = f((x1 + x2) / 2, (y1 + y2) / 2);
					edge_cnt[msk] ++;
					self_cycle[msk] = 1;
				}
				else {
					int msk1 = f(x1, y2);
					int msk2 = f(x2, y1);
					uf.merge(msk1, msk2);
					edge_cnt[msk1] ++;
				}
			}

			for (int i = 0; i < n * m; i ++) {
				if (uf.leader(i) != i) {
					edge_cnt[uf.leader(i)] += edge_cnt[i];
					self_cycle[uf.leader(i)] |= self_cycle[i];
				}
			}

			int ans = 1;
			for (int i = 0; i < n * m; i ++) {
				if (uf.leader(i) == i) {
					if (edge_cnt[i] > uf.size(i)) ans = 0;
					else if (edge_cnt[i] == uf.size(i)) {
						if (!self_cycle[i]) ans = 2 * ans % mod;
					}
					else ans = 1ll * uf.size(i) * ans % mod;
				}
			}

			cout << ans << '\n';
		}
	}

	return 0;
}
```

**提示 1：** 如果我们能用 $d$ 从 $1$ 走到 $v$ ， $d$ 需要满足什么条件？

**提示 2：** 如何分配梯子？

先看提示 1 。如果我们找到一条路径，则 $d$ 至少是这条路径上的边权的最大值。

所以我们只需求这个数值的最小值即可，发现可以直接用最短路来求。

于是每天的任务我们都有一个最小梯子长度。接下来是分配梯子。

我们只需从小到大 / 从大到小依次匹配梯子即可。（指的是小需求匹配小梯子，大需求匹配大梯子）

时间复杂度为 $\mathcal{O}(m+n\log m+d\log d)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n, m = MII()
    path = [[] for _ in range(n)]

    for _ in range(m):
        u, v, w = MII()
        u -= 1
        v -= 1
        path[u].append(w * n + v)
        path[v].append(w * n + u)

    inf = 2 * 10 ** 9
    dis = [inf] * n
    dis[0] = 0

    pq = [0]

    while pq:
        d, u = divmod(heappop(pq), n)

        if dis[u] == d:
            for msk in path[u]:
                w, v = divmod(msk, n)
                if dis[v] > fmax(d, w):
                    dis[v] = fmax(d, w)
                    heappush(pq, dis[v] * n + v)

    d = II()
    v1 = [dis[x] for x in GMI()]
    v2 = LII()

    v1.sort()
    v2.sort()

    ans = 0
    for i in range(d - 1, -1, -1):
        if v1[i] <= v2[-1]:
            ans += 1
            v2.pop()

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, m;
	cin >> n >> m;

	vector<vector<pair<int, int>>> path(n);
	while (m --) {
		int u, v, w;
		cin >> u >> v >> w;
		u --, v --;
		path[u].emplace_back(v, w);
		path[v].emplace_back(u, w);
	}

	vector<int> dis(n, 2'000'000'000);
	dis[0] = 0;

	priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
	pq.push({0, 0});

	while (!pq.empty()) {
		auto [d, u] = pq.top(); pq.pop();
		if (dis[u] == d) {
			for (auto &[v, w]: path[u]) {
				if (max(w, d) < dis[v]) {
					dis[v] = max(w, d);
					pq.push({dis[v], v});
				}
			}
		}
	}

	int d;
	cin >> d;

	vector<int> v1(d), v2(d);
	for (auto &x: v1) cin >> x, x = dis[x - 1];
	for (auto &x: v2) cin >> x;

	sort(v1.begin(), v1.end());
	sort(v2.begin(), v2.end());

	int ans = 0;
	for (int i = d - 1; i >= 0; i --) {
		if (v1[i] <= v2.back()) {
			v2.pop_back();
			ans ++;
		}
	}

	cout << ans;

	return 0;
}
```

**提示 1：** 显然 bitmask DP。过程中如何考虑逆序对和 $|i-p[i]|$ 的和？

**提示 2：** 如何让一个 DP 维度限制在 $0\sim k$ ？

如果我们目前这个数组前缀是 $msk$ ，此时来了个新数 $x$ 连着前缀，则这个新数和后面所有数形成的逆序对数是很容易确定的（即后续的数中比当前数小的数）。

而 $p$ 是排列，所以 $i-p[i]$ 求和为 $0$ ，题中的求和式等价于 $\max(i-p[i],0)$ 的和或者 $\max(p[i]-i,0)$ 的和。

所以考虑当前选取数集合为 $msk$ 时，逆序对和 $\max(p[i]-i,0)$ 的和的差为 $i$ 时的方案数量为 $dp[i][msk]$ 。

值得注意的是这两者之差始终非负。因为 $\max(p[i]-i,0)$ 的和是以 $i$ 为逆序对左端点的逆序对数量的一个更小的估计。

这样我们就保证了 DP 的一个维度是在 $[0,k]$ 之间的，总状态数也就被限制住了（虽然好像你写个 $\mathcal{O}(n^2)$ 的也能过）。

时间复杂度为 $\mathcal{O}(kn2^n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n, k = MII()
    mod = 10 ** 9 + 7

    dp = [[0] * (1 << n) for _ in range(k + 1)]
    dp[0][0] = 1

    for i in range(k + 1):
        for j in range(1 << n):
            cnt = j.bit_count()
            smaller = 0
            for bit in range(n):
                if j >> bit & 1: continue
                ni = i + smaller - fmax(bit - cnt, 0)
                nj = j | (1 << bit)
                if ni <= k:
                    dp[ni][nj] += dp[i][j]
                    dp[ni][nj] %= mod
                smaller += 1

    print(dp[k][-1])
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, k, mod = 1e9 + 7;
	cin >> n >> k;

	vector<vector<int>> dp(k + 1, vector<int>(1 << n, 0));
	dp[0][0] = 1;

	for (int i = 0; i <= k; i ++) {
		for (int j = 0; j < (1 << n); j ++) {
			int cnt = __popcount(j);
			int smaller = 0;
			for (int bit = 0; bit < n; bit ++) {
				if (j >> bit & 1) continue;
				int ni = i + smaller - max(bit - cnt, 0);
				int nj = j | (1 << bit);
				if (ni <= k)
					dp[ni][nj] = (dp[i][j] + dp[ni][nj]) % mod;
				smaller ++;
			}
		}
	}

	cout << dp[k].back();

	return 0;
}
```

**提示 1：** 更新的是什么东西？如何更新？怎么写更方便？

对于每个人的位置，我们在数组的其他位置加上这个人到该位置的距离。

这样我们更新的就是以这个点为中心的等差数列，同时更新方式是做加法。于是用差分更新。

注意这里更新的相当于是一条线段，所以我们直接理解为加一个一次函数。于是用一个差分数组表示一次项系数，一个差分数组表示常数系数，这样差分的逻辑就比较容易写对了。

同时这里环形数组，容易涉及越界问题。可以考虑复制一遍数组，断环为链，这样就能在连续的一段区间上操作了，最后再把实际相同位置的结果加起来就行。

最后取更新结果的最小值。

时间复杂度为 $\mathcal{O}(n+m)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n, m = MII()
    nums = LII()

    diff_k = [0] * (m * 2 + 1)
    diff_b = [0] * (m * 2 + 1)

    v = (m + 1) // 2

    for x in nums:
        diff_k[x] += 1
        diff_k[x + v] -= 1
        diff_b[x] -= x
        diff_b[x + v] += x

        diff_k[x + v] -= 1
        diff_k[x + m] += 1
        diff_b[x + v] += x + m
        diff_b[x + m] -= x + m

    for i in range(m * 2):
        diff_k[i + 1] += diff_k[i]
        diff_b[i + 1] += diff_b[i]

    ans = [0] * m

    for i in range(m * 2):
        ans[i % m] += diff_k[i] * i + diff_b[i]

    print(min(ans))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, m;
	cin >> n >> m;

	vector<long long> diff_k(2 * m + 1, 0), diff_b(2 * m + 1, 0);
	int v = (m + 1) / 2;

	while (n --) {
		int x;
		cin >> x;

		diff_k[x] += 1;
		diff_k[x + v] -= 1;
		diff_b[x] -= x;
		diff_b[x + v] += x;

		diff_k[x + v] -= 1;
		diff_k[x + m] += 1;
		diff_b[x + v] += x + m;
		diff_b[x + m] -= x + m;
	}

	for (int i = 0; i < 2 * m; i ++) {
		diff_k[i + 1] += diff_k[i];
		diff_b[i + 1] += diff_b[i];
	}

	vector<long long> ans(m, 0);
	for (int i = 0; i < 2 * m; i ++)
		ans[i % m] += diff_k[i] * i + diff_b[i];

	cout << *min_element(ans.begin(), ans.end());

	return 0;
}
```

**提示 1：** 我们要求的东西是什么呢？

我们要求的是从 $1$ 结点出发能够到达的平均权值最大的环的平均权值。

这个问题可以用 Karp 算法。一般而言，取 $dis[x][v]$ 为 $x$ 步到达 $v$ 的最大路径权值和，则最大的平均权值等于：

$\max_{i}\min_{j}\frac{dis[n][i]-dis[j][i]}{n-j}$

这里只能从 $1$ 结点出发，所以第一层 $dis[0]$ 的部分只有 $1$ 的位置赋初值 $0$ ，其他位置赋值负无穷。注意上述求最大路径权值和的拓展过程中一定保证拓展的起点是可以到达的位置。

时间复杂度为 $\mathcal{O}(nm)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n, m = MII()
    path = [[] for _ in range(n)]

    for _ in range(m):
        u, v, w = MII()
        u -= 1
        v -= 1
        path[u].append(w * n + v)

    inf = 10 ** 15
    dis = [[-inf] * n for _ in range(n + 1)]

    dis[0][0] = 0

    for i in range(n):
        for u in range(n):
            if dis[i][u] != -inf:
                for msk in path[u]:
                    w, v = divmod(msk, n)
                    dis[i + 1][v] = fmax(dis[i + 1][v], dis[i][u] + w)

    ans = 0
    for u in range(n):
        if dis[n][u] != -inf:
            tmp = inf
            for i in range(n):
                if dis[i][u] != -inf:
                    tmp = fmin(tmp, (dis[n][u] - dis[i][u]) / (n - i))
            ans = fmax(ans, tmp)

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, m;
	cin >> n >> m;

	vector<array<int, 3>> edges(m);
	for (auto &[u, v, w]: edges)
		cin >> u >> v >> w, u --, v --;

	long long inf = 1e15;
	vector<vector<long long>> dis(n + 1, vector<long long>(n, -inf));
	dis[0][0] = 0;

	for (int i = 0; i < n; i ++) {
		for (auto &[u, v, w]: edges) {
			if (dis[i][u] != -inf) {
				dis[i + 1][v] = max(dis[i + 1][v], dis[i][u] + w);
			}
		}
	}

	long double ans = 0;

	for (int u = 0; u < n; u ++) {
		if (dis[n][u] != -inf) {
			long double tmp = inf;
			for (int i = 0; i < n; i ++) {
				if (dis[i][u] != -inf) {
					tmp = min(tmp, (long double)(dis[n][u] - dis[i][u]) / (n - i));
				}
			}
			ans = max(ans, tmp);
		}
	}

	cout << fixed << setprecision(15) << ans;

	return 0;
}
```

