int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	vector<pair<int, int>> pts;

	for (int i = 0; i < n; i ++) {
		int x, y;
		cin >> x >> y;
		if (y - x >= 0)
			pts.emplace_back(y - x, y + x);
