int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int x, y;
		cin >> x >> y;

		if (x == y) cout << "0\n";
		else if (x < y) {
			int ans = 0;
			while (x < y) {
				x *= 2;
				ans ++;
			}
			cout << ans << '\n';
		}
		else {
			if (y <= 2) cout << "-1\n";
			else {
				int ans = 0;
				while (x > y) {
