**提示 1：** 找到合法的每一步和每一步的字母。

我们假设从 $1$ 结点出发，按照答案的路径一步步走到 $n$ 。

则这是一条最短路，也就意味着到 $n$ 的距离是严格减小的，所以我们可以预处理到 $n$ 的距离，把这个作为下一步是否合法的判断依据。

假设走到了 $u$ ，下一步合法的边是使得距离严格减小的边。在所有合法的新边中，我们只需选择最小的字符即可。此时最小的字符能到达的新的结点可能是一个集合，我们维护这个集合就好。注意可能有多条边指向同一个点，此时只能添加一遍这个点。

最后如何恢复路径呢？记录下每一步的前一步是啥就行。

时间复杂度为 $\mathcal{O}(n+m)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n, m = MII()
    us = []
    vs = []
    chs = []

    path = [[] for _ in range(n)]

    for i in range(m):
        u, v, ch = LI()
        u = int(u) - 1
        v = int(v) - 1
        path[u].append(i)
        path[v].append(i)
        us.append(u)
        vs.append(v)
        chs.append(ord(ch))

    dis = [-1] * n
    que = [n - 1]
    dis[n - 1] = 0

    for u in que:
        for eid in path[u]:
            v = us[eid] ^ vs[eid] ^ u
            if dis[v] == -1:
                dis[v] = dis[u] + 1
                que.append(v)

    parent = [-1] * n

    s = []
    cur = [0]

    while cur[0] != n - 1:
        min_ch = 128
        for u in cur:
            for eid in path[u]:
                v = us[eid] ^ vs[eid] ^ u
                if dis[v] == dis[u] - 1:
                    min_ch = fmin(min_ch, chs[eid])

        s.append(min_ch)

        ncur = []
        for u in cur:
            for eid in path[u]:
                v = us[eid] ^ vs[eid] ^ u
                if dis[v] == dis[u] - 1 and chs[eid] == min_ch and parent[v] == -1:
                    ncur.append(v)
                    parent[v] = u

        cur = ncur

    print(len(s))

    ans = [n - 1]
    while ans[-1] != 0:
        ans.append(parent[ans[-1]])

    ans.reverse()
    print(' '.join(str(x + 1) for x in ans))

    print(''.join(chr(c) for c in s))
```

C++ 做法如下——

```cpp []

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, m;
	cin >> n >> m;

	vector<vector<pair<int, char>>> path(n + 1);

	while (m --) {
		int u, v;
		char c;
		cin >> u >> v >> c;
		path[u].emplace_back(v, c);
		path[v].emplace_back(u, c);
	}

	vector<int> dis(n + 1, -1);
	dis[n] = 0;

	queue<int> q;
	q.push(n);

	while (!q.empty()) {
		int u = q.front(); q.pop();
		for (auto &[v, c]: path[u]) {
			if (dis[v] == -1) {
				dis[v] = dis[u] + 1;
				q.push(v);
			}
		}
	}

	vector<int> cur = {1}, parent(n + 1, -1);
	string ans;

	while (cur[0] != n) {
		char min_ch = 'z';
		for (auto &u: cur) {
			for (auto &[v, c]: path[u]) {
				if (dis[v] == dis[u] - 1) {
					min_ch = min(min_ch, c);
				}
			}
		}
		vector<int> ncur;
		ans += min_ch;
		for (auto &u: cur) {
			for (auto &[v, c]: path[u]) {
				if (dis[v] == dis[u] - 1 && min_ch == c && parent[v] == -1) {
					ncur.emplace_back(v);
					parent[v] = u;
				}
			}
		}
		cur.swap(ncur);
	}

	cout << ans.size() << '\n';

	vector<int> route = {n};
	while (route.back() != 1)
		route.emplace_back(parent[route.back()]);
	reverse(route.begin(), route.end());

	for (auto &x: route) cout << x << ' '; cout << '\n';

	cout << ans;

	return 0;
}
```

**提示 1：** 很明显，最容易确定数值的是 $2^i$ 形式的数，查询两个 $2^i$ ，得到的结果就是 $f(2^i)$ 的两倍。

**提示 2：** 如何将其他数变成 $2^i$ 。

先看提示 1，那么剩下的数咋办呢？

我们只能用将求 $f(x)$ 转化为求另一个 $f(2^k-x)$ ，这样能到一个 $2^i$ 吗？

答案是肯定的，我们只需找到最小的满足 $2^k\gt x$ 的 $k$ ，这样 $2^k-x$ 二进制表示的位数一定更小，同时最低的非零位保持不变，因此迟早会只剩下最低的非零位。

一个数所需的查询数量是 $\mathcal{O}(\log M)$ 的。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    def query(a, b):
        print('?', a, b, flush=True)
        return int(LI()[1])

    def answer(x):
        print('!', x, flush=True)
        return I()

    def solve(x):
        if x & -x == x:
            return query(x, x) // 2
        v = 1 << x.bit_length()
        return query(v - x, x) - solve(v - x)

    n = II()
    nums = LII()

    for x in nums:
        answer(solve(x))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	auto query = [&] (long long x, long long y) -> long long {
		cout << "? " << x << ' ' << y << endl;
		char c; long long v;
		cin >> c >> v;
		return v;
	};

	auto answer = [&] (long long x) -> void {
		cout << "! " << x << endl;
		char c; cin >> c;
	};

	auto solve = [&] (auto &self, long long x) -> long long {
		if ((x & -x) == x) return query(x, x) / 2;
		long long v = 1ll << 64 - __builtin_clzll(x);
		return query(v - x, x) - self(self, v - x);
	};

	int n;
	cin >> n;

	vector<long long> vals(n);
	for (auto &v: vals) cin >> v;
	for (auto &v: vals) answer(solve(solve, v));

	return 0;
}
```

**提示 1：** 将问题转化为一个好解决的形式。

因为我们要求均值在 $[a,b]$ 之间的子数组个数，我们可以理解为均值不超过 $b$ 的子数组个数减去均值严格小于 $a$ 的子数组个数。

不超过 $b$ 可以理解为严格小于 $b+\frac{1}{n}$ ，因此这样就完全只需解决均值不超过 $x$ 的子数组个数的问题。

我们将每个元素都减去 $x$ ，这里减去的数是有理数，可以同乘分母后再减，就毫无精度问题了。这样就是求均值小于 $0$ 的子数组个数。

这样的子数组在前缀和数组中对应一个逆序对，因此直接求逆序对个数即可。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n, a, b = MII()
    nums = LII()

    ans = 0

    acc = [0] * (n + 1)

    for i in range(n):
        acc[i + 1] = acc[i] + (nums[i] * n - (b * n + 1))

    ans += reversePairs(acc)

    for i in range(n):
        acc[i + 1] = acc[i] + (nums[i] * n - a * n)

    ans -= reversePairs(acc)

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, a, b;
	cin >> n >> a >> b;

	vector<int> nums(n);
	for (auto &x: nums) cin >> x;

	long long ans = 0;

	vector<long long> acc(n + 1, 0);

	for (int i = 0; i < n; i ++) acc[i + 1] = acc[i] + 1ll * nums[i] * n - (1ll * b * n + 1);
	ans += reversePairs(acc);

	for (int i = 0; i < n; i ++) acc[i + 1] = acc[i] + 1ll * nums[i] * n - 1ll * a * n;
	ans -= reversePairs(acc);

	cout << ans;

	return 0;
}
