	int n, T;
	cin >> n >> T;

	vector<int> ts, bs;

	int ans = 0;
	for (int i = 0; i < n; i ++) {
		int t, b, c;
		cin >> t >> b >> c;
		ans += c;
		ts.emplace_back(t);
		bs.emplace_back(b - c);
	}

	vector<int> dp(n + 1, 0);
	int pt = 0;

	for (int i = 0; i < n; i ++) {
		while (ts[i] - ts[pt] >= T && pt + 1 <= i) pt ++;
