C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	vector<int> v1(n), v2(n);
	for (auto &x: v1) cin >> x;
	for (auto &x: v2) cin >> x;

	int cnt = 0;
	vector<vector<int>> path(n + 1);
	vector<int> indeg(n + 1, 0);

	vector<int> stk;

	for (auto &x: v1) {
		while (!stk.empty() && stk.back() < x) stk.pop_back();
		if (!stk.empty()) {
			path[stk.back()].emplace_back(x);
			indeg[x] ++;
			cnt ++;
		}
		stk.emplace_back(x);
	}

	stk.clear();

	for (auto &x: v2) {
		while (!stk.empty() && stk.back() > x) stk.pop_back();
		if (!stk.empty()) {
			path[stk.back()].emplace_back(x);
			indeg[x] ++;
			cnt ++;
		}
		stk.emplace_back(x);
	}

	priority_queue<int> pq;
	vector<int> saved_indeg;

	vector<int> w1;

	saved_indeg = indeg;
	for (int i = 1; i <= n; i ++) {
		if (!indeg[i]) {
			pq.push(-i);
		}
	}

	while (!pq.empty()) {
		int u = -pq.top(); pq.pop();
		w1.emplace_back(u);

		for (auto &v: path[u]) {
			saved_indeg[v] --;
			if (!saved_indeg[v]) pq.push(-v);
		}
	}

	vector<int> w2;

	saved_indeg = indeg;
	for (int i = 1; i <= n; i ++) {
		if (!indeg[i]) {
			pq.push(i);
		}
	}

	while (!pq.empty()) {
		int u = pq.top(); pq.pop();
		w2.emplace_back(u);

		for (auto &v: path[u]) {
			saved_indeg[v] --;
			if (!saved_indeg[v]) pq.push(v);
		}
	}

	bool flg = true;

	for (int i = 0; i < n; i ++) {
		if (i >= w1.size() || i >= w2.size() || v1[i] != w1[i] || v2[i] != w2[i]) {
			flg = false;
		}
	}

	if (!flg) cout << "No\n";
	else {
		cout << "Yes\n";
		cout << cnt << '\n';
		for (int i = 1; i <= n; i ++) {
			for (auto &j: path[i]) {
				cout << i << ' ' << j << '\n';
			}
		}
	}

	return 0;
}
```

**提示 1：** 预计越早结束的任务实际上也越早结束。

**提示 2：** 两个任务结束之间进行时间间隔的计算。

实际上，预计越早结束的任务实际上也越早结束。

为什么呢？因为一旦一个任务结束了，其余所有时间都相应进行等比例的缩短，这不会导致两个任务之间的排序关系发生变化。

于是考虑结束时间相邻的两个任务。其间的总工作量是原预计时间间隔乘以原下载速度，而新下载速度是总速度，两者相除就是这段的时间。

将这些事件累计即得答案。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n = II()
    vs = []
    ts = []

    for _ in range(n):
        v, t = MII()
        vs.append(v)
        ts.append(t)

    st_range = sorted(range(n), key=lambda x: ts[x])
    total_v = sum(vs)

    res = 0

    cur_t = 0
    cur_v = total_v

    ans = [0] * n

    for i in st_range:
        res += (ts[i] - cur_t) * cur_v / total_v
        cur_t = ts[i]
        cur_v -= vs[i]
        ans[i] = res

    print('\n'.join(map(str, ans)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	vector<long long> vs(n), ts(n);
	long long total_v = 0;

	for (int i = 0; i < n; i ++) {
		cin >> vs[i] >> ts[i];
		total_v += vs[i];
	}

	vector<int> order(n);
	iota(order.begin(), order.end(), 0);
	sort(order.begin(), order.end(), [&] (int i, int j) {return ts[i] < ts[j];});

	long long cur_v = total_v, cur_t = 0;
	vector<long double> ans(n);
	long double res = 0;

	for (auto &id: order) {
		res += (long double)(ts[id] - cur_t) * cur_v / total_v;
		ans[id] = res;
		cur_t = ts[id];
		cur_v -= vs[id];
	}

	cout << fixed << setprecision(15);
	for (auto &x: ans) cout << x << '\n';

	return 0;
}
```

**提示 1：** 考虑以 $i$ 为最大值的子数组。

**提示 2：** 考虑一个相对暴力的做法，其实复杂度是对的。

本题可以使用笛卡尔树等方法达到更通用的做法，下面介绍一个单 $\log$ 的做法。

我们考虑枚举 $i$ ，计算以 $i$ 为最大值的满足条件的子数组个数。

我们暴力扩展左端点，直到无法扩展。接下来枚举左端点，再用双指针不断移动右端点，这样就能统计总的子数组个数。

这样做为啥复杂度是对的呢？每个位置只会被不同的 $i$ 作为左端点 / 右端点遍历 $\log$ 次，因为这些 $i$ 之间基本上至少是 $2$ 倍关系了，而数值有上限 $M$ 。

具体而言，假设从左遍历到 $i$ 这个序列是 $[j_1,j_2,j_3,\dots,j_k]$ ，则 $nums[j_{v}]\gt nums[j_{v+1}]+\dots+nums[j_k]$ 。所以即使最后两项都只有 $1$ ，更前面的项也是指数级别增长，不超过 $M$ 的项一定不超过对数个。

右侧的逻辑也是类似的。所以双指针本质上每个位置都只经过 $\log$ 次，也就没问题了。

时间复杂度为 $\mathcal{O}(n\log M)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    t = II()
    outs = []

    for _ in range(t):
        n = II()
        nums = LII()
        ans = 0

        for i in range(n):
            cur = 0
            l = i
            while l and cur + nums[l - 1] < nums[i]:
                l -= 1
                cur += nums[l]

            r = i + 1
            while l <= i:
                while r < n and cur + nums[r] < nums[i]:
                    cur += nums[r]
                    r += 1
                ans += r - i
                cur -= nums[l]
                l += 1

        outs.append(ans)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int n;
		cin >> n;

		vector<int> nums(n);
		for (auto &v: nums) cin >> v;

		long long ans = 0;
		for (int i = 0; i < n; i ++) {
			int cur = 0, l = i, r = i + 1;

			while (l && cur + nums[l - 1] < nums[i]) {
				l --;
				cur += nums[l];
			}

			while (l <= i) {
				while (r < n && cur + nums[r] < nums[i]) {
					cur += nums[r];
					r ++;
				}
				ans += r - i;
				cur -= nums[l];
				l ++;
			}
		}

		cout << ans << '\n';
	}

	return 0;
}
```

**提示 1：** 先看火山是怎么活动的。

**提示 2：** 接下来，怎么逃跑最优？

活动会受到火山的限制，所以我们先考虑火山的行动。

这里最重要的就是每个点什么时候会开始被火山影响。这件事等于这个点的数值 / 另一点的数值加到这点的最短路长度。

我们可以理解为从一个虚拟节点出发，先按照 $a_i$ 的边权走到 $i$ ，接下来再走图上的边。因此我们只需在这个图上跑一次最短路，就能得到每个点最早被影响的时间。

接下来我们要从 $1$ 结点出发走到 $n$ ，每个点肯定越早走到越好，因此仍然使用最短路算法。但这里需要多满足一个条件，就是走到一个结点时刻不能晚于这个点被火山影响的时刻。如果在这种情况下能走到 $n$ 结点就满足要求。也就是最短路过程中多个判断。

时间复杂度为 $\mathcal{O}(m+n\log m)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    t = II()
    outs = []

    inf = 11 * 10 ** 8

    for _ in range(t):
        n, m = MII()
        nums = LII()

        path = [[] for _ in range(n)]

        for _ in range(m):
            u, v, w = MII()
            u -= 1
            v -= 1
            path[u].append(w * n + v)
            path[v].append(w * n + u)

        pq = [nums[i] * n + i for i in range(n)]

        while pq:
            d, u = divmod(heappop(pq), n)
            if nums[u] == d:
                for msk in path[u]:
                    nd, v = divmod(msk, n)
                    if nd + d < nums[v]:
                        nums[v] = nd + d
                        heappush(pq, nums[v] * n + v)

        dis = [inf] * n
        dis[0] = 0

        pq = [0]

        while pq:
            d, u = divmod(heappop(pq), n)
            if dis[u] == d:
                for msk in path[u]:
                    nd, v = divmod(msk, n)
                    if nd + d < dis[v] and nd + d <= nums[v]:
                        dis[v] = nd + d
                        heappush(pq, dis[v] * n + v)

        outs.append('YES' if dis[n - 1] < inf else 'NO')

    print('\n'.join(outs))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	int inf = 11e8;

	while (t --) {
		int n, m;
		cin >> n >> m;

		vector<int> nums(n);
		for (auto &v: nums) cin >> v;

		vector<vector<pair<int, int>>> path(n);
		while (m --) {
			int u, v, w;
			cin >> u >> v >> w;
			u --, v --;
			path[u].emplace_back(v, w);
			path[v].emplace_back(u, w);
		}

		priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;

		for (int i = 0; i < n; i ++) pq.push({nums[i], i});

		while (!pq.empty()) {
			auto [d, u] = pq.top(); pq.pop();
			if (nums[u] == d) {
				for (auto &[v, w]: path[u]) {
					if (nums[u] + w < nums[v]) {
						nums[v] = nums[u] + w;
						pq.push({nums[v], v});
					}
				}
			}
		}

		vector<int> dis(n, inf);
		dis[0] = 0;

		pq.push({0, 0});

		while (!pq.empty()) {
			auto [d, u] = pq.top(); pq.pop();
			if (dis[u] == d) {
				for (auto &[v, w]: path[u]) {
					if (dis[u] + w < dis[v] && dis[u] + w <= nums[v]) {
						dis[v] = dis[u] + w;
						pq.push({dis[v], v});
					}
				}
			}
		}

		cout << (dis[n - 1] < inf ? "YES\n" : "NO\n");
	}

	return 0;
}
```

**提示 1：** 最大的不满足条件的集合是多大？

**提示 2：** 如何快速提取子矩阵中的元素。

最大的不满足条件的集合多大呢？

第一个数不小于 $1$ ，第二个数不小于 $1$ ，因此第三个数不小于 $2$ ，第四个数不小于 $3$ ，以此类推，发现是个斐波那契数列，只有 $\mathcal{O}(\log M)$ 项不超过 $10^6$ ，具体的最多有 $30$ 项。

所以一旦我们提取出来的数超过了 $30$ 个，就一定满足要求。其他情况下，我们需要提取非零元素进行判断。

我们可以用前缀和对一个子矩阵中是否有非零元素进行判断（前缀和统计子矩阵中非零元素个数），这样我们能先锁定在哪一行。接下来，该行找元素既可以使用二分，也可以预处理标记某个元素右侧第一个非零元素的位置，这样就可以快速提取这行中的非零元素。

最后考虑判断一个序列是否满足要求。我们考虑将其排序，假设从小到大取的三个元素分别是 $a,b,c$ ，则固定 $b$ ， $a$ 越大越好， $c$ 越小越好，因此只需判断所有连续的三元组是否满足要求即可。

时间复杂度为 $\mathcal{O}(nm+q\log M(\log n+\log\log M))$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n, m = MII()
    grid = [LII() for _ in range(n)]

    acc = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(n):
        for j in range(m):
            if grid[i][j]:
                acc[i + 1][j + 1] = 1

    for i in range(n):
        for j in range(m + 1):
            acc[i + 1][j] += acc[i][j]

    for i in range(n + 1):
        for j in range(m):
            acc[i][j + 1] += acc[i][j]

    next_pos = [[m] * (m + 1) for _ in range(n)]

    for i in range(n):
        for j in range(m - 1, -1, -1):
            next_pos[i][j] = next_pos[i][j + 1]
            if grid[i][j]:
                next_pos[i][j] = j

    def calc(x1, y1, x2, y2):
        x2 += 1
        y2 += 1
        return acc[x1][y1] - acc[x1][y2] - acc[x2][y1] + acc[x2][y2]

    q = II()
    outs = []

    for _ in range(q):
        x1, y1, x2, y2 = GMI()

        pt = x1
        tmp = []
        while len(tmp) <= 30:
            l, r = pt, x2

            while l <= r:
                mid = (l + r) // 2
                if calc(pt, y1, mid, y2): r = mid - 1
                else: l = mid + 1

            if l > x2: break

            cur = y1
            while next_pos[l][cur] <= y2:
                cur = next_pos[l][cur]
                if len(tmp) > 30: break
                tmp.append(grid[l][cur])
                cur += 1

            pt = l + 1

        if len(tmp) > 30: outs.append('YES')
        else:
            tmp.sort()
            for i in range(2, len(tmp)):
                if tmp[i - 2] + tmp[i - 1] > tmp[i]:
                    outs.append('YES')
                    break
            else:
                outs.append('NO')

    print('\n'.join(outs))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, m;
	cin >> n >> m;

	vector<vector<int>> grid(n, vector<int>(m));
	for (auto &x: grid) for (auto &y: x) cin >> y;

	vector<vector<int>> acc(n + 1, vector<int>(m + 1, 0));

	for (int i = 0; i < n; i ++) {
		for (int j = 0; j < m; j ++) {
			if (grid[i][j]) {
				acc[i + 1][j + 1] = 1;
			}
		}
	}

	for (int i = 0; i <= n; i ++) {
		for (int j = 0; j < m; j ++) {
			acc[i][j + 1] += acc[i][j];
		}
	}

	for (int i = 0; i < n; i ++) {
		for (int j = 0; j <= m; j ++) {
			acc[i + 1][j] += acc[i][j];
		}
	}

	vector<vector<int>> next_pos(n, vector<int>(m + 1, m));

	for (int i = 0; i < n; i ++) {
		for (int j = m - 1; j >= 0; j --) {
			next_pos[i][j] = next_pos[i][j + 1];
			if (grid[i][j]) next_pos[i][j] = j;
		}
	}

	auto calc = [&] (int x1, int y1, int x2, int y2) -> int {
		x2 ++, y2 ++;
		return acc[x1][y1] - acc[x1][y2] - acc[x2][y1] + acc[x2][y2];
	};

	int q;
	cin >> q;

	while (q --) {
		int x1, y1, x2, y2;
		cin >> x1 >> y1 >> x2 >> y2;
		x1 --, y1 --, x2 --, y2 --;

		int pt = x1;
		vector<int> tmp;

		while (tmp.size() <= 30) {
			int l = pt, r = x2;

			while (l <= r) {
				int mid = (l + r) / 2;
				if (calc(pt, y1, mid, y2)) r = mid - 1;
				else l = mid + 1;
			}

			if (l > x2) break;

			int cur = y1;
			while (next_pos[l][cur] <= y2) {
				cur = next_pos[l][cur];
				tmp.emplace_back(grid[l][cur]);
				if (tmp.size() > 30) break;
				cur ++;
			}

			pt = l + 1;
		}

		if (tmp.size() > 30) cout << "YES\n";
		else {
			sort(tmp.begin(), tmp.end());
			bool flg = false;
			for (int i = 2; i < tmp.size(); i ++) {
				if (tmp[i - 2] + tmp[i - 1] > tmp[i]) {
					flg = true;
					break;
				}
			}
			cout << (flg ? "YES\n" : "NO\n");
		}
	}

	return 0;
}
```

**提示 1：** 可以打印一下打乱的过程。

当你将 $[1,2,\dots,52]$ 进行打乱并输出结果后，你会发现结果是 $8$ 个一循环的。

因此只需模拟 $8$ 次看是否有满足要求的即可。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    nums = LII()

    for _ in range(8):
        nnums = []
        for i in range(26):
            nnums.append(nums[i])
            nnums.append(nums[i + 26])
        nums = nnums

        flg = True
        for i in range(26, 52):
            if nums[i] == 1:
                flg = False

        if flg: exit(print('YES'))

    print('NO')
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	vector<int> nums(52);
	for (auto &v: nums) cin >> v;

	for (int i = 0; i < 8; i ++) {
		vector<int> nnums;
		for (int i = 0; i < 26; i ++) {
			nnums.emplace_back(nums[i]);
			nnums.emplace_back(nums[i + 26]);
		}
		nums.swap(nnums);

		bool flg = true;
		for (int i = 26; i < 52; i ++) {
			if (nums[i] == 1) {
				flg = false;
			}
		}

		if (flg) return cout << "YES", 0;
	}

	cout << "NO";

	return 0;
}
```

**提示 1：** 注意你只需要求期望。有可加性。

**提示 2：** 考虑每个最大值的路径有几条。

表面上求极差期望，其实只需求最大值和最小值的期望再相减。这两者本质一致，我们只说最大值。

我们从小到达遍历结点，并将遍历过的结点之间连边。这样我们可以在遍历 $i$ 结点时，得到总的路径条数（每个大小为 $x$ 的连通块路径有 $C_x^2$ 条）。与前一轮相减就是新增的路径数量，这个数量乘以 $i$ 的权值就是 $i$ 的贡献。将这些贡献相加即可。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n = II()
    nums = LII()

    path = [[] for _ in range(n)]

    for _ in range(n - 1):
        u, v = GMI()
        path[u].append(v)
        path[v].append(u)

    st_range = sorted(range(n), key=lambda x: nums[x])

    ans = 0
    mod = 10 ** 9 + 7

    vis = [0] * n
    uf = UnionFind(n)

    for u in st_range:
        for v in path[u]:
            if vis[v]:
                ans = (ans + nums[u] * uf.getSize(u) % mod * uf.getSize(v) % mod) % mod
                uf.merge(u, v)
        vis[u] = 1

    for i in range(n): vis[i] = 0
    uf.init()

    for u in reversed(st_range):
        for v in path[u]:
            if vis[v]:
                ans = (ans + mod - nums[u] * uf.getSize(u) % mod * uf.getSize(v) % mod) % mod
                uf.merge(u, v)
        vis[u] = 1

    print(ans * pow(n * (n - 1) // 2 % mod, -1, mod) % mod)
```

C++ 做法如下——

```cpp []
long long quickPow(long long base, long long power, long long mod) {
	if (power == 0) return 1 % mod;
	long long cur = quickPow(base, power / 2, mod);
	return power & 1 ? base * cur % mod * cur % mod : cur * cur % mod; 
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	vector<int> nums(n);
	for (auto &v: nums) cin >> v;

	vector<vector<int>> path(n);
	for (int i = 0; i < n - 1; i ++) {
		int u, v;
		cin >> u >> v;
		u --, v --;
		path[u].emplace_back(v);
		path[v].emplace_back(u);
	}

	vector<int> order(n);
	iota(order.begin(), order.end(), 0);
	sort(order.begin(), order.end(), [&] (int i, int j) {return nums[i] < nums[j];});

	int ans = 0, mod = 1e9 + 7;

	atcoder::dsu uf(n);
	vector<int> vis(n, 0);

	for (auto &u: order) {
		for (auto &v: path[u]) {
			if (vis[v]) {
				ans += 1ll * nums[u] * uf.size(u) % mod * uf.size(v) % mod;
				ans %= mod;
				uf.merge(u, v);
			}
		}
		vis[u] = 1;
	}

	reverse(order.begin(), order.end());

	uf.init();
	fill(vis.begin(), vis.end(), 0);

	for (auto &u: order) {
		for (auto &v: path[u]) {
			if (vis[v]) {
				ans += mod - 1ll * nums[u] * uf.size(u) % mod * uf.size(v) % mod;
				ans %= mod;
				uf.merge(u, v);
			}
		}
		vis[u] = 1;
	}

	cout << 1ll * ans * quickPow(1ll * n * (n - 1) / 2 % mod, mod - 2, mod) % mod;

	return 0;
}
```

**提示 1：** 需要检查的数并不多。

**提示 2：** 如何检查一个数？

首先，分成的两个集合的和就是 $a$ 到 $a+b-1$ 的和，因此最大公约数 $g$ 必须得是两个集合的因子，两个集合的和加起来也是 $g$ 的倍数，所以我们只需考虑 $a+(a+1)+\dots+(a+b-1)$ 的因子。

那么怎么检查一个因子能否是答案呢？注意这里给定的 $b$ 很小。

我们考虑枚举其中一个集合的大小，看其能否是 $x$ 的倍数。如果这个集合大小为 $v$ ，则这个集合的数值最小为 $a+(a+1)+\dots+(a+v-1)$ ，最大为 $(a+b-1)+\dots+(a+b-v)$ ，且因为可以从前者不断调整到后者，所以中间每个数值都能取到。因此我们只需检查这个区间内是否有 $v$ 的倍数。

在这个情况下我们只需枚举 $\mathcal{O}(b)$ 次就好。

时间复杂度为 $\mathcal{O}\left(b\times d\left(\frac{b(2a+b-1)}{2}\right)+\sqrt{\frac{b(2a+b-1)}{2}}\right)$ ，其中 $d(x)$ 表示 $x$ 的因子个数。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    t = II()
    outs = []

    for _ in range(t):
        a, b = MII()
        total = (2 * a + b - 1) * b // 2

        def check(x):
            for i in range(1, b):
                l = a * i + i * (i - 1) // 2
                r = a * i + (2 * b - 1 - i) * i // 2
                if r // x * x >= l: return True
            return False

        ans = 0
        for i in range(1, 10 ** 5 * 2):
            if i * i > total: break
            if total % i == 0:
                if check(i): ans = fmax(ans, i)
                if check(total // i): ans = fmax(ans, total // i)

        outs.append(ans)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		long long a, b;
		cin >> a >> b;

		long long total = 1ll * (2 * a + b - 1) * b / 2;

		auto check = [&] (long long x) -> bool {
			for (long long i = 1; i < b; i ++) {
				long long l = a * i + i * (i - 1) / 2;
				long long r = a * i + (2 * b - 1 - i) * i / 2;
				if (r / x * x >= l) return true;
			}
			return false;
		};

		long long ans = 0;

		for (long long i = 1; i * i <= total; i ++) {
			if (total % i == 0) {
				if (check(i)) ans = max(ans, i);
				if (check(total / i)) ans = max(ans, total / i);
			}
		}

		cout << ans << '\n';
	}

	return 0;
}
```

**提示 1：** 可以先缩小范围，再进一步确定。

这题有点神秘瞎搞的意味了。主要思路就在提示。

首先我们可以尝试尽量缩小答案的范围。我们可以对于一个进制 $p$ 查询 $[1,p,p^2,p^3,\dots]$ ，这样查询的集合不算大，同时可以缩小可能的答案范围。

就这样我们用几个进制缩小了范围，最后答案只有某几个了，怎么办呢？

我们可以用二分查询一个数是否在一个集合中。我们先输入 $[1,2,4,\dots]$ 保证每个元素都可以被表示且需要的步数不会太多。接下来我们将集合中一半的数再放入查询的列表。这样，如果查询结果是 $1$ ，答案就在这个集合中，否则不在。我们就可以利用这件事进行二分。

而这样做，我们进行了 $\mathcal{O}(\log k)$ 次查询，而查询的集合的总长度是 $\mathcal{O}(k+\log k\log M)$ ，控制的较小。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    def query(vals):
        print('?', len(vals), *vals, flush=True)
        return II()

    primes = [2, 3, 5, 7]
    saved_vals = []

    for p in primes:
        vals = [1]
        while vals[-1] * p <= 30000:
            vals.append(vals[-1] * p)
        saved_vals.append(query(vals))

    candidates = []
    for x in range(1, 30001):
        flg = True
        for i in range(4):
            v = x
            cur = 0
            while v:
                cur += v % primes[i]
                v //= primes[i]
            if cur != saved_vals[i]:
                flg = False
        if flg: candidates.append(x)

    l, r = 0, len(candidates) - 1
    while l <= r:
        mid = (l + r) // 2

        vals = [1]
        while vals[-1] * 2 <= candidates[mid]:
            vals.append(vals[-1] * 2)

        for i in range(mid, r + 1):
            if candidates[i] & -candidates[i] != candidates[i]:
                vals.append(candidates[i])

        if query(vals) == 1: l = mid + 1
        else: r = mid - 1

    print('!', candidates[r])
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	auto query = [&] (vector<int> &vals) -> int {
		cout << "? " << vals.size();
		for (auto &v: vals) cout << ' ' << v;
		cout << endl;
		int x; cin >> x;
		return x;
	};

	vector<int> primes = {2, 3, 5, 7};
	vector<int> saved_vals(4);

	for (int i = 0; i < 4; i ++) {
		vector<int> vals = {1};
		while (vals.back() * primes[i] <= 30000)
			vals.emplace_back(vals.back() * primes[i]);
		saved_vals[i] = query(vals);
	}

	vector<int> candidates;

	for (int x = 1; x <= 30000; x ++) {
		bool flg = true;
		for (int i = 0; i < 4; i ++) {
			int v = x, cur = 0;
			while (v) {
				cur += v % primes[i];
				v /= primes[i];
			}
			if (cur != saved_vals[i]) flg = false;
		}
		if (flg) candidates.emplace_back(x);
	}

	int l = 0, r = candidates.size() - 1;

	while (l <= r) {
		int mid = (l + r) / 2;
		vector<int> vals = {1};
		while (vals.back() * 2 <= candidates[mid])
			vals.emplace_back(vals.back() * 2);
		for (int i = mid; i <= r; i ++) {
			if (__popcount(candidates[i]) != 1) {
				vals.emplace_back(candidates[i]);
			}
		}
		if (query(vals) == 1) l = mid + 1;
		else r = mid - 1;
	}

	cout << "! " << candidates[r];

	return 0;
}
