**提示 1：** 两个路径相交，满足什么性质？

**提示 2：** 要统计什么？怎么保证不重不漏？

两条路径相交，则一条路径的最浅点（即两端端点的 LCA）在另一条路径上。

所以我们对每条路径，统计在其上的 LCA 数量。我们相当于树上每个点有个权值（这里就是 LCA 数量），求路径上权值和。我们可以预处理根节点到当前结点的总权值，再用 $val[u]+val[v]-val[lca(u,v)]-val[parent[lca(u,v)]]$ 得到答案。

对于满足条件的一对路径会被计算几次呢？如果两条路径 LCA 不同，则只计算一次：更浅的 LCA 上统计一次。否则会被多次统计。

我们只需将这部分剔除就好。我们既然得到了每个点作为 LCA 的出现次数，则其任选两个都是被多统计的元素对，去掉它们就行。（每条路径和自身也被多计算了一次）

这里用的倍增法求 LCA，所以下面的代码复杂度是 $\mathcal{O}(n\log n+m\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n, m = MII()

    path = [[] for _ in range(n)]
    for _ in range(n - 1):
        u, v = GMI()
        path[u].append(v)
        path[v].append(u)

    us = []
    vs = []

    for _ in range(m):
        u, v = GMI()
        us.append(u)
        vs.append(v)

    parent = [-1] * n
    depth = [0] * n
    que = [0]

    for u in que:
        for v in path[u]:
            if parent[u] != v:
                parent[v] = u
                depth[v] = depth[u] + 1
                que.append(v)

    nth_parent = [[-1] * n for _ in range(20)]
    nth_parent[0] = parent

    for i in range(19):
        for j in range(n):
            if nth_parent[i][j] >= 0:
                nth_parent[i + 1][j] = nth_parent[i][nth_parent[i][j]]

    ls = []

    for i in range(m):
        u = us[i]
        v = vs[i]

        if depth[u] > depth[v]:
            u, v = v, u

        d = depth[v] - depth[u]

        while d:
            x = d & -d
            v = nth_parent[x.bit_length() - 1][v]
            d -= x

        if u == v: ls.append(u)
        else:
            for i in range(19, -1, -1):
                if nth_parent[i][u] != nth_parent[i][v]:
                    u = nth_parent[i][u]
                    v = nth_parent[i][v]
            ls.append(parent[u])

    ans = 0

    cnt = [0] * n

    for u in ls:
        cnt[u] += 1
        ans -= cnt[u]

    for u in que:
        if u:
            cnt[u] += cnt[parent[u]]

    for i in range(m):
        u = us[i]
        v = vs[i]
        l = ls[i]

        ans += cnt[u] + cnt[v] - cnt[l]
        if parent[l] >= 0: ans -= cnt[parent[l]]

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, m;
	cin >> n >> m;

	vector<vector<int>> path(n);
	for (int i = 0; i < n - 1; i ++) {
		int u, v;
		cin >> u >> v;
		u --, v --;
		path[u].emplace_back(v);
		path[v].emplace_back(u);
	}

	vector<pair<int, int>> routes(m);
	for (auto &[u, v]: routes) {
		cin >> u >> v;
		u --, v --;
	}

	vector<int> parent(n, -1), depth(n, 0);
	auto dfs = [&] (auto &self, int u, int p) -> void {
		for (auto &v: path[u]) {
			if (v != p) {
				parent[v] = u;
				depth[v] = depth[u] + 1;
				self(self, v, u); 
			}
		}
	};

	dfs(dfs, 0, -1);

	vector<vector<int>> nth_parent(20, vector<int>(n, -1));
	nth_parent[0] = parent;

	for (int i = 0; i < 19; i ++) {
		for (int j = 0; j < n; j ++) {
			if (nth_parent[i][j] != -1) {
				nth_parent[i + 1][j] = nth_parent[i][nth_parent[i][j]];
			}
		}
	}

	auto lca = [&] (int u, int v) -> int {
		if (depth[u] > depth[v]) swap(u, v);

		int d = depth[v] - depth[u];
		for (int i = 0; i < 20; i ++) {
			if (d >> i & 1) {
				v = nth_parent[i][v];
			}
		}

		if (u == v) return u;

		for (int i = 19; i >= 0; i --) {
			if (nth_parent[i][u] != nth_parent[i][v]) {
				u = nth_parent[i][u];
				v = nth_parent[i][v];
			}
		}

		return parent[u];
	};

	long long ans = 0;
	vector<int> ls(m), cnt(n, 0);

	for (int i = 0; i < m; i ++) {
		auto [u, v] = routes[i];
		ls[i] = lca(u, v);
		cnt[ls[i]] ++;
		ans -= cnt[ls[i]];
	}

	auto dfs1 = [&] (auto &self, int u, int p) -> void {
		for (auto &v: path[u]) {
			if (v != p) {
				cnt[v] += cnt[u];
				self(self, v, u); 
			}
		}
	};

	dfs1(dfs1, 0, -1);

	for (int i = 0; i < m; i ++) {
		auto [u, v] = routes[i];
		ans += cnt[u] + cnt[v] - cnt[ls[i]];
		if (ls[i]) ans -= cnt[parent[ls[i]]];
	}

	cout << ans;

	return 0;
}
```

**提示 1：** 典型 DP 计数，用什么当状态呢？转移如何？

很明显是一个 DP 计数的问题。

我们考虑到第 $i$ 项的和是 $X$ ，则其能转移到的状态是 $i+1$ 和 $X+1\sim 2X$ 。

发现 $i$ 是不重要的，关键在于 $X$ 。所以我们以 $X$ 为状态，考虑和为 $v$ 的满足条件的序列数量为 $dp[v]$ 。

则上述过程可以理解为状态转移到一个区间，也可以理解为一个区间的状态转移到 $x$ ，可以用差分更新 / 前缀和进行优化。

时间复杂度为 $\mathcal{O}(k)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n = II()
    mod = 10 ** 9 + 7

    dp = [0] * (n + 1)
    acc = [0] * (n + 1)

    dp[1] = acc[1] = 1

    for i in range(2, n + 1):
        dp[i] = (acc[i - 1] - acc[i - i // 2 - 1]) % mod
        acc[i] = (acc[i - 1] + dp[i]) % mod

    print(dp[n])
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, mod = 1e9 + 7;
	cin >> n;

	vector<int> dp(n + 1, 0), acc(n + 1, 0);
	dp[1] = 1, acc[1] = 1;

	for (int i = 2; i <= n; i ++) {
		dp[i] = (acc[i - 1] + mod - acc[i - i / 2 - 1]) % mod;
		acc[i] = (acc[i - 1] + dp[i]) % mod;
	}

	cout << dp[n];

	return 0;
}
```

**提示 1：** 分两步——每个物品的最低成本，求方案数。

**提示 2：** 其实不用松弛太多次。

我们求完每个物品的最低成本后，就可以用背包问题求解后半部分了。

前半部分怎么求呢？注意到物品成本大于 $c+1$ 时就不需考虑了。我们用合成所需的总价格对 $cost[u]$ 进行松弛操作，每次松弛成本至少 $+1$ ，所以走到 $u$ 结点前经过的松弛操作小于 $c$ 。

于是进行这么多轮就可以得到成本了。

时间复杂度为 $\mathcal{O}((n+m)c)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n, m, c = MII()
    mod = 10 ** 9 + 7

    needed = [[] for _ in range(n)]

    for _ in range(m):
        u, v, w = MII()
        u -= 1
        v -= 1
        needed[v].append((u, w))

    dis = [c + 1] * n
    dis[0] = 1

    for _ in range(c):
        for u in range(1, n):
            res = 0
            for v, w in needed[u]:
                res += dis[v] + w
            dis[u] = fmin(dis[u], res)

    dp = [0] * (c + 1)
    dp[0] = 1

    for x in dis:
        for i in range(x, c + 1):
            dp[i] += dp[i - x]
            dp[i] %= mod

    print(sum(dp[1:]) % mod)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, m, c, mod = 1e9 + 7;
	cin >> n >> m >> c;

	vector<vector<pair<int, int>>> needed(n);
	while (m --) {
		int u, v, w;
		cin >> u >> v >> w;
		u --, v --;
		needed[v].emplace_back(u, w);
	}

	vector<int> dis(n, c + 1);
	dis[0] = 1;

	for (int i = 0; i < c; i ++) {
		for (int u = 1; u < n; u ++) {
			int res = 0;
			for (auto &[v, w]: needed[u]) res += dis[v] + w;
			dis[u] = min(dis[u], res);
		}
	}

	vector<int> dp(c + 1, 0);
	dp[0] = 1;

	for (auto &x: dis)
		for (int i = x; i <= c; i ++)
			dp[i] = (dp[i] + dp[i - x]) % mod;

	int ans = 0;
	for (int i = 1; i <= c; i ++)
		ans = (ans + dp[i]) % mod;

	cout << ans;

	return 0;
}
