**提示 1：** 两条抛物线不相交需要满足什么条件？

**提示 2：** 根据上面的事安排顺序。

两个函数不相交的话，不可能一会一个大，一会另一个大，不然根据介值原理就矛盾了。

所以一定存在明确的上下关系。

所以我们可以根据 $f(0)=c$ 的数值进行排序，这样就可以从下往上一个个找了。

而要两个二次曲线不相交，相当于方程无解。方程无解有两种情况——对应的二次方程无解 / 对应的方程次数为 $0$ 且恒不成立。

因此我们可以确定选取某一条曲线时，其下方 / 上方分别最多能取多少条曲线。两部分加起来就好。

时间复杂度为 $\mathcal{O}(n^2)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    t = II()
    outs = []

    for _ in range(t):
        n = II()
        xs = []
        ys = []
        zs = []

        for _ in range(n):
            x, y, z = MII()
            xs.append(x)
            ys.append(y)
            zs.append(z)

        st_range = sorted(range(n), key=lambda x: zs[x])

        dp_pref = [1] * n

        for i in range(n):
            for j in range(i):
                vi = st_range[i]
                vj = st_range[j]

                if xs[vi] == xs[vj]:
                    if ys[vi] == ys[vj]:
                        dp_pref[vi] = fmax(dp_pref[vi], dp_pref[vj] + 1)
                else:
                    a = xs[vi] - xs[vj]
                    b = ys[vi] - ys[vj]
                    c = zs[vi] - zs[vj]

                    if b * b < 4 * a * c:
                        dp_pref[vi] = fmax(dp_pref[vi], dp_pref[vj] + 1)

        dp_suff = [1] * n

        for i in range(n - 1, -1, -1):
            for j in range(i + 1, n):
                vi = st_range[i]
                vj = st_range[j]

                if xs[vi] == xs[vj]:
                    if ys[vi] == ys[vj]:
                        dp_suff[vi] = fmax(dp_suff[vi], dp_suff[vj] + 1)
                else:
                    a = xs[vi] - xs[vj]
                    b = ys[vi] - ys[vj]
                    c = zs[vi] - zs[vj]

                    if b * b < 4 * a * c:
                        dp_suff[vi] = fmax(dp_suff[vi], dp_suff[vj] + 1)

        outs.append(' '.join(str(x + y - 1) for x, y in zip(dp_pref, dp_suff)))

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int n;
		cin >> n;

		vector<array<int, 3>> funcs(n);
		for (auto &[a, b, c]: funcs) cin >> a >> b >> c;

		vector<int> order(n);
		iota(order.begin(), order.end(), 0);
		sort(order.begin(), order.end(), [&] (int i, int j) {
			return funcs[i][2] < funcs[j][2];
		});

		vector<int> dp_pref(n, 1), dp_suff(n, 1);

		for (int i = 0; i < n; i ++) {
			for (int j = 0; j < i; j ++) {
				int vi = order[i], vj = order[j];

				if (funcs[vi][0] == funcs[vj][0]) {
					if (funcs[vi][1] == funcs[vj][1])
						dp_pref[vi] = max(dp_pref[vi], dp_pref[vj] + 1);
				}
				else {
					int a = funcs[vi][0] - funcs[vj][0];
					int b = funcs[vi][1] - funcs[vj][1];
					int c = funcs[vi][2] - funcs[vj][2];

					if (1ll * b * b < 4ll * a * c)
						dp_pref[vi] = max(dp_pref[vi], dp_pref[vj] + 1);
				}
			}
		}

		for (int i = n - 1; i >= 0; i --) {
			for (int j = i + 1; j < n; j ++) {
				int vi = order[i], vj = order[j];

				if (funcs[vi][0] == funcs[vj][0]) {
					if (funcs[vi][1] == funcs[vj][1])
						dp_suff[vi] = max(dp_suff[vi], dp_suff[vj] + 1);
				}
				else {
					int a = funcs[vi][0] - funcs[vj][0];
					int b = funcs[vi][1] - funcs[vj][1];
					int c = funcs[vi][2] - funcs[vj][2];

					if (1ll * b * b < 4ll * a * c)
						dp_suff[vi] = max(dp_suff[vi], dp_suff[vj] + 1);
				}
			}
		}

		for (int i = 0; i < n; i ++) cout << dp_pref[i] + dp_suff[i] - 1 << ' ';
		cout << '\n';
	}

	return 0;
}
```

**提示 1：** 如果一个排列本身几乎有序，如何从被扰乱交换的过程中恢复过来？

**提示 2：** 上述操作是否能重复进行直到整体排序？

如果一个排好序的数组我们交换了两个位置，我们可以怎么办呢？

我们可以顺序交换所有相邻对，再逆序来一遍，这样一定都回去了。

上述逻辑很类似于冒泡排序之类。我们执行 $n-1$ 轮，如果没有捣乱的话也就排好序了。而每次捣乱后，只需执行过上面的操作，前一轮的捣乱也就失去作用了。所以我们只需不断执行上述交换相邻对的操作即可。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    def swap(i, j):
        print(i, j, flush=True)
        if I()[0] == 'W': exit()

    n = II()

    for _ in range(n):
        for i in range(1, n):
            swap(i, i + 1)

        for i in range(n, 2, -1):
            swap(i - 1, i)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	auto op = [&] (int x, int y) -> void {
		cout << x << ' ' << y << endl;
		string s; cin >> s;
		if (s == "WIN") exit(0);
	};

	int n;
	cin >> n;

	for (int i = 0; i < n; i ++) {
		for (int j = 2; j <= n; j ++) op(j - 1, j);
		for (int j = n; j >= 2; j --) op(j - 1, j);
	}

	return 0;
}
```

**提示 1：** 典型贪心题。

不知道你有没有想起来，这跟网络赛的那个签到是一样的。

霍尔定理。实际上就是检查每个条件子集能凑出来的最大的数值，最后取最小值。

这里子集用二进制枚举即可。

时间复杂度为 $\mathcal{O}(1)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    t = II()
    outs = []

    tmp = [[2, 1, 1, 0], [2, 0, 2, 0], [1, 1, 2, 1]]
    inf = 10 ** 9

    for _ in range(t):
        nums = LII()

        ans = inf
        for i in range(16):
            cur = 0
            for j in range(4):
                if i >> j & 1:
                    cur += nums[j]

            to_check = inf

            for j in range(3):
                val = 0
                for k in range(4):
                    if i >> k & 1:
                        val += tmp[j][k]
                to_check = fmin(to_check, val)

            if to_check: ans = fmin(ans, cur // to_check)

        outs.append(ans)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	vector<vector<int>> tmp = {
		{2, 1, 1, 0},
		{2, 0, 2, 0},
		{1, 1, 2, 1}
	};
	int inf = 1e9;

	int t;
	cin >> t;

	while (t --) {
		vector<int> nums(4);
		for (auto &x: nums) cin >> x;

		unsigned int ans = inf;
		for (int i = 0; i < 16; i ++) {
			unsigned int cur = 0;
			for (int j = 0; j < 4; j ++) {
				if (i >> j & 1)  {
					cur += nums[j];
				}
			}

			int to_check = inf;
			for (int j = 0; j < 3; j ++) {
				int val = 0;
				for (int k = 0; k < 4; k ++) {
					if (i >> k & 1) {
						val += tmp[j][k];
					}
				}
				to_check = min(to_check, val);
			}

			if (to_check) ans = min(ans, cur / to_check);
		}

		cout << ans << '\n';
	}

	return 0;
}
```

**提示 1：** 拆贡献。怎么拆？

**提示 2：** 如何更新贡献？

考虑覆盖每个点的子数组 $[l,r]$ 其 MEX 是 $k$ 。考虑计算覆盖 $i$ 的 MEX 不小于 $v$ 的子数组的个数，将 $v$ 关于 $1,2,\dots, n$ 求和， $[l,r]$ 这个子数组刚好被数 $k$ 次。

所以我们直接求 MEX 不小于 $v$ 的子数组有多少个覆盖了位置 $i$ ，将各个 $v$ 的结果累加即可。

因为整个数组是个排列，所以我们直接找到所有 $0,1,\dots,v-1$ 所在的位置，则子数组需要覆盖它们。我们只需从小到大遍历 $v$ ，维护左右端点 $[l_0,r_0]$ （这里取 $0$ -index ）即可。

如果 $i$ 在区间内，则有 $(l_0+1)\times(n-r_0)$ 个。

如果 $i\lt l_0$ ，则有 $(i+1)\times(n-r_0)$ 个。

如果 $i\gt r_0$ ，则有 $(l_0+1)\times(n-i)$ 个。

整体分为三段，每段都更新一个一次函数，因此只需用差分更新一次函数的一次项系数和常数系数即可。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n = II()
    nums = LII()

    pos = [0] * n
    for i in range(n):
        pos[nums[i]] = i

    l, r = pos[0], pos[0]

    diff_0 = [0] * (n + 1)
    diff_1 = [0] * (n + 1)

    for i in range(n):
        l = fmin(l, pos[i])
        r = fmax(r, pos[i])

        diff_0[l] += (n - r) * (l + 1)
        diff_0[r + 1] -= (n - r) * (l + 1)

        diff_1[0] += n - r
        diff_1[l] -= n - r
        diff_0[0] += n - r
        diff_0[l] -= n - r

        diff_1[r + 1] -= l + 1
        diff_1[n] += l + 1
        diff_0[r + 1] += (l + 1) * n
        diff_0[n] -= (l + 1) * n

    for i in range(n):
        diff_0[i + 1] += diff_0[i]
        diff_1[i + 1] += diff_1[i]

    print('\n'.join(str(diff_1[i] * i + diff_0[i]) for i in range(n)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	vector<int> nums(n), pos(n);
	for (int i = 0; i < n; i ++) {
		int v;
		cin >> v;
		nums[i] = v;
		pos[v] = i;
	}

	int l = pos[0], r = pos[0];

	vector<long long> diff_0(n + 1, 0), diff_1(n + 1, 0);

	for (int i = 0; i < n; i ++) {
		l = min(l, pos[i]);
		r = max(r, pos[i]);

		diff_0[l] += 1ll * (n - r) * (l + 1);
		diff_0[r + 1] -= 1ll * (n - r) * (l + 1);

		diff_1[0] += n - r;
		diff_1[l] -= n - r;
		diff_0[0] += n - r;
		diff_0[l] -= n - r;

		diff_1[r + 1] -= l + 1;
		diff_1[n] += l + 1;
		diff_0[r + 1] += 1ll * (l + 1) * n;
		diff_0[n] -= 1ll * (l + 1) * n;
	}

	for (int i = 0; i < n; i ++) {
		diff_1[i + 1] += diff_1[i];
		diff_0[i + 1] += diff_0[i];
		cout << diff_1[i] * i + diff_0[i] << '\n';
	}

	return 0;
}
```

**提示 1：** DP 有一个状态是考虑的前缀长度。还有哪些信息是重要的？

**提示 2：** 状态转移怎么优化？

很明显是个 DP 问题。

我们 DP 设计状态可以考虑长度为 $i$ 的前缀。此时有哪些信息是需要的呢？

当前有多少个长度为 $4$ 的递增子数组 $x$ 。

为了考虑下一个元素添加时是否产生新的递增子数组，我们需要记录的变量：

- 此时最后有多少项是递增的（可以跟 $3$ 取最小值） $y$ 。

- 为了知道此时最后一项能有多少种选择，我们记录当前有多少个元素比当前最后一项小，设为 $z$ 。

因此 DP 数组为 $DP[i][x][y][z]$ ，第一个维度是可以滚动的。

接下来考虑状态转移。

如果新取的一项比前一项小，则 $x$ 变为 $1$ ， $z$ 保持不变， $y$ 会变小，即变为 $0,1,\dots,y-1$ 。

否则，如果 $x\leq 2$ ，则 $x$ 变为 $x+1$ ， $z$ 保持不变， $y$ 会不变或者变大，即变为 $y,y+1,\dots$ （这里最大值需要算一下）。

如果 $x=3$ ，则 $x$ 变为 $x+1$ ， $z$ 变为 $z+1$ ， $y$ 会不变或者变大，即变为 $y,y+1,\dots$ 。

表面上每个状态需要 $\mathcal{O}(n)$ 的转移，但实际上这里 $y$ 的转移是个区间，所以直接使用差分更新，前缀和计算结果就行。

时间复杂度为 $\mathcal{O}(n^3)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    mod = 10 ** 9 + 7
    n, k = MII()

    def f(i, j):
        return i * (n + 1) + j

    dp = [[0] * (n + 1) * (n + 1) for _ in range(4)]
    ndp = [[0] * (n + 1) * (n + 1) for _ in range(4)]

    for i in range(n):
        dp[1][f(i, 0)] = 1

    for i in range(n - 1):
        for x in range(1, 4):
            for y in range(n - i):
                for z in range(fmax(i - 2, 0) + 1):
                    ndp[1][f(0, z)] += dp[x][f(y, z)]
                    ndp[1][f(y, z)] -= dp[x][f(y, z)]
                    if x < 3:
                        ndp[x + 1][f(y, z)] += dp[x][f(y, z)]
                        ndp[x + 1][f(n - 1 - i, z)] -= dp[x][f(y, z)]
                    else:
                        ndp[3][f(y, z + 1)] += dp[x][f(y, z)]
                        ndp[3][f(n - 1 - i, z + 1)] -= dp[x][f(y, z)]

        i += 1
        for x in range(1, 4):
            for y in range(n - i):
                for z in range(fmax(i - 2, 0) + 1):
                    ndp[x][f(y + 1, z)] += ndp[x][f(y, z)]
                    dp[x][f(y, z)] = ndp[x][f(y, z)] % mod
                    ndp[x][f(y, z)] = 0

    ans = 0
    for x in range(4):
        ans += dp[x][f(0, k)]
        ans %= mod

    print(ans)
```

C++ 做法如下——

```cpp []
int dp[4][505][505];
int ndp[4][505][505];

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, k, mod = 1e9 + 7;
	cin >> n >> k;

	for (int i = 0; i < n; i ++) dp[1][i][0] = 1;

	auto add = [&] (int &x, int y) -> void {
		x += y;
		if (x >= mod) x -= mod;
	};

	auto minus = [&] (int &x, int y) -> void {
		x -= y;
		if (x < 0) x += mod;
	};

	for (int i = 0; i < n - 1;) {
		for (int x = 1; x <= 3; x ++) {
			for (int y = 0; y < n - i; y ++) {
				for (int z = 0; z <= max(i - 2, 0); z ++) {
					add(ndp[1][0][z], dp[x][y][z]);
					minus(ndp[1][y][z], dp[x][y][z]);

					if (x < 3) {
						add(ndp[x + 1][y][z], dp[x][y][z]);
						minus(ndp[x + 1][n - 1 - i][z], dp[x][y][z]);
					}
					else {
						add(ndp[3][y][z + 1], dp[x][y][z]);
						minus(ndp[3][n - 1 - i][z + 1], dp[x][y][z]);
					}
				}
			}
		}

		i ++;
		for (int x = 1; x <= 3; x ++) {
			for (int y = 0; y < n - i; y ++) {
				for (int z = 0; z <= max(i - 2, 0); z ++) {
					add(ndp[x][y + 1][z], ndp[x][y][z]);
					dp[x][y][z] = ndp[x][y][z];
					ndp[x][y][z] = 0;
				}
			}
		}
	}

	int ans = 0;
	for (int x = 1; x <= 3; x ++) add(ans, dp[x][0][k]);

	cout << ans;

	return 0;
}
```

**提示 1：** 数组一般是递增的。如果某个位置非递增呢？

**提示 2：** 剩余的情况？

这个数组几乎每个位置都是递增的，但如果有个位置非递增，那一定跨行了。

而某两个数跨行了的话，第二个数就一定是行号了，此时第一个数在前一行，我们就能很快算出第一个数是第几列，也就找到答案了。

否则数组单调递增，此时直接考虑最后一个元素在第几行第几列即可。此时整体是等差数列，我们只需计算公差就知道是第几行，进而用除法可以快速算出是在第几列。

出题人还是比较善良的，保证了 $n\geq 2$ ，不然你还得找下 $n$ 的因子。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    t = II()
    outs = []

    for _ in range(t):
        n = II()
        nums = LII()

        for i in range(n - 1):
            if nums[i] >= nums[i + 1]:
                outs.append(nums[i] // (nums[i + 1] - 1))
                break
        else:
            outs.append(fmax(nums[-1] - nums[-2], nums[-1] // (nums[-1] - nums[-2])))

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int n;
		cin >> n;

		vector<int> nums(n);
		for (auto &v: nums) cin >> v;

		int ans = -1;
		for (int i = 1; i < n; i ++) {
			if (nums[i] <= nums[i - 1]) {
				ans = nums[i - 1] / (nums[i] - 1);
			}
		}

		if (ans == -1) ans = max(nums[n - 1] - nums[n - 2], nums[n - 1] / (nums[n - 1] - nums[n - 2]));
		cout << ans << '\n';
	}

	return 0;
}
