**提示 1：** 其实分割的位置还是很有规律的。

**提示 2：** 分 $n,m$ 为偶数的情况进行讨论。

如果 $n$ 是偶数，则其实 $nm$ 个数，前 $nm/2$ 个数分成了 $n/2$ 段，后面的 $nm/2$ 个数分成了 $n/2$ 段。所以每一段刚好都重复了一遍，我们只需去重之后任意顺序输出就行。

否则， $m$ 是偶数。我们把每一段切割成两部分，这样就又是前面的情况了。

但此时还需要保证每一段是按切割前的顺序进行排列的，只需记录下这个顺序就好了。而无论我们选取哪个元素作为起点，其实都是合法的答案（因为整个切割会形成一个环，我们无论从哪里断开都是合法的）。

时间复杂度为 $\mathcal{O}(nm)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    t = II()
    outs = []

    for _ in range(t):
        n, m = MII()

        lsts = []
        for _ in range(n):
            lsts.append(LII())

        if n % 2 == 0:
            vis = [0] * (n * m // 2 + 1)

            ans = []
            for x in lsts:
                if vis[x[0]]: continue
                vis[x[0]] = 1
                ans.extend(x)

            outs.append(' '.join(map(str, ans)))

        else:
            next_pos = [0] * (n * m // 2 + 1)
            idxs = [0] * (n * m // 2 + 1)

            for i, lst in enumerate(lsts):
                idxs[lst[0]] = i
                next_pos[lst[0]] = lst[m // 2]

            ans = []

            cur = lsts[0][0]
            for _ in range(n):
                ans.extend(lsts[idxs[cur]][:m // 2])
                cur = next_pos[cur]

            outs.append(' '.join(map(str, ans)))

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int n, m;
		cin >> n >> m;

		vector<vector<int>> lsts(n, vector<int>(m));
		for (auto &x: lsts) for (auto &y: x) cin >> y;

		if (n % 2 == 0) {
			vector<int> vis(n * m / 2 + 1, 0);
			for (auto &x: lsts) {
				if (vis[x[0]]) continue;
				for (auto &v: x) cout << v << ' ';
				vis[x[0]] = 1;
			}
		}
		else {
			vector<int> next_pos(n * m / 2 + 1, 0);
			vector<int> idxs(n * m / 2 + 1, 0);

			for (int i = 0; i < n; i ++) {
				next_pos[lsts[i][0]] = lsts[i][m / 2];
				idxs[lsts[i][0]] = i;
			}

			int cur = lsts[0][0];
			for (int j = 0; j < n; j ++) {
				for (int k = 0; k < m / 2; k ++) {
					cout << lsts[idxs[cur]][k] << ' ';
				}
				cur = next_pos[cur];
			}
		}
		cout << '\n';
	}

	return 0;
}
