int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int n;
		cin >> n;

		vector<int> nums(n);
		for (auto &v: nums) cin >> v;

		vector<int> order(n);
		iota(order.begin(), order.end(), 0);
		sort(order.begin(), order.end(), [&] (int i, int j) {return nums[i] < nums[j];});

		atcoder::fenwick_tree<int> fen(n);
		vector<int> res(n, 0);

		for (int i = n - 1; i >= 0; i --) {
			res[i] = fen.sum(0, order[i]);
			fen.add(order[i], 1);
		}

		int cur = 0;
		bool flg = true;

		for (int i = 0; i < n; i ++) {
			cur += res[i];
			if (cur > nums[order[i]]) {
				flg = false;
				break;
			}
		}

		cout << (flg ? "YES" : "NO") << '\n';
	}

	return 0;
}
