		cin >> n >> m;

		vector<int> cnt(m, 0);

		for (int i = 0; i < n; i ++) {
			string s;
			cin >> s;

			if (s[m - 1] == '1') cnt[m - 1] ++;

			for (int j = 0; j < m - 1; j ++) {
				if (s[j] != s[j + 1]) {
