**提示 1：** 考虑计算每个序列的序号。用二进制表示。

**提示 2：** 最高位如何确定？剩下的呢？

先看提示 1 。

二进制表示的最高位只取决于最后一个片是否到达了目标位置。

我们可以借此不断删掉最后一个片，进而确定每个二进制位。但过程中我们的出发位置和目标会发生调整。

我们称三个位置为出发位置、暂存位置和最终位置。

如果当前最大的一片还没到达最终位置，则倒数第二片还在不断向暂存位置调整（直到所有片都到达暂存位置时，最大片才能到达最终位置，所以倒数第二片目标实际上是暂存位置）。此时删去最大片后，最终位置和暂存位置应当互换。

否则，我们是在从暂存位置往最终位置挪动的过程中，因此是出发位置和暂存位置互换。

按照上述逻辑，不断模拟三种位置得到二进制表示的每一位，最后找最大值对应的下标即可。

时间复杂度为 $\mathcal{O}(nm)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n, m = MII()
    bin_2s = []

    for i in range(m):
        s = I()
        source, tmp, target = 'A', 'C', 'B'

        bin_2 = []

        for c in reversed(s):
            if c == target:
                bin_2.append(1)
                source, tmp = tmp, source
            else:
                bin_2.append(0)
                tmp, target = target, tmp

        bin_2s.append(bin_2)

    print(bin_2s.index(max(bin_2s)) + 1)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, m;
	cin >> n >> m;

	vector<string> bin_2s;

	for (int i = 0; i < m; i ++) {
		string s;
		cin >> s;

		char source = 'A', tmp = 'C', target = 'B';
		string bin_2;

		for (int j = n - 1; j >= 0; j --) {
			if (s[j] == target) {
				bin_2 += '1';
				swap(source, tmp);
			}
			else {
				bin_2 += '0';
				swap(tmp, target);
			}
		}

		bin_2s.emplace_back(bin_2);
	}

	cout << max_element(bin_2s.begin(), bin_2s.end()) - bin_2s.begin() + 1;

	return 0;
}
```

**提示 1：** 一位一位确定答案。

考虑贪心，假设剩下了 $x$ 个位，还要删掉一些数码。

如果我们下一位取的是数字 $v$ ，则最多只能保留 $v$ 及其后面的各个数字。同时，“删去数码” 的条件需要保留的数字个数大于等于把该删的数码全删掉的情况下剩余的数码。

除此之外，如果某个数码不能留下的话，应该退出枚举该数码。

所以我们要维护——某个数码下一次出现的位置，后缀中每个字符出现次数。这两个都很容易预处理。

时间复杂度为 $\mathcal{O}(n|\Sigma|^2)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    s = [int(c) - 1 for c in I()]
    cnt = LII()

    n = len(s)
    acc = [[0] * (n + 1) for _ in range(9)]
    next_pos = [[n] * (n + 1) for _ in range(9)]

    for i in range(n - 1, -1, -1):
        for j in range(9):
            next_pos[j][i] = next_pos[j][i + 1]
            acc[j][i] = acc[j][i + 1]
        next_pos[s[i]][i] = i
        acc[s[i]][i] += 1

    for i in range(n):
        cnt[s[i]] -= 1

    for i in range(9):
        cnt[i] = -cnt[i]

    ans = []
    total = sum(cnt)

    pt = 0
    for _ in range(total):
        for i in range(8, -1, -1):
            npt = next_pos[i][pt]
            flg = True

            for j in range(9):
                if acc[j][npt] < cnt[j]:
                    flg = False

            if flg and cnt[i]:
                ans.append(i + 1)
                cnt[i] -= 1
                pt = npt + 1
                break

    print(''.join(map(str, ans)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	string s;
	cin >> s;

	vector<int> cnt(10);
	for (int i = 1; i < 10; i ++) cin >> cnt[i];

	int n = s.size();

	vector<vector<int>> acc(10, vector<int>(n + 1, 0)), next_pos(10, vector<int>(n + 1, n));

	for (int i = n - 1; i >= 0; i --) {
		for (int j = 0; j < 10; j ++) {
			next_pos[j][i] = next_pos[j][i + 1];
			acc[j][i] = acc[j][i + 1];
		}
		next_pos[s[i] - '0'][i] = i;
		acc[s[i] - '0'][i] ++;
	}

	for (auto &c: s) cnt[c - '0'] --;

	int total = 0;
	for (int i = 0; i < 10; i ++) {
		cnt[i] = -cnt[i];
		total += cnt[i];
	}

	int pt = 0;
	while (total --) {
		for (int i = 9; i > 0; i --) {
			int npt = next_pos[i][pt];
			bool flg = true;

			for (int j = 0; j < 9; j ++) {
				if (acc[j][npt] < cnt[j]) {
					flg = false;
				}
			}

			if (flg && cnt[i]) {
				cout << i;
				cnt[i] --;
				pt = npt + 1;
				break;
			}
		}
	}

	return 0;
}
```

**提示 1：** 用总方案数减去不合法的方案数。

首先，如果 $x+y$ 都超过了 $g$ ，则怎么都没办法满足，输出 $0$ 就行。

否则，考虑总方案数 $C_{b+g}^g$ ，其中哪些方案不合法呢？

我们发现第 $b$ 个女生和倒数第 $g$ 个女生之间不能有任何男生，所以可以把她们看成一个整体，于是总共就有 $b+g-1$ 个女生的整体和 $x$ 个男生，排列方式就有 $C_{b+g-1}^x$ 种。

两者相减即答案，你只需要预处理阶乘和阶乘的逆元就行。预处理复杂度 $\mathcal{O}(M)$ ，每次输出答案复杂度为 $\mathcal{O}(1)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    t = II()
    outs = []

    M = 2 * 10 ** 6
    mod = 10 ** 9 + 7
    f = Factorial(M, mod)

    for _ in range(t):
        b, g, x, y = MII()
        if x + y > g: outs.append(0)
        else: outs.append((f.combi(b + g, b) - f.combi(b + x + y - 1, b)) % mod)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int M = 2e6, mod = 1e9 + 7;

	vector<int> f(M + 1), g(M + 1);
	f[0] = 1;
	for (int i = 1; i <= M; i ++)
		f[i] = 1ll * i * f[i - 1] % mod;
	g[M] = quickPow(f[M], mod - 2, mod);
	for (int i = M; i >= 1; i --)
		g[i - 1] = 1ll * i * g[i] % mod;

	auto comb = [&] (int x, int y) -> int {
		return 1ll * f[x] * g[y] % mod * g[x - y] % mod;
	};

	int t;
	cin >> t;

	while (t --) {
		int b0, g0, x, y;
		cin >> b0 >> g0 >> x >> y;

		if (x + y > g0) cout << "0\n";
		else {
			int ans = 0;
			ans = (ans + comb(b0 + g0, b0)) % mod;
			ans = (ans + mod - comb(b0 + x + y - 1, b0)) % mod;
			cout << ans << '\n';
		}
	}

	return 0;
}
```

**提示 1：** 如果一个元素要变到目标数值，肯定次数越少越好。这一步和别的是独立的。

**提示 2：** 处理完第一步后是经典问题。

如果一个元素要从 $1$ 变成目标的 $b_i$ ，操作次数一定越少越好。所以我们可以预处理这里需要变化多少次。

因为变化的过程是单调递增的，直接顺序进行 DP 即可。

发现这里的步长不超过 $12$ ，所以 $k$ 如果不小于 $12n$ ，其实是都可以变成目标数值的。

接下来相当于每个数字变动的次数是容量，产生的收益是价值，我们只需考虑一个经典的背包问题就好。

时间复杂度为 $\mathcal{O}(n^2M)$ ，其中 $M$ 是变化的步长，不超过 $12$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n = II()
    k = II()

    nums = LII()
    vals = LII()

    ops = [1000] * 1001
    ops[0] = ops[1] = 0

    for i in range(1, 1001):
        for j in range(1, 1001):
            ni = i + i // j
            if ni <= 1000:
                ops[ni] = fmin(ops[ni], ops[i] + 1)

    dp = [0] * 12001

    for i in range(n):
        x = ops[nums[i]]
        y = vals[i]

        for j in range(12000, x - 1, -1):
            dp[j] = fmax(dp[j], dp[j - x] + y)

    print(max(dp[:k + 1]))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int M = 1e3;
	vector<int> ops(M + 1, M);
	ops[0] = ops[1] = 0;

	for (int i = 1; i <= M; i ++) {
		for (int j = 1; j <= i; j ++) {
			int ni = i + i / j;
			if (ni <= M) {
				ops[ni] = min(ops[ni], ops[i] + 1);
			}
		}
	}

	int n, k;
	cin >> n >> k;

	vector<int> target(n), gains(n);
	for (auto &v: target) cin >> v;
	for (auto &v: gains) cin >> v;

	vector<int> dp(12001, 0);
	for (int i = 0; i < n; i ++) {
		int val = ops[target[i]], gain = gains[i];
		for (int j = 12000; j >= val; j --) {
			dp[j] = max(dp[j], dp[j - val] + gain);
		}
	}

	int ans = 0;
	for (int i = 0; i <= 12000 && i <= k; i ++)
		ans = max(ans, dp[i]);
	cout << ans << '\n';

	return 0;
}
```

**提示 1：** 如果 $k$ 足够大？

**提示 2：** 如果 $k$ 小怎么让调整的次数尽可能少？

首先，两个方向的步数是唯一重要的信息，先算出来。

在一个方向走 $x$ 步时，另一个方向最多走了 $(x+1)\times k$ 步（就是把 $x$ 步当中间的分割点，总共有 $x+1$ 段，每段长度是 $k$ ）。

所以如果给出的两个方向的步长差别不大，可以在上述范围内，就只需走两个方向的步数。

否则需要付出一些额外的步数来调整步数较多的那个方向。如果相对上述的基准多出了 $v$ 步，则怎么调整呢？我们应该先朝另一个方向走一步，再走 $k$ 步，走回来，再走 $k$ 步，以此类推。无论怎样，只要走了一个循环的一部分，就会多出两步。所以此时新增的步数是 $v$ 除以 $2k$ 的上取整，再乘 $2$ 。

时间复杂度为 $\mathcal{O}(1)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    t = II()
    outs = []

    for _ in range(t):
        sx, sy, tx, ty, k = MII()
        dx = abs(sx - tx)
        dy = abs(sy - ty)

        if dx < dy: dx, dy = dy, dx

        if dx <= (dy + 1) * k:
            outs.append(dx + dy)
        else:
            other = (dx - (dy + 1) * k + 2 * k - 1) // (2 * k) * 2
            outs.append(dx + dy + other)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		long long sx, sy, tx, ty, k;
		cin >> sx >> sy >> tx >> ty >> k;

		long long dx = abs(sx - tx), dy = abs(sy - ty);
		if (dx < dy) swap(dx, dy);

		if (dx <= (dy + 1) * k) cout << dx + dy << '\n';
		else cout << dx + dy + (dx - (dy + 1) * k + 2 * k - 1) / (2 * k) * 2 << '\n';
	}

	return 0;
}
```

**提示 1：** 先让所有行、列、对角线的和相等，再想办法让每条线都加一个相同的数。

**提示 2：** 特殊情况构造？

因为条件比较多，而自由度也比较高，所以我们不妨强加限制，让我们的构造更有方向。

我们想办法构造一个方案，使得行、列、对角的和都相等。

此时，基准就是一个全都是 $1$ 的矩阵，接下来我们就只要挑选几个位置加数值，使得行、列、对角仍然相等。我们尝试的构造就是让每行、列和对角线都只选择一个位置，加上固定的一个数 $v$ 。这部分的构造可以尽可能让你的构造有规律一些，比如说沿着某条斜线走。如果实在没有想到的话可以打印一下题解的构造。

发现 $n\leq 3$ 的情况比较特殊，但是手动构造也都很容易。

时间复杂度为 $\mathcal{O}(n^2)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n = II()

    if n == 3:
        print(1, 1, 2)
        print(1, 4, 3)
        print(2, 3, 3)
    else:
        ans = [[1] * n for _ in range(n)]

        if n > 2:
            v = 1024 - n
            if n % 2 == 0:
                ans[0][0] += v
                for i in range(1, n - 1):
                    ans[i][i + 1] += v
                ans[n - 1][1] += v
            else:
                ans[0][0] += v
                ans[1][n - 2] += v
                for i in range(2, n - 2):
                    ans[i][i - 1] += v
                ans[n - 2][n - 1] += v
                ans[n - 1][n - 3] += v

        print('\n'.join(' '.join(map(str, x)) for x in ans))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	if (n == 3) {
		cout << "1 1 2\n";
		cout << "1 4 3\n";
		cout << "2 3 3\n";
	}
	else {
		vector<vector<int>> ans(n, vector<int>(n, 1));
		int v = 1024 - n;

		if (n > 2) {
			if (n & 1) {
				ans[0][0] += v;
				ans[1][n - 2] += v;
				for (int i = 2; i < n - 2; i ++)
					ans[i][i - 1] += v;
				ans[n - 2][n - 1] += v;
				ans[n - 1][n - 3] += v;
			}
			else {
				ans[0][0] += v;
				for (int i = 1; i < n - 1; i ++)
					ans[i][i + 1] += v;
				ans[n - 1][1] += v;
			}
		}

		for (auto &x: ans) {
			for (auto &y: x) cout << y << ' ';
