			even ^= 1;
		}
	}

	if (!even) {
		for (int i = 0; i < m; i ++) {
			auto [u, v, w] = edges[i];
			if (w % 2 && !ans[i] && uf2.merge(u, v)) {
				ans[i] = 1;
