    while (t --) {
        int n;
        cin >> n;

        int v = (n + 1) >> 1;
        int l = 1, r = v - 1;

        while (l <= r) {
            int mid = (l + r) >> 1;

            int v1, v2;
            cout << 2 << ' ' << 2 * mid - 1 << endl;
            cin >> v1;
            cout << 1 << ' ' << 2 * mid << endl;
            cin >> v2;

            if (v1 == v2) l = mid + 1;
            else r = mid - 1;
        }

        cout << 3 << ' ' << 2 * r - 1 << ' ' << 2 * r + 1 << endl;
    }

