**提示 1：** 先考虑对于一个前缀， $0$ 对应的下标的方案数可以计算吗？

把问题考虑成一个个插入 $i$ 到已有的排列中。

下面放 $0$ 表示放标记为 $0$ 的那些下标，放 $1$ 也是类似的。

我们考虑放 $0$ 的方案数。

从小到大遍历 $i$ 。如果多了一个 $1$ ，无论插入位置如何，我们就多了一个放 $0$ 的位置。填完一个 $0$ 之后就少了一个位置。所以每个 $0$ 的选择方案数是固定的，可以使用乘法原理计数。

而这里放 $0$ 的方案数和放 $1$ 的位置是无关的，所以可以将原问题拆为两部分考虑。

而 $1$ 的方案数是类似的，只需从大到小遍历 $i$ 考虑即可。注意长度为奇数时无需遍历到开头，开头的 $1$ 可以插空放。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n = II()
    nums = LII()

    mod = 998244353

    ans = 1
    cur = 0

    for i in range(n):
        if nums[i]: cur += 1
        else:
            ans = ans * cur % mod
            cur -= 1

    cur = 0
    for i in range(n - 1, n % 2 - 1, -1):
        if nums[i]:
            ans = ans * cur % mod
            cur -= 1
        else:
            cur += 1

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

    int n;
    cin >> n;

    vector<int> nums(n);
    for (auto &v: nums) cin >> v;

    int mod = 998244353, ans = 1, cur = 0;

    for (int i = 0; i < n; i ++) {
        if (nums[i]) cur ++;
        else {
            ans = 1ll * ans * cur % mod;
            cur --;
        }
    }

    cur = 0;
    for (int i = n - 1; i >= n % 2; i --) {
        if (nums[i]) {
            ans = 1ll * ans * cur % mod;
            cur --;
        }
        else cur ++;
    }

    cout << ans;

	return 0;
}
```

**提示 1：** 相当于到 $x$ 的最低 level 比从 $x$ 返回的最低 level 更高。

**提示 2：** 如何计算这两者？

我们要求到达某个位置后无法折返则输出 NO ，否则输出 YES 。

则假设我们到达的位置是 $x$ ，则 $1$ 到 $x$ 所需的 level 一定低于 $x$ 到 $1$ 所需的 level 。

这两件事可以预处理，前者直接从 $1$ 开始跑最短路即可，后者可以把原有的 $u\to v$ 边变为 $v\to u$ 边跑最短路。接下来枚举 $x$ 进行比较即可。

时间复杂度为 $\mathcal{O}(n+m\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    inf = 2 * 10 ** 9

    def shortest_path(n, path):
        ans = [inf] * n
        ans[0] = 0

        pq = [0]
        while pq:
            d, u = divmod(heappop(pq), n)
            if ans[u] == d:
                for msk in path[u]:
                    nd, v = divmod(msk, n)
                    nd = fmax(d, nd)
                    if nd < ans[v]:
                        ans[v] = nd
                        heappush(pq, ans[v] * n + v)

        return ans

    n, m = MII()
    path = [[] for _ in range(n)]
    rev_path = [[] for _ in range(n)]

    for _ in range(m):
        u, v, w = MII()
        u -= 1
        v -= 1
        path[u].append(w * n + v)
        rev_path[v].append(w * n + u)

    d1 = shortest_path(n, path)
    d2 = shortest_path(n, rev_path)

    for i in range(n):
        if d2[i] > d1[i]:
            exit(print('NO'))

    print('YES')
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

    int n, m;
    cin >> n >> m;

    vector<vector<pair<int, int>>> path(n), rev_path(n);

    while (m --) {
        int u, v, w;
        cin >> u >> v >> w;
        u --, v --;
        path[u].emplace_back(v, w);
        rev_path[v].emplace_back(u, w);
    }

    int inf = 2e9;

    auto shortest_path = [&] (vector<vector<pair<int, int>>> paths) -> vector<int> {
        vector<int> ans(n, inf);
        ans[0] = 0;

        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
        pq.push({0, 0});

        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            if (ans[u] == d) {
                for (auto &[v, nd]: paths[u]) {
                    if (max(d, nd) < ans[v]) {
                        ans[v] = max(d, nd);
                        pq.push({ans[v], v});
                    }
                }
            }
        }

        return ans;
    };

    auto d1 = shortest_path(path);
    auto d2 = shortest_path(rev_path);

    for (int i = 0; i < n; i ++) {
        if (d2[i] > d1[i]) {
            return cout << "NO", 0;
        }
    }

    cout << "YES";

	return 0;
}
```

**提示 1：** 枚举第一个会议，第二个会议能否快速得到？

**提示 2：** 注意边界情况。

枚举第一个会议，第二个会议需要满足什么条件呢？要最优化什么问题呢？

首先我们将所有的 YN 转为 01，进而将字符串转化为二进制数。

则第二个会议需要满足原本是 0 的位目前都是 1，同时 1 的数量尽可能多。在数量一样多的情况下，需要满足这个会议的下标尽可能小。

我们如何预处理才能快速找到第二个会议呢？

我们现在对应的二进制数的位置，标记第二个会议的下标。接下来我们对其所有子集都可以用这个下标进行更新，而这件事可以用 SOS-DP 完成，即一步步转移各个二进制位，转移的过程中注意数字 1 位数的最大化和下标的最小化。

这样枚举第一个会议就可以快速用取反的记录结果得到答案了。

最后注意，如果存在满位的会议，上述查询结果会导致输出两个相同的会议，此时可以特判，只需找到另一个位数最多的会议即可。

时间复杂度为 $\mathcal{O}(n+m2^m)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n, m = MII()
    vals = [-100] * (1 << m)
    idxs = [0] * (1 << m)

    msks = []

    for i in range(n):
        s = I()
        msk = 0
        for j in range(m):
            if s[j] == 'Y':
                msk |= 1 << j

        msks.append(msk)

        if vals[msk] < 0:
            vals[msk] = 0
            idxs[msk] = i

    if vals[-1] == 0:
        chosen = -1
        for i in range(n):
            if i != idxs[-1] and (chosen == -1 or msks[chosen].bit_count() < msks[i].bit_count()):
                chosen = i

        x, y = chosen, idxs[-1]
        if x > y: x, y = y, x
        print(x + 1, y + 1)

    else:
        for i in range(m):
            for j in range(1 << m):
                if j >> i & 1:
                    nj = j ^ (1 << i)

                    if vals[j] + 1 > vals[nj] or (vals[j] + 1 == vals[nj] and idxs[j] < idxs[nj]):
                        vals[nj] = vals[j] + 1
                        idxs[nj] = idxs[j]

        cur = -1
        x, y = -1, -1
        for i in range(n):
            v = (1 << m) - 1 - msks[i]
            if vals[v] > cur:
                cur = vals[v]
                x, y = i, idxs[v]

        if cur >= 0: print(x + 1, y + 1)
        else: print('No')
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, m;
	cin >> n >> m;

	vector<int> vals(1 << m, -100), idxs(1 << m, 0), msks(n);

	for (int i = 0; i < n; i ++) {
		string s;
		cin >> s;

		for (int j = 0; j < m; j ++) {
			if (s[j] == 'Y') {
				msks[i] |= 1 << j;
			}
		}

		if (vals[msks[i]] < 0) {
			vals[msks[i]] = 0;
			idxs[msks[i]] = i;
		}
	}

	if (vals.back() == 0) {
		int x = idxs.back(), y = -1;
		for (int i = 0; i < n; i ++) {
			if (i != idxs.back() && (y == -1 || __popcount(msks[y]) < __popcount(msks[i]))) {
				y = i;
			}
		}
		if (x > y) swap(x, y);
		cout << x + 1 << ' ' << y + 1;
	}
	else {
		for (int i = 0; i < m; i ++) {
			for (int j = 0; j < 1 << m; j ++) {
				if (j >> i & 1) {
					int nj = j ^ (1 << i);
					if (vals[j] + 1 > vals[nj] || (vals[j] + 1 == vals[nj] && idxs[j] < idxs[nj])) {
						vals[nj] = vals[j] + 1;
						idxs[nj] = idxs[j];
					}
				}
			}
		}

		int cur = -1, x = -1, y = -1;

		for (int i = 0; i < n; i ++) {
			int v = (1 << m) - 1 - msks[i];
			if (vals[v] > cur) {
				cur = vals[v];
				x = i;
				y = idxs[v];
			}
		}

		if (cur >= 0) cout << x + 1 << ' ' << y + 1;
		else cout << "No";
	}

	return 0;
}
