**提示 1：** 博弈部分，策略如何？

**提示 2：** 如何最大化子数组数量？

首先，如果子数组中每个数都是偶数，那么第二个人只需要复制第一个人的操作就必胜了。所以我们要最小化全偶数的子数组的个数。

于是我们只需安排一些位置是奇数，一些位置是偶数，再把奇数和偶数分别排列起来就好了。

排列部分的方案很容易。选取位置的方案怎么办呢？

偶数显然可以被分配成一个一个出现的。而两个偶数之间必然插入至少一个奇数，这样最多多出来两个可以放奇数的位置，这个计数是很容易的。

多出来的奇数，可以放开头结尾 / 任何一个间隔，设有 $x$ 种情况，而最多多出来两个。如果多出来一个，方案数是 $x$ ，如果多出来两个，方案数是 $\frac{x(x+1)}{2}$ 。

时间复杂度为 $\mathcal{O}(M)$ 预处理，单次查询时间复杂度为 $\mathcal{O}(1)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    M = 3 * 10 ** 5
    mod = 10 ** 9 + 7

    f = [0] * (M + 1)
    f[0] = 1

    for i in range(1, M + 1):
        f[i] = i * f[i - 1] % mod

    t = II()
    outs = []

    for _ in range(t):
        n = II()
        ans = f[n // 2] * f[n - n // 2] % mod
        if n % 2 == 0: ans = ans * (n // 2 + 1) % mod
        else: ans = ans * ((n // 2 + 1) * (n // 2 + 2) // 2 % mod) % mod
        outs.append(ans)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

    int M = 3e5, mod = 1e9 + 7;
    vector<int> f(M + 1);

    f[0] = 1;
    for (int i = 1; i <= M; i ++) f[i] = 1ll * i * f[i - 1] % mod;

    int t;
    cin >> t;

    while (t --) {
        int n;
        cin >> n;

        int ans = 1ll * f[n / 2] * f[n - n / 2] % mod;
        if (n & 1) ans = 1ll * (n / 2 + 1) * (n / 2 + 2) / 2 % mod * ans % mod;
        else ans = 1ll * (n / 2 + 1) * ans % mod;

        cout << ans << '\n';
    }

	return 0;
}
```

**提示 1：** 选取的数需要满足的条件是什么？

**提示 2：** 设计 DP 状态。如何快速找到所有可行的转移？

考虑 $\max(x,y)\lt x\oplus y$ ，需要满足什么条件呢？不妨 $x\leq y$ ，则需要 $x$ 最高位的位置 $y$ 刚好是 $0$ 。

所以不妨从小到大取所有的数，则之前出现过的最高位在之后选取的数中不能再出现。

于是很自然地想到 $dp[msk]$ 表示当前最高位选取情况是 $msk$ 的情况下的最多选取数字个数。

考虑转移。从 $msk$ 出发，哪些是合法的转移呢？如果我们得到了合法的转移，则每个状态的转移最多只有 $\mathcal{O}(\log M)$ 个，就可以快速解决问题了。

对于某个 $msk$ ，哪些 $val$ 的转移会影响到它呢？对于某个 $val$ 而言，此前选取的 $msk$ 需要满足是 $val$ 中 $0$ 构成的位集合 $S$ 的子集，而转移到的状态是 $msk+val的最高位$ 。

所以我们可以预处理，在所有 $S$ 的位置打标记 $val的最高位$ ，然后可以用 $\mathcal{O}(M\log M)$ 的方式，将这些标记传递到所有自己中，这样所有的状态转移就被记录下来了。

时间复杂度为 $\mathcal{O}(n+M\log M)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n = II()
    nums = LII()

    vis = [0] * (1 << 22)

    for x in nums:
        bit = x.bit_length()
        v = (1 << bit) - 1
        vis[v ^ x] |= 1 << bit - 1

    for i in range(22):
        for j in range(1 << 22):
            if j >> i & 1:
                vis[j ^ (1 << i)] |= vis[j]

    dp = [0] * (1 << 22)

    for i in range(1 << 22):
        for j in range(22):
            if vis[i] >> j & 1:
                ni = i | (1 << j)
                dp[ni] = fmax(dp[ni], dp[i] + 1)

    print(max(dp))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

    int n;
    cin >> n;

    vector<int> nums(n);
    for (auto &v: nums) cin >> v;

    vector<int> vis(1 << 22, 0);
    for (auto &x: nums) {
        int bit = 32 - __builtin_clz(x);
        vis[((1 << bit) - 1) ^ x] |= 1 << (bit - 1);
    }

    for (int i = 0; i < 22; i ++) {
        for (int j = 0; j < 1 << 22; j ++) {
            if (j >> i & 1) {
                vis[j ^ (1 << i)] |= vis[j];
            }
        }
    }

    vector<int> dp(1 << 22, 0);
    for (int i = 0; i < 1 << 22; i ++) {
        for (int j = 0; j < 22; j ++) {
            if (vis[i] >> j & 1) {
                int ni = i | (1 << j);
                dp[ni] = max(dp[ni], dp[i] + 1);
            }
        }
    }

    cout << *max_element(dp.begin(), dp.end());

	return 0;
}
```

**提示 1：** 对于一个子矩形，其数值的范围？

**提示 2：** 存下来一些结果，后面查询就方便了。

首先，对于一个子矩形而言，其对应的最小值和最大值一个在左上角一个在右下角。

因为中间的元素可以比上面的元素大，走到上边缘后比左侧的数大。跟右下角的比较是类似的。

所以我们可以直接遍历可能的正方形，枚举左上角和边长，得到所有可能的子正方形的答案，总共有 $\mathcal{O}(n^3)$ 个正方形。

接下来每次查询，我们枚举可能的正方形边长，看是否被一个正方形的范围包含。这个怎么快速判断呢？我们可以预处理左端点小于等于 $x$ 的最大的右端点，如果 $a$ 对应的数值大于等于 $b$ ，则此时存在对应大小的正方形满足要求。

时间复杂度为 $\mathcal{O}(n^3+qn)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n, q = MII()
    grid = [LII() for _ in range(n)]

    saved = [[n * n + 1] * (n * n + 1) for _ in range(n)]

    for i in range(n):
        for j in range(n):
            for k in range(n):
                if i + k >= n or j + k >= n:
                    break
                saved[k][grid[i][j]] = fmin(saved[k][grid[i][j]], grid[i + k][j + k])

    for i in range(n):
        for j in range(n * n - 1, -1, -1):
            saved[i][j] = fmin(saved[i][j], saved[i][j + 1])

    outs = []

    for _ in range(q):
        a, b = MII()

        for i in range(n - 1, -1, -1):
            if saved[i][a] <= b:
                outs.append((i + 1) ** 2)
                break

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

    int n, q;
    cin >> n >> q;

    vector<vector<int>> grid(n, vector<int>(n));
    for (auto &x: grid) for (auto &y: x) cin >> y;

    vector<vector<int>> saved(n, vector<int>(n * n + 1, n * n + 1));

    for (int i = 0; i < n; i ++) {
        for (int j = 0; j < n; j ++) {
            for (int k = 0; i + k < n && j + k < n; k ++) {
                saved[k][grid[i][j]] = min(saved[k][grid[i][j]], grid[i + k][j + k]);
            }
        }
    }

    for (int i = 0; i < n; i ++) {
        for (int j = n * n - 1; j >= 0; j --) {
            saved[i][j] = min(saved[i][j], saved[i][j + 1]);
        }
    }

    while (q --) {
        int a, b;
        cin >> a >> b;

        for (int i = n - 1; i >= 0; i --) {
            if (saved[i][a] <= b) {
                cout << (i + 1) * (i + 1) << '\n';
                break;
            }
        }
    }

	return 0;
}
```

**提示 1：** 两种想法——检查某个答案是否满足要求；找到分开两条路径的边。

方法一：越大的最小值越难凑，所以考虑使用二分，在树上进行 DP 。DP 维护从更深的位置到当前结点的最大路径权值。DP 的过程中，能合并且凑出大于等于 $x$ 的分支路径直接合并，并将当前节点网上传的数值变为 $-∞$ 。

方法二：对于一个子树而言，我们可以很方便地维护子树内路径的最大权值。而我们枚举分开两条路径的边，则其中一侧是子树的问题，另一侧是去掉这个子树的问题。前者可以直接 DP ，后者用换根 DP 可以解决。

时间复杂度为 $\mathcal{O}(n)$ 或者 $\mathcal{O}(n\log nM)$ ，当然这题原来的时限是 $1$ 秒，所以后者可能被卡，但是我用coach mode 改成了 $2$ 秒。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    t = II()
    outs = []

    for _ in range(t):
        n = II()
        path = [[] for _ in range(n)]

        for _ in range(n - 1):
            u, v, w = MII()
            u -= 1
            v -= 1
            path[u].append(w * n + v)
            path[v].append(w * n + u)

        parent = [-1] * n
        que = [0]

        for u in que:
            for msk in path[u]:
                w, v = divmod(msk, n)
                if parent[u] != v:
                    parent[v] = u
                    que.append(v)

        dp0 = [0] * n
        dp1 = [0] * n

        for u in reversed(que):
            v1, v2 = 0, 0

            for msk in path[u]:
                w, v = divmod(msk, n)
                if parent[v] == u:
                    nw = w + dp0[v]
                    if nw > v1: v1, v2 = nw, v1
                    elif nw > v2: v2 = nw
                    dp1[u] = fmax(dp1[u], dp1[v])

            dp0[u] = v1
            dp1[u] = fmax(dp1[u], v1 + v2)

        up_dp0 = [0] * n
        up_dp1 = [0] * n

        for u in que:
            v1, v2, v3 = up_dp0[u], 0, 0
            w1, w2 = 0, 0

            for msk in path[u]:
                w, v = divmod(msk, n)

                if parent[v] == u:
                    nw = w + dp0[v]
                    if nw > v1: v1, v2, v3 = nw, v1, v2
                    elif nw > v2: v2, v3 = nw, v2
                    elif nw > v3: v3 = nw

                    if dp1[v] > w1: w1, w2 = dp1[v], w1
                    elif dp1[v] > w2: w2 = dp1[v]

            for msk in path[u]:
                w, v = divmod(msk, n)

                if parent[v] == u:
                    nw = w + dp0[v]
                    if nw == v1:
                        up_dp0[v] = v2 + w
                        up_dp1[v] = v2 + v3
                    elif nw == v2:
                        up_dp0[v] = v1 + w
                        up_dp1[v] = v1 + v3
                    else:
                        up_dp0[v] = v1 + w
                        up_dp1[v] = v1 + v2

                    if dp1[v] == w1: up_dp1[v] = fmax(up_dp1[v], w2)
                    else: up_dp1[v] = fmax(up_dp1[v], w1)

        outs.append(max(fmin(dp1[i], up_dp1[i]) for i in range(n)))

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int n;
		cin >> n;

		vector<vector<pair<int, int>>> path(n);
		for (int i = 0; i < n - 1; i ++) {
			int u, v, w;
			cin >> u >> v >> w;
			u --, v --;
			path[u].emplace_back(v, w);
			path[v].emplace_back(u, w);
		}

		vector<long long> dp0(n, 0), dp1(n, 0);

		auto dfs1 = [&] (auto &self, int u, int p) -> void {
			long long v1 = 0, v2 = 0;
			for (auto &[v, w]: path[u]) {
				if (v != p) {
					self(self, v, u);
					long long nw = w + dp0[v];

					if (nw > v1) swap(v1, v2), v1 = nw;
					else if (nw > v2) v2 = nw;

					dp1[u] = max(dp1[u], dp1[v]);
				}
			}

			dp0[u] = v1;
			dp1[u] = max(dp1[u], v1 + v2);
		};

		dfs1(dfs1, 0, -1);

		long long ans = 0;

		auto dfs2 = [&] (auto &self, int u, int p, long long up0, long long up1) -> void {
			long long v1 = up0, v2 = 0, v3 = 0;
			long long w1 = 0, w2 = 0;

			ans = max(ans, min(dp1[u], up1));

			for (auto &[v, w]: path[u]) {
				if (v != p) {
					long long nw = w + dp0[v];
					if (nw > v1) swap(v2, v3), swap(v1, v2), v1 = nw;
					else if (nw > v2) swap(v2, v3), v2 = nw;
					else if (nw > v3) v3 = nw;

					if (dp1[v] > w1) swap(w1, w2), w1 = dp1[v];
					else if (dp1[v] > w2) w2 = dp1[v];
				}
			}

			for (auto &[v, w]: path[u]) {
				if (v != p) {
					long long nup0, nup1;
					long long nw = w + dp0[v];

					if (nw == v1) {
						nup0 = v2 + w;
						nup1 = v2 + v3;
					}
					else if (nw == v2) {
						nup0 = v1 + w;
						nup1 = v1 + v3;
					}
					else {
						nup0 = v1 + w;
						nup1 = v1 + v2;
					}

					if (dp1[v] == w1) nup1 = max(nup1, w2);
					else nup1 = max(nup1, w1);

					self(self, v, u, nup0, nup1);
				}
			}
		};

		dfs2(dfs2, 0, -1, 0, 0);

		cout << ans << '\n';
	}

	return 0;
}
```

**提示 1：** 对一组完全固定的字符串，答案咋算？

**提示 2：** 一个字母一个字母考虑。

如果各个字母的出现次数是 $c_1,c_2,\dots, c_{26}$ ，则方案数是 $\frac{(c_1+c_2+\dots+c_{26})!}{c_1!c_2!\dots c_{26}!}$ 。

分母部分是固定的，而分子是需要分配的。

所以一个字母一个字母考虑，假设原有的字母是 $a_1,a_2,\dots,a_{26}$ ，新增的字母数量是 $b_1,b_2,\dots,b_{26}$ 。

则构造字符串的方案数是 $\frac{((a_1+b_1)+(a_2+b_2)+\dots+(a_{26}+b_{26}))!}{(a_1+b_1)!(a_2+b_2)!\dots(a_{26}+b_{26})!}$ 。

而问号分配成 $b_1,b_2,\dots,b_{26}$ 个对应字母的方案数是 $\frac{(b_1+b_2+\dots+b_{26})!}{b_1!b_2!\dots b_{26}!}$ 。 

所以我们就要求 $\frac{((a_1+b_1)+(a_2+b_2)+\dots+(a_{26}+b_{26}))!}{(a_1+b_1)!(a_2+b_2)!\dots(a_{26}+b_{26})!}\frac{(b_1+b_2+\dots+b_{26})!}{b_1!b_2!\dots b_{26}!}$ 关于不同的 $\{b_i\}$ 的组合的求和，再除以总的方案数。

注意到分子是固定的。而每一步选取 $b_i$ 跟其他的字母是相互独立的，直接用背包，转移系数是 $\frac{1}{(a_i+b_i)!b_i!}$ 即可。

具体地，假设当前的 $b_i$ 的和是 $M$ ，我们枚举新的 $b_i=x$ ，则和转移到 $M+x$ ，且系数多了个 $\frac{1}{(a_i+b_i)!b_i!}$ ，乘上就好。

时间复杂度为 $\mathcal{O}(n^2|\Sigma|)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    mod = 10 ** 9 + 7
    f = Factorial(1000, mod)

    t = II()
    outs = []

    rev26 = pow(26, -1, mod)
    pw_rev26 = [1] * 1001

    for i in range(1000):
        pw_rev26[i + 1] = pw_rev26[i] * rev26 % mod

    for _ in range(t):
        s = I()

        cnt = [0] * 26
        to_fill = 0

        for c in s:
            if 'a' <= c <= 'z':
                cnt[ord(c) - ord('a')] += 1
            else:
                to_fill += 1

        dp = [0] * (to_fill + 1)
        dp[0] = 1

        for i in range(26):
            for j in range(to_fill, -1, -1):
                if dp[j]:
                    for k in range(1, to_fill - j + 1):
                        dp[j + k] += dp[j] * f.fac_inv(cnt[i] + k) % mod * f.fac_inv(k) % mod
                        dp[j + k] %= mod
                    dp[j] = dp[j] * f.fac_inv(cnt[i]) % mod

        outs.append(dp[to_fill] * f.fac(to_fill) % mod * f.fac(len(s)) % mod * pw_rev26[to_fill] % mod)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int mod = 1e9 + 7;

	vector<int> f(1001), g(1001);
	f[0] = 1;
	for (int i = 1; i <= 1000; i ++)
		f[i] = 1ll * i * f[i - 1] % mod;
	g[1000] = quickPow(f[1000], mod - 2, mod);
	for (int i = 1000; i >= 1; i --)
		g[i - 1] = 1ll * i * g[i] % mod;

	int rev26 = quickPow(26, mod - 2, mod);
	vector<int> pw_rev26(1001);
	pw_rev26[0] = 1;
	for (int i = 1; i <= 1000; i ++)
		pw_rev26[i] = 1ll * pw_rev26[i - 1] * rev26 % mod;

	int t;
	cin >> t;

	while (t --) {
		string s;
		cin >> s;

		vector<int> cnt(26, 0);
		int to_fill = 0;

		for (auto &c: s) {
			if (c >= 'a' && c <= 'z') cnt[c - 'a'] ++;
			else to_fill ++;
		}

		vector<int> dp(to_fill + 1, 0);
		dp[0] = 1;

		for (int i = 0; i < 26; i ++) {
			for (int j = to_fill; j >= 0; j --) {
				if (dp[j]) {
					for (int k = 1; k <= to_fill - j; k ++) {
						dp[j + k] = (dp[j + k] + 1ll * dp[j] * g[cnt[i] + k] % mod * g[k] % mod) % mod;
					}
					dp[j] = 1ll * dp[j] * g[cnt[i]] % mod;
				}
			}
		}

		cout << 1ll * dp[to_fill] * f[to_fill] % mod * f[s.size()] % mod * pw_rev26[to_fill] % mod << '\n';
	}

	return 0;
}
```

