	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int a, b, c;
		cin >> a >> b >> c;
		cout << c - gcd((long long)c, 1ll * a * b / gcd(a, b)) << '\n';
	}

	return 0;
}
