	cin.tie(0);
	cout.tie(0);

	int n, m, k;
	cin >> n >> m >> k;

	vector<int> deg(n + 1, 0);
	vector<array<int, 3>> ops;

	for (int i = 0; i < m + k; i ++) {
		int u, v;
		cin >> u >> v;
		deg[u] ^= 1, deg[v] ^= 1;
		if (u > 1 && v > 1) ops.push_back({1, u, v});
	}

