int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int n, q;
		cin >> n >> q;

		vector<vector<int>> grid(n, vector<int>(n));
		for (auto &x: grid) for (auto &y: x) cin >> y;

		vector<int> saved(2 * n - 1, 0);
		vector<vector<long long>> dp(n, vector<long long>(n));

		while (q --) {
			int k, v;
