int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, x, y, mod = 1e9 + 7;
	cin >> n >> x >> y;

	x = n - x, y = n - y;
	vector<vector<int>> dp(x + 1, vector<int>(x + 1, 0));

	int rev2 = (mod + 1) / 2;

	for (int i = 0; i <= x; i ++) {
		for (int j = 0; j < i; j ++) {
			int v = dp[i - 1][abs(j - 1)];
			if (j + 1 <= i - 1) v += dp[i - 1][j + 1];
			dp[i][j] = (1ll * v * rev2 + 1) % mod;
		}
	}

