**提示 1：** 数组至于比较小，高的位不受影响。

**提示 2：** 更低的位有什么不同的情况？

首先，数组的值域严格小于 $2^{17}$ ，所以对于 $x$ 的不小于 $2^{17}$ 的位，实际上都完全不进行异或的操作。我们这一部分认为是 $2^{17}\times n\times val$ 。

而对于更小的位，我们只需预处理 $0\sim 2^{17}-1$ 对应的不同的异或结果，就能得到更低的位的可能数值。

如何快速求 $x$ 对应的答案呢？直接预处理，统计每个位有多少个数是 $0$ ，多少个数是 $1$ 。接下来考虑每一位有多少个数跟 $x$ 产生 $1$ 的异或数值，各个位的结果加总即可。

这样我们就得到了 $0\sim 2^{17}-1$ 对应的不同的异或结果，将其去重。而所有的可能取值就是这些数加上若干倍的 $2^{17}\times n$ ，我们只需算这些数有多少个在 $[l,r]$ 之间。

通过枚举基准数进行计算，这是简单的。

时间复杂度为 $\mathcal{O}((n+M)\log M)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n, l, r = MII()
    nums = LII()

    cnt = [[0] * 17 for _ in range(2)]

    for x in nums:
        for i in range(17):
            cnt[x >> i & 1][i] += 1

    M = 1 << 17

    vals = [0] * M

    for i in range(M):
        for j in range(17):
            vals[i] += cnt[(i >> j & 1) ^ 1][j] << j

    vals.sort()

    ans = 0
    for i in range(M):
        if i == 0 or vals[i] != vals[i - 1]:
            ans += (r - vals[i]) // (M * n) - (l - 1 - vals[i]) // (M * n)

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	long long l, r;
	cin >> n >> l >> r;

	vector<int> nums(n);
	for (auto &v: nums) cin >> v;

	vector<vector<int>> cnt(2, vector<int>(17, 0));

	for (auto &x: nums) {
		for (int i = 0; i < 17; i ++) {
			cnt[x >> i & 1][i] ++;
		}
	}

	long long M = 1 << 17;
	vector<long long> saved(M, 0);

	for (int i = 0; i < M; i ++) {
		for (int j = 0; j < 17; j ++) {
			saved[i] += (1ll << j) * cnt[(i >> j & 1) ^ 1][j];
		}
	}

	sort(saved.begin(), saved.end());

	auto floor_div = [&] (long long x, long long y) -> long long {
		long long res = x / y;
		if (res * y > x) res --;
		return res;
	};

	long long ans = 0;
	for (int i = 0; i < M; i ++) {
		if (i == 0 || saved[i] != saved[i - 1]) {
			ans += floor_div(r - saved[i], M * n) - floor_div(l - 1 - saved[i], M * n);
		}
	}

	cout << ans;

	return 0;
}
```

**提示 1：** 找回文的子数组显然用 Manacher 。

**提示 2：** 考虑每个元素对最终结果的贡献。

对称子数组就是回文子数组，因此可以用 Manacher 得到每个中心位置对应的回文串。

接下来考虑每个位置的对最终结果的贡献。

考虑 $idx$ 为中心的最长回文子数组是 $[l,r]$ ，则 $[l,r],[l+1,r-1],\dots$ 这些都得在最终结果中算一遍，因此每个位置的权值分别是 $1,2,3,\dots,3,2,1$ ，我们只要能更新这个权值，则对于所有中心都更新一遍，就可以得到某个位置的总权值，乘以数值再相加就是答案了。

这个怎么更新呢？我们看成更新两段线段。每段线段相当于取一个区间加了 $k\times 下标+b$ ，因此差分的时候分斜率和截距两部分更新就行。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    t = II()
    outs = []

    mod = 10 ** 9 + 7

    for _ in range(t):
        n = II()
        nums = LII()

        tmp = [-1]
        for x in nums:
            tmp.append(x)
            tmp.append(-1)

        wing = [0] * (2 * n + 1)
        idx = 0

        for i in range(2 * n + 1):
            if idx + wing[idx] >= i:
                wing[i] = fmin(wing[2 * idx - i], idx + wing[idx] - i)

            while i > wing[i] and i + wing[i] < 2 * n and tmp[i - wing[i] - 1] == tmp[i + wing[i] + 1]:
                wing[i] += 1

            if wing[i] + i > wing[idx] + idx:
                idx = i

        diff_k = [0] * (n + 1)
        diff_b = [0] * (n + 1)

        for i in range(2 * n + 1):
            l = (i - wing[i]) // 2
            r = (i + wing[i]) // 2

            mid = (l + r + 1) // 2
            diff_k[l] += 1
            diff_k[mid] -= 1
            diff_b[l] -= l - 1
            diff_b[mid] += l - 1

            diff_k[mid] -= 1
            diff_k[r] += 1
            diff_b[mid] += r
            diff_b[r] -= r

        for i in range(n):
            diff_k[i] %= mod
            diff_b[i] %= mod
            diff_k[i + 1] += diff_k[i]
            diff_b[i + 1] += diff_b[i]

        ans = 0
        for i in range(n):
            ans += (diff_k[i] * i + diff_b[i]) % mod * nums[i] % mod
            ans %= mod

        outs.append(ans)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t, mod = 1e9 + 7;
	cin >> t;

	while (t --) {
		int n;
		cin >> n;

		vector<int> nums(n), tmp(2 * n + 1, -1);
		for (int i = 0; i < n; i ++) {
			cin >> nums[i];
			tmp[2 * i + 1] = nums[i];
		}

		vector<int> wing(2 * n + 1, 0);
		int idx = 0;

		for (int i = 0; i <= 2 * n; i ++) {
			if (idx + wing[idx] >= i)
				wing[i] = min(wing[2 * idx - i], idx + wing[idx] - i);
			while (i > wing[i] && i + wing[i] < 2 * n && tmp[i - wing[i] - 1] == tmp[i + wing[i] + 1])
				wing[i] ++;
			if (wing[i] + i > wing[idx] + idx) idx = i;
		}

		vector<int> diff_k(n + 1, 0), diff_b(n + 1, 0);

		auto add = [&] (int &x, int y) -> void {
			x += y;
			if (x >= mod) x -= mod;
		};

		auto minus = [&] (int &x, int y) -> void {
			x -= y;
			if (x < 0) x += mod;
		};

		for (int i = 0; i <= 2 * n; i ++) {
			int l = (i - wing[i]) / 2, r = (i + wing[i]) / 2;
			int mid = (l + r + 1) / 2;

			add(diff_k[l], 1);
			minus(diff_k[mid], 1);
			minus(diff_b[l], (l - 1 + mod) % mod);
			add(diff_b[mid], (l - 1 + mod) % mod);

			minus(diff_k[mid], 1);
			add(diff_k[r], 1);
			add(diff_b[mid], r);
			minus(diff_b[r], r);
		}

		for (int i = 0; i < n; i ++) {
			add(diff_k[i + 1], diff_k[i]);
			add(diff_b[i + 1], diff_b[i]);
		}

		int ans = 0;
		for (int i = 0; i < n; i ++)
			add(ans, (1ll * diff_k[i] * i + diff_b[i]) % mod * nums[i] % mod);

		cout << ans << '\n';
	}

	return 0;
}
```

**提示 1：** 用一个变量代表当前的状态。

**提示 2：** 状态是如何转移的？应该如何由此推到初始状态和结束状态的关系。

这题表面上操作后的状态特别多，因为每个队伍都有一定的人数，相互组合肯定很庞大。而这题既然可做一定有一个很好的方式来概括当前的状态。

事实上，我们考虑：当前状态至少需要多少次操作到达最终状态。即，此时每条队伍为 $v_1,v_2,\dots,v_n$ ，则我们取变量 $X=\max(a_1-v_1,a_2-v_2,\dots,a_n-v_n)$ ，我们初始的 $X=\max a_i$ ，最终的状态是 $X=0$ 。

这个状态转移好考虑吗？实际上是肯定的。

假设当前状态是 $X$ ，如果操作了第 $i$ 个队列，那么上述最大值怎么改变呢？别的项都减少 $1$ ，就第 $i$ 项重置为 $a_i$ ，因此会变成 $\max(X-1,a_i)$ 。

因此这个状态就足够概括解决问题需要的全部信息。

考虑 $a_i$ 将各个状态分为一段一段的，则上述转移在不同段之间是有差异的，一段段转移即可。

是根据 $f(x)=\frac{1}{n}\sum f(\max(x-1,a_i))+1$ ，推出 $f(x-1)=kf(x)+一堆更大的f(x')+b$ 。

我们不妨设 $f(\max a_i)$ 是 $V$ ，则每一个 $f(x)$ 都可以用 $V$ 的一次函数表示，从后往前，维护 $f(x')$ 的和，则每一段的递推都是类似 $a_{x-1}=Aa_x+B$ 的形式，这个形式可以用矩阵快速幂 / 不动点法 + 快速幂快速完成一段的递推。

具体而言，找到 $x=Ax+B$ 的解 $x_0$ ，则 $a_{x-1}-x_0=A(a_x-x_0)$ ，这样就得到了一段等比数列，快速幂就能得到这一段开头的结果了。

最后，根据 $f(0)=0$ ，求解关于 $V$ 的方程就能得到答案了。

时间复杂度为 $\mathcal{O}(n\log M)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n = II()
    nums = LII()
    mod = 10 ** 9 + 7

    f = Factorial(n, mod)

    nums.sort()
    cnt = [0] * n

    for x in nums:
        cnt[bisect.bisect_left(nums, x)] += 1

    revn = pow(n, -1, mod)

    last_k, last_b = 0, 0
    k, b = 0, 0
    cur = -1
    resid = n

    for i in range(n - 1, -1, -1):
        if cnt[i]:
            if cur == -1:
                last_k, last_b = 1, 0
            else:
                rev_resid = f.inv(resid)
                vk = n * rev_resid % mod
                rev_vk_1 = pow(vk - 1, -1, mod)
                pw_vk = pow(vk, cur - nums[i], mod)

                vb = (mod - k) * rev_resid % mod
                fix = (mod - vb) * rev_vk_1 % mod
                last_k = ((last_k - fix) * pw_vk + fix) % mod

                vb = (mod - (n + b) % mod) * rev_resid % mod
                fix = (mod - vb) * rev_vk_1 % mod
                last_b = ((last_b - fix) * pw_vk + fix) % mod

            k = (k + last_k * cnt[i]) % mod
            b = (b + last_b * cnt[i]) % mod
            cur = nums[i]

            resid -= cnt[i]

    print((mod - last_b) * pow(last_k, -1, mod) % mod)
```

C++ 做法如下——

```cpp []
long long quickPow(long long base, long long power, long long mod) {
    if (power == 0) return 1 % mod;
    long long cur = quickPow(base, power / 2, mod);
    return power & 1 ? base * cur % mod * cur % mod : cur * cur % mod; 
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, mod = 1e9 + 7;
	cin >> n;

	vector<long long> nums(n);
	for (auto &x: nums) cin >> x;

	vector<int> f(n + 1), g(n + 1);
	f[0] = 1;
	for (int i = 1; i <= n; i ++)
		f[i] = 1ll * i * f[i - 1] % mod;
	g[n] = quickPow(f[n], mod - 2, mod);
	for (int i = n; i >= 1; i --)
		g[i - 1] = 1ll * i * g[i] % mod;

	sort(nums.begin(), nums.end());
	vector<int> cnt(n, 0);

	for (auto &x: nums)
		cnt[lower_bound(nums.begin(), nums.end(), x) - nums.begin()] ++;

	int revn = 1ll * f[n - 1] * g[n] % mod;

	int last_k = 0, last_b = 0;
	int k = 0, b = 0;
	long long cur = -1;
	int resid = n;

	for (int i = n - 1; i >= 0; i --) {
		if (cnt[i]) {
			if (cur == -1)
				last_k = 1, last_b = 0;
			else {
				int rev_resid = 1ll * f[resid - 1] * g[resid] % mod;
				int vk = 1ll * n * rev_resid % mod;
				int rev_vk_1 = quickPow(vk - 1, mod - 2, mod);
				int pw_vk = quickPow(vk, cur - nums[i], mod);

				int vb, fix;
				vb = 1ll * (mod - k) * rev_resid % mod;
				fix = 1ll * (mod - vb) * rev_vk_1 % mod;
				last_k = (1ll * (last_k - fix + mod) % mod * pw_vk % mod + fix) % mod;

				vb = 1ll * (mod - (n + b) % mod) * rev_resid % mod;
				fix = 1ll * (mod - vb) * rev_vk_1 % mod;
				last_b = (1ll * (last_b - fix + mod) % mod * pw_vk % mod + fix) % mod;
			}
			k = (1ll * last_k * cnt[i] + k) % mod;
			b = (1ll * last_b * cnt[i] + b) % mod;
			cur = nums[i];
			resid -= cnt[i];
		}
	}

	cout << 1ll * (mod - last_b) * quickPow(last_k, mod - 2, mod) % mod;

	return 0;
}
```

**提示 1：** 假设某一轮插入了元素 $a_i$ ，逆序对数量如何改变？

**提示 2：** 实际选择是独立的。

考虑第 $i$ 轮，在前面插入元素的新增逆序对个数等于前面的数中比它小的数的个数，在后面插入元素的新增逆序对个数等于前面的数中比它大的数的个数。

这两件事都不跟前面 / 后面的选择有关，所以每次选择是独立的。

我们先用树状数组分别求两种贡献。

接下来假设全部插入到后面去，然后不断把一个个操作调整为从前面插入，相当于我们要最小化修改后的变动数值。

考虑将变动数值存在一个数组中，进行排序，按照排序结果一个个变动就行。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    t = II()
    outs = []

    for _ in range(t):
        n = II()
        nums = LII()

        fen = FenwickTree(n + 1)
        ans = 0
        diff = []

        for x in nums:
            v1 = fen.rsum(x + 1, n)
            v2 = fen.rsum(0, x - 1)

            ans += v1
            diff.append(v2 - v1)

            fen.add(x, 1)

        diff.sort()

        res = [ans]

        for x in diff:
            res.append(res[-1] + x)

        outs.append(' '.join(map(str, res)))

    print('\n'.join(outs))
