**提示 1：** 我们相当于要看一个区间内出现过哪些不同的质因数。

**提示 2：** 对于某个固定的左端点而言，我们只在意某个质因子在这个位置后第一次出现的位置。

我们相当于要求一个区间内出现过的质因子的乘积。

对于一个固定的左端点而言，我们只在意每个质因子此后第一次出现的位置，在对应的位置标记。这样我们可以用区间查询区间内标记的所有质数的乘积来解决问题。

我们将查询离线，这样就只需解决上面的东西的维护就行。

考虑从右往左移动左端点，假设从 $i+1$ 移动到 $i$ ，则需要更新的质数就是 $nums[i]$ 的质因子。我们找到这些质因子之前的最早出现位置，将其撤销，也就是除以 $p$ 。最后将这些质数的乘积更新到 $i$ 位置即可。这样每个质因子都标记在了最早出现的位置。而我们的查询就相当于算区间乘积，这是很容易用线段树维护的。

也就是我们从后往前遍历左端点，并且遍历到某个左端点时，解决所有左端点在该位置的查询。

整体而言需要更新 $\mathcal{O}(\log M)$ 个位置，每次更新复杂度是 $\mathcal{O}(\log n)$ 的，查询时只需求区间乘积，所以时间复杂度为 $\mathcal{O}(n\log n\log M+q\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    M = 2 * 10 ** 5
    pr = list(range(M + 1))

    for i in range(2, M + 1):
        if pr[i] == i:
            for j in range(i, M + 1, i):
                pr[j] = i

    mod = 10 ** 9 + 7

    n, q = MII()
    nums = LII()

    queries = [[] for _ in range(n)]

    for i in range(q):
        l, r = GMI()
        queries[l].append((i, r))

    last_pos = [n] * (M + 1)

    def op(x, y): return x * y % mod

    seg = SegTree(op, 1, n)
    ans = [0] * q

    for i in range(n - 1, -1, -1):
        prs = []
        x = nums[i]

        while x > 1:
            p = pr[x]
            prs.append(p)

            while x % p == 0:
                x //= p

        val = 1
        for p in prs:
            if last_pos[p] < n:
                seg.set(last_pos[p], seg.get(last_pos[p]) // p)
            val *= p
            last_pos[p] = i

        seg.set(i, val)

        for idx, r in queries[i]:
            ans[idx] = seg.prod(0, r + 1)

    print('\n'.join(map(str, ans)))
```

C++ 做法如下——

```cpp []
const int mod = 1e9 + 7;

int op(int x, int y) {return 1ll * x * y % mod;}

int e() {return 1;}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int M = 2e5;
	vector<int> pr(M + 1, 0);

	for (int i = 2; i <= M; i ++) {
		if (!pr[i]) {
			for (int j = i; j <= M; j += i) {
				pr[j] = i;
			}
		}
	}

	int n, q;
	cin >> n >> q;

	vector<int> nums(n);
	for (auto &x: nums) cin >> x;

	vector<vector<pair<int, int>>> queries(n);

	for (int i = 0; i < q; i ++) {
		int l, r;
		cin >> l >> r;

		l --, r --;
		queries[l].emplace_back(i, r);
	}

	vector<int> last_pos(M + 1, n);

	atcoder::segtree<int, op, e> seg(n);
	vector<int> ans(q);

	for (int i = n - 1; i >= 0; i --) {
		vector<int> prs;
		int x = nums[i];

		while (x > 1) {
			int p = pr[x];
			prs.emplace_back(p);
			while (x % p == 0) x /= p;
		}

		int val = 1;
		for (auto &p: prs) {
			if (last_pos[p] < n)
				seg.set(last_pos[p], seg.get(last_pos[p]) / p);
			val *= p;
			last_pos[p] = i;
		}

		seg.set(i, val);
		for (auto &[idx, r]: queries[i])
			ans[idx] = seg.prod(0, r + 1);
	}

	for (auto &x: ans) cout << x << '\n';

	return 0;
}
```

**提示 1：** 显然有一个 $\mathcal{O}(n)$ 解决问题的方法。有无别的想法？

**提示 2：** 相当于用了几组 $1$ 隔开了一堆 $0$ 。

首先，考虑单次查询。对于某个固定的 $k$ ，假设长度为 $i$ 的串有 $dp[i]$ 种。考虑其最后一项是 $0$ 还是 $1$ ，如果是 $0$ ，则前面一段的方案数是 $dp[i-1]$ ；如果是 $1$ ，则有一段长度是 $k$ 的 $1$ ，再往前面的方案数是 $dp[i-k]$ ，所以 $dp[i]=dp[i-1]+dp[i-k]$ 。

而如果求 DP 数组的前缀和就可以快速解决对于某个固定的 $k$ 的 $(l,r)$ 查询问题。

有啥别的想法吗？我们将序列视作用一堆长度为 $k$ 的 $1$ 切割一个由 $0$ 构成的序列。

枚举 $1$ 段的个数 $cnt$ ，则剩余的 $0$ 的个数是一个区间 $[l,r]$ ，我们需要用 $cnt+1$ 组 $0$ （每一组数量是非负数），来凑出总共 $[l,r]$ 的个数。

我们先解决 $[1,V]$ 的问题，就可以用 $[1,r]$ 的结果减去 $[1,l-1]$ 的结果来得到答案了。

我们设前 $i$ 组的 $0$ 的个数是 $x_i$ ，则：

$0\leq x_1\leq x_2\leq\dots\leq x_{cnt+1}\leq V$

则：

$1\leq x_1+1\lt x_2+2\lt\dots\lt x_{cnt+1}+(cnt+1)\leq V+cnt+1$ 

我们相当于从 $[1,V+cnt+1]$ 中选取递增的 $cnt+1$ 个数依次赋值给中间的项，就可以一一对应出一种可行的方案。所以总方案数是 $C_{V+cnt+1}^{cnt+1}$ 。

所以此时答案是 $C_{r+cnt+1}^{cnt+1}-C_{l+cnt}^{cnt+1}$ 。组合数在预处理后可以 $\mathcal{O}(1)$ 计算。

此时因为需要枚举 $cnt$ ，而 $cnt$ 是 $\mathcal{O}(\frac{n}{k})$ 量级的，所以复杂度也如此。所以 $k$ 比较大的时候比较适合这种做法。

而 $k$ 较小时可以直接预处理前缀和，所以在 $k\leq\sqrt{n}$ 时，我们用 DP 预处理前缀和， $k\gt\sqrt{n}$ 时，用后面的组合数办法求，复杂度分别是 $\mathcal{O}(n\sqrt{n})$ 和 $\mathcal{O}(q\sqrt{n})$ ，总复杂度符合要求。

总时间复杂度为 $\mathcal{O}((n+q)\sqrt{n})$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    M = 2 * 10 ** 5
    mod = 998244353

    f = Factorial(M * 2, mod)

    saved_dp = [[0] * (M + 1) for _ in range(451)]

    for i in range(1, 451):
        saved_dp[i][0] = 1

        for j in range(1, M + 1):
            saved_dp[i][j] = saved_dp[i][j - 1]
            if j >= i:
                saved_dp[i][j] += saved_dp[i][j - i]
            saved_dp[i][j] %= mod

        for j in range(1, M + 1):
            saved_dp[i][j] += saved_dp[i][j - 1]
            saved_dp[i][j] %= mod

    n, q = MII()
    outs = []

    for _ in range(q):
        l, r, k = MII()
        if k <= 450:
            outs.append((saved_dp[k][r] - saved_dp[k][l - 1]) % mod)
        else:
            ans = 0

            for cnt_k in range(r // k + 1):
                lbound = fmax(l - cnt_k * k, 0) - 1
                rbound = r - cnt_k * k

                ans += f.combi(rbound + cnt_k + 1, cnt_k + 1) - f.combi(lbound + cnt_k + 1, cnt_k + 1)
                ans %= mod

            outs.append(ans)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
const int mod = 998244353;

long long quickPow(long long base, long long power, long long mod) {
    if (power == 0) return 1 % mod;
    long long cur = quickPow(base, power / 2, mod);
    return power & 1 ? base * cur % mod * cur % mod : cur * cur % mod; 
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int M = 2e5;
	vector<int> f(M * 2 + 1), g(M * 2 + 1);

	f[0] = 1;
	for (int i = 1; i <= M * 2; i ++) f[i] = 1ll * f[i - 1] * i % mod;
	g[M * 2] = quickPow(f[M * 2], mod - 2, mod);
	for (int i = M * 2; i >= 1; i --) g[i - 1] = 1ll * g[i] * i % mod;

	auto comb = [&] (int x, int y) -> int {
		if (y < 0 || y > x) return 0;
		return 1ll * f[x] * g[y] % mod * g[x - y] % mod;
	};

	auto add = [&] (int &x, int y) -> void {
		x += y;
		if (x >= mod) x -= mod;
	};

	vector<vector<int>> saved_dp(451, vector<int>(M + 1, 0));

	for (int i = 1; i <= 450; i ++) {
		saved_dp[i][0] = 1;

		for (int j = 1; j <= M; j ++) {
			saved_dp[i][j] = saved_dp[i][j - 1];
			if (j >= i) add(saved_dp[i][j], saved_dp[i][j - i]);
		}

		for (int j = 1; j <= M; j ++)
			add(saved_dp[i][j], saved_dp[i][j - 1]);
	}

	int n, q;
	cin >> n >> q;

	while (q --) {
		int l, r, k;
		cin >> l >> r >> k;

		if (k <= 450)
			cout << (saved_dp[k][r] - saved_dp[k][l - 1] + mod) % mod << '\n';
		else {
			int ans = 0;
			for (int cnt_k = 0; cnt_k <= r / k; cnt_k ++) {
				int lbound = max(l - cnt_k * k, 0) - 1;
				int rbound = r - cnt_k * k;

				add(ans, comb(rbound + cnt_k + 1, cnt_k + 1));
				add(ans, mod - comb(lbound + cnt_k + 1, cnt_k + 1));
			}
			cout << ans << '\n';
		}
	}

	return 0;
}
```

**提示 1：** 考虑某个结点对答案的贡献。

考虑每个结点对答案的贡献，其实等价于这个结点真的被操作的概率。

这个结点要被操作，那么就得比其所有祖先都要先操作。假设有 $x$ 个祖先，则其排在这 $x$ 个祖先之前的概率就是 $\frac{1}{x+1}$ 。

综上，只需求每个结点的深度，再取倒数加总即可，时间复杂度为 $\mathcal{O}(n)$ ，如果你使用预处理来计算逆元的话。下面代码是直接分别求逆元了。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    t = II()
    outs = []

    mod = 998244353

    for _ in range(t):
        n = II()
        path = [[] for _ in range(n)]

        for _ in range(n - 1):
            u, v = GMI()
            path[u].append(v)
            path[v].append(u)

        depth = [0] * n
        depth[0] = 1

        que = [0]
        for u in que:
            for v in path[u]:
                if depth[v] == 0:
                    depth[v] = depth[u] + 1
                    que.append(v)

        ans = 0
        for x in depth:
            ans += pow(x, -1, mod)
            ans %= mod

        outs.append(ans)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t, mod = 998244353;
	cin >> t;

	while (t --) {
		int n;
		cin >> n;
		vector<vector<int>> path(n);

		for (int i = 0; i < n - 1; i ++) {
			int u, v;
			cin >> u >> v;
			u --, v --;
			path[u].emplace_back(v);
			path[v].emplace_back(u);
		}

		int ans = 0;

		auto dfs = [&] (auto &self, int u, int p, int d) -> void {
			ans += quickPow(d, mod - 2, mod);
			ans %= mod;
			for (auto &v: path[u]) {
				if (v != p) {
					self(self, v, u, d + 1);
				}
			}
		};

		dfs(dfs, 0, -1, 1);
		cout << ans << '\n';
	}

	return 0;
}
```

**提示 1：** 对于某一个容量而言，可能的浓度是多少？

**提示 2：** 应该要点很基础的积分。

对于某个容量而言，可能的浓度如何确定呢？

最高浓度——显然挑选最高浓度的几瓶东西混在一起，最低浓度——显然挑选最低浓度的几瓶混在一起。

所以我们可以根据浓度进行排序，然后把对应的容量拼接起来，就能得到最低 / 高酒精含量与总容积的关系图。

而把总容积设定为横坐标，则上下的两条曲线都是分段函数，只有 $\mathcal{O}(n)$ 段，因此每一段算出一个结果进行加总即可。

每一段的上下界都是直线。假设某一段的上界是 $k_1x+b_1$ ，下界是 $k_2x+b_2$ ，则对应的浓度上界是 $k_1+b_1/x$ ，下界是 $k_2+b_2/x$ ，所以满足条件的概率是 $(k_1-k_2)+(b_1-b_2)/x$ 。

我们对这个函数进行积分加总后，最后除以总的积分长度就是要求的概率了，相当于对每个横坐标的计算结果加总后取平均值。

上面这个定积分，其实第一部分 $k_1-k_2$ 是可以不算的，因为整个图形是中心对称的，左边计算的结果和右边计算的结果这一项是抵消的。而 $(b_1-b_2)/x$ 的积分结果是 $(b_1-b_2)(\mathrm{ln}(r)-\mathrm{ln}(l))$ ，直接计算即可。

需要注意第一段左端点是 $0$ ，直接求对数会报错，但其对应的两条线段都过原点，所以 $b_1=b_2=0$ ，忽略这段不影响最终答案。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n = II()
    tots = LII()
    vals = LII()

    portion = [vals[i] / tots[i] for i in range(n)]
    st_range = sorted(range(n), key=lambda x: portion[x])

    down_xs = [0]
    down_ys = [0]

    for i in st_range:
        down_xs.append(down_xs[-1] + tots[i])
        down_ys.append(down_ys[-1] + vals[i])

    st_range.reverse()

    up_xs = [0]
    up_ys = [0]

    for i in st_range:
        up_xs.append(up_xs[-1] + tots[i])
        up_ys.append(up_ys[-1] + vals[i])

    pt1 = 0
    pt2 = 0
    ans = 0

    while pt1 < n and pt2 < n:
        l = fmax(down_xs[pt1], up_xs[pt2])
        r = fmin(down_xs[pt1 + 1], up_xs[pt2 + 1])

        if l < r and l > 0:
            kup = (up_ys[pt2 + 1] - up_ys[pt2]) / (up_xs[pt2 + 1] - up_xs[pt2])
            kdown = (down_ys[pt1 + 1] - down_ys[pt1]) / (down_xs[pt1 + 1] - down_xs[pt1])

            bup = up_ys[pt2] - kup * up_xs[pt2]
            bdown = down_ys[pt1] - kdown * down_xs[pt1]

            ans += (bup - bdown) * (math.log(r) - math.log(l))

        if down_xs[pt1 + 1] < up_xs[pt2 + 1]: pt1 += 1
        else: pt2 += 1

    ans /= up_xs[-1]

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	vector<int> xs(n), ys(n);

	for (auto &x: xs) cin >> x;
	for (auto &x: ys) cin >> x;

	vector<int> order(n);
	iota(order.begin(), order.end(), 0);

	sort(order.begin(), order.end(), [&](int a, int b) {
		return 1ll * xs[b] * ys[a] < 1ll * xs[a] * ys[b];
	});

	vector<long long> down_xs = {0}, down_ys = {0};
	for (auto &x: order) {
		down_xs.push_back(down_xs.back() + xs[x]);
		down_ys.push_back(down_ys.back() + ys[x]);
	}

	reverse(order.begin(), order.end());
	vector<long long> up_xs = {0}, up_ys = {0};
	for (auto &x: order) {
		up_xs.push_back(up_xs.back() + xs[x]);
		up_ys.push_back(up_ys.back() + ys[x]);
	}

	long double ans = 0;
	int pt1 = 0, pt2 = 0;

	while (pt1 < n && pt2 < n) {
		long long l = max(up_xs[pt1], down_xs[pt2]);
		long long r = min(up_xs[pt1 + 1], down_xs[pt2 + 1]);

		if (l < r && l > 0) {
			long double kup = (long double)(up_ys[pt1 + 1] - up_ys[pt1]) / (up_xs[pt1 + 1] - up_xs[pt1]);
			long double kdown = (long double)(down_ys[pt2 + 1] - down_ys[pt2]) / (down_xs[pt2 + 1] - down_xs[pt2]);

			long double bup = up_ys[pt1] - kup * up_xs[pt1];
			long double bdown = down_ys[pt2] - kdown * down_xs[pt2];

			ans += (bup - bdown) * (logl(r) - logl(l));
		}

		if (down_xs[pt2 + 1] < up_xs[pt1 + 1]) pt2++;
		else pt1++;
	}

	ans /= up_xs[n];

	cout << fixed << setprecision(15) << ans << '\n';

	return 0;
}
```

**提示 1：** 在没有环的图中，连通块数量可以用点数和边数表示。

**提示 2：** 期望可加性。

在没有环的图中，连通块数量等于点的数量减去边的数量。我们从没有边的情况开始考虑，新增一条边就少一个连通块，所以也就证明了这个结论。

所以答案就是点数的期望减去边数的期望。

点的数量可以用每个点的存在概率相加得到，边的数量可以用每条边的存在概率相加得到（相当于每个点对），而两个概率分别是 $\frac{1}{i}$ 和 $\frac{1}{i(i+1)}$ 。

两个都可以用前缀和预处理，同时逆元也很容易求（不熟悉的可以搜索一下），当然后者也可以裂项化简。

所以 $\mathcal{O}(M)$ 预处理， $\mathcal{O}(1)$ 查询即可。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    M = 10 ** 6
    mod = 10 ** 9 + 7

    f = Factorial(M, mod)

    acc = [0] * (M + 1)

    for i in range(1, M + 1):
        acc[i] = (acc[i - 1] + f.inv(i)) % mod

    t = II()
    outs = []

    for _ in range(t):
        n = II()
        outs.append((acc[n] - (1 - f.inv(n))) % mod)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t, mod = 1e9 + 7, M = 1e6;
	cin >> t;

	vector<int> f(M + 1), g(M + 1);
	f[0] = 1;
	for (int i = 1; i <= M; i ++)
		f[i] = 1ll * i * f[i - 1] % mod;

	g[M] = quickPow(f[M], mod - 2, mod);
	for (int i = M; i >= 1; i --)
		g[i - 1] = 1ll * i * g[i] % mod;

	vector<int> acc(M + 1);
	acc[0] = 0;

	for (int i = 1; i <= M; i ++)
		acc[i] = (acc[i - 1] + 1ll * f[i - 1] * g[i]) % mod;

	while (t --) {
		int n;
		cin >> n;
		cout << (acc[n] - (1 - 1ll * f[n - 1] * g[n])) % mod << '\n';
	}

	return 0;
}
