	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t, mod = 998244353;
	cin >> t;

	while (t --) {
		int n, k;
		cin >> n >> k;

		int ans = n, revk = quickPow(k, mod - 2, mod);
		for (int i = 1; i < k; i ++) {
			int prob = 1ll * i * revk % mod;
			ans += (mod + 1 - quickPow(prob, n, mod)) * quickPow(mod + 1 - prob, mod - 2, mod) % mod;
