	while (t --) {
		long long a, b;
		cin >> a >> b;

		if (a > b) swap(a, b);

		if (2 * a < b) cout << "NO\n";
		else if (a == b) {
			if (a & 1) cout << "NO\n";
			else cout << "SI\n";
		}
