	for (auto &v: nums2) cin >> v;

	vector<int> vals;

	for (int i = 0; i < n; i ++) {
		if (nums1[i] > nums2[i]) {
			vals.emplace_back(nums1[i]);
			vals.emplace_back(nums2[i]);
