**提示 2：** 可以构造吗？怎么构造？怎么找到路径？

首先，对于某个叶子结点而言，设其他结点和它的最远距离是 $v$ ，则答案不可能超过 $v$ ，因为我们考虑经过这个结点的满足条件的 $K$ 路径，路径终点到这个点的距离是 $K$ ，也就不超过最大值 $v$ 。

怎么求这个最大距离呢？找到直径，两个端点中一定有一个是可取的。

能构造吗？答案是肯定的。

上述路径来自于直径，所以考虑通过直径入手。

我们先对直径上的边进行 $0,1,2,\dots,K-1,0,1,2,\dots,K-1,\dots$ 染色。

接下来直径中点的左边部分，其更远的直径端点在右边，所以寻找路径应该往右找，所以从直径上的点除法，应该往小里编号。同样地，右边部分应该往大里编号。

我们已经完成了边的编号。接下来我们如何找到合法经过给定边的路径呢？

有很多种构造方案，这里给出个人认为还算能写的一种。

对于某条边的查询，我们找到这条边远离中点的一个叶子结点，接下来再找该叶子结点对应的直径上的点。

等下，这个点一定在直径上吗？答案是肯定的，因为任何一个点到直径的两个端点的距离和不小于直径长度，所以对于每个叶子节点而言，其中的较大值 $K$ 一定大于直径的一半。所以如果走 $K$ 步还没走到直径上，那么走的距离已经大于直径的一半，而进入直径的点到某个端点的距离也不小于直径的一半，这样我们就构造出了一条比直径还长的路径，也就产生了矛盾。

而这个直径上的点怎么找呢？我们用刚刚的标号结果，如果不对标号结果取模，那么距离叶子节点为 $K$ 的点其编号结果也刚好差 $K$ （可以想下为啥，其实标号相当于我们把整棵树分成了一层一层的），而直径上只存在这么一个点（也是因为 $K$ 超过了直径长度的一半），所以我们就找出了对应的路径。

时间复杂度为 $\mathcal{O}(n)$ 。

**拓展：** 想想这题怎么检查你的答案对不对？

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n = II()
    us = []
    vs = []
    path = [[] for _ in range(n)]

    for _ in range(n - 1):
        u, v = MII()
        us.append(u)
        vs.append(v)
        path[u].append(v)
        path[v].append(u)

    def dis(start):
        ans = [-1] * n
        ans[start] = 0

        que = [start]
        for u in que:
            for v in path[u]:
                if ans[v] == -1:
                    ans[v] = ans[u] + 1
                    que.append(v)

        return ans

    d = dis(0)
    diameter_u = d.index(max(d))
    d1 = dis(diameter_u)
    diameter_v = d1.index(max(d1))
    d2 = dis(d1.index(max(d1)))

    ans = n
    chosen = -1

    for i in range(n):
        if len(path[i]) == 1:
            v = fmax(d1[i], d2[i])
            if v < ans:
                ans = v
                chosen = i

    outs = []
    outs.append(str(ans))

    cur = [diameter_v]
    while cur[-1] != diameter_u:
        for v in path[cur[-1]]:
            if d1[cur[-1]] - d1[v] == 1:
                cur.append(v)
                break

    k = len(cur)

    notes = [-1] * n
    idx = cur[k // 2]
    notes[idx] = k // 2

    parent = [-1] * n

    que = [idx]

    for u in que:
        for v in path[u]:
            if notes[v] == -1:
                if d1[v] >= d2[v]: notes[v] = notes[u] - 1
                else: notes[v] = notes[u] + 1
                parent[v] = u
                que.append(v)

    find_leaf = list(range(n))

    for u in reversed(que):
        if parent[u] != -1:
            find_leaf[parent[u]] = find_leaf[u]

    for i in range(n - 1):
        u, v = us[i], vs[i]
        if notes[u] > notes[v]:
            u, v = v, u

        leaf = find_leaf[u] if d1[u] >= d2[u] else find_leaf[v]
        end = cur[notes[leaf] - ans] if notes[leaf] >= ans else cur[notes[leaf] + ans]
        outs.append(f'{notes[u] % ans} {leaf} {end}')

    print('\n'.join(outs))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	vector<pair<int, int>> edges(n - 1);
	vector<vector<int>> path(n);

	for (auto &[u, v]: edges) {
		cin >> u >> v;
		path[u].emplace_back(v);
		path[v].emplace_back(u);
	}

	auto dis = [&] (int start) -> vector<int> {
		vector<int> ans(n, -1);
		ans[start] = 0;

		queue<int> q;
		q.push(start);

		while (!q.empty()) {
			auto u = q.front(); q.pop();
			for (auto &v: path[u]) {
				if (ans[v] == -1) {
					ans[v] = ans[u] + 1;
					q.push(v);
				}
			}
		}

		return ans;
	};

	auto d = dis(0);
	int diameter_u = max_element(d.begin(), d.end()) - d.begin();
	auto d1 = dis(diameter_u);
	int diameter_v = max_element(d1.begin(), d1.end()) - d1.begin();
	auto d2 = dis(diameter_v);

	int ans = n, chosen = -1;

	for (int i = 0; i < n; i ++) {
		if (path[i].size() == 1) {
			int v = max(d1[i], d2[i]);
			if (v < ans) {
				ans = v;
				chosen = i;
			}
		}
	}

	vector<int> cur = {diameter_v};

	while (cur.back() != diameter_u) {
		for (auto &v: path[cur.back()]) {
			if (d1[cur.back()] - d1[v] == 1) {
				cur.emplace_back(v);
				break;
			}
		}
	}

	int k = cur.size();
	vector<int> notes(n, -1), find_leaf(n);
	int idx = cur[k / 2];
	notes[idx] = k / 2;

	iota(find_leaf.begin(), find_leaf.end(), 0);

	auto dfs = [&] (auto &self, int u, int p) -> void {
		for (auto &v: path[u]) {
			if (v != p) {
				notes[v] = notes[u] + (d1[v] >= d2[v] ? -1 : 1);
				self(self, v, u);
				find_leaf[u] = find_leaf[v];
			}
		}
	};

	dfs(dfs, idx, -1);

	cout << ans << '\n';
	for (auto &[u, v]: edges) {
		if (notes[u] > notes[v]) swap(u, v);

		int leaf = (d1[u] >= d2[u] ? find_leaf[u] : find_leaf[v]);
		int other_end = (notes[leaf] >= ans ? cur[notes[leaf] - ans] : cur[notes[leaf] + ans]);
		cout << notes[u] % ans << ' ' << leaf << ' ' << other_end << '\n';
	}

	return 0;
}
```

**提示 1：** 相当于一个经过变换后的匹配。可以考虑字符串算法。

**提示 2：** 怎么处理之后就是完全一致的匹配了？

考虑对数组进行差分，因为操作不改变差分数组，同时第二个数组在第一个数组的匹配位置的差分数组的数值一定跟第二个的差分数组一致。

（注意这里差分的结果需要关于 $10^4$ 取模）

所以用 KMP 或其他算法，找到匹配的位置。而是否匹配只取决于第一个元素是否相同，因此对于所有差分数组匹配的位置，可以直接比对第一个元素，看对应位置需要操作几次才能匹配上，对这个操作数进行统计。

最后对统计结果，取最大者，并得到下标即可。

时间复杂度为 $\mathcal{O}(n+m)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    def prep(p):
        pi = [0] * len(p)
        j = 0
        for i in range(1, len(p)):
            while j != 0 and p[j] != p[i]:
                j = pi[j - 1]
            if p[j] == p[i]:
                j += 1
            pi[i] = j
        return pi

    M = 10 ** 4

    n, m = MII()
    nums1 = LII()
    nums2 = LII()

    vals = []

    for i in range(1, m):
        vals.append((nums2[i] - nums2[i - 1]) % M)

    vals.append(-1)

    for i in range(1, n):
        vals.append((nums1[i] - nums1[i - 1]) % M)

    kmp = prep(vals)

    cnt = [0] * M

    for i in range(m, n + m - 1):
        if kmp[i] == m - 1:
            cnt[(nums2[0] - nums1[i - 2 * (m - 1)]) % M] += 1

    ma = max(cnt)
    print(cnt.index(ma), ma)
```

C++ 做法如下——

```cpp []
vector<int> prep(vector<int>& nums) {
	int n = nums.size();
	vector<int> pi(n, 0);
	int j = 0;

	for (int i = 1; i < n; i ++) {
		while (j && nums[i] != nums[j])
			j = pi[j - 1];
		if (nums[i] == nums[j]) j ++;
		pi[i] = j;
	}

	return pi;
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int M = 1e4, n, m;
	cin >> n >> m;

	vector<int> nums1(n), nums2(m);
	for (auto &x: nums1) cin >> x;
	for (auto &x: nums2) cin >> x;

	vector<int> vals;

	for (int i = 1; i < m; i ++)
		vals.emplace_back((nums2[i] - nums2[i - 1] + M) % M);

	vals.emplace_back(-1);

	for (int i = 1; i < n; i ++)
		vals.emplace_back((nums1[i] - nums1[i - 1] + M) % M);

	auto kmp = prep(vals);

	vector<int> cnt(M, 0);

	for (int i = m; i < n + m - 1; i ++) {
		if (kmp[i] == m - 1) {
			cnt[(nums2[0] - nums1[i - 2 * (m - 1)] + M) % M] ++;
		}
	}

	auto ma_ele = max_element(cnt.begin(), cnt.end());

	cout << ma_ele - cnt.begin() << ' ' << *ma_ele;

	return 0;
}
```

**提示 1：** 显然 $k$ 越大越容易满足要求。

**提示 2：** 我们需要检查的条件是什么？

显然 $k$ 越大越容易满足要求，因此考虑二分。接下来只需检查对于某个 $k$ 是否存在解即可。

我们的条件相当于是每个位置的数值有其范围，子数组和也有范围。

后者包含的变量太多了，如何减少变量呢？

考虑使用前缀和，则上述的两类不等式都变成了差分约束，这就是很容易解决的问题了，跑 Bellman-Ford 的东西就好了，最后只需检查一遍解是否符合要求。

时间复杂度为 $\mathcal{O}(n(n+m)\log M)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n, m = MII()
    nums = LII()

    ls = []
    rs = []
    xs = []
    ys = []

    for _ in range(m):
        l, r, x, y = MII()
        ls.append(l - 1)
        rs.append(r)
        xs.append(x)
        ys.append(y)

    bound = 10 ** 13
    l, r = 0, bound
    sol = [0] * (n + 1)

    while l <= r:
        mid = (l + r) // 2

        for _ in range(n):
            for i in range(m):
                sol[rs[i]] = fmax(sol[rs[i]], sol[ls[i]] + xs[i])
                sol[ls[i]] = fmax(sol[ls[i]], sol[rs[i]] - ys[i])

            for i in range(n):
                sol[i + 1] = fmax(sol[i + 1], sol[i] + fmax(1, nums[i] - mid))
                sol[i] = fmax(sol[i], sol[i + 1] - nums[i] - mid)

        flg = True

        for i in range(n):
            if not fmax(1, nums[i] - mid) <= sol[i + 1] - sol[i] <= nums[i] + mid:
                flg = False

        for i in range(m):
            if not xs[i] <= sol[rs[i]] - sol[ls[i]] <= ys[i]:
                flg = False

        if flg: r = mid - 1
        else: l = mid + 1

        for i in range(n + 1):
            sol[i] = 0

    print(l if l < bound else -1)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, m;
	cin >> n >> m;

	vector<long long> nums(n);
	for (auto &x: nums) cin >> x;

	vector<long long> ls(m), rs(m), xs(m), ys(m);

	for (int i = 0; i < m; i ++) {
		cin >> ls[i] >> rs[i] >> xs[i] >> ys[i];
		ls[i] --;
	}

	long long bound = 1e13;
	long long l = 0, r = bound;

	vector<long long> sol(n + 1, 0);

	while (l <= r) {
		long long mid = (l + r) / 2;

		for (int _ = 0; _ < n; _ ++) {
			for (int i = 0; i < m; i ++) {
				sol[rs[i]] = max(sol[rs[i]], sol[ls[i]] + xs[i]);
				sol[ls[i]] = max(sol[ls[i]], sol[rs[i]] - ys[i]);
			}
			for (int i = 0; i < n; i ++) {
				sol[i + 1] = max(sol[i + 1], sol[i] + max(1ll, nums[i] - mid));
				sol[i] = max(sol[i], sol[i + 1] - nums[i] - mid);
			}
		}

		bool flg = true;

		for (int i = 0; i < n; i ++) {
			if (!(max(1ll, nums[i] - mid) <= sol[i + 1] - sol[i]) || !(sol[i + 1] - sol[i] <= nums[i] + mid)) {
				flg = false;
			}
		}

		for (int i = 0; i < m; i ++) {
			if (!(xs[i] <= sol[rs[i]] - sol[ls[i]]) || !(sol[rs[i]] - sol[ls[i]] <= ys[i])) {
				flg = false;
			}
		}

		if (flg) r = mid - 1;
		else l = mid + 1;

		for (int i = 0; i <= n; i ++) sol[i] = 0;
	}

	cout << (l < bound ? l : -1);

	return 0;
}
```

**提示 1：** 把两个数变成更小的数。

我们先看下一个大数关于 $mod$ 取模咋做。

假设考虑了前 $k$ 位的取模结果是 $x$ ，此时第 $k+1$ 位是 $y$ ，则新的数是 $10$ 倍的前 $k$ 位加上第 $k+1$ 位，因此新结果是 $(10x+y)\bmod mod$ 。

对于加法、减法、乘法而言，我们直接两个数都取模 $10^9+7$ 就好。

对于幂次，因为 $x^{mod-1}\bmod mod=1$ ，当 $x$ 不能被 $mod$ 整除且 $mod$ 是质数的情况下，所以我们可以对幂次关于 $mod-1$ 取模。 $x$ 是 $mod$ 的倍数的情况下，输出 $0$ 即可。

时间复杂度为 $\mathcal{O}(\sum|s|)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    s1, op, s2 = LI()

    mod1 = 10 ** 9 + 7
    mod2 = 10 ** 9 + 6

    v1 = 0
    for c in s1:
        v1 = (10 * v1 + int(c)) % mod1

    v2 = 0
    for c in s2:
        v2 = (10 * v2 + int(c)) % (mod1 if op != '^' else mod2)

    if op == '+': print((v1 + v2) % mod1)
    elif op == '-': print((v1 - v2) % mod1)
    elif op == '*': print(v1 * v2 % mod1)
    else: print(pow(v1, v2, mod1))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	string s1, op, s2;
	cin >> s1 >> op >> s2;

	int mod1 = 1e9 + 7, mod2 = mod1 - 1;

	int v1 = 0, v2 = 0;

	for (auto &c: s1)
		v1 = (10ll * v1 + c - '0') % mod1;

	for (auto &c: s2)
		v2 = (10ll * v2 + c - '0') % (op[0] == '^' ? mod2 : mod1);

	if (op == "+") cout << (v1 + v2) % mod1;
	else if (op == "-") cout << (v1 - v2 + mod1) % mod1;
	else if (op == "*") cout << 1ll * v1 * v2 % mod1;
	else cout << quickPow(v1, v2, mod1);

	return 0;
}
