**提示 2：** 完全子图不好做，但是反图之后完全子图里面就没有边了，就很方便了

**提示 3：** 接下来要凑两侧点数相等。

题目中要求可以拆分为两个 $n/2$ 的部分，每个部分都是完全图。

因此，一旦 $n$ 是奇数，就直接不可能。同时这也要求至少有 $(n/2-1)n/2$ 条边，而 $m\leq 10^6$ ，所以 $n\geq 2002$ 的情况下边数就已经不够了，直接输出不可能。

接下来考虑怎么判条件，且有 $n\leq 2000, m\leq 10^6$ 。

一个完全图是不好刻画的，但是我们考虑反图，就是在原图中相连的两点不连边，不相连的两点连边。这样完全图内部就完全没有边了，就更干净了。

而整体有两个完全图，说明反图中的边只能是完全图之间的，也就是整体是个二分图。如果不是二分图也是直接不可能。

我们就是要对二分图染色，使得两种颜色的点都恰好占一半。

考虑每个连通块，其有两种染色方式，也就是将其视为二部后，一部分是 $x_i$ 另一部分是 $y_i$ 。

我们相当于每个连通块选一种染色为 $0$ ，最后要求 $0$ 的个数是 $n/2$ 。这显然是个背包问题，因此只需处理背包并输出方案即可。

时间复杂度为 $\mathcal{O}(m)$ ，因为 $n^2$ 只能是 $\mathcal{O}(m)$ 量级的。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n, m = MII()

    if n % 2 or n > 2005: exit(print('impossible'))

    path = [[1] * n for _ in range(n)]

    for _ in range(m):
        u, v = GMI()
        path[u][v] = path[v][u] = 0

    for i in range(n):
        path[i][i] = 0

    vis = [-1] * n
    groups = []
    cnts = []

    for i in range(n):
        if vis[i] == -1:
            vis[i] = 0
            que = [i]
            cnt = 0

            for u in que:
                for v in range(n):
                    if path[u][v]:
                        if vis[v] == -1:
                            vis[v] = 1 - vis[u]
                            cnt += vis[v]
                            que.append(v)
                        elif vis[u] == vis[v]:
                            exit(print('impossible'))

            groups.append(que)
            cnts.append(cnt)

    k = len(groups)
    dp = [[0] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 1

    for i in range(k):
        c1 = cnts[i]
        c2 = len(groups[i]) - c1
        for j in range(n + 1):
            if dp[i][j]:
                dp[i + 1][j + c1] = 1
                dp[i + 1][j + c2] = 1

    if not dp[k][n // 2]:
        exit(print('impossible'))

    cur = n // 2
    chosen = []

    for i in range(k - 1, -1, -1):
        c1 = cnts[i]
        c2 = len(groups[i]) - c1
        if dp[i][cur - c1]: 
            chosen.append(c1)
            cur -= c1
        else:
            chosen.append(c2)
            cur -= c2

    chosen.reverse()

    for i in range(k):
        if chosen[i] != cnts[i]:
            for u in groups[i]:
                vis[u] ^= 1

    print('\n'.join('rb'[x] for x in vis))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, m;
	cin >> n >> m;

	if (n & 1 || n > 2005) return cout << "impossible", 0;

	vector<vector<int>> path(n, vector<int>(n, 1));

	while (m --) {
		int u, v;
		cin >> u >> v;
		u --, v --;
		path[u][v] = 0;
		path[v][u] = 0;
	}

	for (int i = 0; i < n; i ++)
		path[i][i] = 0;

	vector<int> ans(n, -1), cnts;
	vector<vector<int>> groups;

	for (int i = 0; i < n; i ++) {
		if (ans[i] == -1) {
			ans[i] = 0;
			int cnt = 0;
			vector<int> group;

			auto dfs = [&] (auto &self, int u) -> void {
				group.emplace_back(u);
				cnt += ans[u];
				for (int v = 0; v < n; v ++) {
					if (path[u][v]) {
						if (ans[v] == -1) {
							ans[v] = ans[u] ^ 1;
							self(self, v);
						}
						else if (ans[u] == ans[v]) {
							cout << "impossible";
							exit(0);
						}
					}
				}
			};

			dfs(dfs, i);
			cnts.emplace_back(cnt);
			groups.emplace_back(group);
		}
	}

	int k = cnts.size();
	vector<vector<int>> dp(k + 1, vector<int>(n + 1, 0));
	dp[0][0] = 1;

	for (int i = 0; i < k; i ++) {
		int c1 = cnts[i], c2 = groups[i].size() - c1;
		for (int j = 0; j <= n; j ++) {
			if (dp[i][j]) {
				dp[i + 1][j + c1] = 1;
				dp[i + 1][j + c2] = 1;
			}
		}
	}

	if (!dp[k][n / 2]) return cout << "impossible", 0;

	int cur = n / 2;
	vector<int> chosen;

	for (int i = k - 1; i >= 0; i --) {
		int c1 = cnts[i], c2 = groups[i].size() - c1;
		if (cur >= c1 && dp[i][cur - c1]) chosen.emplace_back(c1), cur -= c1;
		else chosen.emplace_back(c2), cur -= c2;
	}

	reverse(chosen.begin(), chosen.end());

	for (int i = 0; i < k; i ++) {
		if (chosen[i] != cnts[i]) {
			for (auto &u: groups[i]) {
				ans[u] ^= 1;
			}
		}
	}

	for (auto &x: ans) cout << "rb"[x] << '\n';

	return 0;
}
```

**提示 1：** 对于一个确定的边长，如何判断是否成立？

**提示 2：** 哪些边长是值得检查的？

对于某个确定的边长，直接顺序遍历，遇到一个 `'#'` 的时候，暴力检查右下角的正方形中是否存在非 `'#'` 并染色为 `'.'` ，如果出边界或不符合条件则直接不成立。注意不成立时及时推出循环。

因为每个位置最多查一次，所以这么做的时间复杂度是 $\mathcal{O}(nm)$ 的。

如果直接检查所有边长是不符合要求的，那怎么办呢？

对于某一行连续的 `'#'` ，假设长度为 $k$ ，则答案一定是 $k$ 的因子，否则凑不出来这一行。所以枚举这个数的因子就好。

这么做的时间复杂度为 $\mathcal{O}(nmd(\min(n, m)))$ ， $d(x)$ 表示不超过 $x$ 的数的因子最大个数，我们可以选择横着 / 竖着的最短的一段。下面的代码并非完全按照上面的思路实现。

其实也可以用从 $1$ 开始不断乘质数（这个质数是 $k$ 的质因子）的方式不断得到最大值，这样可以降低复杂度到 $\mathcal{O}(nm\log\min(n,m))$ ，但这不是必要的。

### 具体代码如下——

Python 做法如下——

```Python []
def main(): 
    n, m = MII()
    grid = [[1 if c == '#' else 0 for c in I()] for _ in range(n)]
    total = sum(sum(x) for x in grid)

    tmp = [[0] * m for _ in range(n)]

    for i in range(fmin(n, m), 0, -1):
        if total % (i * i) == 0:
            for x in range(n):
                for y in range(m):
                    tmp[x][y] = grid[x][y]

            flg = True
            for x in range(n):
                for y in range(m):
                    if tmp[x][y]:
                        for dx in range(x, x + i):
                            for dy in range(y, y + i):
                                if dx >= n or dy >= m or tmp[dx][dy] == 0:
                                    flg = False
                                    break
                                tmp[dx][dy] = 0
                            if not flg: break
                        if not flg: break
                if not flg: break

            if flg:
                print(i)
                break
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, m;
	cin >> n >> m;

	vector<string> grid(n);
	for (auto &s: grid) cin >> s;

	int total = 0;
	for (auto &s: grid) {
		for (auto &c: s) {
			total += (c == '#');
		}
	}

	vector<vector<int>> tmp(n, vector<int>(m, 0));
	for (int i = min(n, m); i > 0; i --) {
		if (total % (i * i) == 0) {

			for (int x = 0; x < n; x ++) {
				for (int y = 0; y < m; y ++) {
					if (grid[x][y] == '#') {
						tmp[x][y] = 1;
					}
				}
			}

			bool flg = true;
			for (int x = 0; x < n; x ++) {
				for (int y = 0; y < m; y ++) {
					if (tmp[x][y]) {
						for (int dx = x; dx < x + i; dx ++) {
							for (int dy = y; dy < y + i; dy ++) {
								if (dx >= n || dy >= m || !tmp[dx][dy]) {
									flg = false;
									break;
								}
								tmp[dx][dy] = 0;
							}
							if (!flg) break;
						}
						if (!flg) break;
					}
				}
				if (!flg) break;
			}

			if (flg) return cout << i, 0;
		}
	}

	return 0;
}
