	int cur = 0, pos = 0, ans = 1;

	for (int i = 0; i < n; i ++) {
		int x;
		cin >> x;

		if (x > cur) {
			ans = 1ll * ans * (i - pos + 1) % mod;
			cur = x;
			pos = i;
		}
	}

	cout << ans;

