    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector<int> nums(n), ops;
    for (auto &x: nums) cin >> x;

    for (int i = n - 1; i >= 0; i --) {
        bool flg = false;
        for (int j = i; j >= 0; j --) {
            if (nums[j] == j + 1) {
                flg = true;
                ops.emplace_back(nums[j]);
                nums.erase(nums.begin() + j);
