**提示 1：** 只需求每个元素的贡献。检查贡献有没有算错可以使用 Q 题。

**提示 2：** 加速贡献计算：同底数的组合数没法直接优化计算，只能找相关关系。

考虑第 $i$ 个元素出现在 $[L,R]$ 的方案数，这就是第 $i$ 个元素对于结果的贡献。

如果第 $i$ 个元素是从左侧加入的，那么前 $i-1$ 个元素有 $2^{i-1}$ 种方案（怎么加入对于第 $i$ 个元素毫无影响）。而剩余的 $n-i$ 个元素而言，需要有 $[L-1,R-1]$ 个元素从左侧加入，因此，权重是 $2^{i-1}\sum\limits_{k=L-1}^{R-1}C_{n-i}^k$ 。

如果第 $i$ 个元素是从右侧加入的，那么前 $i-1$ 个元素仍然有 $2^{i-1}$ 种方案。剩余的 $n-i$ 个元素需要有 $[L-i,R-i]$ 个元素从左侧加入，因此权重是 $2^{i-1}\sum\limits_{k=L-i}^{R-i}C_{n-i}^k$ 。

两者相加即为总权重。

这足够完成 Easy Version 。但这些权重的计算如果一个个算就太慢了，怎么优化呢？

这里是一个比较经典的技巧，下面底数一样的情况下，相邻的底数的结果有数量关系。

以 $\sum\limits_{k=L-1}^{R-1}C_{n-i}^k$ 为例：

$2\sum\limits_{k=L-1}^{R-1}C_{n-i}^k=\sum\limits_{k=L-1}^{R-1}(C_{n-i}^k+C_{n-i}^{k-1})-C_{n-i}^{L-2}+C_{n-i}^{R-1}=\sum\limits_{k=L-1}^{R-1}C_{n-(i-1)}^k-C_{n-i}^{L-2}+C_{n-i}^{R-1}$

也就发现了相邻的两个权重之间存在很方便的转移关系，因此利用这种转移关系计算权重即可。

主要使用的组合恒等式是 $C_x^y=C_{x-1}^y+C_{x-1}^{y-1}$ ，所以考虑将组合求和式用这种形式进行组合，并进而化简。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    mod = 10 ** 9 + 7

    n, l, r = MII()
    nums = LII()

    f = Factorial(n, mod)

    pw2 = 1
    rev2 = (mod + 1) // 2

    ans = 0
    weight_left = 0

    for i in range(l - 1, r):
        weight_left += f.combi(n - 1, i)
        weight_left %= mod

    weight_right = weight_left

    ans += (weight_left + weight_right) * nums[0] % mod

    for i in range(1, n):
        pw2 = pw2 * 2 % mod

        weight_left = (weight_left + f.combi(n - i - 1, l - i - 1) - f.combi(n - i - 1, r - i)) % mod * rev2 % mod
        weight_right = (weight_right - f.combi(n - i - 1, l - 2) + f.combi(n - i - 1, r - 1)) % mod * rev2 % mod

        ans += (weight_left + weight_right) * nums[i] % mod * pw2 % mod

    print(ans % mod)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, l, r;
    cin >> n >> l >> r;

    vector<int> nums(n);
    for (auto &v: nums) cin >> v;

    int mod = 1e9 + 7;

    vector<int> f(n + 1, 1), g(n + 1);

    for (int i = 1; i <= n; i ++)
        f[i] = 1ll * i * f[i - 1] % mod;

    g[n] = quickPow(f[n], mod - 2, mod);

    for (int i = n; i >= 1; i --)
        g[i - 1] = 1ll * i * g[i] % mod;

    auto comb = [&] (int x, int y) -> int {
        if (x < y || x < 0 || y < 0) return 0;
        return 1ll * f[x] * g[y] % mod * g[x - y] % mod;
    };

    int ans = 0;
    int pw2 = 1, rev2 = (mod + 1) / 2;
    int weight_left = 0, weight_right;

    for (int i = l - 1; i <= r - 1; i ++)
        weight_left += comb(n - 1, i), weight_left %= mod;

    weight_right = weight_left;
    ans += 1ll * (weight_left + weight_right) * nums[0] % mod;

    for (int i = 1; i < n; i ++) {
        pw2 = pw2 * 2 % mod;

        weight_left = (0ll + weight_left + comb(n - i - 1, l - i - 1) - comb(n - i - 1, r - i)) * rev2 % mod;
        weight_right = (0ll + weight_right - comb(n - i - 1, l - 2) + comb(n - i - 1, r - 1)) * rev2 % mod;

        ans += 1ll * (weight_left + weight_right) * nums[i] % mod * pw2 % mod;
        ans %= mod;
    }

    cout << (ans + mod) % mod;

    return 0;
}
```

**提示 1：** 你取的 $x$ 只需要考虑那些质数。

**提示 2：** 需要检查的有哪些？

首先，如果一个 $x$ 可以达成目标，那么对其质因子也一定是可以的。所以只需考虑质数就行。

为此，我们先统计每个质数能被多少个数组中的数整除。

我们只需挑选其中出现次数过半的进行检查，接下来相当于将树上的点根据是否被该质数整除分为两类，不能整除的染为黑色，能整除的染为白色，问是否存在一条长度超过 $n/2$ 的路径，这件事可以直接使用 DP 完成检查，维护每个点往下的最长的白色路径长度。而每个白色结点又可以挑选两条向下的路径拼到一起，再看看能否凑出长度超过 $n/2$ 的路径即可。

这样做时间复杂度如何呢？时间复杂度为 $\mathcal{O}(n\log M + M)$ ，因为每个数的质因子的总次数之和不超过 $\mathcal{O}(n\log M)$ ，因此频率至少为 $n/2$ 的至多只有 $\mathcal{O}(\log M)$ 个，所以只需跑 $\mathcal{O}(\log M)$ 轮 DP 就行。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    M = 10 ** 7
    prime_factor = list(range(M + 1))

    for i in range(2, M + 1):
        if prime_factor[i] == i:
            for j in range(i, M + 1, i):
                prime_factor[j] = i

    n = II()
    nums = LII()

    path = [[] for _ in range(n)]

    for _ in range(n - 1):
        u, v = GMI()
        path[u].append(v)
        path[v].append(u)

    cnt = [0] * (M + 1)

    for x in nums:
        while x > 1:
            p = prime_factor[x]
            cnt[p] += 1
            while x % p == 0:
                x //= p

    parent = [-1] * n
    que = [0]

    for u in que:
        for v in path[u]:
            if parent[u] != v:
                parent[v] = u
                que.append(v)

    que.reverse()
    dp = [0] * n

    for i in range(M + 1):
        if cnt[i] * 2 > n:
            total = 0

            for u in que:
                if nums[u] % i == 0: dp[u] = 1
                else: dp[u] = 0

                if dp[u]:
                    v1, v2 = 0, 0
                    for v in path[u]:
                        if parent[v] == u:
                            if dp[v] > v1: v1, v2 = dp[v], v1
                            elif dp[v] > v2: v2 = dp[v]

                    dp[u] = v1 + 1
                    total = fmax(total, v1 + v2 + 1)

            if total * 2 > n:
                exit(print('YES'))

    print('NO')
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int M = 1e7;
    vector<int> prime_factor(M + 1);
    iota(prime_factor.begin(), prime_factor.end(), 0);

    for (int i = 2; i <= M; i ++) {
        if (prime_factor[i] == i) {
            for (int j = i; j <= M; j += i) {
                prime_factor[j] = i;
            }
        }
    }

    int n;
    cin >> n;

    vector<int> nums(n);
    for (auto &x: nums) cin >> x;

    vector<vector<int>> path(n);
    for (int i = 0; i < n - 1; i ++) {
        int u, v;
        cin >> u >> v;
        u --, v --;
        path[u].emplace_back(v);
        path[v].emplace_back(u);
    }

    vector<int> cnt(M + 1, 0);

    for (auto &x: nums) {
        int vx = x;
        while (vx > 1) {
            int p = prime_factor[vx];
            cnt[p] ++;
            while (vx % p == 0) vx /= p;
        }
    }

    int to_check, max_len;
    vector<int> dp(n);

    auto dfs = [&] (auto &self, int u, int p) -> void {
        int v1 = 0, v2 = 0;

        for (auto &v: path[u]) {
            if (v != p) {
                self(self, v, u);
                if (dp[v] > v1) swap(v1, v2), v1 = dp[v];
                else if (dp[v] > v2) v2 = dp[v];
            }
        }

        if (nums[u] % to_check == 0) {
            max_len = max(max_len, v1 + v2 + 1);
            dp[u] = v1 + 1;
        }
    };

    for (int i = 0; i <= M; i ++) {
        if (cnt[i] * 2 > n) {
            to_check = i, max_len = 0;
            dfs(dfs, 0, -1);
            if (max_len * 2 > n) return cout << "YES", 0;
        }
    }

    cout << "NO";

    return 0;
}
```

**提示 1：** 不妨枚举 GPS 失效的时刻。

**提示 2：** 此前此后有何要求？

坏了的 GPS 相当于要求我们走了某一条边。此前我们在某一条 $s$ 到 $t$ 的最短路上，此后是按照最短路走到 $t$ 。

如果 $L$ 刚好等于 $s$ 到 $t$ 的最短路长度，那么就相当于歪打正着，直接求最短路径条数就行。转移是根据边来的，所以转移次数是 $\mathcal{O}(m)$ 的。

否则，我们枚举失效的那条边。设边从 $u$ 到 $v$ ，则 $u$ 必须得在 $s$ 到 $t$ 的某条最短路上，于是 $dis(s,u)=dis(s,t)-dis(u,t)$ ，而从 $v$ 到终点的距离是 $dis(v,t)$ ，所以可以计算这种情况下的总路程并跟 $L$ 对比。

此时只需看前半部分和后半部分分别的方案数，再相乘即可。

前半部分是 $s$ 开始的路径个数，转移需要满足转移过程中的每个点都在 $s,t$ 的最短路上。

后半部分是从某个点到 $t$ 的路径个数，直接从 $t$ 的位置开始往外 DP 推答案就行。

需要注意的细节：如果你到了终点，那就没法折返了。

时间复杂度为 $\mathcal{O}(n\log m+m)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m = MII()
    s, t, l = MII()
    s -= 1
    t -= 1

    path = [[] for _ in range(n)]

    for _ in range(m):
        u, v, w = MII()
        u -= 1
        v -= 1
        path[u].append(w * n + v)
        path[v].append(w * n + u)

    inf = 10 ** 15
    mod = 10 ** 9 + 7

    dis = [inf] * n
    dis[t] = 0

    pq = [t]
    nodes = []

    while pq:
        d, u = divmod(heappop(pq), n)

        if dis[u] == d:
            nodes.append(u)

            for msk in path[u]:
                nd, v = divmod(msk, n)
                if dis[v] > nd + d:
                    dis[v] = nd + d
                    heappush(pq, dis[v] * n + v)

    from_s_dp = [0] * n
    from_s_dp[s] = 1

    nodes.reverse()

    for u in nodes:
        for msk in path[u]:
            d, v = divmod(msk, n)

            if dis[u] - dis[v] == d:
                from_s_dp[v] += from_s_dp[u]
                from_s_dp[v] %= mod

    if dis[s] == l:
        print(from_s_dp[t])
        exit()

    from_t_dp = [0] * n
    from_t_dp[t] = 1

    nodes.reverse()

    for u in nodes:
        for msk in path[u]:
            d, v = divmod(msk, n)

            if dis[v] - dis[u] == d:
                from_t_dp[v] += from_t_dp[u]
                from_t_dp[v] %= mod

    ans = 0

    for u in range(n):
        if from_s_dp[u]:
            for msk in path[u]:
                d, v = divmod(msk, n)

                if dis[s] - dis[u] + d + dis[v] == l and u != t:
                    ans += from_s_dp[u] * from_t_dp[v] % mod
                    ans %= mod

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, m, s, t;
    long long l;

    cin >> n >> m >> s >> t >> l;
    s --, t --;

    vector<vector<pair<int, int>>> path(n);

    while (m --) {
        int u, v, w;
        cin >> u >> v >> w;

        u --, v --;
        path[u].emplace_back(v, w);
        path[v].emplace_back(u, w);
    }

    long long inf = 1e15;
    int mod = 1e9 + 7;

    vector<long long> dis(n, inf);
    dis[t] = 0;

    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
    pq.push({0, t});
    vector<int> nodes;

    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();

        if (dis[u] == d) {
            nodes.emplace_back(u);
            for (auto &[v, w]: path[u]) {
                if (dis[v] > dis[u] + w) {
                    dis[v] = dis[u] + w;
                    pq.push({dis[v], v});
                }
            }
        }
    }

    vector<int> from_s_dp(n, 0), from_t_dp(n, 0);

    auto add = [&] (int &x, int y) -> void {
        x += y;
        if (x >= mod) x -= mod;
    };

    from_s_dp[s] = 1, from_t_dp[t] = 1;

    reverse(nodes.begin(), nodes.end());

    for (auto &u: nodes) {
        for (auto &[v, w]: path[u]) {
            if (dis[u] - dis[v] == w) {
                add(from_s_dp[v], from_s_dp[u]);
            }
        }
    }

    if (dis[s] == l) return cout << from_s_dp[t], 0;

    reverse(nodes.begin(), nodes.end());

    for (auto &u: nodes) {
        for (auto &[v, w]: path[u]) {
            if (dis[v] - dis[u] == w) {
                add(from_t_dp[v], from_t_dp[u]);
            }
        }
    }

    int ans = 0;

    for (int u = 0; u < n; u ++) {
        if (from_s_dp[u]) {
            for (auto &[v, w]: path[u]) {
                if (dis[s] - dis[u] + w + dis[v] == l && u != t) {
                    add(ans, 1ll * from_s_dp[u] * from_t_dp[v] % mod);
                }
            }
        }
    }

    cout << ans;

    return 0;
}
```

