int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    long long n;
    cin >> n;

    if (n == 1) return cout << 'N', 0;

    vector<int> pws;

    for (int i = 2; i <= 1000000; i ++) {
