    int tot1 = 0, tot2 = 0, dot = 0;

    for (auto &x: v1) tot1 += x, tot1 %= mod;
    for (auto &x: v2) tot2 += x, tot2 %= mod;

    for (int i = 0; i < n; i ++) {
        dot += 1ll * v1[i] * v2[i] % mod;
        dot %= mod;
    }

    int ans = 1ll * tot1 * tot2 % mod * quickPow(dot, k - 1, mod) % mod;

    cout << (ans + mod) % mod;

    return 0;
}
