            vis[i] = pt
            que = [i]
            for u in que:
                for v in range(n):
                    if path[u][v] == 0 and vis[v] == 0:
                        vis[v] = pt

    if pt > k: print(-1)
    else:
        for u in range(n):
            for v in range(n):
                if (vis[u] == vis[v]) == path[u][v]:
