    int cur_max = 0;
    map<pair<int, int>, int> saved;

    auto query = [&] (int x, int y) -> int {
        if (x == 0 || x == n + 1) return 0;
        if (y == 0 || y == n + 1) return 0;

        if (saved.find({x, y}) != saved.end()) return saved[{x, y}];

        cout << "? " << x << ' ' << y << endl;
