        cur_max = max(cur_max, res);
        saved[{x, y}] = res;
        return res;
    };

    auto solve = [&] (auto &self, int xl, int xr, int yl, int yr) -> void {

        int xm = (xl + xr) / 2;
        int ym = (yl + yr) / 2;

        int val = 0, vx, vy;

        for (int x = xl; x <= xr; x ++) {
            int nval;
            nval = query(x, ym);
            if (nval > val) {
                val = nval;
                vx = x;
                vy = ym;
            }
            nval = query(x, yl - 1);
            if (nval > val) {
                val = nval;
                vx = x;
                vy = yl - 1;
            }
            nval = query(x, yr + 1);
            if (nval > val) {
                val = nval;
                vx = x;
                vy = yr + 1;
            }
        }

        for (int y = yl; y <= yr; y ++) {
            int nval;
            nval = query(xm, y);
            if (nval > val) {
                val = nval;
                vx = xm;
                vy = y;
