            nval = query(xr + 1, y);
            if (nval > val) {
                val = nval;
                vx = xr + 1;
                vy = y;
            }
        }

        vector<pair<int, int>> dirs = {
            {-1, 0},
            {0, 1},
            {1, 0},
            {0, -1}
        };
        for (auto &[dx, dy]: dirs) {
            int nx = vx + dx, ny = vy + dy;
            if (nx >= xl && nx <= xr && ny >= yl && ny <= yr && query(nx, ny) > val) {
