int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    long long inf = 1e16;

    int t;
    cin >> t;

    while (t --) {
        int n, a, b;
        string s;

        cin >> n >> a >> b >> s;

        long long dp0 = b, dp1 = inf;
        for (auto &c: s) {
            if (c == '1')
                dp0 = inf, dp1 = dp1 + a + 2 * b;
            else {
