int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, m;
    cin >> n >> m;

    vector<array<int, 3>> edges(m);

    for (auto &[u, v, c]: edges) {
        char x;
        cin >> u >> v >> x;
        u --, v --;
        c = (x == 'S' ? 1 : 0);
    }

    if (n % 2 == 0) return cout << -1, 0;

