        auto [u, v, c] = edges[i];
        if (c == 0 && real_uf.merge(u, v)) {
            ans.emplace_back(i);
        }
    }

    if (ans.size() == n - 1) {
        cout << ans.size() << '\n';
        for (auto &x: ans) cout << x + 1 << ' ';
    }
    else cout << -1;

