**提示 1：** 如何比较两个序列的字典序。

**提示 2：** 唯一需要比较的位置，有哪些 $x$ 是合法的？

比较两个序列的字典序只需——

- 找到第一个不同的位置，看对应字符哪个更小。

- 在找不到的情况下，看一个是否是另一个的前缀。

所以对相邻的两个序列，进行上述操作。

如果后一个序列是前一个序列的前缀，则无法满足要求，直接输出无解。

如果前一个序列是后一个序列的前缀，则这两个序列总是满足要求。

否则，总能找到第一个不同的位置，设数值分别是 $x,y$ 。

- 如果 $x\lt y$ ，则要么 $y+V\leq c$ 或者 $x+V\gt c$ 。

- 如果 $x\gt y$ ，则 $x+V\gt c$ 且 $y+V\leq c$ 。

对应的都是区间，因此可以差分数组维护，最后用前缀和计算每个位置满足的条件的数量。只有满足条件的数量等于总条件个数的情况下，该位置是满足要求的。如果没有这样的位置，同样输出无解。

时间复杂度为 $\mathcal{O}(n+c)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, c = MII()
    diff = [0] * (c + 1)

    k1 = 0
    v1 = []

    for _ in range(n):
        k2, *v2 = LII()

        for i in range(fmin(k1, k2)):
            if v1[i] != v2[i]:
                if v1[i] < v2[i]:
                    diff[0] += 1
                    diff[c - v2[i] + 1] -= 1
                    diff[c - v1[i] + 1] += 1
                    diff[c] -= 1
                else:
                    diff[c - v1[i] + 1] += 1
                    diff[c - v2[i] + 1] -= 1
                break
        else:
            if k1 > k2:
                exit(print(-1))
            else:
                diff[0] += 1
                diff[c] -= 1

        k1 = k2
        v1 = v2

    for i in range(c):
        diff[i + 1] += diff[i]

    for i in range(c + 1):
        if diff[i] == n:
            exit(print(i))

    print(-1)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, c;
    cin >> n >> c;

    vector<int> diff(c + 1, 0);

    int k1 = 0;
    vector<int> v1;

    for (int i = 0; i < n; i ++) {
        int k2;
        cin >> k2;

        vector<int> v2(k2);
        for (auto &x: v2) cin >> x;

        bool flg = false;
        for (int i = 0; i < min(k1, k2); i ++) {
            if (v1[i] != v2[i]) {
                if (v1[i] < v2[i]) {
                    diff[0] ++, diff[c - v2[i] + 1] --;
                    diff[c - v1[i] + 1] ++, diff[c] --;
                }
                else diff[c - v1[i] + 1] ++, diff[c - v2[i] + 1] --;
                flg = true;
                break;
            }
        }

        if (!flg) {
            if (k1 > k2) return cout << -1, 0;
            else diff[0] ++, diff[c] --;
        }

        k1 = k2;
        v1 = v2;
    }

    for (int i = 1; i <= c; i ++)
        diff[i] += diff[i - 1];

    for (int i = 0; i <= c; i ++)
        if (diff[i] == n) return cout << i, 0;

    cout << -1;

    return 0;
}
```

**提示 1：** 路径的开头和结尾有条件，所以应该从这两个位置入手。

每条路径重要条件是 $1$ 开头， $2$ 结尾，中间是 $0$ 或者 $2$ 。所以关键点一定是开头和结尾。

因此路径中可以经过的店一定可以从 $1$ 出发到达，并从这个点出发到达一个 $2$ 。前者是原图可计算，后者是反图可计算。

具体地，我们从标记为 $1$ 的点出发，看走 $0$ 或者 $2$ 标记的点，能到达的位置。再在反图中，从标记为 $2$ 的点出发，并走到 $1$ 时不继续走，看能到达的店的位置。

这样两次遍历后，我们取交集就是能在路径上的点。

时间复杂度为 $\mathcal{O}(n+m)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m = MII()
    vals = LII()

    path = [[] for _ in range(n)]
    rev_path = [[] for _ in range(n)]

    for _ in range(m):
        u, v = GMI()
        path[u].append(v)
        rev_path[v].append(u)

    vis1 = [0] * n
    que = []

    for i in range(n):
        if vals[i] == 1:
            vis1[i] = 1
            que.append(i)

    for u in que:
        for v in path[u]:
            if not vis1[v] and (vals[v] == 0 or vals[v] == 2):
                vis1[v] = 1
                que.append(v)

    vis2 = [0] * n
    que = []

    for i in range(n):
        if vals[i] == 2:
            vis2[i] = 1
            que.append(i)

    for u in que:
        if vals[u] == 1: continue

        for v in rev_path[u]:
            if not vis2[v]:
                vis2[v] = 1
                que.append(v)

    print('\n'.join(str(vis1[i] & vis2[i]) for i in range(n)))
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, m;
    cin >> n >> m;

    vector<int> nums(n);
    for (auto &x: nums) cin >> x;

    vector<vector<int>> path(n), rev_path(n);
    for (int i = 0; i < m; i ++) {
        int u, v;
        cin >> u >> v;
        u --, v --;
        path[u].emplace_back(v);
        rev_path[v].emplace_back(u);
    }

    vector<int> vis1(n, 0), vis2(n, 0);

    auto dfs1 = [&] (auto &self, int u) -> void {
        vis1[u] = 1;
        for (auto &v: path[u]) {
            if (!vis1[v] && nums[v] != 1) {
                self(self, v);
            }
        }
    };

    for (int i = 0; i < n; i ++)
        if (nums[i] == 1) dfs1(dfs1, i);

    auto dfs2 = [&] (auto &self, int u) -> void {
        vis2[u] = 1;
        if (nums[u] == 1) return ;

        for (auto &v: rev_path[u]) {
            if (!vis2[v]) {
                self(self, v);
            }
        }
    };

    for (int i = 0; i < n; i ++)
        if (nums[i] == 2) dfs2(dfs2, i);

    for (int i = 0; i < n; i ++)
        cout << (vis1[i] & vis2[i]) << '\n';

    return 0;
}
```

**提示 1：** 先选出来数再排列。

总长度是 $n$ 的话，每个元素最多选多少个呢？最多选 $\lfloor n/2\rfloor$ 个，因为隔一个放一个也只能放那么多。

因此我们按照这个界提取元素，直到拿到 $n$ 个元素，接下来再排列它们。如果取不出来这么多，就无法构造。

取出来后有多种构造方案，一种是这样：

列出两个序列 $1,3,5,\dots$ ， $2,4,6,\dots$ ，先填入第一组，再填入第二组。

容易产生矛盾的是出现频率较高的数字，且只有刚好是 $n/2$ 的情况下会在上面的构造中产生矛盾（可能出现填入 $3,5,\dots$ 位置和 $2$ 位置的情况）。于是直接先处理 $n/2$ 频率的元素避免上面的矛盾，再填入其他元素。

时间复杂度为 $\mathcal{O}(n+m)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m = MII()
    nums = LII()

    for i in range(m):
        nums[i] = fmin(nums[i], n // 2)

    total = []

    for i in sorted(range(m), key=lambda x: -nums[x]):
        while len(total) < n and nums[i]:
            total.append(i + 1)
            nums[i] -= 1

    if len(total) < n:
        exit(print(-1))

    ans = [0] * n

    pt = 0
    for x in total:
        ans[pt] = x
        pt += 2

        if pt >= n:
            pt = 1

    print(*ans)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, m;
    cin >> n >> m;

    vector<int> nums(m);
    for (auto &x: nums) cin >> x;

    vector<int> order(m);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&] (int i, int j) {return nums[i] > nums[j];});

    vector<int> to_assign;
    for (auto &x: order) {
        int v = min(nums[x], n / 2);
        while ((v --) && to_assign.size() < n) {
            to_assign.emplace_back(x + 1);
        }
    }

    if (to_assign.size() < n) return cout << -1, 0;

    vector<int> ans(n);
    int pt = 0;

    for (auto &x: to_assign) {
        ans[pt] = x;
        pt += 2;
        if (pt >= n) pt = 1;
    }

    for (auto &x: ans) cout << x << ' ';

    return 0;
}
```

**提示 1：** 用 $c_{47},c_{74}$ 搭框架。

一个字符串内有多少个 $47,74$ 字符串，只跟开头元素是什么以及总共分了多少段有关系。

所以我们先看开头是 $4$ 的能否构造，再看开头是 $7$ 的能否构造。我们先把这个串构造出来，最后在一些 $4,7$ 所在的块分别插入剩余的 $4,7$ 即可。

如果 $4$ 和 $7$ 已经不够用了，就直接输出 $-1$ 。

在哪个位置插入剩下的 $4,7$ 呢？ $4$ 尽可能往前放， $7$ 尽可能往后放就行。于是只需找到最前面的一段 $4$ ，最后面的一段 $7$ 。

时间复杂度为 $\mathcal{O}(M)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    c4, c7, c47, c74 = MII()

    if abs(c47 - c74) > 1: print(-1)
    else:
        if c47 - c74 == 1 or (c47 == c74 and c4 >= c47 + 1 and c7 >= c47):
            ans = [4, 7] * c47
            if c47 == c74: ans.append(4)
        else:
            ans = [7, 4] * c74
            if c47 == c74: ans.append(7)

        c4 -= ans.count(4)
        c7 -= ans.count(7)
        if c4 >= 0 and c7 >= 0:
            res = []

            for x in ans:
                if x == 4:
                    while c4:
                        c4 -= 1
                        res.append(4)
                res.append(x)

            if res[-1] == 7:
                for x in range(c7):
                    res.append(7)
            else:
                res.pop()
                for x in range(c7):
                    res.append(7)
                res.append(4)

            print(''.join(map(str, res)))
        else:
            print(-1)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int c4, c7, c47, c74;
    cin >> c4 >> c7 >> c47 >> c74;

    if (abs(c47 - c74) > 1) cout << -1;
    else {
        vector<int> ans;
        if (c47 - c74 == 1 || (c47 == c74 && c4 >= c47 + 1 && c7 >= c47)) {
            for (int i = 0; i < c47; i ++) {
                ans.emplace_back(4);
                ans.emplace_back(7);
                c4 --, c7 --;
            }
            if (c47 == c74) ans.emplace_back(4), c4 --;
        }
        else {
            for (int i = 0; i < c74; i ++) {
                ans.emplace_back(7);
                ans.emplace_back(4);
                c4 --, c7 --;
            }
            if (c47 == c74) ans.emplace_back(7), c7 --;
        }

        if (c4 >= 0 && c7 >= 0) {
            vector<int> res;
            for (auto &x: ans) {
                if (x == 4)
                    while (c4) res.emplace_back(4), c4 --;
                res.emplace_back(x);
            }

            if (res.back() == 7)
                while (c7) res.emplace_back(7), c7 --;
            else {
                res.pop_back();
                while (c7) res.emplace_back(7), c7 --;
                res.emplace_back(4);
            }
            for (auto &x: res) cout << x;
        }
        else cout << -1;
    }

    return 0;
}
```

**提示 1：** 其实每个位置操作的数是多少是很容易算出来的。

考虑在 $(x,y)$ 位置变化数值是 $f(x,y)$ 。

在 $(x,y)$ 位置，有多少操作会影响到它呢？

考虑 $(x,y)$ 往右下角的所有位置的变化数值的总和，刚好就是 $A_{x,y}$ 。则 $f(x,y)=A_{x,y}-A_{x+1,y}-A_{x,y+1}+A_{x+1,y+1}$ ，因为 $A$ 是一个类似前缀和的数组，我们相当于用它恢复原数组。

于是只要这个 $f(x,y)$ 不是 $0$ ，这个位置就必须得操作，对答案 $+1$ 即可。

时间复杂度为 $\mathcal{O}(nm)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m = MII()
    grid = [[1 if c == 'B' else -1 for c in I()] for _ in range(n)]

    ans = 0

    for i in range(n):
        for j in range(m):
            v = grid[i][j]
            if i + 1 < n: v -= grid[i + 1][j]
            if j + 1 < m: v -= grid[i][j + 1]
            if i + 1 < n and j + 1 < m: v += grid[i + 1][j + 1]

            if v: ans += 1

    print(ans)
```

C++ 做法如下——

