    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, m;
    cin >> n >> m;

    vector<string> grid(n);
    for (auto &s: grid) cin >> s;

    int ans = 0;

    for (int i = 0; i < n; i ++) {
        for (int j = 0; j < m; j ++) {
            int v = grid[i][j];
            if (i + 1 < n) v -= grid[i + 1][j];
            if (j + 1 < m) v -= grid[i][j + 1];
            if (i + 1 < n && j + 1 < m) v += grid[i + 1][j + 1];

            if (v) ans ++;
        }
    }

