        int total = 0;
        for (auto &v: nums) total ^= v;

        auto solve = [&] (auto &self, long long x) -> int {
            if (x <= n) return nums[x - 1];

            if (x <= n * 2) {
                int ans = 0;
                for (int i = 0; i < x / 2; i ++)
                    ans ^= nums[i];
                return ans;
            }

            long long v = x / 2;
            if (v % 2 == 0) return total ^ self(self, v);
            return total;
        };

        cout << solve(solve, l) << '\n';
    }

    return 0;
}
