                    nth_parent[i + 1][j] = nth_parent[i][nth_parent[i][j]];
                }
            }
        }

        vector<int> sz(n, 1), diff(n, 0);

        for (auto &[u, v]: edges) {
            diff[u] ++, diff[v] ++;
            if (depth[u] < depth[v]) swap(u, v);
            int d = depth[u] - depth[v];

            for (int i = 0; i < 20; i ++) {
