    vector<int> cnt(n, 0), max_flg(n, 0);

    for (int i = 0; i < n - 1; i ++) {
        int a, b;
        cin >> a >> b;

        if (b != n) return cout << "NO", 0;
        cnt[a] ++, max_flg[a] = 1;
    }

    vector<int> chain;
