        }
    }

    int q;
    cin >> q;

    while (q --) {
        int u, v;
        cin >> u >> v;
        u --, v --;

        if (depth[u] < depth[v]) swap(u, v);

        int d = depth[u] - depth[v];

        for (int i = 19; i >= 0; i --) {
            if (d >> i & 1) {
                u = nth_parent[i][u];
            }
        }

        if (u == v) cout << u + 1 << ' ';
        else {
            for (int i = 19; i >= 0; i --) {
                if (nth_parent[i][u] != nth_parent[i][v]) {
                    u = nth_parent[i][u];
                    v = nth_parent[i][v];
                }
            }

            cout << nth_parent[0][u] + 1 << ' ';
        }
    }

    return 0;
}
```

**提示 1：** 典型的树上 DP 问题。你需要维护什么状态？

这很明显是一个树上的 DP 问题，需要维护什么状态呢？

对于 $u$ 结点对应的子树，真正影响子树内数值的是对这个点的操作数量，因此设进行加一操作 $f[u]$ 次，减一操作 $g[u]$ 次。

如果 $u$ 的子节点 $v$ 需要进行 $f[v],g[v]$ 次加一 / 减一操作，则这些操作一定也作用在了 $u$ 这个节点上，因为 $u$ 在 $v$ 到 $1$ 的路径上。因此对应的，有 $f[u]\geq f[v], g[u]\geq g[v]$ 。

所以，我们先令 $f[u]=\max(f[v]), g[u]=\max(g[v])$ 。

此时，查看 $u$ 这个结点数值跟目标数值可能有一定差距，此时再把需要增加的操作，增加到 $f[u]$ 或者 $g[u]$ 上即可。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    path = [[] for _ in range(n)]

    for _ in range(n - 1):
        u, v = GMI()
        path[u].append(v)
        path[v].append(u)

    nums = LII()

    parent = [-1] * n
    q = [0]

    for u in q:
        for v in path[u]:
            if parent[u] != v:
                parent[v] = u
                q.append(v)

    f = [0] * n
    g = [0] * n

    for u in reversed(q):
        for v in path[u]:
            if parent[v] == u:
                f[u] = fmax(f[u], f[v])
                g[u] = fmax(g[u], g[v])

        k = nums[u] + f[u] - g[u]
        if k > 0: g[u] += k
        else: f[u] += -k

    print(f[0] + g[0])
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector<vector<int>> path(n);
    for (int i = 0; i < n - 1; i ++) {
        int u, v;
        cin >> u >> v;
        u --, v --;
        path[u].emplace_back(v);
        path[v].emplace_back(u);
    }

    vector<int> nums(n);
    for (auto &v: nums) cin >> v;

    vector<long long> f(n, 0), g(n, 0);

    auto dfs = [&] (auto &self, int u, int p) -> void {
        for (auto &v: path[u])
            if (v != p) self(self, v, u);

        for (auto &v: path[u]) {
            if (v != p) {
                f[u] = max(f[u], f[v]);
                g[u] = max(g[u], g[v]);
            }
        }

        long long k = nums[u] + f[u] - g[u];
        if (k > 0) g[u] += k;
        else f[u] -= k;
    };

    dfs(dfs, 0, -1);

    cout << f[0] + g[0];

    return 0;
}
```

**提示 1：** 注意 $f(x)$ 不可能很大。

虽然这里需要逐步确定 $f(x)$ 和 $g(x)$ ，但实际上没那么复杂。

因为这里的 $f(x)$ 最大只能是最大的二进制位数，也就是 $59$ 。所以考虑枚举 $f(x)$ 。

而对于每一个 $f(x)$ ，可能的 $g(x)$ 也只有 $\log_{f(x)}M$ 个，我们枚举这个 $g(x)$ ，则对应的 $x$ 需要在 $[l,r]$ 之间，且二进制位恰好有 $f(x)$ 位，且数值在 $[f(x)^{g(x)},f(x)^{g(x)+1})$ 之间。

这就是一个区间取交的问题，直接左端点取最大值，右端点取最小值，即可得到对应区间，在区间合法，即左端点小于右端点时，可以使用区间长度计算区间中元素个数，乘以 $g(x)$ 加入到结果中即可。

时间复杂度为 $\mathcal{O}(\log M\log\log M)$ ，考虑成 $\log x$ 在 $[2,\log M]$ 上的积分。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []
    mod = 10 ** 9 + 7

    for _ in range(t):
        l, r = MII()
        r += 1

        xl, xr = 2, 4
        ans = 0

        for fx in range(2, 60):
            xl *= 2
            xr *= 2

            vl = fmax(l, xl)
            vr = fmin(r, xr)

            if vl >= vr: continue

            nl, nr = 1, fx
            for v in range(1, 60):
                nl *= fx
                nr *= fx
                if nr <= vl: continue
                if nl >= vr: break

                cnt = fmin(vr, nr) - fmax(vl, nl)
                ans += cnt * v % mod

        outs.append(ans % mod)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int t, mod = 1e9 + 7;
    cin >> t;

    while (t --) {
        long long l, r;
        cin >> l >> r;

        r ++;
        long long xl = 2, xr = 4;
        int ans = 0;

        for (int fx = 2; fx < 60; fx ++) {
            xl <<= 1, xr <<= 1;

            long long vl = max(l, xl), vr = min(r, xr);
            if (vl >= vr) continue;

            long long nl = 1, nr = fx;

            for (int v = 1; v < 60; v ++) {
                nl = min(nl, vr / fx + 5) * fx;
                nr = min(nr, vr / fx + 5) * fx;

                if (nl >= vr) break;
                long long cnt = max(0ll, min(vr, nr) - max(vl, nl));
                ans += cnt % mod * v % mod;

                if (ans >= mod) ans -= mod;
            }
        }

        cout << ans << '\n';
    }

    return 0;
}
```

**提示 1：** 每个元素的权重可能如何？

这题非常的简单！

因为操作的是前缀和后缀，所以最后每个元素的权重一定是，开始一段 $-1$ ，中间一段 $1$ ，最后一段 $-1$ （每一段都可以是空的）。

于是我们用 $dp[status][idx]$ 作为 DP 的数组，表示在第 $status$ 段时，遍历到第 $idx$ 情况下的最大和。接下来只需看后面的元素给哪一段就可以进行状态转移了。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    nums = LII()

    dp1, dp2, dp3 = 0, 0, 0
    for x in nums:
        dp3 = fmax(dp2, dp3) - x
        dp2 = fmax(dp1, dp2) + x
        dp1 -= x

    print(max(dp1, dp2, dp3))
```

C++ 做法如下——

