    vector<int> pos1(n), pos2(n);

    for (int i = 0; i < n; i ++) {
        int x;
        cin >> x;
        pos1[x - 1] = i;
    }

    for (int i = 0; i < n; i ++) {
        int x;
        cin >> x;
        pos2[x - 1] = i;
    }

    vector<int> ar(n);
    for (int i = 0; i < n; i ++)
        ar[pos1[i]] = -pos2[i];

