    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, mod = 1e9 + 7;
    cin >> n;

    int dp0 = 0, dp1 = 0;
    for (int i = 0; i < n; i ++) {
        if (i & 1) dp1 = (dp0 + dp1 + 1) % mod;
        else dp0 = (dp0 + dp1 + 1) % mod;
    }

    cout << (dp0 + dp1) % mod;

    return 0;
}
