**提示 1：** 第一个数字一定得跟哪些数字是一组的？

**提示 2：** 接下来呢？

考虑 $a_1$ ，则后面连续的一段不超过 $a_1$ 的数字只能跟 $a_1$ 一组，不然拼不出来最后的序列。

这样我们分割出了第一段。对于下一个元素，我们也能找到连续的不超过这个数的一段。

这样我们将数组一段段切割，每一段都只能出现在一个数组里。

接下来就只需考虑通过这些段能否凑成一个长度为 $n$ 的数组。这件事就是简单的背包 DP 。

而找到了序列后，只需顺序拼接即可，因为这些段落的第一个元素一定是单调递增的，而段内其他元素小于第一个元素，所以直接拼接就是满足条件的（可以脑中模拟下其中一段的拼接——第一个元素选了一段的开头后，接下来这一段的剩余元素也被添加了进去）。

时间复杂度为 $\mathcal{O}(n^2)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    nums = LII()

    intervals = []

    l = 0

    while l < n * 2:
        r = l
        while r + 1 < n * 2 and nums[r + 1] < nums[l]:
            r += 1
        intervals.append((l, r))
        l = r + 1

    dp = [-2] * (n + 1)
    dp[0] = -1

    for i in range(len(intervals)):
        x = intervals[i][1] - intervals[i][0] + 1
        for y in range(n, x - 1, -1):
            if dp[y - x] != -2 and dp[y] == -2:
                dp[y] = i

    if dp[n] == -2:
        exit(print(-1))

    choice = [0] * (2 * n)
    cur = n

    while cur:
        idx = dp[cur]
        l, r = intervals[idx]

        for i in range(l, r + 1):
            choice[i] = 1

        cur -= r - l + 1

    print(' '.join(str(nums[i]) for i in range(2 * n) if choice[i]))
    print(' '.join(str(nums[i]) for i in range(2 * n) if not choice[i]))
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector<int> nums(n * 2);
    for (auto &v: nums) cin >> v;

    vector<pair<int, int>> intervals;

    int l = 0;
    while (l < n * 2) {
        int r = l;
        while (r + 1 < n * 2 && nums[r + 1] < nums[l])
            r ++;
        intervals.emplace_back(l, r);
        l = r + 1;
    }

    vector<int> dp(n + 1, -2);
    dp[0] = -1;

    for (int i = 0; i < intervals.size(); i ++) {
        int x = intervals[i].second - intervals[i].first + 1;
        for (int y = n; y >= x; y --) {
            if (dp[y - x] != -2 && dp[y] == -2) {
                dp[y] = i;
            }
        }
    }

    if (dp[n] == -2) return cout << -1, 0;

    vector<int> choice(2 * n, 0);
    int cur = n;

    while (cur) {
        int idx = dp[cur];
        auto [l, r] = intervals[idx];

        for (int i = l; i <= r; i ++)
            choice[i] = 1;

        cur -= r - l + 1;
    }

    for (int i = 0; i < 2 * n; i ++)
        if (choice[i]) cout << nums[i] << ' ';
    cout << '\n';

    for (int i = 0; i < 2 * n; i ++)
        if (!choice[i]) cout << nums[i] << ' ';
    cout << '\n';

    return 0;
}
```

**提示 1：** 每个元素是被相邻的东西吃掉的。

**提示 2：** 相邻的东西对应于一个区间。

考虑每个元素最后被吃掉的那一刻，一定是相邻的一个元素。

这个元素一定是一段连续的区间合成的。这个区间需要满足什么条件呢？

首先，这个区间的和大于当前元素，不然吃不掉。

除此之外，要么这个区间只有一个元素，要么至少包含两种不同的元素，否则这个区间没法合并为一个元素（一旦有不同元素，总能合并；因为总可以找最大且相邻有更小的那个元素进行吃的动作，接下来最大值就唯一了）。

对于第一个条件，可以用前缀和搭配二分找到对应位置，对于第二个条件，我们只需找 $i-1$ 往前 / $i+1$ 往后第一个不同元素，这个可以通过顺序 / 逆序遍历的预处理，找到这个元素所在段的第一个 / 最后一个位置即可。

于是两个条件都被顺利检查，完成。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    for _ in range(t):
        n = II()
        nums = LII()

        acc = list(accumulate(nums, initial=0))

        last_pos = list(range(n + 1))
        for i in range(1, n):
            if nums[i] == nums[i - 1]:
                last_pos[i] = last_pos[i - 1]

        next_pos = list(range(n + 1))
        for i in range(n - 2, -1, -1):
            if nums[i] == nums[i + 1]:
                next_pos[i] = next_pos[i + 1]

        ans = [n] * n

        for i in range(n):
            if i:
                l, r = 0, i - 1
                while l <= r:
                    mid = (l + r) // 2
                    if acc[i] - acc[mid] > nums[i]:
                        l = mid + 1
                    else:
                        r = mid - 1
                r = fmin(r, last_pos[i - 1] - 1)

                if r >= 0: ans[i] = fmin(ans[i], i - r)
                if nums[i - 1] > nums[i]: ans[i] = 1

            if i + 1 < n:
                l, r = i + 1, n - 1
                while l <= r:
                    mid = (l + r) // 2
                    if acc[mid + 1] - acc[i + 1] > nums[i]:
                        r = mid - 1
                    else:
                        l = mid + 1
                l = fmax(l, next_pos[i + 1] + 1)

                if l < n: ans[i] = fmin(ans[i], l - i)
                if nums[i + 1] > nums[i]: ans[i] = 1

            if ans[i] == n: ans[i] = -1

        outs.append(' '.join(map(str, ans)))

    print('\n'.join(outs))
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int t;
    cin >> t;

    while (t --) {
        int n;
        cin >> n;

        vector<int> nums(n);
        for (auto &v: nums) cin >> v;

        vector<long long> acc(n + 1, 0);
        for (int i = 0; i < n; i ++)
            acc[i + 1] = acc[i] + nums[i];

        vector<int> last_pos(n), next_pos(n);
        iota(last_pos.begin(), last_pos.end(), 0);
        iota(next_pos.begin(), next_pos.end(), 0);

        for (int i = 1; i < n; i ++)
            if (nums[i] == nums[i - 1])
                last_pos[i] = last_pos[i - 1];

        for (int i = n - 2; i >= 0; i --)
            if (nums[i] == nums[i + 1])
                next_pos[i] = next_pos[i + 1];

        vector<int> ans(n, n);
        for (int i = 0; i < n; i ++) {
            if (i) {
                int l = 0, r = i - 1;
                while (l <= r) {
                    int mid = (l + r) / 2;
                    if (acc[i] - acc[mid] > nums[i]) l = mid + 1;
                    else r = mid - 1;
                }
                r = min(r, last_pos[i - 1] - 1);
                if (r >= 0) ans[i] = min(ans[i], i - r);
                if (nums[i - 1] > nums[i]) ans[i] = 1;
            }
            if (i + 1 < n) {
                int l = i + 1, r = n - 1;
                while (l <= r) {
                    int mid = (l + r) / 2;
                    if (acc[mid + 1] - acc[i + 1] > nums[i]) r = mid - 1;
                    else l = mid + 1;
                }
                l = max(l, next_pos[i + 1] + 1);
                if (l < n) ans[i] = min(ans[i], l - i);
                if (nums[i + 1] > nums[i]) ans[i] = 1;
            }
            if (ans[i] == n) ans[i] = -1;
        }
        for (auto &x: ans) cout << x << ' '; cout << '\n';
    }

    return 0;
}
```

**提示 1：** 相当于是通过子弹进行分段。

这题洛谷题解似乎说的很错，类似 “第一个位置不要放子弹，不然上来就死了” 的表述是有问题的，因为你开局是需要随机选择一个位置作为起点的，并不是直接开始。

首先 $k=0$ 的平凡情况先进行特判。

接下来，一定有一个子弹放最后，这是因为当最后一个子弹不放最后时，吧最后的空位置移动到开头一定是更优的。

此时，根据每个子弹分段，每一段是 $x_1,x_2,\dots,x_l$ 的长度，则其中每一段只有 $\left\lfloor\frac{x_i}{2}\right\rfloor$ 个位置是先手胜利的，所以我们要最大化这一点。

同时，越长的段越应该放在开头（根据拼接字典序最小的规则）。

而前面的段越长越好。

事实上，后面的每一段长度都不应该超过 $3$ ，因为一旦超过了 $3$ ，不如缩短长度 $2$ 添加到第一段去。

在奇数情况下，总有一段是奇数，此时不妨将这段的唱多缩减为 $1$ ，并将剩余的长度全部添加到除此之外最长的一段上，则这个序列排列后一定更优。于是去掉这个元素就变成了偶数的情况。

偶数的情况，上述数值不会超过 $\sum\frac{x_i}{2}$ ，所以在分割段数不超过 $\frac{n}{2}$ 的情况下，不妨后面段落长度均为 $2$ 。

否则，至少 $2k-n$ 段长度为 $1$ ，剩余总长为 $2n-2k$ ，所以最优结果为 $n-k$ ，当且仅当有 $n-k$ 段长度非 $1$ 时取到，也就只能是 $n-k$ 段 $2$ ， $k$ 段 $1$ 。

单次查询时间复杂度为 $\mathcal{O}(1)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, k, p = MII()
    outs = []

    for _ in range(p):
        x = II()

        if k == 0: outs.append('.')
        else:
            vn, vk = n, k
            if n % 2:
                if x == n:
                    outs.append('X')
                    continue
                else:
                    vn -= 1
                    vk -= 1

            if vk * 2 <= vn:
                if x % 2 == 0 and x // 2 + vk > vn // 2:
                    outs.append('X')
                else:
                    outs.append('.')
            else:
                if x % 2 == 0: outs.append('X')
                elif (x + 1) // 2 + (vk - vn // 2) > vn // 2:
                    outs.append('X')
                else: outs.append('.')

    print(''.join(outs))
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    long long n, k;
    cin >> n >> k;

    int p;
    cin >> p;

    while (p --) {
        long long x;
        cin >> x;

        if (k == 0) cout << '.';
        else {
            long long vn = n, vk = k;
            if (n & 1) {
                if (x == n) {
                    cout << 'X';
                    continue;
                }
                vn --, vk --;
            }

            if (vk * 2 <= vn)
                if (x % 2 == 0 && x / 2 + vk > vn / 2) cout << 'X';
                else cout << '.';
            else
                if (x % 2 == 0) cout << 'X';
                else if ((x + 1) / 2 + (vk - vn / 2) > vn / 2) cout << 'X';
                else cout << '.';
        }
    }

    return 0;
}
```

**提示 1：** 枚举所有可能重要的三分球线。

**提示 2：** 哪些是重要的？

我们可以枚举所有可能的三分球线的位置。

其实很多位置本身是不重要的，我们只需要枚举所有可能切割不同距离的位置。即假设投篮的距离是 $x_1,x_2,\dots,x_n$ ，那么我们只需要考虑边界在区间 $[0,x_1),(x_1,x_2),\dots,(x_n,+∞)$ 。

而枚举后，可以将两个数组分别排序，二分找到二分球和三分球的个数，也可以用双指针来找，都是很可行的事情。注意最后贪心取答案需要的字典序的细节。

时间复杂度为 $\mathcal{O}(n\log n+m\log m)$ ，注意无需写 $(n+m)\log (n+m)$ ，因为这个不会超过前面那个两项的和。

### 具体代码如下——

Python 做法如下——

