            p2 += 1

        v1 = 2 * p1 + 3 * (n - p1)
        v2 = 2 * p2 + 3 * (m - p2)

        if v1 - v2 > ans1 - ans2:
            ans1, ans2 = v1, v2

    print(f'{ans1}:{ans2}')
