    while (q --) {
        int x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;
        x1 --, y1 --, x2 --, y2 --;
        if (flg) cout << dist[x2][y2] - dist[x1][y1] << '\n';
