    cin.tie(0);
    cout.tie(0);

    int n, m;
    cin >> n >> m;

    vector<string> grid(n);
    for (auto &s: grid) cin >> s;

    vector<pair<int, int>> dirs = {
        {0, 1},
        {1, 0},
        {0, -1},
        {-1, 0}
    };

    int target = 0;
    for (int i = 0; i < n; i ++) {
        for (int j = 0; j < m; j ++) {
            if (grid[i][j] != '.') target ++;
        }
