            int x = 0, y = i, dir = 1;
            while (x >= 0 && x < n && y >= 0 && y < m) {
                if (grid[x][y] != '.') {
                    vis[x][y] = 1;
                    dir ^= (grid[x][y] == '\\' ? 1 : 3);
                }
                auto [dx, dy] = dirs[dir];
                x += dx, y += dy;
