            if (c == target) ans.emplace_back(1, i);
        }
        {
            int x = n - 1, y = i, dir = 3;
            while (x >= 0 && x < n && y >= 0 && y < m) {
                if (grid[x][y] != '.') {
                    vis[x][y] = 1;
                    dir ^= (grid[x][y] == '\\' ? 1 : 3);
                }
                auto [dx, dy] = dirs[dir];
                x += dx, y += dy;
            }

            int c = 0;
            for (int i = 0; i < n; i ++) {
                for (int j = 0; j < m; j ++) {
                    c += vis[i][j];
                    vis[i][j] = 0;
                }
            }
            if (c == target) ans.emplace_back(3, i);
        }
    }

    for (int i = 0; i < n; i ++) {
        {
            int x = i, y = 0, dir = 0;
            while (x >= 0 && x < n && y >= 0 && y < m) {
                if (grid[x][y] != '.') {
                    vis[x][y] = 1;
                    dir ^= (grid[x][y] == '\\' ? 1 : 3);
                }
                auto [dx, dy] = dirs[dir];
                x += dx, y += dy;
            }

            int c = 0;
            for (int i = 0; i < n; i ++) {
                for (int j = 0; j < m; j ++) {
                    c += vis[i][j];
                    vis[i][j] = 0;
                }
            }
            if (c == target) ans.emplace_back(0, i);
        }
        {
            int x = i, y = m - 1, dir = 2;
            while (x >= 0 && x < n && y >= 0 && y < m) {
                if (grid[x][y] != '.') {
                    vis[x][y] = 1;
                    dir ^= (grid[x][y] == '\\' ? 1 : 3);
                }
                auto [dx, dy] = dirs[dir];
                x += dx, y += dy;
            }

            int c = 0;
            for (int i = 0; i < n; i ++) {
                for (int j = 0; j < m; j ++) {
                    c += vis[i][j];
                    vis[i][j] = 0;
                }
            }
            if (c == target) ans.emplace_back(2, i);
        }
    }

    cout << ans.size() << '\n';
    for (auto &[x, y]: ans) {
        if (x == 0) cout << 'W' << y + 1 << ' ';
        else if (x == 1) cout << 'N' << y + 1 << ' ';
