**提示 1：** 关键在于点不多。

**提示 2：** 所以，关键的，共线关系也不多。

虽然底下要判断的点很多，但实际上，即使两两算直线，对应的直线数量也只是平方量级的。

所以，我们只需计算两两的直线，看有多少直线重合了——最后判断下这些直线哪些经过 $(i,0)$ 点即可。下面代码用了类似 $Ax+By+C=0$ 的方式来表示一条直线。

这里求直线用了保守的除去公因数的方式，因此复杂度是 $\mathcal{O}(m^2\log M)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m = MII()
    xs = []
    ys = []

    for _ in range(m):
        x, y = MII()
        xs.append(x)
        ys.append(y)

    cnt = Counter()

    for i in range(m):
        x1, y1 = xs[i], ys[i]
        for j in range(i):
            x2, y2 = xs[j], ys[j]
            dx, dy = x2 - x1, y2 - y1

            g = math.gcd(dx, dy)
            dx //= g
            dy //= g

            if dx < 0 or (dx == 0 and dy < 0):
                dx = -dx
                dy = -dy

            cnt[(dx, dy, x1 * dy - dx * y1)] += 1

    ans = [0] * (n + 1)

    for dx, dy, val in cnt:
        v = cnt[(dx, dy, val)]
        if dy and val % dy == 0 and 1 <= val // dy <= n:
            ans[val // dy] = fmax(ans[val // dy], v)

    res = 0
    for i in range(1, n + 1):
        res += math.isqrt(ans[i] * 2) + 1

    print(res)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, m;
    cin >> n >> m;

    vector<pair<int, int>> pts(m);
    for (auto &[x, y]: pts) cin >> x >> y;

    map<tuple<int, int, long long>, int> mp;

    for (int i = 0; i < m; i ++) {
        auto [x1, y1] = pts[i];
        for (int j = 0; j < i; j ++) {
            auto [x2, y2] = pts[j];
            int dx = x2 - x1, dy = y2 - y1;
            int g = gcd(dx, dy);
            dx /= g, dy /= g;

            if (dx < 0 || (dx == 0 && dy < 0))
                dx = -dx, dy = -dy;

            mp[{dx, dy, 1ll * x1 * dy - 1ll * dx * y1}] ++;
        }
    }

    vector<int> ans(n + 1, 0);

    for (auto &[k, v]: mp) {
        auto [dx, dy, val] = k;
        if (dy && val % dy == 0 && val / dy >= 1 && val / dy <= n) {
            ans[val / dy] = max(ans[val / dy], v);
        }
    }

    int res = 0;
    for (int i = 1; i <= n; i ++)
        res += sqrt(ans[i] * 2) + 1;

    cout << res;

    return 0;
}
```

**提示 1：** 很典型的问题。区间赋值取最大。

**提示 2：** 最后提取答案怎么办。

我们先确定对于每一个横坐标，竖着是多少。这是典型的区间复制，最后提取最大值的问题。

有很多种方式——

- 染色——从大数往小数染色。染过色的位置进行删除。这样只要快速得到没被染色过的区间就行，可以使用有序结构维护，或者用类似并查集定向往右合并，找到下一个还没合并的位置。

- 扫描线——从左到右，用有序集合维护到某个位置为止还有的高度的数据。这个数据集的最大值就是对应高度。

- 懒更新线段树——区间赋值，很典型。

最后输出答案的时候，只需看当前的高度跟之前的高度有无差别，如果有差别，就会多两个拐点，把它们加入答案即可。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    delta = random.getrandbits(30)

    infile = open('input.txt', 'r')
    input = lambda: infile.readline().strip()
    outfile = open('output.txt', 'w')
    print = lambda x: outfile.write(str(x) + '\n')

    n = II()

    ls = []
    rs = []
    hs = []

    for _ in range(n):
        h, l, r = MII()
        l += delta
        r += delta
        ls.append(l)
        rs.append(r)
        hs.append(h)

    seps = sorted(set(ls + rs))
    k = len(seps)
    d = {v: i for i, v in enumerate(seps)}

    vals = [0] * k
    dsu = UnionFind(k)

    for i in sorted(range(n), key=lambda x: -hs[x]):
        pl = d[ls[i]]
        pr = d[rs[i]]
        h = hs[i]
        while dsu.find(pl) < pr:
            pl = dsu.find(pl)
            vals[pl] = h
            dsu.merge_to(pl, pl + 1)

    pts = []
    cur_h = 0

    for i in range(k):
        if vals[i] != cur_h:
            pts.append(f'{seps[i] - delta} {cur_h}')
            pts.append(f'{seps[i] - delta} {vals[i]}')
            cur_h = vals[i]

    print(len(pts))
    print('\n'.join(pts))
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    ifstream fin("input.txt");
    ofstream fout("output.txt");

    int n;
    fin >> n;

    map<int, vector<int>> diff;
    while (n --) {
        int h, l, r;
        fin >> h >> l >> r;
        diff[l].emplace_back(h);
        diff[r].emplace_back(-h);
    }

    int cur_h = 0;
    multiset<int> vals;
    vals.insert(0);

    vector<pair<int, int>> pts;

    for (auto &[k, v]: diff) {
        for (auto &x: v) {
            if (x > 0) vals.insert(x);
            else vals.erase(vals.find(-x));
        }
        int new_h = *vals.rbegin();
        if (cur_h != new_h) {
            pts.emplace_back(k, cur_h);
            pts.emplace_back(k, new_h);
            cur_h = new_h;
        }
    }

    fout << pts.size() << '\n';
    for (auto &[x, y]: pts) fout << x << ' ' << y << '\n';

    return 0;
}
```

**提示 1：** 先把最后几个完整的轮去掉。

**提示 2：** 最后不停往前推。

考虑最后几轮，每一轮 $1,2,\dots,n$ 每个人都拿一个。

有几轮呢？答案是 $\min(a_1,a_2,\dots,a_n)$ 。

接下来，从最后拿到的 $x$ 出发，往前推，把球进行收回，直到无法收回——即遇到了 $0$ 。最后再把所有的撤销的球都给这个人即可。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, x = MII()
    nums = LII()

    x -= 1
    mn = min(nums)

    for i in range(n):
        nums[i] -= mn

    mn *= n

    while nums[x]:
        nums[x] -= 1
        mn += 1
        x = (x - 1) % n

    nums[x] = mn

    print(*nums)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, x;
    cin >> n >> x;

    vector<long long> nums(n);
    for (auto &v: nums) cin >> v;

    x --;
    long long mn = *min_element(nums.begin(), nums.end());

    for (auto &v: nums) v -= mn;
    mn *= n;

    while (nums[x]) {
        nums[x] --, mn ++;
        x = (x + n - 1) % n;
    }

    nums[x] = mn;
    for (auto &v: nums) cout << v << ' ';

    return 0;
}
