    vector<int> cur;
    int v1 = 0, v2 = 0, v3 = 0;

    while (q --) {
        int x;
        cin >> x;

        if (x) {
            if (x > v1) {
                v3 = x;
                swap(v2, v3);
                swap(v1, v2);
            }
            else if (x > v2) {
                v3 = x;
                swap(v2, v3);
            }
            else if (x > v3)
