**提示 1：** 按照时间考虑每个目标。

**提示 2：** 状态是什么？什么情况下可以状态转移？

首先，一定按照时间的顺序射击每个目标。因此先关于时间排序。

假设我们最后射击目标为 $i$ 时的最优期望为 $dp[i]$ ，则状态转移就只需考虑下次设计什么。

假设下次射击的目标是 $j$ ，那么怎么判断能不能走到呢？就只需距离不超过 $t$ 。注意这里两边平方就可以只涉及整数运算了，虽然这里给的题目并卡不了用浮点数。

如果能转移，就可以用 $dp[i]+prob[j]$ 来更新 $dp[j]$ 了。对于每个 $i$ 尝试转移到所有时间更靠后的 $j$ 即可。

时间复杂度为 $\mathcal{O}(n^2)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    xs = []
    ys = []
    ts = []
    ps = []

    for _ in range(n):
        x, y, t, p = LI()
        x = int(x)
        y = int(y)
        t = int(t)
        p = float(p)
        xs.append(x)
        ys.append(y)
        ts.append(t)
        ps.append(p)

    st_range = sorted(range(n), key=lambda x: ts[x])
    dp = [0] * n

    for i in range(n):
        i1 = st_range[i]

        x1 = xs[i1]
        y1 = ys[i1]
        t1 = ts[i1]
        p1 = ps[i1]

        for j in range(i):
            i2 = st_range[j]

            x2 = xs[i2]
            y2 = ys[i2]
            t2 = ts[i2]
            p2 = ps[i2]

            if (x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1) <= (t2 - t1) * (t2 - t1):
                dp[i1] = fmax(dp[i1], dp[i2])

        dp[i1] += p1

    print(max(dp))
```

C++ 做法如下——

```cpp []
struct node {
    int x, y, t;
    long double p;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector<node> nodes(n);
    for (auto &v: nodes)
        cin >> v.x >> v.y >> v.t >> v.p;

    sort(nodes.begin(), nodes.end(), [&] (node x, node y) {
        return x.t < y.t;
    });

    vector<long double> dp(n, 0);
    for (int i = 0; i < n; i ++) {
        for (int j = 0; j < i; j ++) {
            if ((nodes[i].x - nodes[j].x) * (nodes[i].x - nodes[j].x) +
                (nodes[i].y - nodes[j].y) * (nodes[i].y - nodes[j].y) <=
                1ll * (nodes[i].t - nodes[j].t) * (nodes[i].t - nodes[j].t))
                dp[i] = max(dp[i], dp[j]);
        }
        dp[i] += nodes[i].p;
    }

    cout << fixed << setprecision(15) << *max_element(dp.begin(), dp.end());

    return 0;
}
```

**提示 1：** 又是典型的分割 $k$ 轮，每种分割会有成本。

**提示 2：** 先预处理分割的成本，再 DP 最小总分割成本。

是典型的划分 DP 。

我们可以预处理每个子串修改成回文串的成本。这个可以使用 DP 快速解决： $dp[l][r]=dp[l+1][r-1]+(s[l]\neq s[r])$ （ $dp[l][r]$ 表示 $s[l\dots r]$ 变为回文串的最小成本）。相当于从外侧往内侧推。

接下来就是看切割为不超过 $k$ 个串的最小成本。那么就考虑长度为 $x$ 的前缀分为 $y$ 个部分时的最小成本即可。每次考虑新的一段就好。由于状态数量是 $\mathcal{O}(nk)$ 的，同时枚举新的一段的数量是 $\mathcal{O}(n)$ 的，因此，时间复杂度为 $\mathcal{O}(n^2k)$ 。

由于要输出方案，需要记录当前状态是哪里转移过来的。同时，这里要求的是分割段数不超过 $k$ ，因此需要遍历一下分割为 $1\sim k$ 段的情况。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    s = [ord(c) for c in I()]
    k = II()

    n = len(s)

    change = [[0] * n for _ in range(n)]

    for diff in range(1, n):
        for l in range(n - diff):
            r = l + diff
            change[l][r] = change[l + 1][r - 1] + (s[l] != s[r])

    dp = [[n + 1] * n for _ in range(k)]
    pre = [[-1] * n for _ in range(k)]

    for i in range(n):
        dp[0][i] = change[0][i]

    for i in range(k - 1):
        for j in range(n - 1):
            for nj in range(j + 1, n):
                if dp[i][j] + change[j + 1][nj] < dp[i + 1][nj]:
                    dp[i + 1][nj] = dp[i][j] + change[j + 1][nj]
                    pre[i + 1][nj] = j

    v = n + 1
    chosen = -1

    for i in range(k):
        if dp[i][n - 1] < v:
            v = dp[i][n - 1]
            chosen = i

    ans = []

    cur = n - 1
    for i in range(chosen, -1, -1):
        ncur = pre[i][cur]

        l, r = ncur + 1, cur
        while l < r:
            s[l] = s[r]
            l += 1
            r -= 1

        ans.append(''.join(chr(s[x]) for x in range(ncur + 1, cur + 1)))

        cur = ncur

    ans.reverse()

    print(v)
    print('+'.join(ans))
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    string s;
    int k;

    cin >> s >> k;

    int n = s.size();

    vector<vector<int>> change(n, vector<int>(n, 0));
    for (int diff = 1; diff < n; diff ++) {
        for (int l = 0; l < n - diff; l ++) {
            int r = l + diff;
            change[l][r] = change[l + 1][r - 1] + (s[l] != s[r]);
        }
    }

    vector<vector<int>> dp(k, vector<int>(n, n + 1)), pre(k, vector<int>(n, -1));

    for (int i = 0; i < n; i ++)
        dp[0][i] = change[0][i];

    for (int i = 0; i < k - 1; i ++) {
        for (int j = 0; j < n - 1; j ++) {
            for (int nj = j + 1; nj < n; nj ++) {
                if (dp[i][j] + change[j + 1][nj] < dp[i + 1][nj]) {
                    dp[i + 1][nj] = dp[i][j] + change[j + 1][nj];
                    pre[i + 1][nj] = j;
                }
            }
        }
    }

    int v = n + 1, chosen = -1;
    for (int i = 0; i < k; i ++) {
        if (dp[i][n - 1] < v) {
            v = dp[i][n - 1];
            chosen = i;
        }
    }

    vector<string> ans;
    int cur = n - 1;

    for (int i = chosen; i >= 0; i --) {
        int ncur = pre[i][cur];

        int l = ncur + 1, r = cur;
        while (l < r) {
            s[l] = s[r];
            l ++, r --;
        }

        ans.push_back(s.substr(ncur + 1, cur - ncur));
        cur = ncur;
    }

    reverse(ans.begin(), ans.end());

    cout << v << '\n';
    for (int i = 0; i < ans.size(); i ++) {
        if (i) cout << '+';
        cout << ans[i];
    }

    return 0;
}
