        if (c == 'T') {
            for (int i = 0; i < 2; i ++) {
                for (int x = 0; x <= k; x ++) {
                    for (int y = 0; y <= 2 * n; y ++) {
                        if (dp[i][f(x, y)]) {
                            ndp[i ^ 1][f(x, y)] = 1;
                            if (x < k) {
                                ndp[i][f(x + 1, y + (i ? -1 : 1))] = 1;
                            }
                        }
                    }
                }
            }
        }
        else {
            for (int i = 0; i < 2; i ++) {
                for (int x = 0; x <= k; x ++) {
                    for (int y = 0; y <= 2 * n; y ++) {
                        if (dp[i][f(x, y)]) {
                            ndp[i][f(x, y + (i ? -1 : 1))] = 1;
                            if (x < k) {
                                ndp[i ^ 1][f(x + 1, y)] = 1;
                            }
                        }
                    }
                }
            }
        }
        dp.swap(ndp);
    }

    int ans = 0;
    for (int i = 0; i < 2; i ++) {
        for (int x = 0; x <= k; x ++) {
