    vector<pair<int, int>> pts(n);
    for (auto &[x, y]: pts)
        cin >> x >> y;

    auto area = [&] (int i, int j, int k) -> long long {
        int dx1 = pts[j].first - pts[i].first;
        int dy1 = pts[j].second - pts[i].second;
        int dx2 = pts[k].first - pts[i].first;
        int dy2 = pts[k].second - pts[i].second;
