**提示 1：** 我们只需记录每条边向上走了几次，向下走了几次就很容易计算得到结果了。

**提示 2：** 如何统计呢？

我们要看的是有向边违背原有方向的次数，违背 $x$ 次的成本是 $2^0+2^1+\dots+2^{x-1}=2^x-1$ 。

所以干脆统计每条边按照每个方向走的次数就行。

不妨以 $1$ 为根，我们从 $u$ 走到 $v$ ，就是先从 $u$ 走到 $u,v$ 的 LCA （不了解的可以自行搜索这一步），再从 LCA 走到 $v$ ，因此前一段朝着 $1$ 的方向 $+1$ ，后一段背着 $1$ 的方向 $+1$ 。

这个相当于路径更新（而且是很简单的情况），直接使用树上差分就行。

对于每一段路径执行上述步骤就行，即切分两段，分别对两个方向更新。

时间复杂度主要看你是怎么实现 LCA 的。

### 具体代码如下——

Python 做法如下——（这个似乎过不去）

```Python []
def main():
    n = II()
    us = []
    vs = []
    ts = []

    path = [[] for _ in range(n)]

    for eid in range(n - 1):
        u, v, t = MII()
        u -= 1
        v -= 1

        us.append(u)
        vs.append(v)
        ts.append(t)
        path[u].append(eid)
        path[v].append(eid)

    parent = [-1] * n
    parent_eid = [0] * n
    depth = [0] * n
    que = [0]

    for u in que:
        for eid in path[u]:
            v = us[eid] + vs[eid] - u
            if parent[u] != v:
                parent[v] = u
                parent_eid[v] = eid
                depth[v] = depth[u] + 1
                que.append(v)

    nth_parent = [[-1] * n for _ in range(20)]
    nth_parent[0] = parent

    for i in range(1, 20):
        for u in range(n):
            if nth_parent[i - 1][u] != -1:
                nth_parent[i][u] = nth_parent[i - 1][nth_parent[i - 1][u]]

    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        d = depth[u] - depth[v]
        while d:
            x = d & -d

            bit = x.bit_length() - 1
            u = nth_parent[bit][u]

            d -= x

        if u == v: return u

        for i in range(19, -1, -1):
            if nth_parent[i][u] != nth_parent[i][v]:
                u = nth_parent[i][u]
                v = nth_parent[i][v]

        return nth_parent[0][u]

    ups = [0] * n
    downs = [0] * n

    k = II()
    nodes = LGMI()

    u = 0
    for i in range(k):
        v = nodes[i]

        l = lca(u, v)

        ups[u] += 1
        ups[l] -= 1
        downs[v] += 1
        downs[l] -= 1
        u = v

    for i in reversed(que):
        if i > 0:
            ups[parent[i]] += ups[i]
            downs[parent[i]] += downs[i]

    mod = 10 ** 9 + 7
    pw2 = [1] * (k + 1)

    for i in range(1, k + 1):
        pw2[i] = pw2[i - 1] + pw2[i - 1]
        if pw2[i] >= mod: pw2[i] -= mod

    ans = 0
    for i in range(1, n):
        if ts[parent_eid[i]]:
            if i == us[parent_eid[i]]: ans += pw2[downs[i]] - 1
            else: ans += pw2[ups[i]] - 1
            if ans >= mod: ans -= mod

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector<int> us, vs, ts;
    vector<vector<int>> path(n);

    for (int eid = 0; eid < n - 1; eid ++) {
        int u, v, t;
        cin >> u >> v >> t;

        u --, v --;
        us.emplace_back(u);
        vs.emplace_back(v);
        ts.emplace_back(t);

        path[u].emplace_back(eid);
        path[v].emplace_back(eid);
    }


    vector<vector<int>> nth_parent(20, vector<int>(n, -1));
    vector<int> parent_eid(n), depth(n, 0), order;

    auto dfs = [&] (auto &self, int u, int p) -> void {
        order.emplace_back(u);

        for (auto &eid: path[u]) {
            int v = us[eid] + vs[eid] - u;
            if (v != p) {
                nth_parent[0][v] = u;
                parent_eid[v] = eid;
                depth[v] = depth[u] + 1;
                self(self, v, u);
            }
        }
    };

    dfs(dfs, 0, -1);

    for (int i = 1; i < 20; i ++) {
        for (int u = 0; u < n; u ++) {
            if (nth_parent[i - 1][u] != -1) {
                nth_parent[i][u] = nth_parent[i - 1][nth_parent[i - 1][u]];
            }
        }
    }

    auto lca = [&] (int u, int v) -> int {
        if (depth[u] < depth[v]) swap(u, v);

        int d = depth[u] - depth[v];

        for (int i = 0; i < 20; i ++) {
            if (d >> i & 1) {
                u = nth_parent[i][u];
            }
        }

        if (u == v) return u;

        for (int i = 19; i >= 0; i --) {
            if (nth_parent[i][u] != nth_parent[i][v]) {
                u = nth_parent[i][u];
                v = nth_parent[i][v];
            }
        }

        return nth_parent[0][u];
    };

    vector<int> ups(n, 0), downs(n, 0);

    int mod = 1e9 + 7;

    auto add = [&] (int &x, int y) -> void {
        x += y;
        if (x >= mod) x -= mod;
    };

    int k;
    cin >> k;

    vector<int> pw2(k + 1, 0); pw2[0] = 1;
    for (int i = 1; i <= k; i ++) {
        pw2[i] = pw2[i - 1];
        add(pw2[i], pw2[i - 1]);
    }

    int u = 0;
    while (k --) {
        int v;
        cin >> v;
        v --;

        int l = lca(u, v);
        ups[u] ++;
        ups[l] --;
        downs[v] ++;
        downs[l] --;

        u = v;
    }

    reverse(order.begin(), order.end());
    for (auto &i: order) {
        if (i) {
            ups[nth_parent[0][i]] += ups[i];
            downs[nth_parent[0][i]] += downs[i];
        }
    }

    int ans = 0;
    for (int i = 1; i < n; i ++) {
        if (ts[parent_eid[i]]) {
            add(ans, pw2[(i == us[parent_eid[i]] ? downs[i] : ups[i])] - 1);
        }
    }

    cout << ans;

    return 0;
}
```

**提示 1：** 连接连通块时，一定选择两个连通块内分别下标最小的点。

**提示 2：** 考虑结点 $1$ 。

不妨设某一次连接了边 $(i,j)$ ，那么我们一定可以将其替换为 $i,j$ 分别所在连通块内的下标最小的点，结果一定不劣。

因为编号小的点很 “好”，所以特别考虑结点 $1$ 。

同时，我们有 $S_i+S_j\geq i\times j\times c$ ，而在 $i,j\gt 1$ 的情况下 $i\times j\geq i+j+1\ ((i-1)(j-1)\geq 1)$ ，因此， $S_i+S_j\geq c\times(i+j+1)$ ，所以以下两个式子至少有一个满足：

$S_i\geq c\times i\times 1, S_j\geq c\times j\times 1$

不妨设是第一个满足，则第一条边 $(1,i)$ 连完后， $(1,j)$ 一定可连，因为 $S_i+a_1+S_j\geq i\times j\times c\geq c\times 1\times j$ 。（这里讨论的是 $i,j$ 都不在 $1$ 所在连通块内，如果已经和 $1$ 联通了，这条边本来就应该取 $(1,u)$ ，因为 $1$ 下标更小。）

因此通过上述转化，所有边都可以变为和 $1$ 相连的边。

而按照什么顺序和 $1$ 相连呢？就看上述条件满足的难度，即 $\sum a_k\geq c\times j$ 的情况。也就是除了当前节点之外，其他结点的和需要足够大，考虑的这些限制应当从宽到严，即对其他结点的数值和的要求应该从小到大考虑。

于是按照 $c\times idx-a_{idx}$ 从小到大进行排序，依次连边即可。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    for _ in range(t):
        n, c = MII()
        nums = LII()

        st_range = sorted(range(1, n), key=lambda x: x * c - nums[x])

        cur = nums[0]
        flg = True

        for i in st_range:
            if cur + nums[i] >= c * (i + 1): cur += nums[i]
            else: flg = False

        outs.append('Yes' if flg else 'No')

    print('\n'.join(outs))
```

