**提示 1：** 到达每个点的时候只有一个状态是重要的。

**提示 2：** 把同点的不同状态认为是图论中不同的点。

假设我们要到达的点是 $i$ ，那么我们就要计算的是 $1$ 到 $i$ 和 $n$ 到 $i$ 的最短用时。即从 $1$ 和 $n$ 出发分别跑一次最短路。

到达每个点的状态只有两种：有马 / 无马。其对应于不同的边权。

因此把每个点的不同状态拆开变为图论中不同的点，也就是类似分层图的想法。这样使用 $u$ 表示还没遇到马， $u+n$ 表示已经遇到马了。可以借此把原图进行改编。（不需要真的建新图，跑最短路的时候走到一条边，算对应边权即可）

这样每一步的边权就很好确定了，下一步有无马的状态也很好确定。在这个新图中，边数不超过 $2m$ ，点数为 $2n$ ，因此直接在新图中跑最短路即可。

最后，是否会有马已经被骑走了，所以发生了无马可用的冲突情况呢？答案是否定的，因为如果走到一个点的时候这匹马已经被骑走了，那么两个人都已经到过这个点了。实际上骑走马的人可以退回到这个点，用时更少且满足题意。也就不影响问题求解了。

时间复杂度为 $\mathcal{O}(n+m\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    inf = 10 ** 13

    for _ in range(t):
        n, m, h = MII()
        pos = LGMI()

        horses = [0] * n
        for u in pos:
            horses[u] = 1

        path = [[] for _ in range(n)]

        for _ in range(m):
            u, v, w = MII()
            u -= 1
            v -= 1
            path[u].append(w * n + v)
            path[v].append(w * n + u)

        f = lambda x, y: x * (2 * n) + y

        d1 = [inf] * (2 * n)
        d1[0] = 0
        pq = [f(d1[0], 0)]

        while pq:
            d, u = divmod(heappop(pq), 2 * n)
            if d1[u] == d:
                flg = False
                if u >= n:
                    u -= n
                    flg = True
                elif horses[u]:
                    flg = True

                for msk in path[u]:
                    w, v = divmod(msk, n)
                    if flg:
                        nd = d + w // 2
                        nv = v + n
                    else:
                        nd = d + w
                        nv = v
                    if d1[nv] > nd:
                        d1[nv] = nd
                        heappush(pq, f(nd, nv))

        d2 = [inf] * (2 * n)
        d2[n - 1] = 0
        pq = [f(d2[n - 1], n - 1)]

        while pq:
            d, u = divmod(heappop(pq), 2 * n)
            if d2[u] == d:
                flg = False
                if u >= n:
                    u -= n
                    flg = True
                elif horses[u]:
                    flg = True

                for msk in path[u]:
                    w, v = divmod(msk, n)
                    if flg:
                        nd = d + w // 2
                        nv = v + n
                    else:
                        nd = d + w
                        nv = v
                    if d2[nv] > nd:
                        d2[nv] = nd
                        heappush(pq, f(nd, nv))

        ans = inf
        for i in range(n):
            ans = fmin(ans, fmax(fmin(d1[i], d1[i + n]), fmin(d2[i], d2[i + n])))

        outs.append(ans if ans < inf else -1)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int t;
    cin >> t;
    long long inf = 1e13;

    while (t --) {
        int n, m, h;
        cin >> n >> m >> h;

        vector<bool> horses(n, 0);
        while (h --) {
            int p;
            cin >> p;
            horses[p - 1] = 1;
        }

        vector<vector<pair<int, int>>> path(n);
        while (m --) {
            int u, v, w;
            cin >> u >> v >> w;
            u --, v --;
            path[u].emplace_back(v, w);
            path[v].emplace_back(u, w);
        }

        vector<long long> d1(2 * n, inf);
        d1[0] = 0;

        priority_queue<pair<long long, int>> pq;
        pq.push({0, 0});

        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            d = -d;
            if (d1[u] == d) {
                bool flg = false;
                if (u >= n) {
                    u -= n;
                    flg = true;
                }
                else if (horses[u])
                    flg = true;

                for (auto &[v, w]: path[u]) {
                    int nv;
                    long long nd;
                    if (flg) {
                        nv = v + n;
                        nd = d + w / 2;
                    }
                    else {
                        nv = v;
                        nd = d + w;
                    }
                    if (nd < d1[nv]) {
                        d1[nv] = nd;
                        pq.push({-nd, nv});
                    }
                }
            }
        }

        vector<long long> d2(2 * n, inf);
        d2[n - 1] = 0;

        pq.push({0, n - 1});

        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            d = -d;
            if (d2[u] == d) {
                bool flg = false;
                if (u >= n) {
                    u -= n;
                    flg = true;
                }
                else if (horses[u])
                    flg = true;

                for (auto &[v, w]: path[u]) {
                    int nv;
                    long long nd;
                    if (flg) {
                        nv = v + n;
                        nd = d + w / 2;
                    }
                    else {
                        nv = v;
                        nd = d + w;
                    }
                    if (nd < d2[nv]) {
                        d2[nv] = nd;
                        pq.push({-nd, nv});
                    }
                }
            }
        }

        long long ans = inf;
        for (int i = 0; i < n; i ++)
            ans = min(ans, max(min(d1[i], d1[i + n]), min(d2[i], d2[i + n])));
        cout << (ans < inf ? ans : -1) << '\n';
    }

    return 0;
}
