```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    string s;
    cin >> s;

    vector<int> cnt1(10, 0);
    for (auto &c: s) cnt1[c - '0'] ++;
    vector<int> cnt2 = cnt1;

    int val = min(cnt1[0], cnt2[0]), chosen = -1;

    for (int i = 1; i < 10; i ++) {
