            int cur = 1;
            for (int x = 0; x < 10; x ++)
                cur += min(cnt1[x], cnt2[9 - x]);
            cur += min(cnt1[0] - min(cnt1[0], cnt2[9]), cnt2[0] - min(cnt2[0], cnt1[9]));
            if (cur > val) val = cur, chosen = i;

            cnt1[i] ++, cnt2[10 - i] ++;
        }
    }

