**提示 1：** 最小操作次数是什么？

**提示 2：** 字典序——从头到尾的贪心。怎么可以在贪心的过程中保证不改变操作次数。

首先，我们先统计每个字符在其实字符串和最终字符串中的出现次数，其中重合的部分不需要操作，剩余的都需要操作。

接下来，比较朴素的做法是，直接枚举每一个位置是否改变，变为什么字符，再看后面部分需要操作几次，取其中操作次数最小的，以及满足操作次数最小性时，字符最小的数值。

也可以有更优的做法。当前字符可能修改，当且仅当这一类字符 “还有多的”。

替换的逻辑：

- 找到了一个字符比当前字符更小，且目标字符串中这个字符是需要被改出来的。

- 当前对应的字符是不得不改的，即如果不改的话，当前字符最后一定会多出来。此时修改目标字符串中 “需要被改出来的” 中最小的字符。

时间复杂度为 $\mathcal{O}(n|\Sigma|)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    fin = open('input.txt', 'r')
    input = lambda: fin.readline().strip()

    fout = open('output.txt', 'w')
    print = lambda x: fout.write(x + '\n')

    s1 = [ord(c) - ord('A') for c in I()]
    s2 = [ord(c) - ord('A') for c in I()]

    cnt1 = [0] * 26
    for c in s1:
        cnt1[c] += 1

    cnt2 = [0] * 26
    for c in s2:
        cnt2[c] += 1

    n = len(s1)
    ans = 0

    v1 = [0] * 26
    v2 = [0] * 26

    for i in range(26):
        v = abs(cnt1[i] - cnt2[i])
        if cnt1[i] > cnt2[i]: v1[i] = v
        else: v2[i] = v
        ans += v

    for i in range(n):
        cnt1[s1[i]] -= 1

        if v1[s1[i]]:
            for j in range(26):
                if j >= s1[i] and cnt1[s1[i]] >= v1[s1[i]]: break
                if v2[j]:
                    v1[s1[i]] -= 1
                    v2[j] -= 1
                    s1[i] = j
                    break

    print(str(ans // 2))
    print(''.join(chr(ord('A') + c) for c in s1))
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    ifstream fin("input.txt");
    ofstream fout("output.txt");

    string s1, s2;
    fin >> s1 >> s2;

    vector<int> cnt1(26, 0), cnt2(26, 0);
    for (auto &c: s1) cnt1[c - 'A'] ++;
    for (auto &c: s2) cnt2[c - 'A'] ++;

    int n = s1.size(), ans = 0;
    vector<int> v1(26, 0), v2(26, 0);
    for (int i = 0; i < 26; i ++) {
        int v = abs(cnt1[i] - cnt2[i]);
        if (cnt1[i] > cnt2[i]) v1[i] = v;
        else v2[i] = v;
        ans += v;
    }

    for (int i = 0; i < n; i ++) {
        cnt1[s1[i] - 'A'] --;

        if (v1[s1[i] - 'A']) {
            for (int j = 0; j < 26; j ++) {
                if (j >= s1[i] - 'A' && cnt1[s1[i] - 'A'] >= v1[s1[i] - 'A']) break;
                if (v2[j]) {
                    v1[s1[i] - 'A'] --;
                    v2[j] --;
                    s1[i] = 'A' + j;
                    break;
                }
            }
        }
    }

    fout << ans / 2 << '\n';
    fout << s1;

    return 0;
}
```

**提示 1：** 一定操作的是叶子——不然中间就出现个 $0$ 断掉了。

**提示 2：** 挑选哪个叶子呢？

首先，操作的一定是叶子，否则中间就会出现 $0$ ，而之后再也无法跨过中间的结点。

选哪个结点操作呢？选择当前值最小的叶子结点。因为这个结点操作不会影响到其他结点。它是最容易满足要求的结点，同时也会使得其他结点的任务更容易满足。（可以想下为啥）

于是，用一个堆维护当前操作结束后的 $(叶子结点数值, 叶子节点编号)$ 对，每次取出值最小的叶子节点进行操作即可。操作后，根据被操作的结点是否度数变为 $1$ 判断它是否变为了叶子节点。

最终的判断只需看是否满足，只需看上述操作能否进行 $n-1$ 次。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    path = [[] for _ in range(n)]

    degs = [0] * n

    for _ in range(n - 1):
        u, v = GMI()
        path[u].append(v)
        path[v].append(u)
        degs[u] += 1
        degs[v] += 1

    val = [1] * n

    pq = [val[i] * n + i for i in range(n) if degs[i] == 1]
    cnt = 0

    for _ in range(n - 1):
        x, u = divmod(heappop(pq), n)
        cnt += 1
        for v in path[u]:
            if val[v]:
                if val[v] >= val[u]:
                    val[v] += val[u]
                    val[u] = 0
                    degs[v] -= 1

                    if degs[v] == 1:
                        heappush(pq, val[v] * n + v)
                else:
                    exit(print('NO'))

    print('YES')
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector<vector<int>> path(n);
    vector<int> degs(n, 0);

    for (int i = 0; i < n - 1; i ++) {
        int u, v;
        cin >> u >> v;
        u --, v --;
        path[u].emplace_back(v);
        path[v].emplace_back(u);
        degs[u] ++, degs[v] ++;
    }

    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
    vector<int> val(n, 1);

    for (int i = 0; i < n; i ++) {
        if (degs[i] == 1) {
            pq.push({1, i});
        }
    }

    for (int i = 0; i < n - 1; i ++) {
        auto [d, u] = pq.top(); pq.pop();

        for (auto &v: path[u]) {
            if (val[v]) {
                if (val[v] < val[u]) return cout << "NO", 0;
                val[v] += val[u];
                val[u] = 0;

                degs[v] --;
                if (degs[v] == 1) pq.push({val[v], v});
            }
        }
    }
    cout << "YES";

    return 0;
}
```

**提示 1：** 本题查询的是子树中 DFS 序在第 $k$ 个的元素。

**提示 2：** 其实子树的 DFS 序跟原树 DFS 序有关系。

这题要我们求的某个点 $u$ 对应的子树的 DFS 序的第 $k$ 个元素。

而一棵树的 DFS 序也就是 根节点 + 各个子树的 DFS 序。所以，我们只需预处理整棵树的 DFS 序，一棵子树的 DFS 序就对应于其中一个子数组。

而查询的时候，只需找到该子树根节点的位置，再往后走 $k-1$ 步即可。注意可能走出子树（就是说子树大小并不够大），此时 $k$ 超过了子树的大小，判断一下就行。

时间复杂度为 $\mathcal{O}(n+q)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, q = MII()
    parent = [-1] + LGMI()

    path = [[] for _ in range(n)]

    for i in range(1, n):
        path[parent[i]].append(i)

    for i in range(n):
        path[i].reverse()

    stk = [0]
    order = []
    pos = [-1] * n

    while stk:
        u = stk.pop()
        pos[u] = len(order)
        order.append(u)

        for v in path[u]:
            stk.append(v)

    sz = [1] * n
    for u in reversed(order):
        if u: sz[parent[u]] += sz[u]

    outs = []
    for _ in range(q):
        u, k = GMI()
        outs.append(order[pos[u] + k] + 1 if k < sz[u] else -1)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, q;
    cin >> n >> q;

    vector<int> parent(n, -1);
    for (int i = 1; i < n; i ++) {
        cin >> parent[i];
        parent[i] --;
    }

    vector<vector<int>> path(n);
    for (int i = 1; i < n; i ++)
        path[parent[i]].push_back(i);

    vector<int> order, pos(n, -1), sz(n, 1);

    auto dfs = [&] (auto &self, int u) -> void {
        pos[u] = order.size();
        order.emplace_back(u);
        for (auto &v: path[u]) {
            self(self, v);
            sz[u] += sz[v];
        }
    };

    dfs(dfs, 0);

    while (q --) {
        int u, k;
        cin >> u >> k;
        u --;
        cout << (k <= sz[u] ? order[pos[u] + k - 1] + 1 : -1) << '\n';
    }

    return 0;
}
```

**提示 1：** 题目给的这个 $n/3$ 让人想把整个数组分为三段进行构造。

**提示 2：** 假设分为了从小到大的 $3$ 个部分，应该怎么分配给两个数组呢？因此每一个部分的元素数量如何？

挺有意思的构造题！

首先，根据题目提示，应该把数组分为大小基本相等的三组。而这三组不应该随便分，应该排序后，从小到大分为三块（这样看起来组间差距会更明确）。

而这样操作后，应该选取两块，使得第一个数组在这两块中的数值完全不同；第二个数组情况也类似。

两个数组各有一块没选，不妨让丢掉的两块越长越好，就取题中所给的 $\lceil n/3\rceil$ 。

因为第三个数组相对来说数值更大，分配空间更大，因此我们让第三块作为公用的块。

而关键在于第三个数组，需要拆成两个数组，使得元素两两不相同，且可以避开前面的数。

怎么办呢？第三个数组排序后递增，我们只需其拆分为一个递减序列，一个递增序列，就一定满足元素两两不同了。而只要递减序列数值足够小，剩余的递增元素数值也就足够大，两个都很容易避开。

所以，取递减的序列为 $[\dots,2,1,0]$ ，递增序列即得。

而第一个数组不太能拆出来东西（因为数值较小），所以跟递增序列配对。递增序列数值较大，所以只需第一个数组拆出来 $[0,1,2,\dots]$ 的部分就行。

而第二个数组需要避开过小的数，因为需要跟前面的递减序列配对。因此直接从递减序列的起点起步开始递增即可。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    nums = LII()

    order = sorted(range(n), key=lambda x: nums[x])

    k1 = (n + 2) // 3
    k2 = k1 * 2

    ans1 = [0] * n
    ans2 = [0] * n

    for i in range(k1):
        ans1[order[i]] = i
        ans2[order[i]] = nums[order[i]] - ans1[order[i]]

    for i in range(k1, k2):
        ans2[order[i]] = i
        ans1[order[i]] = nums[order[i]] - ans2[order[i]]

    for i in range(k2, n):
        ans2[order[i]] = n - 1 - i
        ans1[order[i]] = nums[order[i]] - ans2[order[i]]

    print('YES')
    print(' '.join(map(str, ans1)))
    print(' '.join(map(str, ans2)))
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector<int> nums(n);
    for (auto &v: nums) cin >> v;

    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&] (int i, int j) {return nums[i] < nums[j];});

    int k1 = (n + 2) / 3, k2 = k1 * 2;
    vector<int> ans1(n), ans2(n);

    for (int i = 0; i < k1; i ++) {
        int u = order[i];
        ans1[u] = i;
        ans2[u] = nums[u] - ans1[u];
    }

    for (int i = k1; i < k2; i ++) {
        int u = order[i];
        ans2[u] = i;
        ans1[u] = nums[u] - ans2[u];
    }

    for (int i = k2; i < n; i ++) {
        int u = order[i];
        ans2[u] = n - 1 - i;
        ans1[u] = nums[u] - ans2[u];
    }

    cout << "YES\n";
    for (auto &v: ans1) cout << v << ' '; cout << '\n';
    for (auto &v: ans2) cout << v << ' '; cout << '\n';

    return 0;
}
```

**提示 1：** 可以先猜猜答案。

**提示 2：** 尝试构造。

事实上，这题能找到构造当且仅当 $r=b$ 。

首先，必要性很明显，因为你需要一一配对。

关于充分性，我们需要完成构造。这里有个神奇的构造方法。

我们找到所有的配对方案中，线段长度和最小的一种构造。

则此时，线段一定两两不相交，因为如果 $A_1B_1,A_2B_2$ 相交了，换成 $A_1B_2,A_2B_1$ 一定不相交且更优（相当于四边形两条对角线长度之和大于一组对边长度之和，可以使用三角形两边之和大于第三边解决）。

所以线段和长度最小的一组，一定满足线段两两不交，即完成构造。

时间复杂度为 $\mathcal{O}(1)$ 。

本题也可以尝试枚举每一组匹配，看线段是否相交，不过好像复杂度达到了 $1.5\times 10^8$ 以上。

