**提示 1：** 相当于每一行提供了一些大小关系的信息，这件事常用于拓扑排序以用来寻找最终的序列。

**提示 2：** 怎么让这个拓扑排序的图边数足够小？

本题实际上是给出了一些元素的大小关系，然后让最终的排列满足这些大小关系。

一种朴素的做法是，对于每一行，选取所有有数值的位置，最后将所有不相等的位置之间进行建边。从小数指向大数，这样的做法是 $\mathcal{O}(nm^2)$ 的，因为建立的边可能很多。

接下来考虑减小边的数量。

首先，如果能找到 $a\to b,b\to c$ ，则 $a\to c$ 是没必要连的边。所以只需在相邻的数值之间进行连边即可。

但如果有一堆 $x$ 一堆 $y$ ，目前的连边方法会将每个 $x$ 和每个 $y$ 之间都进行连边。这会导致边数过多。怎么办呢？

考虑建立一个虚拟节点 $v$ ，将所有 $x$ 连向 $v$ 再由 $v$ 连向 $y$ 。这样，新增的节点数在每一行而言是 $\mathcal{O}(m)$ 的，同时，边数与元素个数是同量级的，满足要求。

时间复杂度为 $\mathcal{O}(nm\log m)$ 。因为每一行至少需要排序一次。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m = MII()
    grid = [LII() for _ in range(n)]

    path = [[] for _ in range(m + n * m)]
    indeg = [0] * (m + n * m)
    pt = m

    for i in range(n):
        idxs = [j for j in range(m) if grid[i][j] != -1]
        idxs.sort(key=lambda x: grid[i][x])

        l, r = 0, 0
        last_node = -1

        for j in range(1, len(idxs)):
            if grid[i][idxs[j]] == grid[i][idxs[j - 1]]:
                r = j
            else:
                if last_node != -1:
                    for idx in range(l, r + 1):
                        path[last_node].append(idxs[idx])
                        indeg[idxs[idx]] += 1

                for idx in range(l, r + 1):
                    path[idxs[idx]].append(pt)
                    indeg[pt] += 1

                last_node = pt
                pt += 1
                l = r = j

        if last_node!= -1:
            for idx in range(l, r + 1):
                path[last_node].append(idxs[idx])
                indeg[idxs[idx]] += 1

    stk = [i for i in range(m + n * m) if indeg[i] == 0]
    ans = []

    while stk:
        u = stk.pop()
        if u < m:
            ans.append(u)
        for v in path[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                stk.append(v)

    if len(ans) == m: print(' '.join(str(x + 1) for x in ans))
    else: print(-1)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, m;
    cin >> n >> m;

    vector<vector<int>> grid(n, vector<int>(m));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> grid[i][j];
        }
    }

    vector<vector<int>> path(m + n * m);
    vector<int> indeg(m + n * m, 0);

    int pt = m;

    for (int i = 0; i < n; i ++) {
        vector<int> idxs;
        for (int j = 0; j < m; j ++) {
            if (grid[i][j] != -1) {
                idxs.push_back(j);
            }
        }
        sort(idxs.begin(), idxs.end(), [&](int x, int y) {return grid[i][x] < grid[i][y];});

        int l = 0, r = 0, last_node = -1;
        for (int j = 1; j < idxs.size(); j ++) {
            if (grid[i][idxs[j]] == grid[i][idxs[j - 1]])
                r = j;
            else {
                if (last_node != -1) {
                    for (int k = l; k <= r; k ++) {
                        path[last_node].push_back(idxs[k]);
                        indeg[idxs[k]] ++;
                    }
                }

                for (int k = l; k <= r; k ++) {
                    path[idxs[k]].emplace_back(pt);
                    indeg[pt] ++;
                }

                last_node = pt;
                pt ++;
                l = j, r = j;
            }
        }

        if (last_node != -1) {
            for (int k = l; k <= r; k ++) {
                path[last_node].push_back(idxs[k]);
                indeg[idxs[k]] ++;
            }
        }
    }

    vector<int> ans;
    vector<int> stk;

    for (int i = 0; i < m + n; i ++) {
        if (indeg[i] == 0) {
            stk.emplace_back(i);
        }
    }

    while (!stk.empty()) {
        int u = stk.back();
        stk.pop_back();

        if (u < m) ans.emplace_back(u);
        for (auto &v: path[u]) {
            indeg[v] --;
            if (indeg[v] == 0) {
                stk.emplace_back(v);
            }
        }
    }

    if (ans.size() == m)
        for (auto &x: ans) cout << x + 1 << ' ';
    else cout << -1;

    return 0;
}
```

**提示 1：** 三角形一定有两个顶点是已经给定的。

**提示 2：** 考虑给定两个顶点，如何找到最大的面积。

因为我们最多只能将一个顶点染色，所以三角形中一定有两个顶点是没有染色的。

所以，如果有两个顶点是 $(x_1,y_1)$ 和 $(x_2,y_2)$ ，怎么才能构造出面积最大的三角形呢。

假设平行于横轴或纵轴的边是经过 $(x_1,y_1)$ 的，则最优选择一定是最上 / 下 / 左 / 右的位置。因此，可以列出这四种情况的具体长度。

而此时 $(x_2,y_2)$ 的位置是不重要的。我们只需找到距离所作直线最远的点即可。因此一定找的是横坐标最大 / 最小 / 纵坐标最大 / 最小的点。

于是只需维护每个数字出现的最大 / 最小的横 / 纵坐标即可。

时间复杂度为 $\mathcal{O}(n^2)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    for _ in range(t):
        n = II()
        grid = [[int(x) for x in I()] for _ in range(n)]

        min_x = [n + 1] * 10
        min_y = [n + 1] * 10
        max_x = [-1] * 10
        max_y = [-1] * 10

        for i in range(n):
            for j in range(n):
                min_x[grid[i][j]] = fmin(min_x[grid[i][j]], i)
                min_y[grid[i][j]] = fmin(min_y[grid[i][j]], j)
                max_x[grid[i][j]] = fmax(max_x[grid[i][j]], i)
                max_y[grid[i][j]] = fmax(max_y[grid[i][j]], j)

        ans = [0] * 10

        for i in range(n):
            for j in range(n):
                ans[grid[i][j]] = fmax(ans[grid[i][j]], fmax(i, n - 1 - i) * fmax(max_y[grid[i][j]] - j, j - min_y[grid[i][j]]))
                ans[grid[i][j]] = fmax(ans[grid[i][j]], fmax(j, n - 1 - j) * fmax(max_x[grid[i][j]] - i, i - min_x[grid[i][j]]))

        outs.append(ans)

    print('\n'.join(' '.join(map(str, out)) for out in outs))
