    res[4] = max(res[4], b[1] - a[0]);
    res[4] = max(res[4], a[3] - b[2]);
    return res;
}

node e() {
    return {inf, -inf, inf, -inf, 0};
}

node e1(int idx, int val) {
    return {val - idx, val - idx, val + idx, val + idx, 0};
}

