**提示 2：** 分别维护即可。

表面上，这题给每个元素分配的权重有很多种可能。

但实际上，在固定 $k$ 的情况下，我们只需要考虑 $2k-2$ 种可能的权重分配。因为权值是个循环数组，数组的长度是 $2k-2$ ，只需枚举第一项所在的权值位置，即可确定剩余所有元素的权值位置。

所以我们枚举这样的 $k(2k-2)=\mathcal{O}(k^2)$ 种情况，使用树状数组更新，在考虑到对应情况下的查询即可。

时间复杂度为 $\mathcal{O}(nk^2\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    nums = LII()

    q = II()
    ts = []
    xs = []
    ys = []
    zs = []

    for _ in range(q):
        query = LII()
        if query[0] == 1:
            ts.append(0)
            xs.append(query[1] - 1)
            ys.append(query[2])
            zs.append(0)
        else:
            ts.append(1)
            xs.append(query[1] - 1)
            ys.append(query[2] - 1)
            zs.append(query[3])

    fen = FenwickTree(n)
    tmp = [0] * n

    ans = [-1] * q

    for i in range(2, 7):
        weight = [0] * (2 * i - 2)
        for j in range(i - 1):
            weight[j] = j + 1
        for j in range(i - 1, 2 * i - 2):
            weight[j] = 2 * i - j - 1
        l = 2 * i - 2

        for start in range(l):
            for j in range(n):
                tmp[j] = nums[j] * weight[(j - start) % l]
            fen.init(tmp)

            for j in range(q):
                if ts[j] == 0:
                    fen.add(xs[j], ys[j] * weight[(xs[j] - start) % l] - tmp[xs[j]])
                    tmp[xs[j]] = ys[j] * weight[(xs[j] - start) % l]
                elif xs[j] % l == start and zs[j] == i:
                    ans[j] = fen.rsum(xs[j], ys[j])

    print('\n'.join(str(x) for x in ans if x != -1))
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector<int> nums(n);
    for (auto &v: nums) cin >> v;

    int q;
    cin >> q;

    vector<array<int, 4>> queries(q);
    for (int i = 0; i < q; i ++) {
        int t;
        cin >> t;
        if (t == 1) {
            int k, u;
            cin >> k >> u;
            queries[i] = {1, k - 1, u, 0}; 
        }
        else {
            int l, r, k;
            cin >> l >> r >> k;
            queries[i] = {2, l - 1, r - 1, k};
        }
    }

    atcoder::fenwick_tree<long long> fen(n);
    vector<long long> tmp(n);

    vector<long long> ans(q, -1);
    for (int i = 2; i <= 6; i ++) {
        vector<int> weight(2 * i - 2);
        for (int j = 0; j < i - 1; j ++)
            weight[j] = j + 1;
        for (int j = i - 1; j < 2 * i - 2; j ++)
            weight[j] = 2 * i - 1 - j;
        int l = 2 * i - 2;

        for (int start = 0; start < l; start ++) {
            for (int j = 0; j < n; j ++)
                tmp[j] = 1ll * nums[j] * weight[(j - start + l) % l];
            fen.init(tmp);
            for (int j = 0; j < q; j ++) {
                auto &q = queries[j];
                if (q[0] == 1) {
                    int k = q[1], u = q[2];
                    fen.add(k, 1ll * u * weight[(k - start + l) % l] - tmp[k]);
                    tmp[k] = 1ll * u * weight[(k - start + l) % l];
                }
                else if (q[1] % l == start && q[3] == i) {
                    ans[j] = fen.sum(q[1], q[2] + 1);
                }
            }
        }
    }

    for (auto &x: ans)
        if (x != -1) cout << x << '\n';

    return 0;
}
