        for (int i = 1; i < n; i ++) {
            total += grid[i][0] - (grid[0][0] - v);
            rows.emplace_back(i + 1, grid[i][0] - (grid[0][0] - v));
        }

        for (int i = 1; i < m; i ++) {
            total += grid[0][i] - v;
            cols.emplace_back(i + 1, grid[0][i] - v);
