**提示 1：** 固定 $h$ ，考虑 $w$ 怎么分配。

这里面积涉及到两个维度，这种情况下，常见的思路是固定一个维度考虑另一个。

固定哪个呢？宽度是一堆东西的和，高度是一堆东西的最大值。分别处理的是控制和的情况下要最小化高度 / 控制最大高度的时候最小化和。

后者是更容易处理的，因为我们最大高度小于等于某个数，只需满足每个高度都不超过这个数就行，这个条件就很容易了！

于是考虑枚举高度。此时有一些人是不得不卧倒的，这些人先让他们卧倒。如果人数已经超出限制，则直接不考虑该高度。否则，接下来要在剩余的人中选择一部分卧倒。这部分卧倒的人首先应该使得卧倒后宽度更小，同时应该选择变动更大的一些人。

因此，可以根据 $w-h$ 进行降序排序，一定是选取开头的几个正的。

这个排序不根据我们选取的 $h$ 变动，可以预处理。

综上——先根据 $w-h$ 排序，接下来枚举最终高度，先处理不得不卧倒的人，再考虑剩余没取的人中 $w-h$ 最大，且 $w-h\gt 0$ 的那些人卧倒，即可得到当前高度的最小面积。

时间复杂度为 $\mathcal{O}(n\log n+nM)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    ws = []
    hs = []

    for _ in range(n):
        w, h = MII()
        ws.append(w)
        hs.append(h)

    st_range = sorted(range(n), key=lambda x: hs[x] - ws[x])

    ans = 10 ** 9 * 2
    used = [0] * n

    cur = sum(ws)

    for h in range(1, 1001):
        flg = True
        cnt = 0
        cur_w = cur

        for i in st_range:
            if hs[i] > h:
                if ws[i] > h:
                    flg = False
                    break
                else:
                    used[i] = 1
                    cnt += 1
                    cur_w += hs[i] - ws[i]
            else:
                used[i] = 0

        if cnt * 2 > n or not flg: continue

        for i in st_range:
            if not used[i] and cnt < n // 2 and ws[i] <= h and hs[i] - ws[i] < 0:
                cnt += 1
                cur_w += hs[i] - ws[i]

        ans = fmin(ans, cur_w * h)

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, cur = 0;
    cin >> n;

    vector<int> ws(n), hs(n);
    for (int i = 0; i < n; i ++)    
        cin >> ws[i] >> hs[i], cur += ws[i];

    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&] (int i, int j) {return hs[i] - ws[i] < hs[j] - ws[j];});

    int ans = 2e9;
    vector<bool> used(n, 0);

    for (int h = 1; h <= 1000; h ++) {
        bool flg = true;
        int cnt = 0, cur_w = cur;

        for (auto &i: order) {
            if (hs[i] > h) {
                if (ws[i] > h) {
                    flg = false;
                    break;
                }
                else {
                    used[i] = 1;
                    cnt ++;
                    cur_w += hs[i] - ws[i];
                }
            }
            else used[i] = 0;
        }

        if (cnt * 2 > n || !flg) continue;

        for (auto &i: order) {
            if (!used[i] && cnt < n / 2 && ws[i] <= h && hs[i] - ws[i] < 0) {
                cnt ++;
                cur_w += hs[i] - ws[i];
            }
        }

        ans = min(ans, cur_w * h);
    }

    cout << ans;

    return 0;
}
```

**提示 1：** 是不是没啥可说的，就是你的实现要过关噢！

一些实现上需要注意的东西。

- 每一个转折的位置怎么算？就使用交错的前缀和。

- 出现负数了怎么办？集体减去最小值。这样就可以确定第一个字符在第几行了。

- 先放好一个矩阵再在矩阵里面填字符，注意每次的字符跟前面的得接起来——要么斜着走，要么横着走。

时间复杂度为 $\mathcal{O}(n\max |\sum (-1)^i a_i|)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    nums = [0] + LII()
    total = sum(nums)

    for i in range(1, n + 1):
        if i % 2: nums[i] = nums[i - 1] - nums[i]
        else: nums[i] = nums[i - 1] + nums[i]

    mi = min(nums)
    ma = max(nums)

    for i in range(n + 1):
        nums[i] -= mi

    ans = [[' '] * total for _ in range(ma - mi)]

    cur = 0
    for i in range(n):
        l, r = nums[i], nums[i + 1]
        if l < r:
            for j in range(nums[i + 1] - nums[i]):
                ans[nums[i] + j][cur + j] = '\\'
            cur += r - l
        else:
            for j in range(nums[i] - nums[i + 1]):
                ans[nums[i] - 1 - j][cur + j] = '/'
            cur += l - r

    print('\n'.join(''.join(x) for x in ans))
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector<int> nums(n + 1);

    int total = 0;

    for (int i = 1; i <= n; i ++) {
        cin >> nums[i];
        total += nums[i];
    }

    for (int i = 1; i <= n; i ++)
        nums[i] = (i & 1 ? nums[i - 1] - nums[i] : nums[i - 1] + nums[i]);

    int mi = *min_element(nums.begin(), nums.end());
    int ma = *max_element(nums.begin(), nums.end());

    for (int i = 0; i <= n; i ++)
        nums[i] -= mi;

    vector<string> ans(ma - mi, string(total, ' '));

    int cur = 0;
    for (int i = 0; i < n; i ++) {
        int l = nums[i], r = nums[i + 1];
        if (l < r) {
            for (int j = 0; j < nums[i + 1] - nums[i]; j ++)
                ans[nums[i] + j][cur + j] = '\\';
            cur += r - l;
        }
        else {
            for (int j = 0; j < nums[i] - nums[i + 1]; j ++)
                ans[nums[i] - 1 - j][cur + j] = '/';
            cur += l - r;
        }
    }

    for (auto &x: ans) cout << x << '\n';

    return 0;
}
```

**提示 1：** 一个连通块内应该和为 $0$ 。

**提示 2：** 满足这个条件的情况下一定能构造吗？能否加强一下问题？

首先，能构造的情况下，连通块内和为 $0$ ，因为考虑每条边，对边上两点的权值总贡献是 $0$ 。

和为 $0$ 的情况下一定能构造吗？这里是个连通图。

连通图最 “不连通” 的情况就是一棵树，如果一棵树能够满足要求，那么任意一个图，我们取一个生成树进行构造也就可以满足要求。

因此，树的情况作为特殊情况，是不得不解决的（解决的必要性）；同时可以推导出其他的连通图情况（解决的充分性）。因此和原命题是等价的。

树怎么处理呢？考虑每条边上的流如何确定就行。假设某个点对应的子树和是 $x$ ，则需要从子树向父结点流出 $x$ 。（有点像昨天的第一题！）

而这么处理后一定满足要求——考虑每个点在上述构造下的权值，相当于是该结点的子树总权值，减去其子结点对应子树的总权值。

时间复杂度为 $\mathcal{O}(n+m)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    nums = LII()

    m = II()

    us = []
    vs = []

    path = [[] for _ in range(n)]
    dsu = UnionFind(n)

    for i in range(m):
        u, v = GMI()
        us.append(u)
        vs.append(v)

        if dsu.merge(u, v):
            path[u].append(i)
            path[v].append(i)

    parent = [-2] * n
    ans = [0] * m

    for i in range(n):
        if parent[i] == -2:
            parent[i] = -1

            que = [i]
            for u in que:
                for eid in path[u]:
                    v = us[eid] + vs[eid] - u
                    if parent[u] != v:
                        parent[v] = u
                        que.append(v)

            for j in range(len(que) - 1, 0, -1):
                u = que[j]
                p = parent[u]
                nums[p] += nums[u]

                for eid in path[u]:
                    v = us[eid] + vs[eid] - u
                    if v == p:
                        if us[eid] == u: ans[eid] = -nums[u]
                        else: ans[eid] = nums[u]

            if nums[i]:
                exit(print('Impossible'))

    print('Possible')
    print(*ans, sep='\n')
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector<int> nums(n);
    for (auto &x: nums) cin >> x;

    atcoder::dsu uf(n);
    vector<vector<pair<int, int>>> path(n);

    int m;
    cin >> m;

    for (int i = 0; i < m; i ++) {
        int u, v;
        cin >> u >> v;
        u --, v --;

        if (uf.merge(u, v)) {
            path[u].emplace_back(v, i);
            path[v].emplace_back(u, ~i);
        }
    }

    vector<bool> vis(n, 0);
    vector<int> ans(m, 0); 

    auto dfs = [&] (auto &self, int u, int p) -> void {
        vis[u] = 1;
        for (auto &[v, eid]: path[u]) {
            if (v != p) {
                self(self, v, u);
                if (eid >= 0) ans[eid] = nums[v];
                else ans[~eid] = -nums[v];
                nums[u] += nums[v];
            }
        }
    };

    for (int i = 0; i < n; i ++) {
        if (!vis[i]) {
            dfs(dfs, i, -1);
            if (nums[i]) return cout << "Impossible\n", 0;
        }
    }

    cout << "Possible\n";
    for (auto &x: ans) cout << x << '\n';

    return 0;
}
```

**提示 1：** 考虑每两个间隔之间至少要移动多少次。

**提示 2：** 上述确定的最小值能达到吗？

考虑每个间隔至少要有多少个东西跨过去。

前 $i$ 个位置和后面的位置之间的空当，需要多少次移动呢？

前面 $i$ 个位置原有 $x$ 样东西，最终状态要有 $y$ 样东西，则至少需要移动 $|x-y|$ 次。（因为每次移动最多改变 $1$ ）

对于所有的间隔位置将上述结果求和，就可以得到答案。

这件事一定能做到吗？答案是肯定的。每次只需找到 $x\neq y$ 的位置，在对应的位置进行一次移动就好啦！

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    nums = LII()

    val = sum(nums) // n

    ans = 0
    cur = 0

    for x in nums:
        cur += x - val
        ans += abs(cur)

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector<int> nums(n);
    long long sum = 0;

    for (auto &x: nums)
        cin >> x, sum += x;

    int val = sum / n;

    long long cur = 0, ans = 0;

    for (auto &x: nums)
        cur += x - val, ans += abs(cur);

    cout << ans;

    return 0;
}
```

**提示 1：** 其实一个点的数值确定，和他相邻的点就确定了。

**提示 2：** 一个点的初始选择如何呢？

首先，提示 1，为什么呢？

一个经典的恒等式！ $\mathrm{gcd}(x,y)\times\mathrm{lcm}(x,y)=xy$

所以，只需知道 $x$ ，以及 $\mathrm{gcd}(x,y),\mathrm{lcm}(x,y)$ ，就可以知道 $y$ 了。一个连通块内只需要一个点确定了，其他数值也就都确定了！

而确定完后，该连通块内各个最大公约数、最小公倍数的条件也就能检查一遍了。

于是考虑枚举连通块内其中一个点的数值。怎么枚举呢？

- 如果没有边，直接赋值 $1$ 。

- 如果有边，取一条边，该点的数值一定是最小公倍数的因子。因子个数并不会特别多。

时间复杂度为 $\mathcal{O}(md(M)\log M)$ ，其中 $d(M)$ 表示不超过 $M$ 的数中因子最多的数的因子个数。当然这个并跑不满。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m = MII()

    us = [0] * m
    vs = [0] * m
    gcds = [0] * m
    lcms = [0] * m

    path = [[] for _ in range(n)]

    for i in range(m):
        us[i], vs[i], gcds[i], lcms[i] = MII()
        us[i] -= 1
        vs[i] -= 1
        path[us[i]].append(i)
        path[vs[i]].append(i)

    ans = [-1] * n

    for i in range(n):
        if ans[i] == -1:
            if len(path[i]) == 0:
                ans[i] = 1
                continue

            total_flg = False

            cur_l = 0
            for eid in path[i]:
                cur_l = math.gcd(cur_l, lcms[eid])

            for x in range(1, 1001):
                if cur_l % x == 0:
                    f = x
                    flg = True

                    ans[i] = f

                    stk = [i]
                    tmp = [i]


                    while stk:
                        u = stk.pop()

                        for eid in path[u]:
                            v = us[eid] + vs[eid] - u
                            g = gcds[eid]
                            l = lcms[eid]

                            if ans[u] == 0: break

                            if ans[v] == -1:
                                ans[v] = g * l // ans[u]
                                tmp.append(v)
                                stk.append(v)

                            if math.gcd(ans[u], ans[v]) != g or ans[u] * ans[v] != g * l:
                                flg = False
                                break

                    if flg:
                        total_flg = True
                        break

                    for u in tmp:
                        ans[u] = -1

                    f = cur_l // x
                    flg = True

                    ans[i] = f

                    stk = [i]
                    tmp = [i]

                    while stk:
                        u = stk.pop()

                        for eid in path[u]:
                            v = us[eid] + vs[eid] - u
                            g = gcds[eid]
                            l = lcms[eid]

                            if ans[u] == 0: break

                            if ans[v] == -1:
                                ans[v] = g * l // ans[u]
                                tmp.append(v)
                                stk.append(v)

                            if math.gcd(ans[u], ans[v]) != g or ans[u] * ans[v] != g * l:
                                flg = False
                                break

                    if flg:
                        total_flg = True
                        break

                    for u in tmp:
                        ans[u] = -1

            if not total_flg:
                exit(print('NO'))

    print('YES')
    print(*ans)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, m;
    cin >> n >> m;

    vector<vector<array<int, 3>>> path(n);

    for (int i = 0; i < m; i ++) {
        int u, v, g, l;
        cin >> u >> v >> g >> l;

        u --, v --;
        path[u].push_back({v, g, l});
        path[v].push_back({u, g, l});
    }

    vector<long long> ans(n, -1);

    for (int i = 0; i < n; i ++) {
        if (ans[i] == -1) {
            if (path[i].size() == 0) {
                ans[i] = 1;
                continue;
            }

            bool total_flg = false;

            int cur_l = 0;
            for (auto &[u, g, l]: path[i])
                cur_l = gcd(cur_l, l);

            for (int x = 1; x <= 1000; x ++) {
                if (cur_l % x == 0) {
                    bool flg;

                    auto dfs = [&] (auto &self, int u) -> void {
                        if (!ans[u]) {
                            flg = false;
                            return;
                        }

                        for (auto &[v, g, l]: path[u]) {
                            if (ans[v] == -1) {
                                ans[v] = 1ll * g * l / ans[u];
                                self(self, v);
                            }
                            if (1ll * ans[v] * ans[u] != 1ll * g * l || gcd(ans[u], ans[v]) != g) {
                                flg = false;
                                break;
                            }
                        }
                    };

                    auto reset = [&] (auto &self, int u) -> void {
                        ans[u] = -1;
                        for (auto &[v, g, l]: path[u]) {
                            if (ans[v] != -1) {
                                ans[v] = -1;
                                self(self, v);
                            }
                        }
                    };

                    flg = true;
                    ans[i] = x;
                    dfs(dfs, i);

                    if (flg) {
                        total_flg = true;
                        break;
                    }

                    reset(reset, i);

                    flg = true;
                    ans[i] = cur_l / x;
                    dfs(dfs, i);

                    if (flg) {
                        total_flg = true;
                        break;
                    }

                    reset(reset, i);
                }
            }
            if (!total_flg) return cout << "NO", 0;
        }
    }
    cout << "YES\n";
    for (auto &x: ans) cout << x << ' ';

    return 0;
}
```

**提示 1：** 每条评论如何确定父结点？也就是图的结构是如何确定的。

**提示 2：** 事实上可以栈模拟。

我们如何确定当前结点对应的 “父评论” 是什么呢？

考虑前一条评论，依次往 “父评论” 走，一旦遇到一个评论数不满的位置，则在该位置添加上该评论。如果走到根结点了还没有遇到空的结点，则直接添加该评论。

因为一直是往上走，且新增元素时只需往下走一步，所以本质上来说可以使用栈模拟，具体可见后面的代码。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    s = I().split(',')
    n = len(s)

    ans = []

    cur = [10 ** 7]

    for i in range(0, n, 2):
        x = s[i]
        v = int(s[i + 1])

        while cur[-1] == 0:
            cur.pop()

        if len(cur) - 1 == len(ans):
            ans.append([])
        ans[len(cur) - 1].append(x)

        cur[-1] -= 1

        cur.append(v)

    print(len(ans))
    print('\n'.join(' '.join(x) for x in ans))
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    string s;
    cin >> s;

    string tmp;
    vector<string> strs;

    for (auto &c: s) {
        if (c == ',') {
            strs.emplace_back(tmp);
            tmp = "";
        }
        else tmp += c;
    }

    strs.emplace_back(tmp);

    int n = strs.size();

    vector<vector<string>> ans;
    vector<int> cur = {10000000};

    for (int i = 0; i < n; i += 2) {
        int v = stoi(strs[i + 1]);

        while (cur.back() == 0) cur.pop_back();

        if (cur.size() - 1 == ans.size())
            ans.push_back(vector<string>());

        ans[cur.size() - 1].emplace_back(strs[i]);
        cur.back() -= 1; cur.emplace_back(v);
    }

    cout << ans.size() << '\n';
    for (auto &x: ans) {
        for (int i = 0; i < x.size(); i ++) {
            if (i) cout << ' ';
            cout << x[i];
        }
        cout << '\n';
    }

    return 0;
}
```

**提示 1：** 矩形计数的时候遇到这种数据范围可以考虑枚举上下边界。

**提示 2：** 接下来要计算的是什么？

考虑枚举上下边界，再在顺序遍历的过程中 $\mathcal{O}(m)$ 解决问题，这样复杂度就符合预期了。

此时，我们要关注的两件事是—— `'a'` 的数量不能超，矩形角落得相等。

对于前者，我们可以在遍历下边界的过程中，顺便维护每一列的 `'a'` 的个数。

考虑枚举右边界，这样使用双指针就可以直接得到左边界的最左侧位置。

此时我们只需要看这个位置到当前右边界中，有多少个矩形满足角落都相等。

首先，最右侧一列的两个角得一样。

除此之外，左侧对应的一列上下两个角也得一样。我们可以在进行双指针的过程中，维护区间中 “角一样” 的列。因为我们要求左边列和右边列的角落字符是一样的，因此这里的维护需要分字符统计。

我们只需使用统计出来的，左边界的可行区间内，跟右边界角落字符一样的位置的数量就行。移动左右端点时，这个统计是可以快速维护的，具体可见代码。

时间复杂度为 $\mathcal{O}(n^2m)$ 。注意本题是文件读入输出。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    fin = open('input.txt', 'r')
    fout = open('output.txt', 'w')
    input = lambda: fin.readline().strip()
    print = lambda x: fout.write(str(x))

    n, m, k = MII()
    grid = [[ord(c) - ord('a') for c in I()] for _ in range(n)]

    ans = 0

    for i in range(n):
        cnt = [0] * m
        for j in range(i, n):
            for a in range(m):
                if grid[j][a] == 0:
                    cnt[a] += 1

            if j > i:
                l = 0
                cur = 0

                tmp = [0] * 26

                for r in range(m):
                    cur += cnt[r]

                    while cur > k:
                        if grid[i][l] == grid[j][l]:
                            tmp[grid[i][l]] -= 1
                        cur -= cnt[l]
                        l += 1

                    if grid[i][r] == grid[j][r]:
                        if r > l:
                            ans += tmp[grid[i][r]]
                        tmp[grid[i][r]] += 1

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    ifstream fin("input.txt");
    ofstream fout("output.txt");

    int n, m, k;
    fin >> n >> m >> k;

    vector<string> grid(n);
    for (auto &s: grid) fin >> s;

    long long ans = 0;

    for (int i = 0; i < n; i ++) {
        vector<int> cnt(m, 0);
        for (int j = i; j < n; j ++) {
            for (int a = 0; a < m; a ++)
                if (grid[j][a] == 'a') cnt[a] ++;

            if (j > i) {
                int l = 0, cur = 0;
                vector<int> tmp(26, 0);

                for (int r = 0; r < m; r ++) {
                    cur += cnt[r];

                    while (cur > k) {
                        if (grid[i][l] == grid[j][l]) tmp[grid[i][l] - 'a'] --;
                        cur -= cnt[l];
                        l ++;
                    }

                    if (grid[i][r] == grid[j][r]) {
                        if (l < r) ans += tmp[grid[i][r] - 'a'];
                        tmp[grid[i][r] - 'a'] ++;
                    }
                }
            }
        }
    }
    fout << ans;

    return 0;
}
```

**提示 1：** 好像主要就只是看懂题。

**提示 2：** 枚举每一个区域，要算什么？

枚举每一个区域，区域总数是不超过 $\sum k$ 的，所以没问题。

对于每一个区域，需要看左侧和右侧的一块中有多少分割点。也就是说查询某个区间内的数的个数。

为此，可以将数组排序，二分找到两个端点的位置，作差即可得到结果。

时间复杂度为 $\mathcal{O}(n\log n)$ ，因为你至少得排序。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    ars = []

    for _ in range(n):
        k, *vals = MII()
        vals.sort()
        ars.append(vals)

    ans = 0

    for i in range(n):
        for j in range(1, len(ars[i])):
            v1 = bisect.bisect_left(ars[i - 1], ars[i][j]) - bisect.bisect_left(ars[i - 1], ars[i][j - 1])
            v2 = bisect.bisect_left(ars[(i + 1) % n], ars[i][j]) - bisect.bisect_left(ars[(i + 1) % n], ars[i][j - 1])
            if v1 != v2: ans += 1

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector<vector<int>> ars(n);
    for (int i = 0; i < n; i ++) {
        int k;
        cin >> k;

        while (k --) {
            int x;
            cin >> x;
            ars[i].emplace_back(x);
        }

        sort(ars[i].begin(), ars[i].end());
    }

    int ans = 0;

    auto count_in_interval = [&] (vector<int> &ar, int l, int r) -> int {
        return lower_bound(ar.begin(), ar.end(), r) - lower_bound(ar.begin(), ar.end(), l);
    };

    for (int i = 0; i < n; i ++) {
        for (int j = 1; j < ars[i].size(); j ++) {
            ans += count_in_interval(ars[(i + 1) % n], ars[i][j - 1], ars[i][j]) != count_in_interval(ars[(i + n - 1) % n], ars[i][j - 1], ars[i][j]);
        }
    }
    cout << ans;

    return 0;
}
```

**提示 1：** 首先确定已经出现在图中的字符应该怎么画。

**提示 2：** 剩下的怎么办呢？

**提示 3：** 得到的结果合法吗？

考虑一个字符出现的最左、右、上、下侧，则这一笔至少得包含这些。

如果这些无法一行 / 一列画完，则永远不可能满足要求。

剩余的就只是些没出现过的字符，这些字符可以有两种可能：

- 这个字符压根没参与过操作。也就是目前的图案中最大字符都比它小。

- 参与过操作但是被覆盖了。此时只需使用之后会被覆盖的区域就行。也就是找更大的字符对应的一个区域。

因此上述就完成了方案的构造。

为了验证方案成立，直接模拟一遍过程就行。

时间复杂度为 $\mathcal{O}(nm+|\Sigma|(n+m))$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    for _ in range(t):
        n, m = MII()
        grid = [[-1 if c == '.' else ord(c) - ord('a') for c in I()] for _ in range(n)]

        x_min = [n] * 26
        x_max = [-1] * 26

        y_min = [m] * 26
        y_max = [-1] * 26

        for i in range(n):
            for j in range(m):
                if grid[i][j] >= 0:
                    c = grid[i][j]

                    x_min[c] = fmin(x_min[c], i)
                    x_max[c] = fmax(x_max[c], i)

                    y_min[c] = fmin(y_min[c], j)
                    y_max[c] = fmax(y_max[c], j)

        ops = []
        xl, xr, yl, yr = n, -1, m, -1

        flg = True

        for i in range(25, -1, -1):
            if x_min[i] <= x_max[i]:
                if x_min[i] == x_max[i] or y_min[i] == y_max[i]:
                    xl = x_min[i]
                    xr = x_max[i]
                    yl = y_min[i]
                    yr = y_max[i]
                else:
                    flg = False
                    break
            if xl != n:
                ops.append((xl, xr, yl, yr))

        if not flg:
            outs.append('NO')
        else:
            ops.reverse()

            k = len(ops)
            tmp_grid = [[-1] * m for _ in range(n)]

            for i in range(k):
                xl, xr, yl, yr = ops[i]
                for x in range(xl, xr + 1):
                    for y in range(yl, yr + 1):
                        tmp_grid[x][y] = i

            for i in range(n):
                for j in range(m):
                    if grid[i][j] != tmp_grid[i][j]:
                        flg = False

            if not flg:
                outs.append('NO')
            else:
                outs.append('YES')
                outs.append(str(k))

                for xl, xr, yl, yr in ops:
                    outs.append(f'{xl + 1} {yl + 1} {xr + 1} {yr + 1}')

    print('\n'.join(outs))
