    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    set<pair<int, int>> st;

    while (n --) {
        int k, b;
        cin >> k >> b;

        if (k) {
            int g = gcd(k, b);
            k /= g;
            b /= g;

            if (k < 0 || (k == 0 && b < 0))
                k = -k, b = -b;

            st.insert({k, b});
        }
    }

