    long long w, m, k;
    cin >> w >> m >> k;
    w /= k;

    long long v = 10, digit = 1, ans = 0;

    while (true) {
        long long l = max(0ll, v - m);
        if (l * digit <= w) {
            w -= l * digit;
            ans += l;
            m += l;
        }
        else {
            ans += w / digit;
