    vector<long long> f(32, 0);
    for (int i = 1; i < 32; i ++)
        f[i] = 4 * f[i - 1] + 1;

    while (t --) {
        long long n, k;
        cin >> n >> k;

        if (n > 31) cout << "YES " << n - 1 << '\n';
