```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, m, k;
    cin >> n >> m >> k;

    long long val = 1e9, x;

    for (int i = 0; i < n; i ++) {
        cin >> x;
        if (i % 2 == 0) val = min(val, x);
    }

    if (n % 2 == 0) cout << 0;
    else cout << min(val, 1ll * m / (n / 2 + 1) * k);

    return 0;
}
