**提示 1：** 考虑枚举所有 $k\times k$ 的子矩形。

**提示 2：** 加入延申的部分——和子矩形相邻的所有连通块。最终的总面积包含了这里所有的连通块。还包含了什么？

考虑枚举所有子矩形。

需要加入的包括所有跟子矩形上下左右四连通的连通分量。考虑加入所有不同的连通分量的大小。这是可以预处理每一个连通分量后快速得到的。枚举四条边的过程是 $\mathcal{O}(k)$ 的。

最终的总面积首先包含这里所有的连通块的总面积。

还包含了什么呢？还包含了 $k\times k$ 内原本的所有的障碍物的总面积。

还有漏吗？还少了完全在 $k\times k$ 范围内的所有连通块的总面积。

相对来说更难的只有最后这种情况了。最后这件事如何统计呢？考虑所有连通块的最左 / 右 / 上 / 下边缘，则能包含这个连通块的 $k\times k$ 矩形一定各个边界都更靠外侧，这样的合法的矩形的左上角构成一个矩形区域。对于这个矩形区域，需要对答案新增这个连通块的面积。矩形加可以通过二维差分 + 前缀和完成。

时间复杂度为 $\mathcal{O}(n^3)$ ，因为后半部分的复杂度为 $\mathcal{O}((n-k)^2k)$ ，容易由均值不等式有 $(n-k)^2k=\frac{(n-k)^22k}{2}=\frac{\left(\frac{(n-k)+(n-k)+2k}{3}\right)^3}{2}=\frac{4}{27}n^3$ ，因此常数并不大。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, k = MII()
    grid = [[1 if c == '.' else 0 for c in I()] for _ in range(n)]

    acc = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(n):
        for j in range(n):
            if grid[i][j] == 0:
                acc[i + 1][j + 1] = 1

    for i in range(n):
        for j in range(n + 1):
            acc[i + 1][j] += acc[i][j]

    for i in range(n + 1):
        for j in range(n):
            acc[i][j + 1] += acc[i][j]

    group = [[-1] * n for _ in range(n)]
    group_cnt = [0] * (n * n)
    re_calc = [[0] * (n + 1) for _ in range(n + 1)]

    dirs = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    def f(x, y):
        return x * n + y

    for i in range(n):
        for j in range(n):
            if grid[i][j] and group[i][j] == -1:
                group_id = f(i, j)
                sz = 1

                mxx, mnx = i, i
                mxy, mny = j, j

                stk = [f(i, j)]
                group[i][j] = group_id

                while stk:
                    x, y = divmod(stk.pop(), n)
                    mxx = fmax(mxx, x)
                    mnx = fmin(mnx, x)
                    mxy = fmax(mxy, y)
                    mny = fmin(mny, y)
                    for dx, dy in dirs:
                        if 0 <= x + dx < n and 0 <= y + dy < n and group[x + dx][y + dy] == -1 and grid[x + dx][y + dy]:
                            group[x + dx][y + dy] = group_id
                            stk.append(f(x + dx, y + dy))
                            sz += 1

                group_cnt[f(i, j)] = sz

                if mxx - mnx < k and mxy - mny < k:
                    lx = fmax(0, mxx - k + 1)
                    rx = fmin(mnx, n - k)

                    ly = fmax(0, mxy - k + 1)
                    ry = fmin(mny, n - k)

                    re_calc[lx][ly] += sz
                    re_calc[lx][ry + 1] -= sz
                    re_calc[rx + 1][ly] -= sz
                    re_calc[rx + 1][ry + 1] += sz

    for i in range(n):
        for j in range(n + 1):
            re_calc[i + 1][j] += re_calc[i][j]

    for i in range(n + 1):
        for j in range(n):
            re_calc[i][j + 1] += re_calc[i][j]

    vis = [0] * (n * n)

    ans = 0

    for i in range(n - k + 1):
        for j in range(n - k + 1):
            res = 0
            tmp = []

            if i:
                for nj in range(j, j + k):
                    if grid[i - 1][nj] and not vis[group[i - 1][nj]]:
                        vis[group[i - 1][nj]] = 1
                        tmp.append(group[i - 1][nj])
                        res += group_cnt[group[i - 1][nj]]

            if i + k < n:
                for nj in range(j, j + k):
                    if grid[i + k][nj] and not vis[group[i + k][nj]]:
                        vis[group[i + k][nj]] = 1
                        tmp.append(group[i + k][nj])
                        res += group_cnt[group[i + k][nj]]

            if j:
                for ni in range(i, i + k):
                    if grid[ni][j - 1] and not vis[group[ni][j - 1]]:
                        vis[group[ni][j - 1]] = 1
                        tmp.append(group[ni][j - 1])
                        res += group_cnt[group[ni][j - 1]]

            if j + k < n:
                for ni in range(i, i + k):
                    if grid[ni][j + k] and not vis[group[ni][j + k]]:
                        vis[group[ni][j + k]] = 1
                        tmp.append(group[ni][j + k])
                        res += group_cnt[group[ni][j + k]]

            res += acc[i + k][j + k] - acc[i][j + k] - acc[i + k][j] + acc[i][j]
            res += re_calc[i][j]

            ans = fmax(ans, res)

            for x in tmp:
                vis[x] = 0

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, k;
    cin >> n >> k;

    vector<string> grid(n);
    for (auto &s: grid) cin >> s;

    vector<vector<int>> acc(n + 1, vector<int>(n + 1, 0));

    for (int i = 0; i < n; i ++) {
        for (int j = 0; j < n; j ++) {
            acc[i + 1][j + 1] = (grid[i][j] == 'X');
        }
    }

    for (int i = 0; i < n; i ++) {
        for (int j = 0; j <= n; j ++) {
            acc[i + 1][j] += acc[i][j];
        }
    }

    for (int i = 0; i <= n; i ++) {
        for (int j = 0; j < n; j ++) {
            acc[i][j + 1] += acc[i][j];
        }
    }

    vector<vector<int>> group(n, vector<int>(n, -1));
    vector<int> group_cnt(n * n);
    vector<vector<int>> re_calc(n + 1, vector<int>(n + 1, 0));

    vector<pair<int, int>> dirs = {{-1, 0}, {0, 1}, {1, 0}, {0, -1}};

    auto f = [&] (int i, int j) -> int {return i * n + j;};

    for (int i = 0; i < n; i ++) {
        for (int j = 0; j < n; j ++) {
            if (grid[i][j] == '.' && group[i][j] == -1) {
                int group_id = f(i, j), sz = 0;
                int mxx = i, mnx = i, mxy = j, mny = j;

                auto dfs = [&] (auto &self, int x, int y) -> void {
                    sz ++;
                    group[x][y] = group_id;
                    mxx = max(mxx, x);
                    mnx = min(mnx, x);
                    mxy = max(mxy, y);
                    mny = min(mny, y);

                    for (auto &[dx, dy]: dirs) {
                        if (x + dx >= 0 && x + dx < n && y + dy >= 0 && y + dy < n && group[x + dx][y + dy] == -1 && grid[x + dx][y + dy] == '.')
                            self(self, x + dx, y + dy);
                    }
                };

                dfs(dfs, i, j);

                group_cnt[group_id] = sz;

                if (mxx - mnx < k && mxy - mny < k) {
                    int lx = max(0, mxx - k + 1), rx = min(mnx, n - k);
                    int ly = max(0, mxy - k + 1), ry = min(mny, n - k);

                    re_calc[lx][ly] += sz;
                    re_calc[lx][ry + 1] -= sz;
                    re_calc[rx + 1][ly] -= sz;
                    re_calc[rx + 1][ry + 1] += sz;
                }
            }
        }
    }

    for (int i = 0; i < n; i ++) {
        for (int j = 0; j <= n; j ++) {
            re_calc[i + 1][j] += re_calc[i][j];
        }
    }

    for (int i = 0; i <= n; i ++) {
        for (int j = 0; j < n; j ++) {
            re_calc[i][j + 1] += re_calc[i][j];
        }
    }

    vector<bool> vis(n * n, 0);
    int ans = 0;

    for (int i = 0; i <= n - k; i ++) {
        for (int j = 0; j <= n - k; j ++) {
            int res = 0;
            vector<int> tmp;

            if (i) {
                for (int nj = j; nj < j + k; nj ++) {
                    if (grid[i - 1][nj] == '.' && !vis[group[i - 1][nj]]) {
                        vis[group[i - 1][nj]] = 1;
                        tmp.emplace_back(group[i - 1][nj]);
                        res += group_cnt[group[i - 1][nj]];
                    }
                }
            }

            if (i + k < n) {
                for (int nj = j; nj < j + k; nj ++) {
                    if (grid[i + k][nj] == '.' && !vis[group[i + k][nj]]) {
                        vis[group[i + k][nj]] = 1;
                        tmp.emplace_back(group[i + k][nj]);
                        res += group_cnt[group[i + k][nj]];
                    }
                }
            }

            if (j) {
                for (int ni = i; ni < i + k; ni ++) {
                    if (grid[ni][j - 1] == '.' && !vis[group[ni][j - 1]]) {
                        vis[group[ni][j - 1]] = 1;
                        tmp.emplace_back(group[ni][j - 1]);
                        res += group_cnt[group[ni][j - 1]];
                    }
                }
            }

            if (j + k < n) {
                for (int ni = i; ni < i + k; ni ++) {
                    if (grid[ni][j + k] == '.' && !vis[group[ni][j + k]]) {
                        vis[group[ni][j + k]] = 1;
                        tmp.emplace_back(group[ni][j + k]);
                        res += group_cnt[group[ni][j + k]];
                    }
                }
            }

            res += acc[i + k][j + k] - acc[i][j + k] - acc[i + k][j] + acc[i][j];
            res += re_calc[i][j];
            ans = max(ans, res);

            for (auto &x: tmp) vis[x] = 0;
        }
    }

    cout << ans;

    return 0;
}
```

**提示 1：** 注意任意两行都可以交换位置。所以我们固定右侧边界的时候，可以挑选 “最好” 的几行，凑成最大的矩阵。

**提示 2：** 我们挑哪些行呢？

列是相对固定的，因此我们考虑枚举某一列作为边界。不妨作为右边界。

则每一行可以往左侧延申的最大长度是可以快速维护的。

而我们要凑成的最大的矩阵，一定选择其中能延申的长度最长的几行。

于是考虑将该数组逆序排序，取其中长度为 $k$ 的前缀时，对应的面积为 $k$ 乘以这个前缀的最小值。

如果直接使用排序是带 $\log$ 的，但这里数组的值域不会超过 $[0,m]$ ，因此可以使用基数排序等做法，规避掉这一个 $\log$ 。

时间复杂度为 $\mathcal{O}(nm+m^2)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m = MII()
    grid = [[int(c) for c in I()] for _ in range(n)]

    cur = [0] * n
    cnt = [0] * (m + 1)

    ans = 0

    for j in range(m):
        for i in range(n):
            cur[i] = cur[i] + 1 if grid[i][j] else 0

        for x in cur:
            cnt[x] += 1

        c = 0
        for i in range(m, -1, -1):
            c += cnt[i]
            ans = fmax(ans, c * i)

        for x in cur:
            cnt[x] -= 1

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, m;
    cin >> n >> m;

    vector<string> grid(n);
    for (auto &s: grid) cin >> s;

    vector<int> cur(n), cnt(m + 1, 0);
    int ans = 0;

    for (int j = 0; j < m; j ++) {
        for (int i = 0; i < n; i ++) {
            cur[i] = (grid[i][j] == '1' ? cur[i] + 1 : 0);
        }

        for (auto &x: cur) cnt[x] ++;

        int c = 0;
        for (int j = m; j >= 0; j --) {
            c += cnt[j];
            ans = max(ans, c * j);
        }

        for (auto &x: cur) cnt[x] --;
    }

    cout << ans;

    return 0;
}
