        print('(' * (n - 1), end='')
        for i in range(n):
            if i: print('+', end='')
            print(f'({lst[i] // 2}*((1-abs((t-{i})))+abs((1-abs((t-{i}))))))', end='')
            if i: print(')', end='')
        print()

    solve(xs)
    solve(ys)
