**提示 2：** 最多拐两次弯——中间那段一旦确定是哪条直线其实整条路经都确定了。

先看上面的提示。

整条路经最多有三段，那么特别地肯定是考虑中间的一段。

一旦我们确定中间的一段是横着的某一条线，则第一段一定是从起始点直走走到这条线，最后一段一定是这条线直走走到终点。

于是枚举中间的一条直线，则整条路径完全确定，我们只需检查路径中有无障碍即可。

中间的一段是竖着的情况也是完全类似的。

时间复杂度为 $\mathcal{O}(nm)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m = MII()
    grid = [I() for _ in range(n)]
    sx, sy = -1, -1
    tx, ty = -1, -1

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'S':
                sx, sy = i, j
            if grid[i][j] == 'T':
                tx, ty = i, j

    check = [[1 if grid[i][j] == '*' else 0 for j in range(m)] for i in range(n)]

    def f(x1, y1, x2, y2):
        if x1 > x2:
            x1, x2 = x2, x1
        if y1 > y2:
            y1, y2 = y2, y1

        for i in range(x1, x2 + 1):
            for j in range(y1, y2 + 1):
                if check[i][j]:
                    return False
        return True

    for i in range(n):
        if f(sx, sy, i, sy) and f(i, sy, i, ty) and f(i, ty, tx, ty):
            exit(print('YES'))

    for i in range(m):
        if f(sx, sy, sx, i) and f(sx, i, tx, i) and f(tx, i, tx, ty):
            exit(print('YES'))

    print('NO')
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, m;
    cin >> n >> m;

    vector<string> grid(n);
    for (auto &s: grid) cin >> s;

    int sx, sy, tx, ty;
    for (int i = 0; i < n; i ++) {
        for (int j = 0; j < m; j ++) {
            if (grid[i][j] == 'S')
                sx = i, sy = j;
            if (grid[i][j] == 'T')
                tx = i, ty = j;
        }
    }

    auto check = [&] (int x1, int y1, int x2, int y2) -> bool {
        if (x1 > x2) swap(x1, x2);
        if (y1 > y2) swap(y1, y2);

        for (int i = x1; i <= x2; i ++) {
            for (int j = y1; j <= y2; j ++) {
                if (grid[i][j] == '*') {
                    return false;
                }
            }
        }
        return true;
    };

    for (int i = 0; i < n; i ++) {
        if (check(sx, sy, i, sy) && check(i, sy, i, ty) && check(i, ty, tx, ty)) {
            return cout << "YES", 0;
        }
    }

    for (int i = 0; i < m; i ++) {
        if (check(sx, sy, sx, i) && check(sx, i, tx, i) && check(tx, i, tx, ty)) {
            return cout << "YES", 0;
        }
    }
    cout << "NO";

    return 0;
}
