    cin.tie(0);
    cout.tie(0);

    int t;
    cin >> t;

    while (t --) {
        int n, m, a, b;
        cin >> n >> m >> a >> b;

        vector<int> nums(m);
        for (auto &x: nums)
            cin >> x;

        sort(nums.begin(), nums.end());

        int to_consider = min(m, abs(a - b) - 1);
        int caught = (a < b ? b - 1 : n - b);

        int ans = 0;
        for (int i = to_consider - 1; i >= 0; i --) {
