**提示 1：** 长度最长的前缀 / 后缀提供了最多的原串的信息。

**提示 2：** 原串的可能情况出来了只需判断是否可能再找对应的前后缀输出就行。

越长的串给出了原串越多的信息。

我们找到长度为 $n-1$ 的两个串，不妨设为 $s_1,s_2$ ，则只有两种可能： $s_1$ 前缀， $s_2$ 后缀，或者是相反过来。

$s_1$ 做前缀时，原串等于 $s_1+s_2的第一个字符$ ，否则原串只能等于 $s_2+s_1的第一个字符$ 。

于是只有两个可能的原串，我们可以暴力判断是否成立。判断方法就是取出原串的各个前缀，看能否跟给定的序列形成一一对应。如果能对应起来，则一一对应后输出每个下标分别是前缀还是后缀即可。

时间复杂度为 $\mathcal{O}(n^2)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    strs = [I() for _ in range(2 * n - 2)]
    ans = [''] * (2 * n - 2)

    d = defaultdict(list)
    for i in range(2 * n - 2):
        d[strs[i]].append(i)

    idxs = []
    for i in range(2 * n - 2):
        if len(strs[i]) == n - 1:
            idxs.append(i)

    s1 = strs[idxs[0]]
    s2 = strs[idxs[1]]

    def check(s):
        cnt = defaultdict(list)
        for i in range(1, n):
            cnt[s[:i]].append(1)
            cnt[s[-i:]].append(0)

        for x in cnt:
            if len(cnt[x]) != len(d[x]):
                return

        for x in cnt:
            for i in range(len(cnt[x])):
                ans[d[x][i]] = 'P' if cnt[x][i] else 'S'

        exit(print(''.join(ans)))

    check(s1 + s2[-1])
    check(s2 + s1[-1])
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector<string> strs(2 * n - 2);
    for (auto &s: strs) cin >> s;

    map<string, vector<int>> mp;
    for (int i = 0; i < 2 * n - 2; i ++)
        mp[strs[i]].emplace_back(i);

    vector<int> tmp;
    for (int i = 0; i < 2 * n - 2; i ++)
        if (strs[i].size() == n - 1)
            tmp.emplace_back(i);

    string s1 = strs[tmp[0]], s2 = strs[tmp[1]];
    string ans(2 * n - 2, ' ');

    auto check = [&] (string s) -> void {
        map<string, vector<bool>> cnt;
        for (int i = 1; i < n; i ++) {
            cnt[s.substr(0, i)].emplace_back(1);
            cnt[s.substr(n - i, i)].emplace_back(0);
        }

        for (auto &[k, v]: mp) {
            if (cnt[k].size() != v.size()) {
                return ;
            }
        }

        for (auto &[k, v]: mp) {
            for (int i = 0; i < v.size(); i ++) {
                ans[v[i]] = (cnt[k][i] ? 'P' : 'S');
            }
        }

        cout << ans;
        exit(0);
    };

    check(s1 + s2.back());
    check(s2 + s1.back());

    return 0;
}
```

**提示 1：** 我们只需快速计算出每个沙发的任何一个方向的沙发数量就行。不妨考虑左边（其他方向都是一样的）。

**提示 2：** 发现只需要考虑一个维度的信息。

先看提示 1。我们以如何计算左边的沙发数量作为例子，其余方向逻辑非常类似。

计算 $(x_1,y_1,x_2,y_2)$ （不妨调整后使得 $x_1\leq x_2,y_1\leq y_2$ ）左侧的沙发个数，只需看有多少个沙发存在一个格点使得该点的 $x$ 比 $x_2$ 严格小。

于是，只需在每个沙发的最左侧边界进行标记就行，看有多少个有边界比当前考虑的沙发的右边界小。（因为这样左右关系是最有可能实现的）

这件事可以通过记录左边界再二分得到，也可以考虑到 $n,m$ 很小，直接前缀和后查询（可见后面的代码）。

注意上面的计算没有考虑“自己在自己的左边”，如果沙发本身有 $x_1\lt x_2$ ，则会多算上自己，去掉就行。

时间复杂度为 $\mathcal{O}(n+m+d)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    d = II()
    n, m = MII()

    cols_l = [0] * (n + 2)
    cols_r = [0] * (n + 2)

    rows_u = [0] * (m + 2)
    rows_d = [0] * (m + 2)

    x1s = []
    y1s = []
    x2s = []
    y2s = []

    for _ in range(d):
        x1, y1, x2, y2 = MII()
        if x1 > x2:
            x1, x2 = x2, x1
        if y1 > y2:
            y1, y2 = y2, y1
        x1s.append(x1)
        y1s.append(y1)
        x2s.append(x2)
        y2s.append(y2)

        cols_l[x1] += 1
        cols_r[x2] += 1

        rows_u[y1] += 1
        rows_d[y2] += 1

    for i in range(1, n + 1):
        cols_l[i] += cols_l[i - 1]

    for i in range(n, -1, -1):
        cols_r[i] += cols_r[i + 1]

    for i in range(1, m + 1):
        rows_u[i] += rows_u[i - 1]

    for i in range(m, -1, -1):
        rows_d[i] += rows_d[i + 1]

    cl, cr, cu, cd = MII()

    for i in range(d):
        vcl = cols_l[x2s[i] - 1]
        vcr = cols_r[x1s[i] + 1]
        vcu = rows_u[y2s[i] - 1]
        vcd = rows_d[y1s[i] + 1]

        if x1s[i] < x2s[i]:
            vcl -= 1
            vcr -= 1
        else:
            vcu -= 1
            vcd -= 1

        if cl == vcl and cr == vcr and cu == vcu and cd == vcd:
            print(i + 1)
            exit()

    print(-1)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int d, n, m;
    cin >> d >> n >> m;

    vector<int> cols_l(n + 2, 0), cols_r(n + 2, 0), rows_u(m + 2, 0), rows_d(m + 2, 0);
    vector<int> x1s(d), y1s(d), x2s(d), y2s(d);

    for (int i = 0; i < d; i ++) {
        cin >> x1s[i] >> y1s[i] >> x2s[i] >> y2s[i];
        if (x1s[i] > x2s[i]) swap(x1s[i], x2s[i]);
        if (y1s[i] > y2s[i]) swap(y1s[i], y2s[i]);

        cols_l[x1s[i]] ++, cols_r[x2s[i]] ++;
        rows_u[y1s[i]] ++, rows_d[y2s[i]] ++;
    }

    for (int i = 1; i <= n; i ++) cols_l[i] += cols_l[i - 1];
    for (int i = n; i >= 0; i --) cols_r[i] += cols_r[i + 1];
    for (int i = 1; i <= m; i ++) rows_u[i] += rows_u[i - 1];
    for (int i = m; i >= 0; i --) rows_d[i] += rows_d[i + 1];

    int cl, cr, cu, cd;
    cin >> cl >> cr >> cu >> cd;

    for (int i = 0; i < d; i ++) {
        int vcl = cols_l[x2s[i] - 1];
        int vcr = cols_r[x1s[i] + 1];
        int vcu = rows_u[y2s[i] - 1];
        int vcd = rows_d[y1s[i] + 1];

        if (x1s[i] < x2s[i])
            vcl --, vcr --;
        else 
            vcu --, vcd --;

        if (cl == vcl && cr == vcr && cu == vcu && cd == vcd) 
            return cout << i + 1, 0;
    }

    cout << -1;

    return 0;
}
```

**提示 1：** 先猜下什么情况下可以进行构造。

**提示 2：** 对于 $n$ 的问题，可以转化为 $n-1$ 的问题。

有多种构造方法，但我认为自己的这个方法有一定的启发性！

首先，最大的结果是把所有括号套起来，此时为 $0+1+\dots+n-1=\frac{n(n-1)}{2}$ 。

这种情况下总能构造吗？事实上，可以用数学归纳法进行构造和证明。

首先 $n=1$ 时，我们能构造不超过 $\frac{1\times 0}{2}=0$ 的结果。

假设我们已经掌握了 $n=m$ 的构造，考虑 $n=m+1$ 的情况。

考虑第一个左括号的匹配。

我们可以直接选择在字符串开头放入 `()` ，此时剩余的 $m$ 情况的字符串要求的括号深度和结果和原 $m+1$ 的括号深度和结果一致。因此，对于括号深度和结果不超过 $\frac{m(m-1)}{2}$ 的情况，都可以进行这个操作，来转化为 $n=m$ 的问题。

否则，我们在最开头和最结尾分别放上 `(`, `)` （并认为它们匹配），并考虑考虑中间被围起来的字符串是否可构造。中间的子字符串对应括号深度和的结果是 $k-(m-1)$ （一定非负），因为最外层的括号让中间的每一对括号深度加一了。而此时 $k-(m-1)\leq \frac{m(m-1)}{2}$ ，符合可构造的条件。

于是总能转化为 $n=m$ 情况下的问题。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, k = MII()
    if n * (n - 1) // 2 < k: print('Impossible')
    else:
        ans = []
        cur = 0

        for i in range(n):
            if k - (n - 1 - i) >= 0:
                ans.append('(')
                cur += 1
                k -= n - 1 - i
            else:
                ans.append('()')

        for _ in range(cur):
            ans.append(')')

        print(''.join(ans))
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    long long n, k;
    cin >> n >> k;

    if (n * (n - 1) / 2 < k) cout << "Impossible";
    else {
        int cur = 0;
        for (int i = 0; i < n; i ++) {
            if (k >= n - 1 - i) {
                cout << '(';
                cur ++;
                k -= n - 1 - i;
            }
            else cout << "()";
        }
        while (cur --) cout << ')';
    }

    return 0;
}
```

**提示 1：** 两种操作有啥用呢？考虑面积的质因数分解。

**提示 2：** 其实应该先做其中一种操作噢！

两种操作分别有啥用呢？

- 吃掉 $\frac{1}{3}$ ：面积的 $3$ 因子减少 $1$ 个， $2$ 因子增加 $1$ 个。

- 吃掉 $\frac{1}{2}$ ：面积的 $2$ 因子减少 $1$ 个。

而一旦面积中有 $3$ 因子就可以进行第一种操作，一旦面积中有 $2$ 因子就可以进行第二种操作（因为一定有一条边是 $3/2$ 的倍数）。

而只有第一种操作可以调整 $3$ 因子的个数，所以先进行第一种操作，同时第一个操作也可能产生 $2$ 因子，导致第二种操作的进行次数相对更小。第一个矩形面积 $3$ 因子更多就对第一个矩形操作，否则对第二个矩形操作。

接下来再考虑 $2$ 因子的情况，第一个矩形面积 $2$ 因子更多就对第一个矩形操作，否则对第二个矩形操作。

这样调整后 $2/3$ 两个因子的次数已经调整到一致。其他质因子本身就无法调整，因此，如果此时面积不相等，直接输出无法构造即可。上述过程也是步数最少的。

时间复杂度为 $\mathcal{O}(\log M)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    a1, b1 = MII()
    a2, b2 = MII()

    def c3(x):
        cnt = 0
        while x % 3 == 0:
            x //= 3
            cnt += 1
        return cnt

    def c2(x):
        cnt = 0
        while x % 2 == 0:
            x //= 2
            cnt += 1
        return cnt

    ans = 0

    v = c3(a1) + c3(b1) - c3(a2) - c3(b2)
    while v > 0:
        v -= 1
        ans += 1
        if a1 % 3 == 0: a1 = a1 // 3 * 2
        else: b1 = b1 // 3 * 2

    while v < 0:
        v += 1
        ans += 1
        if a2 % 3 == 0: a2 = a2 // 3 * 2
        else: b2 = b2 // 3 * 2

    v = c2(a1) + c2(b1) - c2(a2) - c2(b2)
    while v > 0:
        v -= 1
        ans += 1
        if a1 % 2 == 0: a1 = a1 // 2
        else: b1 = b1 // 2

    while v < 0:
        v += 1
        ans += 1
        if a2 % 2 == 0: a2 = a2 // 2
        else: b2 = b2 // 2

    if a1 * b1 == a2 * b2:
        print(ans)
        print(a1, b1)
        print(a2, b2)
    else: print(-1)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int a1, b1, a2, b2;
    cin >> a1 >> b1 >> a2 >> b2;

    auto c3 = [&] (int x) -> int {
        int cnt = 0;
        while (x % 3 == 0) {
            x /= 3;
            cnt ++;
        }
        return cnt;
    };

    auto c2 = [&] (int x) -> int {
        int cnt = 0;
        while (x % 2 == 0) {
            x /= 2;
            cnt ++;
        }
        return cnt;
    };

    int ans = 0, v = c3(a1) + c3(b1) - c3(a2) - c3(b2);

    while (v > 0) {
        v --;
        ans ++;
        if (a1 % 3 == 0) a1 = a1 / 3 * 2;
        else b1 = b1 / 3 * 2;
    }

    while (v < 0) {
        v ++;
        ans ++;
        if (a2 % 3 == 0) a2 = a2 / 3 * 2;
        else b2 = b2 / 3 * 2;
    }

    v = c2(a1) + c2(b1) - c2(a2) - c2(b2);

    while (v > 0) {
        v --;
        ans ++;
        if (a1 % 2 == 0) a1 = a1 / 2;
        else b1 = b1 / 2;
    }

    while (v < 0) {
        v ++;
        ans ++;
        if (a2 % 2 == 0) a2 = a2 / 2;
        else b2 = b2 / 2;
    }

    if (1ll * a1 * b1 == 1ll * a2 * b2) {
        cout << ans << '\n';
        cout << a1 << ' ' << b1 << '\n';
        cout << a2 << ' ' << b2 << '\n';
    }
    else cout << -1;

    return 0;
}
```

**提示：** 欸，好像没啥要提示的，读懂题，想想怎么实现就好啦！

首先，有两个基础类 `void` 和 `errtype` 。

前者是可以变为 `void**...` 的类，后者无论如何操作都是 `errtype` 。

然后你做的操作叫做定义类，在一个类的基础上，如果多了一个 `&` ，那么少一个 `*` ，如果多了一个 `*` ，那么多一个 `*` （形式上）。

于是，我们可以根据原类，进行上述运算得到新的类有多少个 `*` 。如果新的类的 `*` 变为小于 0 的话，那么新的类就是 `errtype` 了。

因此，为了方便实现，我们对 `void` 记录数值为 $0$ ，对 `errtype` 记录数值为负的足够大的数，分别表示对应的 `*` 的个数。这样，我们只需通过加法减法，即可得到新类型的 `*` 的个数。

这样，从 `errtype` 起步一定得到非法类。否则，新类型的 `*` 的个数可以从其原本元素的 `*` 的个数推导出来（数 `*` 和 `&` 的个数）。如果个数是负数，则又得到了 `errtype` ，重置为负无穷就行。

注意没被定义的类都是 `errtype` ，可以直接赋值负无穷。同时，输出的一行是可以包含 `*` 和 `&` 的，你需要进行类似上面的判断。

时间复杂度为 $\mathcal{O}(n^2)$ ，因为可能不断加入 `*` 后输出 $\mathcal{O}(n)$ 轮。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    cnt = Counter()

    cnt['void'] = 0
    cnt['errtype'] = -100000
    outs = []

    for _ in range(n):
        op = LI()
        if op[0] == 'typedef':
            v1 = op[1]
            v2 = op[2]

            l = 0
            r = len(v1) - 1
            cur = 0

            while v1[l] == '&':
                l += 1
                cur -= 1

            while v1[r] == '*':
                r -= 1
                cur += 1

            orig = v1[l:r + 1]

            if orig not in cnt:
                cnt[orig] = -100000

            nval = cnt[orig] + cur
            cnt[v2] = nval if nval >= 0 else -100000
        else:
            v = op[1]

            l = 0
            r = len(v) - 1
            cur = 0

            while v[l] == '&':
                l += 1
                cur -= 1

            while v[r] == '*':
                r -= 1
                cur += 1

            orig = v[l:r + 1]

            outs.append('errtype' if orig not in cnt or cnt[orig] + cur < 0 else "void" + '*' * (cnt[orig] + cur))

    print('\n'.join(outs))
