**提示 1：** 本质上找到最短的两条路径就行。

**提示 2：** 最短的一条显然很好办。第二短的怎么办呢？

本质上，可以考虑成从 $1$ 用两种方式到 $n$ ，使得总成本最小。再反转第二次的步骤就行。

也就是求最短路和第二短路。

前者直接 Dijkstra 就行，后者呢？

我们可以枚举其使用的跟第一条最短路不同的一条边 $u\to v$ ，那么走过这条边的最短路等于——从 $1$ 出发到 $u$ ，从 $u$ 到 $v$ ，再从 $v$ 出发到 $n$ 的总路径。

于是，我们只需预处理从 $1$ 到任何一个点的最短路，以及从 $n$ 出发到任何一个点的最短路即可。

注意这里枚举的边需要不在原先的 $1$ 到 $n$ 的路径上。可以使用一些方式标记在 $1$ 到 $n$ 的最短路上的边。

时间复杂度为 $\mathcal{O}(m\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m = MII()
    path = [[] for _ in range(n)]

    for _ in range(m):
        u, v, w = MII()
        u -= 1
        v -= 1

        path[u].append(w * n + v)
        path[v].append(w * n + u)

    parent = [-1] * n

    inf = 10 ** 9

    dis1 = [inf] * n
    dis1[0] = 0

    pq = [0]

    while pq:
        d, u = divmod(heappop(pq), n)
        if dis1[u] == d:
            for msk in path[u]:
                w, v = divmod(msk, n)
                if d + w < dis1[v]:
                    dis1[v] = d + w
                    parent[v] = u
                    heappush(pq, dis1[v] * n + v)

    vis = [0] * n
    cur = n - 1

    vis[cur] = 1

    while parent[cur] != -1:
        cur = parent[cur]
        vis[cur] = 1

    disn = [inf] * n
    disn[n - 1] = 0

    pq = [n - 1]

    while pq:
        d, u = divmod(heappop(pq), n)
        if disn[u] == d:
            for msk in path[u]:
                w, v = divmod(msk, n)
                if d + w < disn[v]:
                    disn[v] = d + w
                    parent[v] = u
                    heappush(pq, disn[v] * n + v)

    ans = inf

    for u in range(n):
        for msk in path[u]:
            w, v = divmod(msk, n)
            if vis[u] and vis[v] and (parent[u] == v or parent[v] == u):
                continue
            ans = fmin(ans, dis1[u] + disn[v] + w)

    print(ans + dis1[n - 1] if ans < inf else -1)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, m;
    cin >> n >> m;

    vector<vector<pair<int, int>>> path(n);

    for (int i = 0; i < m; i ++) {
        int u, v, w;
        cin >> u >> v >> w;
        u --, v --;
        path[u].emplace_back(v, w);
        path[v].emplace_back(u, w);
    }

    int inf = 1e9;

    vector<int> dis1(n, inf), disn(n, inf), parent(n, -1);
    vector<bool> vis(n, 0);
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;

    dis1[0] = 0;
    pq.push({0, 0});

    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();

        if (dis1[u] == d) {
            for (auto &[v, w]: path[u]) {
                if (dis1[v] > d + w) {
                    dis1[v] = w + d;
                    parent[v] = u;
                    pq.push({dis1[v], v});
                }
            }
        }
    }

    int cur = n - 1;
    vis[cur] = 1;

    while (parent[cur] >= 0) {
        cur = parent[cur];
        vis[cur] = 1;
    }

    disn[n - 1] = 0;
    pq.push({0, n - 1});

    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();

        if (disn[u] == d) {
            for (auto &[v, w]: path[u]) {
                if (disn[v] > d + w) {
                    disn[v] = w + d;
                    parent[v] = u;
                    pq.push({disn[v], v});
                }
            }
        }
    }

    int ans = inf;

    for (int u = 0; u < n; u ++) {
        for (auto &[v, w]: path[u]) {
            if (vis[u] && vis[v] && (parent[u] == v || parent[v] == u)) continue;
            ans = min(ans, dis1[u] + disn[v] + w);
        }
    }

    cout << (ans < inf ? ans + dis1[n - 1] : -1);

    return 0;
}
```

**提示 1：** $a,b,c$ 位数固定，因此只需找到字典序第 $k$ 大的二元组 $(a,b)$ 。

**提示 2：** 注意题目数据范围允许枚举每一个 $a$ 。

首先，由于 $a,b,c$ 位数固定，因此算式的字典序首先取决于 $a$ （因为是整个算式的前面部分的字符），接下来取决于 $b$ 。 $c$ 是用 $a+b$ 算的。

因此只需找到字典序第 $k$ 大的二元组 $(a,b)$ 。

而题目数据范围是支持枚举所有的 $a$ 的，因为 $\sum 10^A$ 并不大。所以考虑从小到大枚举可能的 $a$ 。

对于某个 $a$ ，可选的 $b$ 需要满足条件——

- $b$ 本身的位数。在 $[10^B,10^{B+1}-1]$ 之间。

- $a+b$ 的位数。在 $[10^C-a,10^{C+1}-1-a]$ 之间。

因此取交集即可得到 $b$ 的范围。

用 $k$ 表示目标算式在第一项至少为 $a$ 的算式中的位置。

而如果这个范围内的整数数量不小于 $k$ ，则目标算式第一位就是 $a$ ，直接取上面第 $k$ 大的 $b$ 即可。

否则，就不可能使用 $a$ 作为算式的一部分，用 $k$ 减掉 $a$ 开头的算式数量，并重新考虑第一项至少为 $a+1$ 的算式即可。

时间复杂度为 $\mathcal{O}(10^A)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    for _ in range(t):
        a, b, c, k = MII()

        la = 10 ** (a - 1)
        ra = 10 ** a - 1
        lb = 10 ** (b - 1)
        rb = 10 ** b - 1
        lc = 10 ** (c - 1)
        rc = 10 ** c - 1

        flg = False

        for x in range(la, ra + 1):
            l = fmax(lb, lc - x)
            r = fmin(rb, rc - x)

            if l <= r:
                diff = r - l + 1
                if diff >= k:
                    flg = True
                    y = l + k - 1
                    outs.append(f'{x} + {y} = {x + y}')
                    break
                else:
                    k -= diff

        if not flg:
            outs.append('-1')

    print('\n'.join(outs))
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int t;
    cin >> t;

    auto find_interval = [&] (int x) -> pair<int, int> {
        int l = 1, r = 10;
        while (x > 1)
            x --, l *= 10, r *= 10;
        return {l, r - 1};
    };

    while (t --) {
        int a, b, c;
        long long k;
        cin >> a >> b >> c >> k;
        auto [la, ra] = find_interval(a);
        auto [lb, rb] = find_interval(b);
        auto [lc, rc] = find_interval(c);

        bool flg = false;

        for (int x = la; x <= ra; x ++) {
            int l = max(lb, lc - x), r = min(rb, rc - x);

            if (l <= r) {
                int diff = r - l + 1;
                if (k <= diff) {
                    flg = true;
                    int y = l + k - 1;
                    cout << x << " + " << y << " = " << x + y << '\n';
                    break;
                }
                else k -= diff;
            }
        }

        if (!flg) cout << "-1\n";
    }

    return 0;
}
