                    grid[j][k] = min(grid[j][k], grid[j][i] + grid[i][k]);
                }
            }
        }

        for (int i = 0; i < n; i ++) {
            for (int j = 0; j < n; j ++) {
                dis[0][i][j] = min(dis[0][i][j], grid[i][j]);
            }
        }
    }

    for (int i = 1; i < n; i ++) {
        for (int j = 0; j < n; j ++) {
            for (int k = 0; k < n; k ++) {
                for (int nk = 0; nk < n; nk ++) {
                    dis[i][j][nk] = min(dis[i][j][nk], dis[i - 1][j][k] + dis[0][k][nk]);
                }
            }
        }
    }

    while (q --) {
        int u, v, k;
        cin >> u >> v >> k;
        u --, v --;
        cout << dis[min(k, n - 1)][u][v] << '\n';
    }

    return 0;
}
```

