    vector<int> dp(n + 1, 0);
    for (int i = 0; i < n; i ++) {
        int x;
        cin >> x;
        dp[x] = dp[x - 1] + 1;
    }

    cout << n - *max_element(dp.begin(), dp.end());

    return 0;
