    for i in range(n):
        if s[i] == 'A':
            dp0, dp1 = dp0 + dp1, (0 if s[i + 1] == 'A' else dp1)
        else:
            dp0, dp1 = dp1, (dp0 if s[i + 1] == 'A' else dp1)

    ans += dp1

    print(ans)
