**提示 1：** 纯最短路，只需找到用什么代表状态就行。

我们相当于要求从 $(x,y,z)$ 按某种规则走到 $(1,2,3)$ 的最短路。

于是用三元组表示我们的当前状态。但 $(x,y,z)$ 和其任意排列是等价的，因此我们不妨强行使得 $x\lt y\lt z$ 。

接下来考虑 $(x,y,z)$ 可以到哪些状态。不妨考虑 $x$ 移动， $y,z$ 移动是一回事。

枚举 $x$ 出发的边，我们只需其到达的位置非 $x,y,z$ ，且 $x\to nx$ 的边上标记等于 $y\to z$ 的边上标记即可。

综上，我们完成了图中点的定义（三元组）和边的确定，因此直接进行 BFS 求最短路即可。

为了输出最短路方案，需要记录每个点前一步是什么，注意这件事即可。

时间复杂度为 $\mathcal{O}(n^3\times n)=\mathcal{O}(n^4)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    tx, ty, tz = GMI()
    if tx > ty: tx, ty = ty, tx
    if ty > tz: ty, tz = tz, ty
    if tx > ty: tx, ty = ty, tx
    grid = [[ord(c) for c in I()] for _ in range(n)]

    def f(i, j, k):
        return (i * n + j) * n + k

    prev = [-2] * (n ** 3)
    trans = [-1] * (n ** 3)

    que = [f(0, 1, 2)]
    prev[que[0]] = -1

    for u in que:
        v, z = divmod(u, n)
        x, y = divmod(v, n)

        for nx in range(n):
            if nx == x or nx == y or nx == z: continue
            if grid[x][nx] == grid[y][z]:
                a, b, c = nx, y, z
                if a > b: a, b = b, a
                if b > c: b, c = c, b
                if a > b: a, b = b, a
                nu = f(a, b, c)
                if prev[nu] == -2:
                    prev[nu] = u
                    trans[nu] = nx * n + x
                    que.append(nu)

        for ny in range(n):
            if ny == x or ny == y or ny == z: continue
            if grid[y][ny] == grid[x][z]:
                a, b, c = x, ny, z
                if a > b: a, b = b, a
                if b > c: b, c = c, b
                if a > b: a, b = b, a
                nu = f(a, b, c)
                if prev[nu] == -2:
                    prev[nu] = u
                    trans[nu] = ny * n + y
                    que.append(nu)

        for nz in range(n):
            if nz == x or nz == y or nz == z: continue
            if grid[z][nz] == grid[x][y]:
                a, b, c = x, y, nz
                if a > b: a, b = b, a
                if b > c: b, c = c, b
                if a > b: a, b = b, a
                nu = f(a, b, c)
                if prev[nu] == -2:
                    prev[nu] = u
                    trans[nu] = nz * n + z
                    que.append(nu)

    cur = f(tx, ty, tz)

    if prev[cur] == -2:
        exit(print(-1))

    outs = []

    while cur != f(0, 1, 2):
        a, b = divmod(trans[cur], n)
        outs.append(f'{a + 1} {b + 1}')
        cur = prev[cur]

    print(len(outs))
    print('\n'.join(outs))
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    auto order = [&] (int &x, int &y, int &z) -> void {
        if (x > y) swap(x, y);
        if (y > z) swap(y, z);
        if (x > y) swap(x, y);
    };

    int n, tx, ty, tz;
    cin >> n >> tx >> ty >> tz;
    tx --, ty --, tz --;

    order(tx, ty, tz);

    vector<string> grid(n);
    for (auto &s: grid) cin >> s;

    auto f = [&] (int x, int y, int z) -> int {
        return (x * n + y) * n + z;
    };

    vector<int> prev(n * n * n, -2);
    vector<pair<int, int>> trans(n * n * n);
    queue<array<int, 3>> q;

    q.push({0, 1, 2});
    prev[f(0, 1, 2)] = -1;

    while (!q.empty()) {
        auto [x, y, z] = q.front();
        q.pop();

        for (int nx = 0; nx < n; nx ++) {
            if (nx == x || nx == y || nx == z) continue;
            if (grid[x][nx] == grid[y][z]) {
                int a = nx, b = y, c = z;
                order(a, b, c);
                int nu = f(a, b, c);
                if (prev[nu] == -2) {
                    prev[nu] = f(x, y, z);
                    trans[nu] = {nx + 1, x + 1};
                    q.push({a, b, c});
                }
            }
        }

        for (int ny = 0; ny < n; ny ++) {
            if (ny == x || ny == y || ny == z) continue;
            if (grid[y][ny] == grid[x][z]) {
                int a = x, b = ny, c = z;
                order(a, b, c);
                int nu = f(a, b, c);
                if (prev[nu] == -2) {
                    prev[nu] = f(x, y, z);
                    trans[nu] = {ny + 1, y + 1};
                    q.push({a, b, c});
                }
            }
        }

        for (int nz = 0; nz < n; nz ++) {
            if (nz == x || nz == y || nz == z) continue;
            if (grid[z][nz] == grid[x][y]) {
                int a = x, b = y, c = nz;
                order(a, b, c);
                int nu = f(a, b, c);
                if (prev[nu] == -2) {
                    prev[nu] = f(x, y, z);
                    trans[nu] = {nz + 1, z + 1};
                    q.push({a, b, c});
                }
            }
        }
    }

    int cur = f(tx, ty, tz);
    if (prev[cur] == -2) cout << -1;
    else {
        vector<pair<int, int>> ans;
        while (cur != f(0, 1, 2)) {
            ans.emplace_back(trans[cur]);
            cur = prev[cur];
        }
        cout << ans.size() << '\n';
        for (auto &[x, y]: ans)
            cout << x << ' ' << y << '\n';
    }

    return 0;
}
```

**提示 1：** 两组和相等的最简单的凑法就是每一项都完全相等。按照这个逻辑先配对。

**提示 2：** 如果某一对的元素同时被选了怎么办？

我们要两组元素的对应和相等，一种简单的思路就是让每一项都相等，即：

$x-1=s-y, x+y=s+1$

因此，对于每一个在 $X$ 中的 $x$ ，如果 $s+1-x$ 还没被选中，我们将其纳入我们构造的集合。

接下来只剩下了一堆和为 $s+1$ 的对。此时我们只需也构造对应数量的和为 $s+1$ 的对即可。

上述构造的过程中，由于 $n\leq 5\times 10^5$ ，假设其中 $k$ 项数是不成对的，那么我们先构造了 $k$ 个数让它们成对，接下来 $X$ 中有 $\frac{n-k}{2}$ 对，我们也要构造 $\frac{n-k}{2}$ 对，总对数等于 $n$ ，用到的数共计 $2n$ 个，不会超出范围。（也可以考虑最后的 $2n$ 个元素都是两两配对的）

因此只需找出剩余的还没出现过的对即可。

时间复杂度为 $\mathcal{O}(n+M)$ ，这里判断用数组实现，如果用哈希表可以 $\mathcal{O}(n)$ 。

