**提示 2：** 基于提示 1，可以如何计算？

首先，开始声音的最大强度不超过 $q\times|\Sigma|\leq 26\times 10^6$ 。而这些声音每次传播强度减半，因此 $\log (q\times|\Sigma|)$ 轮就会完全衰减为 $0$ ，就不会往外传播了。这个数字是相对较小的。

而传播 $x$ 轮时，最多有 $\mathcal{O}(x)$ 个点在边界上，因此总传播的格子数是 $\mathcal{O}(x^2)$ 的，因此任何一个声源向外传播的范围不超过 $\mathcal{O}(\log^2 (q\times|\Sigma|))$ 。

这个数字相对而言并不大，因此，我们可以枚举每一个声源进行 BFS 直到该声源无法向外传播。最后将该声源传播到的位置更新噪音强度即可。

时间复杂度为 $\mathcal{O}(nm\log^2(q|\Sigma|))$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m, q, p = MII()
    grid = [I() for _ in range(n)]
    vis = [[0] * m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*':
                vis[i][j] = -1

    ans = [[0] * m for _ in range(n)]
    dirs = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    for i in range(n):
        for j in range(m):
            if grid[i][j].isupper():
                que = [i * m + j]
                vis[i][j] = (ord(grid[i][j]) - ord('A') + 1) * q

                for u in que:
                    x, y = divmod(u, m)
                    ans[x][y] += vis[x][y]

                    for dx, dy in dirs:
                        nx = x + dx
                        ny = y + dy
                        if 0 <= nx < n and 0 <= ny < m and vis[nx][ny] == 0:
                            vis[nx][ny] = vis[x][y] // 2
                            if vis[nx][ny]:
                                que.append(nx * m + ny)

                for u in que:
                    x, y = divmod(u, m)
                    vis[x][y] = 0

    res = 0
    for i in range(n):
        for j in range(m):
            if ans[i][j] > p:
                res += 1

    print(res)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, m, q, p;
    cin >> n >> m >> q >> p;

    vector<string> grid(n);
    for (auto &s: grid) cin >> s;

    vector<vector<int>> vis(n, vector<int>(m, 0));
    for (int i = 0; i < n; i ++) {
        for (int j = 0; j < m; j ++) {
            if (grid[i][j] == '*') {
                vis[i][j] = -1;
            }
        }
    }

    vector<vector<int>> ans(n, vector<int>(m, 0));
    vector<pair<int, int>> dirs = {{-1, 0}, {0, 1}, {1, 0}, {0, -1}};

    for (int i = 0; i < n; i ++) {
        for (int j = 0; j < m; j ++) {
            if (grid[i][j] >= 'A' && grid[i][j] <= 'Z') {
                queue<pair<int, int>> que;
                que.push({i, j});
                vis[i][j] = (grid[i][j] - 'A' + 1) * q;
                vector<pair<int, int>> cur;

                while (!que.empty()) {
                    auto [x, y] = que.front();
                    que.pop();
                    cur.emplace_back(x, y);
                    ans[x][y] += vis[x][y];

                    for (auto &[dx, dy]: dirs) {
                        int nx = x + dx, ny = y + dy;
                        if (nx >= 0 && nx < n && ny >= 0 && ny < m && vis[nx][ny] == 0) {
                            vis[nx][ny] = vis[x][y] / 2;
                            if (vis[nx][ny]) que.push({nx, ny});
                        }
                    }
                }

                for (auto &[x, y]: cur) vis[x][y] = 0;
            }
        }
    }

    int res = 0;
    for (int i = 0; i < n; i ++) {
        for (int j = 0; j < m; j ++) {
            if (ans[i][j] > p) {
                res ++;
            }
        }
    }

    cout << res;

    return 0;
}
