    ans = [[-1] * 10 for _ in range(10)]

    for i in range(10):
        for j in range(10):
            dis = [10] * 10

            dis[i] = 0
            dis[j] = 0
            que = [i, j]

            for u in que:
                nu = (u + i) % 10
                if dis[nu] == 10:
