                    que.append(nu)

                nu = (u + j) % 10
                if dis[nu] == 10:
                    dis[nu] = dis[u] + 1
                    que.append(nu)

            res = 0
            for x in range(10):
                if cnt[x] and dis[x] == 10:
                    break
                res += cnt[x] * dis[x]
            else:
                ans[i][j] = res

    for x in ans:
        print(*x)
