    s = I()

    v1 = [0]
    v2 = [0]

    flg = True

    for c in s:
        if c == '.': flg = False
        else:
            if flg: v1.append(int(c))
            else: v2.append(int(c))

    k1 = len(v1)
    k2 = len(v2)

    for i in range(k2):
        if v2[i] >= 5:
            while i < len(v2):
                v2.pop()
            v2[-1] += 1
            t -= 1
            break

