        t -= 1
        v2.pop()
        v2[-1] += 1

    v1[-1] += v2[0]
    v2[0] = 0

    while v2 and v2[-1] == 0:
        v2.pop()

    for i in range(k1 - 1, -1, -1):
        if v1[i] == 10:
            v1[i] = 0
            v1[i - 1] += 1

    print(''.join(str(v1[i]) for i in range(k1) if i or v1[i]), end='')

    if v2: print('.', ''.join(str(v2[i]) for i in range(1, len(v2))), sep='')
