C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector<int> us, vs;
    vector<vector<int>> path(n);

    for (int i = 0; i < n - 1; i ++) {
        int u, v;
        cin >> u >> v;
        u --, v --;
        us.emplace_back(u);
        vs.emplace_back(v);
        path[u].emplace_back(i);
        path[v].emplace_back(i);
    }

    vector<int> col(n - 1, -1);

    auto dfs = [&] (auto &self, int u) -> void {
        int used = -1;
        for (auto &eid: path[u]) {
            if (col[eid] != -1) {
                used = col[eid];
            }
        }

        int cur = 0;
        for (auto &eid: path[u]) {
            if (col[eid] == -1) {
                while (cur == used)
                    cur ++;
                col[eid] = cur;
                cur ++;
                self(self, us[eid] + vs[eid] - u);
            }
        }
    };

    dfs(dfs, 0);

    int ans = *max_element(col.begin(), col.end()) + 1;

    vector<vector<int>> tmp(ans);
    for (int i = 0; i < n - 1; i ++)
        tmp[col[i]].emplace_back(i);

    cout << ans << '\n';
    for (int i = 0; i < ans; i ++) {
        cout << tmp[i].size() << ' ';
        for (auto &x: tmp[i]) {
            cout << x + 1 << ' ';
        }
        cout << '\n';
    }

    return 0;
}
