**提示 1：** 考虑所有被操作的元素，如果连成了一段长度为 $k$ 的区间，则操作后的 MEX 不会超过 $k$ ，因此最大取值就是全为 $k$ 。依此进行 DP 。

**提示 2：** 如何让一个长度为 $k$ 的段变得全是 $k$ 。

先看提示 1，把所有操作过的位置记录下来，形成了一系列的段，每一段如果长度为 $k$ ，则这一段的最大取值为 $k$ ，因为区间中最多只有 $k$ 个数，最大 MEX 如此。

事实上这个最大值是可以取到的，我们后续会进行构造。而这里，我们先利用这件事进行 DP 。

考虑长度为 $i$ 的前缀的最大和为 $dp[i]$ 。考虑最后一个元素是否经过操作，如果没有，就直接用 $nums[i]$ 作为取值。否则，枚举最后一段的长度 $l$ ，产生的和为 $l^2$ ，因此可以用 $dp[i-l]+l^2$ 更新。

根据上述过程进行 DP，可以计算得到最大和，也可以根据转移关系得到所有需要操作的区间。接下来就要让一个长度为 $k$ 的区间变得全是 $k$ 。

怎么办到呢？我们先对区间进行清零——进行 1 / 2 次全区间操作即可。

接下来，为了使得长度为 $k$ 的区间变得全是 $k$ ，前一步一定是整个区间包含 $0,1,\dots,k-1$ 。

于是考虑构造 $0,1,\dots,i$ 。

我们可以递归构造，假设 $i$ 项的情况已经完成了构造。

- 先令前 $i$ 项为 $0,1,\dots,i-1$ ，这样，整个序列就变成了 $0,1,\dots,i-1,0$ 。

- 再操作一次全区间即可得到 $i,i,\dots,i,i$ 。

- 最后处理前 $i$ 项变回 $0,1,\dots,i-1$ 即可得到 $0,1,\dots, i$ 。

上述构造需要的步骤数量等于 $2f(i-1)+1$ ，因此是 $\mathcal{O}(2^i)$ 量级的，符合要求。

时间复杂度为 $\mathcal{O}(n2^n)$ ，主要来源于构造。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    nums = LII()

    dp = [0] * (n + 1)
    prev = [-1] * (n + 1)

    for i in range(1, n + 1):
        for j in range(i):
            v = dp[j] + (i - j) * (i - j)
            if v > dp[i]:
                dp[i] = v
                prev[i] = j

        v = dp[i - 1] + nums[i - 1]
        if v > dp[i]:
            dp[i] = v
            prev[i] = i - 1

    ops = []

    def mex(l, r):
        vis = set()
        for i in range(l, r):
            vis.add(nums[i])
        for i in range(n + 1):
            if i not in vis:
                return i
        return -1

    def op(l, r):
        ops.append(f'{l + 1} {r}')
        v = mex(l, r)
        for i in range(l, r):
            nums[i] = v
        return v

    def set_zero(l, r):
        if op(l, r):
            op(l, r)

    def mid_process(l, r):
        if l + 1 == r:
            set_zero(l, r)
            return
        mid_process(l, r - 1)
        op(l, r)
        mid_process(l, r - 1)

    def process(l, r):
        set_zero(l, r)
        mid_process(l, r)
        op(l, r)

    cur = n
    while cur:
        p = prev[cur]
        if p < cur - 1 or nums[p] == 0:
            process(p, cur)
        cur = p

    print(dp[n], len(ops))
    print('\n'.join(ops))
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector<int> nums(n);
    for (auto &x: nums) cin >> x;

    vector<int> dp(n + 1, 0), prev(n + 1, -1);
    for (int i = 1; i <= n; i ++) {
        int v;
        for (int j = 0; j < i; j ++) {
            v = dp[j] + (i - j) * (i - j);
            if (v > dp[i]) {
                dp[i] = v;
                prev[i] = j;
            }
        }
        v = dp[i - 1] + nums[i - 1];
        if (v > dp[i]) {
            dp[i] = v;
            prev[i] = i - 1;
        }
    }

    vector<pair<int, int>> ops;

    auto mex = [&] (int l, int r) -> int {
        set<int> vis;
        for (int i = l; i < r; i ++)
            vis.insert(nums[i]);
        for (int i = 0; i <= n; i ++)
            if (vis.find(i) == vis.end())
                return i;
        return -1;
    };

    auto op = [&] (int l, int r) -> int {
        ops.emplace_back(l, r);
        int v = mex(l, r);
        for (int i = l; i < r; i ++)
            nums[i] = v;
        return v;
    };

    auto set_zero = [&] (int l, int r) -> void {
        if (op(l, r)) op(l, r);
    };

    auto mid_process = [&] (auto &self, int l, int r) -> void {
        if (r < 0) return ;
        if (l + 1 == r) set_zero(l, r);
        else {
            self(self, l, r - 1);
            op(l, r);
            self(self, l, r - 1);
        }
    };

    auto process = [&] (int l, int r) -> void {
        set_zero(l, r);
        mid_process(mid_process, l, r);
        op(l, r);
    };

    int cur = n;

    while (cur) {
        int p = prev[cur];
        if (p < cur - 1 || nums[p] == 0)
            process(p, cur);
        cur = p;
    }

    cout << dp[n] << ' ' << ops.size() << '\n';
    for (auto &[x, y]: ops)
        cout << x + 1 << ' ' << y << '\n';

    return 0;
}
```

**提示 1：** 将题目中的条件相当于变量之间满足的等式关系，可以将其转化为图。

**提示 2：** 什么时候会产生矛盾呢？

把每个点的位置关系表示为变量 $x_i$ ，则题中的条件相当于给出了一系列 $x_i$ 对需要满足的方程。

可以考虑以此建立有向图：边 $(u,v,w)$ 表示 $x_v-x_u=w$ 。于是我们只需研究该图是否有矛盾即可。注意需要同时建立边 $x_u-x_v=-w$ 。

考虑其中一个连通块内，如果一个元素数值确定了，则其余元素的数值都可以通过这个点 DFS 得到，因此也都确定了。

在整个连通块中，如果存在一条边不满足要求，则直接返回 `'NO'` 即可，这件事也可以在 DFS 的过程中顺便完成。如果所有连通块都满足要求，返回 `'YES'` 。

当然，本题也可以使用带权并查集来做，具体可以自行搜索相关知识，是比较直接的。

时间复杂度为 $\mathcal{O}(n+m)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    inf = 10 ** 15

    for _ in range(t):
        n, m = MII()
        path = [[] for _ in range(n + 1)]
        us = []
        vs = []
        ws = []

        for i in range(m):
            u, v, w = MII()

            us.append(u)
            vs.append(v)
            ws.append(w)

            path[u].append(i)
            path[v].append(i)

        cur = [inf] * (n + 1)

        flg = True
        for i in range(n + 1):
            if cur[i] == inf:
                cur[i] = 0

                stk = [i]
                while stk:
                    u = stk.pop()
                    for eid in path[u]:
                        if us[eid] == u:
                            v = vs[eid]
                            if cur[v] == inf:
                                cur[v] = cur[u] + ws[eid]
                                stk.append(v)
                            elif cur[v] != cur[u] + ws[eid]:
                                flg = False
                        else:
                            v = us[eid]
                            if cur[v] == inf:
                                cur[v] = cur[u] - ws[eid]
                                stk.append(v)
                            elif cur[v] != cur[u] - ws[eid]:
                                flg = False

        outs.append('YES' if flg else 'NO')

    print('\n'.join(outs))
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int t;
    cin >> t;

    long long inf = 1e15;

    while (t --) {
        int n, m;
        cin >> n >> m;

        vector<vector<pair<int, int>>> path(n + 1);
        for (int i = 0; i < m; i ++) {
            int u, v, w;
            cin >> u >> v >> w;
            path[u].emplace_back(v, w);
            path[v].emplace_back(u, -w);
        }

        vector<long long> cur(n + 1, inf);
        bool flg = true;

        auto dfs = [&] (auto &self, int u) -> void {
            for (auto &[v, w]: path[u]) {
                if (cur[v] == inf) {
                    cur[v] = cur[u] + w;
                    self(self, v);
                }
                else if (cur[v] != cur[u] + w)
                    flg = false;
            }
        };

        for (int i = 0; i <= n; i ++) {
            if (cur[i] == inf) {
                cur[i] = 0;
                dfs(dfs, i);
            }
        }

        cout << (flg ? "YES" : "NO") << '\n';
    }

    return 0;
}
