**提示 1：** 对于一个长方体，答案是多少？

**提示 2：** 两种情况——一个石头、两个石头。后者只需对于一个面找最长的一条边就行。

对于一个长方体，其最大能雕出多大的球呢？是其最短边长度除以 $2$ 。

因此我们只需找到最短边最大的长方体即可。

如果是单个长方体形成的答案，直接取该长方体对应的最短边就行。

否则，两个长方体需要发生拼接，考虑拼接面必须一致。考虑第 $i$ 个石头和前面 $i-1$ 个石头能拼出来的最大的长方体。

我们只需枚举拼接的那个面，找到前 $i-1$ 个石头中，有对应面的剩下一条边尽可能长（这一步是贪心，会使得最小值尽可能大）的长方体。因此，只需维护每个面对应的最大高，及对应的石头即可。

在遍历的过程中不断枚举拼接面，并将当前长方体加入维护即可。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()

    d = {}

    ans = 0
    chosen = [-1]

    for i in range(1, n + 1):
        a, b, c = sorted(MII())

        if a >= ans:
            ans = a
            chosen = [i]

        if (a, b) in d:
            nc, ni = d[(a, b)]
            res = min(a, b, nc + c)
            if res > ans:
                ans = res
                chosen = [ni, i]

        if (a, c) in d:
            nb, ni = d[(a, c)]
            res = min(a, b + nb, c)
            if res > ans:
                ans = res
                chosen = [ni, i]

        if (b, c) in d:
            na, ni = d[(b, c)]
            res = min(na + a, b, c)
            if res > ans:
                ans = res
                chosen = [ni, i]

        if (a, b) not in d or d[(a, b)] < (c, i):
            d[(a, b)] = (c, i)

        if (a, c) not in d or d[(a, c)] < (b, i):
            d[(a, c)] = (b, i)

        if (b, c) not in d or d[(b, c)] < (a, i):
            d[(b, c)] = (a, i)

    print(len(chosen))
    print(*chosen)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    map<pair<int, int>, pair<int, int>> mp;

    int ans = 0;
    vector<int> chosen = {-1};

    for (int i = 1; i <= n; i ++) {
        vector<int> ar(3);
        for (auto &x: ar) cin >> x;
        sort(ar.begin(), ar.end());

        if (ar[0] >= ans)
            ans = ar[0], chosen = {i};

        int a = ar[0], b = ar[1], c = ar[2];

        if (mp.find({a, b}) != mp.end()) {
            auto &[nc, ni] = mp[{a, b}];
            int res = min({a, b, nc + c});
            if (res > ans) {
                ans = res;
                chosen = {ni, i};
            }
        }

        if (mp.find({a, c}) != mp.end()) {
            auto &[nb, ni] = mp[{a, c}];
            int res = min({a, nb + b, c});
            if (res > ans) {
                ans = res;
                chosen = {ni, i};
            }
        }

        if (mp.find({b, c}) != mp.end()) {
            auto &[na, ni] = mp[{b, c}];
            int res = min({na + a, b, c});
            if (res > ans) {
                ans = res;
                chosen = {ni, i};
            }
        }

        mp[{a, b}] = max(mp[{a, b}], {c, i});
        mp[{a, c}] = max(mp[{a, c}], {b, i});
        mp[{b, c}] = max(mp[{b, c}], {a, i});
    }

    cout << chosen.size() << '\n';
    for (auto &x: chosen) cout << x << ' ';

    return 0;
}
```

**提示 1：** 如何能让 `'O'` 发生移动？

**提示 2：** 如何计算密铺图形的方案数？

要让 `'O'` 发生移动，其必须左侧 / 右侧 / 上侧 / 下侧中至少又一个方向放了个 “指着它” 的骨牌。

于是可以枚举指着它的骨牌。考虑使用容斥原理，计算在至少放了 $k$ 个指着它的骨牌的情况下（二进制枚举），密铺整个图形的方案数即可。

接下来就是已经有一些格子被占据的情况下，求剩余图形的密铺方案数。

注意到行数很小，考虑使用行的状态用二进制表示进行 DP 。假设到第 $i$ 列时，前 $i$ 列的骨牌使得最后一列仍有 $v_0$ 对应的位置为空，考虑第 $i+1$ 列的状态 $v_1$ 。

首先第 $i+1$ 列在 $v_0$ 对应的位置必须放下横着的骨牌，因此 $v_0$ 对应的位置必须没有被占据，且 $v_1$ 对应位置必须填满（即对应位置都不为空）。

第 $i+1$ 列除了填补第 $i$ 列的空缺，还可能自己使用竖着的骨牌。容易发现，竖着放骨牌只可能产生 $3$ 种状态。如果设第一行是 $1$ ，第二行是 $2$ ，第三行是 $4$ ，则对应状态为 $0,3,6$ ，都是 $3$ 的倍数。只需看刨除了上面的 “被占据位置” 和 “填前一列位置” 后，剩余位置是否对应为 $3$ 的倍数。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    note = [[0] * n for _ in range(3)]

    x, y = -1, -1
    for i in range(3):
        s = I()
        for j in range(n):
            if s[j] == 'X': note[i][j] = 1
            elif s[j] == 'O':
                note[i][j] = 2
                x, y = i, j

    dirs = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    chosen = []

    for dx, dy in dirs:
        flg = True
        for i in range(1, 3):
            vx, vy = x + dx * i, y + dy * i
            if not (0 <= vx < 3 and 0 <= vy < n and note[vx][vy] == 0):
                flg = False
        if flg:
            chosen.append((dx, dy))

    k = len(chosen)
    ans = 0
    mod = 10 ** 9 + 7

    for msk in range(1, 1 << k):
        c = -1
        for i in range(k):
            if msk >> i & 1:
                c = -c
                dx, dy = chosen[i]
                for j in range(1, 3):
                    note[x + dx * j][y + dy * j] = 1

        dp = [0] * 8
        dp[0] = 1

        ndp = [0] * 8

        for i in range(n):
            must = 0
            for j in range(3):
                if note[j][i]:
                    must |= 1 << j

            for v0 in range(8):
                for v1 in range(8):
                    if v1 & must == 0 and v0 & v1 == 0 and v0 & must == 0 and (7 - v1 - must - v0) % 3 == 0:
                        ndp[v1] += dp[v0]
                        if ndp[v1] >= mod:
                            ndp[v1] -= mod

            for j in range(8):
                dp[j] = ndp[j]
                ndp[j] = 0

        ans += c * dp[0]

        for i in range(k):
            if msk >> i & 1:
                dx, dy = chosen[i]
                for j in range(1, 3):
                    note[x + dx * j][y + dy * j] = 0

    print(ans % mod)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector<vector<int>> note(3, vector<int>(n, 0));
    int x, y;

    for (int i = 0; i < 3; i ++) {
        string s;
        cin >> s;
        for (int j = 0; j < n; j ++) {
            if (s[j] == 'X') note[i][j] = 1;
            else if (s[j] == 'O') {
                note[i][j] = 2;
                x = i, y = j;
            }
        }
    }

    vector<int> dirs = {-1, 0, 1, 0, -1};
    vector<pair<int, int>> chosen;

    for (int i = 0; i < 4; i ++) {
        int dx = dirs[i], dy = dirs[i + 1];
        bool flg = true;

        for (int j = 1; j < 3; j ++) {
            int vx = x  + dx * j, vy = y + dy * j;
            if (!(vx >= 0 && vx < 3 && vy >= 0 && vy < n && note[vx][vy] == 0)) {
                flg = false;
            }
        }

        if (flg) chosen.emplace_back(dx, dy);
    }

    int k = chosen.size(), ans = 0, mod = 1e9 + 7;

    for (int msk = 1; msk < (1 << k); msk ++) {
        int c = -1;
        for (int i = 0; i < k; i ++) {
            if (msk >> i & 1) {
                c = -c;
                auto &[dx, dy] = chosen[i];
                for (int j = 1; j < 3; j ++) {
                    note[x + dx * j][y + dy * j] = 1;
                }
            }
        }

        vector<int> dp(8, 0), ndp(8, 0);
        dp[0] = 1;

        for (int i = 0; i < n; i ++) {
            int must = 0;
            for (int j = 0; j < 3; j ++) {
                if (note[j][i]) {
                    must |= 1 << j;
                }
            }

            for (int v0 = 0; v0 < 8; v0 ++) {
                for (int v1 = 0; v1 < 8; v1 ++) {
                    if ((v1 & must) == 0 && (v0 & v1) == 0 && (v0 & must) == 0 && (7 - v1 - must - v0) % 3 == 0) {
                        ndp[v1] += dp[v0];
                        if (ndp[v1] >= mod) ndp[v1] -= mod;
                    }
                }
            }

            for (int j = 0; j < 8; j ++)
                dp[j] = ndp[j], ndp[j] = 0;
        }

        ans += c * dp[0];
        if (ans >= mod) ans -= mod;
        if (ans < 0) ans += mod;

        for (int i = 0; i < k; i ++) {
            if (msk >> i & 1) {
                auto &[dx, dy] = chosen[i];
                for (int j = 1; j < 3; j ++) {
                    note[x + dx * j][y + dy * j] = 0;
                }
            }
        }
    }

    cout << ans;

    return 0;
}
```

**提示 1：** 字典序最小——只需从头到尾每一步都最小就行。

**提示 2：** 题中的重要限制——同组数不能超过 $k$ 个。

这里要求字典序最小，因此还是常见套路，从头到尾依次最小。

于是，我们只需考虑在有些颜色已经被合并时，当前字符的最优选择为何即可。

当当前颜色对应的颜色组和前一组颜色（有颜色相邻的）的大小之和不超过 $k$ 时，这组颜色可以跟前一组颜色合并。我们不断进行对应的合并就行。

这里可以使用并查集，但事实上，合并过的颜色不会在下一轮贪心时再往前合并，因为如果可以合并，之前贪心的时候就已经合并了。

所以这里可以找到当前颜色的目标后，直接把目标到当前颜色中不等于目标颜色的位置全部改为目标颜色。这样每个位置最多修改一次，时间复杂度是 $\mathcal{O}(k)$ 的。

时间复杂度为 $\mathcal{O}(n+k)$ ，这是最优复杂度，但后面的代码实际是按照 $k^2$ 的实现。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, k = MII()
    nums = LII()

    col = list(range(256))
    sz = [1] * 256

    ans = [0] * n

    for i in range(n):
        while True:
            cur = col[nums[i]]
            if cur == 0: break

            ncur = col[cur - 1]
            if sz[ncur] + sz[cur] > k:
                break

            for j in range(cur, nums[i] + 1):
                col[j] = ncur
            sz[ncur] += sz[cur]

        ans[i] = col[nums[i]]

    print(' '.join(map(str, ans)))
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, k;
    cin >> n >> k;

    vector<int> nums(n);
    for (auto &x: nums) cin >> x;

    vector<int> col(256), sz(256, 1);
    iota(col.begin(), col.end(), 0);

    for (int i = 0; i < n; i ++) {
        while (true) {
            int cur = col[nums[i]];
            if (!cur) break;

            int ncur = col[cur - 1];
            if (sz[ncur] + sz[cur] > k) break;

            for (int j = cur; j <= nums[i]; j ++)
                col[j] = ncur;
            sz[ncur] += sz[cur];
        }
        cout << col[nums[i]] << ' ';
    }

    return 0;
}
```

**提示 1：** 操作之间没啥关联——似乎只能暴力搜索了。

**提示 2：** 可以发现有些不必要的操作。

题中所给的操作很怪——至少是混合起来不可理解的，所以考虑搜索。

但是直接搜索的不同状态可达 $2^{30}$ ，这并不合理，怎么办呢？

就得想办法去掉一些没道理搜的东西。事实上，连续做两次操作 1 就相当于没做，这一步是可以省略的。

于是，我们只需操作序列保证没有连续的 $1$ ，这样搜索的状态就少多了！

因此搜索时，只需记录当前步数、最后一步是否是第一次操作、当前的数组情况即可。

但是这样是不足够的，我们上面相当于删掉了若干组长度为偶数的连续的操作 1。这些步数虽然不对最终数组产生影响，但会影响步数；但事实上，对步数的影响总是偶数。因此，所有距离最终态有偶数步的状态，我们都可以计算其结果作为答案。

将上述所有结果取最大值即可。

上面涉及到了多少状态呢？设一个长度为 $n$ 的以操作 1、操作 2 结尾的合法操作序列分别有 $a_n, b_n$ 个。则：

$a_1=b_1=1,a_n=b_{n-1},b_n=a_{n-1}+b_{n-1}$

时间复杂度为 $\mathcal{O}\left(n\left(\sum\limits_{i=1}^n a_i+\sum\limits_{i=1}^n b_i\right)\right)$ ，事实上是足够小的。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, u, r = MII()
    nums1 = LII()
    nums2 = LII()
    ks = LII()
    perm = LGMI()

    ans = -10 ** 18
    def f(nums, op, last):
        global ans
        if (u - op) % 2 == 0:
            ans = fmax(ans, sum(nums[i] * ks[i] for i in range(n)))
        if op == u: return
        f([nums[x] + r for x in perm], op + 1, 0)
        if not last:
            f([nums[x] ^ nums2[x] for x in range(n)], op + 1, 1)

    f(nums1, 0, 0)
    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, u, r;
    cin >> n >> u >> r;

    vector<int> a(n), b(n), k(n), p(n);
    for (auto &x: a) cin >> x;
    for (auto &x: b) cin >> x;
    for (auto &x: k) cin >> x;
    for (auto &x: p) cin >> x, x --;

    long long ans = -1e18;

    auto dfs = [&] (auto &self, vector<int> &cur, int steps, bool last_op) -> void {
        if (((u - steps) & 1) == 0) {
            long long res = 0;
            for (int i = 0; i < n; i ++)
                res += cur[i] * k[i];
            ans = max(ans, res);
        }
        if (steps == u) return ;

        steps ++;
        vector<int> ncur(n);
        for (int i = 0; i < n; i ++)
            ncur[i] = cur[p[i]] + r;
        self(self, ncur, steps, false);

        if (!last_op) {
            for (int i = 0; i < n; i ++)
                ncur[i] = cur[i] ^ b[i];
            self(self, ncur, steps, true);
        }
    };

    dfs(dfs, a, 0, false);
    cout << ans;

    return 0;
}
```

**提示 1：** 想想给出的点数对答案有啥限制。

一方面，三个点形成一个三角形——所以最后三角形的个数不超过总点数除以 3 。

另一方面，考虑单拎出来一条边。则任意一个三角形中至少有 1 个点不在这条边上，因此答案不超过总点数减去一条边上的点数。不妨减去点数最多的边。

上述两者取最小值即可。为何能构造呢？可以根据总点数进行数学归纳法进一步证明。

时间复杂度为 $\mathcal{O}(n)$ 。

