    cin.tie(0);
    cout.tie(0);

    int n, m, k;
    cin >> n >> m >> k;

    vector<int> ispos(n + 1, 0);
    for (int i = 0; i < k; i ++) {
        int x;
        cin >> x;
        ispos[x] = 1;
    }

    vector<pair<int, int>> edges(m);
    vector<vector<int>> path(n + 1);

    for (auto &[u, v]: edges) {
