        if c == ' ' or c == '-':
            nums.append(cnt)
            cnt = 0

    nums.append(cnt)

    l = max(nums)
    r = 10 ** 6

    while l <= r:
        m = (l + r) // 2
        cnt = 1
        cur = 0
        for x in nums:
            cur += x
            if cur > m:
                cnt += 1
                cur = x
        if cnt > k: l = m + 1
