int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    map<char, pair<int, int>> mp;
    mp['L'] = {-1, 0};
    mp['R'] = {1, 0};
    mp['D'] = {0, -1};
    mp['U'] = {0, 1};

    int t;
    cin >> t;

    while (t --) {
        string s;
