                    auto &[tx, ty] = mp[nc];
                    if (vx + tx != cx || vy + ty != cy) {
                        vx += tx;
                        vy += ty;
                    }
                }

                if (!vx && !vy)
                    x = cx, y = cy;
            }
        }

        cout << x << ' ' << y << '\n';
