    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, k;
    cin >> n >> k;

    vector<int> nums(n);
    for (auto &v: nums) cin >> v;

    int l = 0, r = 0, v = 0;
    int ans = -1, choice = -1;

    while (l < n) {
