    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    string s1, s2;

    cin >> n >> s1 >> s2;

    unionfind uf(26);
    vector<pair<char, char>> ans;

    for (int i = 0; i < n; i ++) {
        if (uf.merge(s1[i] - 'a', s2[i] - 'a')) {
            ans.emplace_back(s1[i], s2[i]);
