**提示 1：** 由于最后相当于使得字典序最大 / 最小化，因此每一步贪心选能选的最大编号 / 最小编号的方块即可。

**提示 2：** 根据提示 1，我们只需维护当前可以选择的方块，并能做到快速提取其中未被选择的最大值和最小值即可。

请先看提示。

每一步都只需要贪心取即可，不涉及到博弈，我们只需维护可以选择的方块就行。

如何检查取走一个方块是否合法呢？我们就要看它是不是上面的某个方块的唯一支撑。如果是，则不合法。

接下来维护不是唯一支撑的所有方块。

在去掉一个方块时，这个结构会发生什么变化呢？这个方块底下的唯一支撑可以被取走了；这个方块同一层的某个位置可能变成唯一支撑（这个位置不会离当前位置太远）。

于是我们维护的结构需要支持增删元素并提取最值，只需使用懒删除堆即可。

下面的写法没有直接找同层中变为唯一支撑的元素，是在弹出答案时多一层检查，想想为啥这样也是对的（不会超过时间复杂度要求）。

（本质上是因为每个元素只会这样错误弹出一次）

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()

    pts = []
    for _ in range(n):
        x, y = MII()
        pts.append((x, y))

    d = {v: i for i, v in enumerate(pts)}

    used = [0] * n
    pq1 = []
    pq2 = []

    def find_support(x, y):
        cnt = 0
        for dx in range(-1, 2):
            if (x + dx, y - 1) in d:
                cnt += 1
        return cnt

    def check(x, y):
        if (x, y) not in d: return False
        for dx in range(-1, 2):
            if (x + dx, y + 1) in d and find_support(x + dx, y + 1) == 1:
                return False
        return True

    for i in range(n):
        if check(pts[i][0], pts[i][1]):
            pq1.append(-i)
            pq2.append(i)

    heapify(pq1)
    heapify(pq2)

    ans = 0
    mod = 10 ** 9 + 9

    for i in range(n):
        while True:
            if i % 2 == 0:
                while used[-pq1[0]]:
                    heappop(pq1)
                u = -heappop(pq1)
            else:
                while used[pq2[0]]:
                    heappop(pq2)
                u = heappop(pq2)

            x, y = pts[u][0], pts[u][1]

            if check(x, y):
                ans = (ans * n + u) % mod
                used[u] = 1
                del d[(x, y)]

                for dx in range(-1, 2):
                    if check(x + dx, y - 1):
                        heappush(pq1, -d[(x + dx, y - 1)])
                        heappush(pq2, d[(x + dx, y - 1)])
                break

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector<pair<int, int>> pts(n);
    for (auto &[x, y]: pts)
        cin >> x >> y;

    map<pair<int, int>, int> mp;
    for (int i = 0; i < n; i ++)
        mp[pts[i]] = i;

    vector<int> used(n);
    priority_queue<int> pq1;
    priority_queue<int, vector<int>, greater<int>> pq2; 

    auto find_support = [&] (int x, int y) -> int {
        int cnt = 0;
        for (int dx = -1; dx < 2; dx ++) {
            if (mp.find({x + dx, y - 1}) != mp.end()) {
                cnt ++;
            }
        }
        return cnt;
    };

    auto check = [&] (int x, int y) -> bool {
        if (mp.find({x, y}) == mp.end()) return false;
        for (int dx = -1; dx < 2; dx ++) {
            if (mp.find({x + dx, y + 1}) != mp.end() && find_support(x + dx, y + 1) == 1) {
                return false;
            }
        }
        return true;
    };

    for (int i = 0; i < n; i ++) {
        if (check(pts[i].first, pts[i].second)) {
            pq1.push(i);
            pq2.push(i);
        }
    }

    int ans = 0, mod = 1e9 + 9;

    for (int i = 0; i < n; i ++) {
        while (true) {
            int u;
            if (i % 2 == 0) {
                while (used[pq1.top()]) pq1.pop();
                u = pq1.top(), pq1.pop();
            }
            else {
                while (used[pq2.top()]) pq2.pop();
                u = pq2.top(), pq2.pop();
            }

            auto &[x, y] = pts[u];

            if (check(x, y)) {
                ans = (1ll * ans * n + u) % mod;
                used[u] = 1;
                mp.erase(pts[u]);

                for (int dx = -1; dx < 2; dx ++) {
                    if (check(x + dx, y - 1)) {
                        int v = mp[{x + dx, y - 1}];
                        pq1.push(v);
                        pq2.push(v);
                    }
                }
                break;
            }
        }
    }

    cout << ans;

    return 0;
}
```

**提示 1：** 容量越大越容易到终点。

**提示 2：** 对于某个容量，如何计算两站之间的最小成本？

首先，容量越大越容易到终点。

而成本只跟初始租赁成本有关，因此，我们只需算出一个最小容量，再找到所有容量比最小容量大的车，取其成本最小值即可。

这里的最小容量可以仅仅在已有的可选容量中二分。

接下来考虑检查使用某个容量的车能否在 $t$ 时间内到达终点。

假设某两站之间的距离为 $s$ 。

- 如果 $s$ 超过了容量，则无法到达。

- 先假定这段路都是按慢的速度走的，这样需要的时间是 $2s$ ，多出来的油是 $v-s$ 。而多出来的每单位油可以使得每单位的路减小一单位的用时，因此最小用时为 $2s-\min(v-s,s)$ 。（直接用这个式子不容易爆 `int` ）

将每一段的答案求和，即可得到某个容量的最小时间，也就完成了二分中的检查工作。

时间复杂度为 $\mathcal{O}((n+k)\log n+k\log k)$ 来源于二分与排序。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, k, s, t = MII()

    cs = []
    vs = []

    for _ in range(n):
        c, v = MII()
        cs.append(c)
        vs.append(v)

    st_range = sorted(range(n), key=lambda x: vs[x])

    stations = [0] + LII() + [s]
    stations.sort()

    inf = 2 * 10 ** 9 + 10

    l, r = 0, n - 1
    while l <= r:
        m = (l + r) // 2

        v = vs[st_range[m]]

        total = 0
        for i in range(k + 1):
            dis = stations[i + 1] - stations[i]
            if dis > v:
                total = inf
                break
            else:
                total += 2 * dis - fmin(dis, v - dis)

        if total <= t: r = m - 1
        else: l = m + 1

    print(min(cs[st_range[i]] for i in range(l, n)) if l < n else -1)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, k, s, t;
    cin >> n >> k >> s >> t;

    vector<pair<int, int>> cars(n);
    for (auto &[x, y]: cars)
        cin >> y >> x;

    sort(cars.begin(), cars.end());

    vector<int> stations(k + 2);
    for (int i = 1; i <= k; i ++)
        cin >> stations[i];

    stations[0] = 0, stations[k + 1] = s;
    sort(stations.begin(), stations.end());

    int l = 0, r = n - 1, inf = 2e9 + 10;

    while (l <= r) {
        int m = (l + r) / 2;
        int v = cars[m].first, total = 0;

        for (int i = 0; i <= k; i ++) {
            int dis = stations[i + 1] - stations[i];
            if (dis > v) {
                total = inf;
                break;
            }
            else total += 2 * dis - min(dis, v - dis);
        }

        if (total <= t) r = m - 1;
        else l = m + 1;
    }

    int ans = inf;
    for (int i = l; i < n; i ++)
        ans = min(ans, cars[i].second);

    cout << (ans < inf ? ans : -1);

    return 0;
}
