    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector<int> nums(n);
    long long ans = 0;

    for (auto &x: nums)
        cin >> x, ans -= x;

    for (int i = n - 2; i >= 0; i --)
        nums[i] = max(nums[i], nums[i + 1] - 1);

    for (int i = 1; i < n; i ++)
        nums[i] = max(nums[i - 1], nums[i]), ans += nums[i];

