**提示 1：** 实际上没有那么多花里胡哨的操作。

**提示 2：** 每次操作的元素数量很有限。

首先，因为 $4=2+2,5=2+3$ ，所以我们只需考虑操作 $2$ 或 $3$ 个数。

而我们操作时，不妨操作最大的几个数。直觉上讲，可以理解为如果操作了较小的数会使得数组更加的不平均。实际证明可以找后续的操作交换，因为小的数的总操作次数一定可以更少。

那么我们怎么选择是操作两个元素还是三个元素呢？

由于操作的是最大元素，我们考虑最大元素本身。

此时，如果最大元素的出现频率大于等于 $2$ ，则我们可以使用 $2/3$ 把这些最大值全部减去 $1$ 。之后，最大值的出现频率总是不小于 $2$ 的（因为原先的最大元素操作后虽然减小了，但还是最大元素），于是可以一步一步减小最大值而不改变其他取值，保证了最终结果就是数组的最小值。

否则，最大值只出现了一次，而前面已经说过了只操作最大的几个元素，只是选择操作的元素个数。此时，应当选择操作最大的两个元素，这样可以使得数组变小的元素尽可能少，保证在最大元素能尽早出现频率不小于 $1$ ，变为前一种情况。

时间复杂度为 $\mathcal{O}(n^2m)$ ，在一个数取 $0$ ，剩余都取 $100$ 时达到。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    nums = LII()

    ops = []

    def op(idxs):
        for i in idxs:
            nums[i] = fmax(0, nums[i] - 1)
        res = ['0'] * n
        for i in idxs:
            res[i] = '1'
        ops.append(''.join(res))

    while min(nums) != max(nums):
        v = max(nums)
        idxs = [i for i in range(n) if nums[i] == v]
        c = len(idxs)

        if c > 1:
            if c % 2 == 0:
                for i in range(0, c, 2):
                    op([idxs[i], idxs[i + 1]])
            else:
                op(idxs[:3])
                for i in range(3, c, 2):
                    op([idxs[i], idxs[i + 1]])
        else:
            idx = -1
            for i in range(n):
                if nums[i] != v and (idx == -1 or nums[i] > nums[idx]):
                    idx = i
            op([idx, idxs[0]])

    print(nums[0])
    print(len(ops))
    print('\n'.join(ops))
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector<int> nums(n);
    for (auto &v: nums)
        cin >> v;

    vector<string> ops;

    auto op = [&] (vector<int> idxs) -> void {
        for (auto &i: idxs) nums[i] = max(nums[i] - 1, 0);
        string res(n, '0');
        for (auto &i: idxs) res[i] = '1';
        ops.emplace_back(res);
    };

    while (*min_element(nums.begin(), nums.end()) != *max_element(nums.begin(), nums.end())) {
        int v = *max_element(nums.begin(), nums.end());
        vector<int> idxs;
        for (int i = 0; i < n; i ++) {
            if (nums[i] == v) {
                idxs.emplace_back(i);
            }
        }
        int c = idxs.size();

        if (c > 1) {
            if (c % 2 == 0) {
                for (int i = 0; i < c; i += 2) {
                    op({idxs[i], idxs[i + 1]});
                }
            }
            else {
                op({idxs[0], idxs[1], idxs[2]});
                for (int i = 3; i < c; i += 2) {
                    op({idxs[i], idxs[i + 1]});
                }
            }
        }
        else {
            int idx = -1;
            for (int i = 0; i < n; i ++) {
                if (nums[i] != v && (idx == -1 || nums[i] > nums[idx])) {
                    idx = i;
                }
            }
            op({idx, idxs[0]});
        }
    }

    cout << nums[0] << '\n';
    cout << ops.size() << '\n';
    for (auto &x: ops) cout << x << '\n';

    return 0;
}
```

**提示 1：** 相当于选 $k$ 个位置当山头的最小成本。

**提示 2：** 特殊情况时山头之间只隔了一个山谷。

我们考虑选择山头后计算成本。

山头需要满足的条件很显然，就是两个山头之间至少间隔为 $2$ 。

考虑前 $i$ 个位置中选了 $cnt$ 个山头的最小成本为 $dp[i][cnt]$ ，则继续选择 $j$ 为山头的最小成本为 $dp[i][cnt]+cost(j)$ ，其中 $cost(j)$ 为让 $j$ 成为山头的最小成本。

于是，我们需要找到所有满足 $i\leq j-2$ 的上述成本的最小值，只需维护一个前缀最小值即可。

特殊情况是 $j=i+2$ ，此时 $i+1$ 的调整在 $i$ 和 $j$ 处各自算了一个成本，于是单独考虑这一步转移，减去多算的成本即可。

可以根据选择的山头数量一层层 DP ，这样空间复杂度可以下降到 $\mathcal{O}(n)$ 。

时间复杂度为 $\mathcal{O}(n^2)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    nums = LII()

    k = (n + 1) // 2
    ans = [-1] * k

    inf = 10 ** 9

    cost = [0] * n

    for i in range(n):
        if i: cost[i] += fmax(nums[i - 1] - nums[i] + 1, 0)
        if i < n - 1: cost[i] += fmax(nums[i + 1] - nums[i] + 1, 0)

    dp = cost[:]
    pref = [0] * n

    ans[0] = min(dp)

    for i in range(1, k):
        pref[0] = dp[0]
        for j in range(1, n):
            pref[j] = fmin(pref[j - 1], dp[j])

        for j in range(n - 1, 1, -1):
            dp[j] = fmin(pref[j - 2] + cost[j], dp[j - 2] + cost[j] - fmax(nums[j - 1] - fmax(nums[j], nums[j - 2]) + 1, 0))

        dp[0] = inf
        dp[1] = inf
        ans[i] = min(dp)

    print(' '.join(map(str, ans)))
```

C++ 做法如下——

```cpp []

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector<int> nums(n);
    for (auto &x: nums)
        cin >> x;

    int k = (n + 1) / 2;

    int inf = 1e9;
    vector<int> cost(n);
    for (int i = 0; i < n; i ++) {
        if (i) cost[i] += max(nums[i - 1] - nums[i] + 1, 0);
        if (i < n - 1) cost[i] += max(nums[i + 1] - nums[i] + 1, 0);
    }

    vector<int> dp = cost, ndp(n, inf), pref(n);
    cout << *min_element(dp.begin(), dp.end()) << ' ';

    for (int i = 1; i < k; i ++) {
        pref[0] = dp[0];
        for (int j = 1; j < n; j ++) 
            pref[j] = min(pref[j - 1], dp[j]);

        for (int j = n - 1; j >= 2; j --)
            dp[j] = min(dp[j - 2] + cost[j] - max(nums[j - 1] - max(nums[j], nums[j - 2]) + 1, 0), pref[j - 2] + cost[j]);

        dp[0] = inf, dp[1] = inf;
        cout << *min_element(dp.begin(), dp.end()) << ' ';
    }

    return 0;
}
