int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, m;
    cin >> n >> m;

    vector<long long> nums1(n), nums2(m);
    long long v1 = 0, v2 = 0;

    for (auto &x: nums1)
        cin >> x, v1 += x;

    for (auto &x: nums2) 
        cin >> x, v2 += x;

    long long ans1 = 0, ans2 = 0;

    for (auto &x: nums1)
        ans1 += min(v2, x);
    ans1 += v2 - min(*max_element(nums1.begin(), nums1.end()), v2);

    for (auto &x: nums2)
        ans2 += min(v1, x);
    ans2 += v1 - min(*max_element(nums2.begin(), nums2.end()), v1);

    cout << min(ans1, ans2);

    return 0;
}
