        else {
            vector<int> to_pair(n, -1);
            vector<int> ans(m);
            iota(ans.begin(), ans.end(), 0);

            for (auto &e: mf.edges()) {
                if (e.flow && e.from < n) {
                    int u = e.to - n;
                    if (to_pair[e.from] != -1) {
                        ans[u] = to_pair[e.from];
                        to_pair[e.from] = -1;
                    }
                    else to_pair[e.from] = e.to - n;
                }
            }

            for (auto &x: ans) cout << x + 1 << ' ';
        }
        cout << '\n';
    }

    return 0;
}
