int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int t;
    cin >> t;

    while (t --) {
        string s1, s2;
        cin >> s1 >> s2;

        int k = s1.size(), a = 0, b = 0, pos = k - 1;
        for (int i = k - 2; i >= 0; i --) {
            if (s1[i] < s1[pos]) pos = i;
            else if (s1[i] > s1[pos]) a = i, b = pos;
