    for (int i = 0; i < n - 1; i ++) {
        int u, v;
        cin >> u >> v;
        u --, v --;
        path[u].emplace_back(v);
        path[v].emplace_back(u);
    }

    cout << 1 << ' ';

    auto operate = [&] (int x) -> void {
        cols[x] = -cols[x];
        cout << x + 1 << ' ';
    };

    auto dfs = [&] (auto &self, int u, int p) -> void {
        if (u > 0) operate(u);
        for (auto &v: path[u]) {
            if (v != p) {
                self(self, v, u);
            }
        }
        if (u > 0) operate(p);
        if (cols[u] != 1) {
            if (u > 0) {
                operate(u);
                operate(p);
            }
            else {
                int v = path[u][0];
                operate(v);
                operate(u);
                operate(v);
            }
        }
    };

    dfs(dfs, 0, -1);

    return 0;
}
```

**提示 1：** 这题有哪些状态是重要的？

**提示 2：** 如何进行状态转移？

比较明显的需要使用 DP 解决的问题。

我们最后需要判断两件事：是否赢了足够的次数，是否装下了足够的奖品。

因此我们维护的状态至少包含：当前获胜的次数、一个判断是否装下奖品的变量。

对于后者，我们可以用 “当前袋子的剩余空间” 进行维护，这样就可以快速进行状态转移了。

整体而言，我们需要遍历每个位置，枚举当前位置是否中奖进行状态转移。第一个状态的总数为 $\mathcal{O}(n)$ 的，第二个状态的总数为 $\mathcal{O}(nM)$ 的，这样总时间复杂度达到了 $\mathcal{O}(n\times n\times nM)=\mathcal{O}(n^3M)$ （最前面的 $n$ 是数组长度），不满足要求。

但是实际上，背包的空闲空间超过 $200$ 就没意义了，因为不用装那么多东西，所以跟 $200$ 取最小值就行（也可以是 $n$ ） 。

最后，空闲空间暂时为负怎么办呢？我们可以先处理那些增大空闲空间的游戏，再处理那些减小空闲空间的游戏。这样，合法的游戏过程中一定不会出现负容量。

时间复杂度为 $\mathcal{O}(n^3)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, l, k = MII()
    probs = [v / 100 for v in MII()]
    vals = LII()

    dp = [[0] * 201 for _ in range(n + 1)]
    dp[0][k] = 1

    ndp = [[0] * 201 for _ in range(n + 1)]

    for idx in range(n):
        if vals[idx] >= 0:
            for i in range(n + 1):
                for j in range(201):
                    if dp[i][j]:
                        ndp[i][j] += (1 - probs[idx]) * dp[i][j]
                        ndp[i + 1][fmin(j + vals[idx], 200)] += probs[idx] * dp[i][j]

            for i in range(n + 1):
                for j in range(201):
                    dp[i][j] = ndp[i][j]
                    ndp[i][j] = 0

    for idx in range(n):
        if vals[idx] == -1:
            for i in range(n + 1):
                for j in range(201):
                    if dp[i][j]:
                        ndp[i][j] += (1 - probs[idx]) * dp[i][j]
                        if j: ndp[i + 1][j - 1] += probs[idx] * dp[i][j]

            for i in range(n + 1):
                for j in range(201):
                    dp[i][j] = ndp[i][j]
                    ndp[i][j] = 0

    print(sum(sum(x) for x in dp[l:]))
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, l, k;
    cin >> n >> l >> k;

    vector<int> probs(n), vals(n);

    for (auto &v: probs) cin >> v;
    for (auto &v: vals) cin >> v;

    vector<vector<long double>> dp(n + 1, vector<long double>(201, 0)), ndp(n + 1, vector<long double>(201, 0));

    dp[0][k] = 1;

    for (int idx = 0; idx < n; idx ++) {
        if (vals[idx] >= 0) {
            for (int i = 0; i <= n; i ++) {
                for (int j = 0; j <= 200; j ++) {
                    if (dp[i][j]) {
                        long double p = (long double)1.0 * probs[idx] / 100;
                        ndp[i][j] += (-p + 1) * dp[i][j];
                        ndp[i + 1][min(j + vals[idx], 200)] += p * dp[i][j];
                    }
                }
            }
            for (int i = 0; i <= n; i ++) {
                for (int j = 0; j <= 200; j ++) {
                    dp[i][j] = ndp[i][j];
                    ndp[i][j] = 0;
                }
            }
        }
    }

    for (int idx = 0; idx < n; idx ++) {
        if (vals[idx] == -1) {
            for (int i = 0; i <= n; i ++) {
                for (int j = 0; j <= 200; j ++) {
                    if (dp[i][j]) {
                        long double p = (long double)1.0 * probs[idx] / 100;
                        ndp[i][j] += (-p + 1) * dp[i][j];
                        if (j) ndp[i + 1][j - 1] += p * dp[i][j];
                    }
                }
            }
            for (int i = 0; i <= n; i ++) {
                for (int j = 0; j <= 200; j ++) {
                    dp[i][j] = ndp[i][j];
                    ndp[i][j] = 0;
                }
            }
        }
    }

    long double ans = 0;
    for (int i = l; i <= n; i ++) {
        for (int j = 0; j <= 200; j ++) {
