**提示 1：** 每个消息的传播相当于是树上的一条路径。

**提示 2：** 注意树的形态是固定的。

**提示 3：** 如何判断一点是否在路径上？

将每个人向其直属上司连边，则我们可以得到几棵树，而消息的传播总是树上的一条路径。因此我们只需找到路径并判断即可。

首先，这棵树怎么确定呢？我们可以离线来做，先读入所有的查询进而得到所有需要连接的边。

在连好所有的边后，如何确定我们每个消息的传播路径呢？我们可以使用并查集，每次将子结点合并到父结点上，这样就可以直接查询当前结点合并到的位置，进而得到路径的端点。（这里不能使用并查集从小到大合并的优化，不然就不是子节点连到父节点的方向了）

得到路径后，如何判断一个点是否在路径上呢？这条路径是从一个结点 $x$ 走向祖先结点 $y$ 的，我们只需判断要查询的点是否是 $x$ 的祖先，以及 $y$ 是否为查询的点的祖先。

这件事有很多种判断方法，可以转成欧拉序的区间后，变为区间包含的判断。下面按照这个逻辑实现。

（当然，如果你没想到这一层，也可以直接使用树链剖分等方法）

查询次数为 $\mathcal{O}(n\log n+q)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, q = MII()

    ts = []
    xs = []
    ys = []

    parent = [0] * (n + 1)
    parent[0] = -1

    for _ in range(q):
        query = LII()

        ts.append(query[0])
        xs.append(query[1])
        ys.append(-1 if len(query) < 3 else query[2])

        if query[0] == 1:
            parent[query[1]] = query[2]

    path = [[] for _ in range(n + 1)]
    for i in range(1, n + 1):
        p = parent[i]
        path[i].append(p)
        path[p].append(i)

    ls = [-1] * (n + 1)
    rs = [-1] * (n + 1)

    tmstamp = 0

    stk = [0]

    while stk:
        u = stk.pop()
        if u >= 0:
            ls[u] = tmstamp
            tmstamp += 1
            stk.append(~u)

            for v in path[u]:
                if parent[v] == u:
                    stk.append(v)
        else:
            rs[~u] = tmstamp

    dsu = UnionFind(n + 1)
    outs = []

    starts = [0]
    ends = [0]

    for i in range(q):
        if ts[i] == 1:
            dsu.merge(ys[i], xs[i])
        elif ts[i] == 2:
            starts.append(xs[i])
            ends.append(dsu.find(xs[i]))
        else:
            x = starts[ys[i]]
            y = ends[ys[i]]

            outs.append('YES' if ls[y] <= ls[xs[i]] <= ls[x] and rs[x] <= rs[xs[i]] <= rs[y] else 'NO')

    print('\n'.join(outs))
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, q;
    cin >> n >> q;

    vector<int> ts(q), xs(q), ys(q);
    vector<int> parent(n + 1, 0);
    parent[0] = -1;

    for (int i = 0; i < q; i ++) {
        cin >> ts[i] >> xs[i];
        if (ts[i] != 2) cin >> ys[i];
        if (ts[i] == 1) parent[xs[i]] = ys[i];
    }

    vector<vector<int>> path(n + 1);
    for (int i = 1; i <= n; i ++) {
        int p = parent[i];
        path[i].emplace_back(p);
        path[p].emplace_back(i);
    }

    vector<int> ls(n + 1, -1), rs(n + 1, -1);
    int tmstamp = 0;

    auto dfs = [&] (auto &self, int u) -> void {
        ls[u] = tmstamp;
        tmstamp ++;
        for (auto &v: path[u]) {
            if (parent[v] == u) {
                self(self, v);
            }
        }
        rs[u] = tmstamp;
    };

    dfs(dfs, 0);

    unionfind dsu(n + 1);
    vector<int> starts = {0}, ends = {0};
    for (int i = 0; i < q; i ++) {
        if (ts[i] == 1) dsu.merge(ys[i], xs[i]);
        else if (ts[i] == 2) {
            starts.emplace_back(xs[i]);
            ends.emplace_back(dsu.leader(xs[i]));
        }
        else {
            int x = starts[ys[i]], y = ends[ys[i]];
            cout << (ls[y] <= ls[xs[i]] && ls[xs[i]] <= ls[x] &&
                rs[x] <= rs[xs[i]] && rs[xs[i]] <= rs[y] ? "YES" : "NO") << '\n';
        }
    }

    return 0;
}
```

**提示 1：** 只有相邻两项有相互之间的限制。因此前缀构造完后，只有前缀的最后一项影响后续构造。

**提示 2：** 可以利用提示 1 进行 DP 。

只需注意，在本题中，每个点取值的限制只跟相邻的位置有关。

于是，如果我们构造好了长度为 $i$ 的前缀，在考虑长度为 $i+1$ 的前缀的构造时，只需看第 $i$ 项是什么再填入新的数字即可。

因此可知，最后一项是唯一重要的状态。我们进行 DP ，用 $dp[i][j]$ 表示长度为 $i$ 且最后一项是 $j$ 的前缀是否有办法构造，再枚举所有可行的新的一位即可。

最后要构造方案，只需在 DP 的过程中记录当前状态是从哪里转移过来的就行。

时间复杂度为 $\mathcal{O}(n)$ 。本题也可以进行贪心，将除了等号的部分构造完，再尝试上下平移使得满足等号的条件，但相对需要处理的细节就多了很多。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    nums = LII()

    dp = [[-2] * n for _ in range(6)]

    for i in range(1, 6):
        dp[i][0] = -1

    for i in range(1, n):
        for j in range(1, 6):
            if dp[j][i - 1] != -2:
                for nj in range(1, 6):
                    if (nums[i] > nums[i - 1] and nj > j) or \
                        (nums[i] == nums[i - 1] and nj != j) or \
                        (nums[i] < nums[i - 1] and nj < j):
                        dp[nj][i] = j

    for i in range(1, 6):
        if dp[i][n - 1] != -2:
            ans = [i]
            for j in range(n - 1, 0, -1):
                ans.append(dp[ans[-1]][j])
            ans.reverse()
            print(' '.join(map(str, ans)))
            exit()

    print(-1)
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector<int> nums(n);
    for (auto &x: nums)
        cin >> x;

    vector<vector<int>> dp(6, vector<int>(n, -2));

    for (int i = 1; i <= 5; i ++)
        dp[i][0] = -1;

    for (int i = 1; i < n; i ++) {
        for (int j = 1; j <= 5; j ++) {
            if (dp[j][i - 1] != -2) {
                for (int nj = 1; nj <= 5; nj ++) {
                    if ((nums[i] > nums[i - 1] && nj > j) || 
                        (nums[i] == nums[i - 1] && nj != j) ||
                        (nums[i] < nums[i - 1] && nj < j)) {
                        dp[nj][i] = j;
                    }
                }
            }
        }
    }

    for (int i = 1; i <= 5; i ++) {
        if (dp[i][n - 1] != -2) {
            vector<int> ans = {i};
