int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    vector<int> cnt(200002, 0);

    int n;
    cin >> n;

    vector<int> nums(n);
    for (auto &v: nums)
        cin >> v, cnt[v] ++;

    int ans = 0, start = -1;

    int pt = 0;
    while (pt < cnt.size()) {
        if (cnt[pt] > 1) {
            int lpt = pt, cur = 0;
            while (cnt[pt] > 1) {
                cur += cnt[pt];
                pt ++;
            }
            if (cnt[lpt - 1]) cur ++;
            if (cnt[pt]) cur ++;
            if (cur > ans) {
                ans = cur;
                start = lpt;
