        if (cnt[l - 1]) ans.emplace_back(l - 1);

        for (int i = l; i < r; i ++)
            ans.emplace_back(i);

        if (cnt[r]) ans.emplace_back(r);

        for (int i = r - 1; i >= l; i --) {
            for (int j = 0; j < cnt[i] - 1; j ++) {
                ans.emplace_back(i);
            }
