    long long n, d, s;
    cin >> n >> d >> s;

    n /= s;
    d /= s;

    if (n <= d + 1) cout << n * s;
    else {
        n = min(n, 2 * d);
        for (int i = 2; i <= 1000000; i ++) {
            if (n % i == 0 && n - n / i <= d) {
                return cout << n * s, 0;
            }
        }
        cout << (n - 1) * s;
    }

    return 0;
}
