int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;

    cin >> n;

    if (n & 1) cout << -1;
    else {
        for (int i = 0; i < n; i ++) {
            if (i) cout << '\n';
            for (int j = 0; j < n; j ++) {
                for (int k = 0; k < n; k ++) {
                    cout << ((i & 1) ^ ((j >> 1) & 1) ^ ((k >> 1) & 1) ? 'w' : 'b');
