                cout << d - depth[v] << endl;
                if (v > 0) {
                    fens[chain_id].add(d - depth[v], x);
                    if (depth[v] + d < chain_len[chain_id])
                        fens[chain_id].add(depth[v] + d, -x);
                }
            }
        }
    }

    return 0;
}
