int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int t;
    cin >> t;

    while (t --) {
        int x;
        cin >> x;
        if (x == 0) cout << "1 1\n";
        else {
            bool flg = false;
            for (int i = 1; i * i < x; i ++) {
                if (x % i == 0) {
                    int a = x / i, b = i;
                    int n = (a + b) / 2, m = (a + b) / (a - b);
                    if (1ll * n * n - 1ll * (n / m) * (n / m) == x) {
                        flg = true;
                        cout << n << ' ' << m << '\n';
                        break;
                    }
                }
            }
            if (!flg) cout << "-1\n";
        }
    }

