    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector<int> ans;
    for (int i = 1000; i > 1; i --) {
        while (n >= i * (i - 1) / 2) {
            n -= i * (i - 1) / 2;
            ans.emplace_back(i);
        }
    }

    if (ans.size()) {
        for (int i = 0; i < ans.size(); i ++) {
            while (ans[i] --) {
                cout << (char)('a' + i);
            }
        }
    }
    else cout << 'a';

    return 0;
}
