**提示 1：** 可以每个连通块分别考虑。

**提示 2：** 如果一个连通块中一个元素确定了，则剩余元素也都确定了。

**提示 3：** 什么情况下一个连通块数值不可变？什么情况下可变？可变的情况下如何求解最优化问题？

首先，这里每个连通块的结果互不影响，因此可以分别考虑每个连通块，最后再汇总结果。

而对于一个连通块，如果一个元素的数值确定了，则其邻接的点的数值也都确定了，进而不断用相邻关系，可以确定连通块内每一个元素的数值。

于是，对于每个连通块，相当于要求解其中一个元素的数值。

我们不妨用 $x$ 表示这个元素，则这个连通块内每个元素都可以用 $x+b$ 或 $-x+b$ 的形式进行表示。

接下来，考虑这个连通块中的边，如果存在一条边，两侧分别是 $x+b_1, x+b_2$ 或 $-x+b_1, -x+b_2$ ，则此时已经形成了一个方程，我们可以根据方程解 $x$ 。

否则， $x$ 无法唯一确定，此时我们要最小化 $\sum |x+a_i|+\sum |-x+b_i|$ 。由于 $|x|=|-x|$ ，问题可以进一步转化为 $\sum |x+a'_i|$ 的最小值（把上面的 $|-x+b_i|$ 变为 $|x-b_i|$ 后合并）。

而这件事要最优化，只需令 $x$ 是 $a'_i$ 的中位数即可。（这件事不清楚可以自行搜索绝对值函数最值相关知识，可以用 $|x-a|+|x-b|\geq |a-b|$ ，再将大的数值和小的数值两两匹配得到）

最后检查是否连通块的每条边都被满足即可。这里可以使用浮点数运算，因为计算结果不会太大，且小鼠点后只可能是 $0.5$ （我们解的方程一次项系数总是 $2$ ）。而同样地，边的检查也不需严格，因为误差不会过大。

时间复杂度为 $\mathcal{O}(n+m)$ ，如果采取 $\mathcal{O}(n)$ 的方式求中位数，否则可能带 $\log$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m = MII()

    us = []
    vs = []
    ws = []
    path = [[] for _ in range(n)]

    for i in range(m):
        u, v, w = MII()
        u -= 1
        v -= 1
        path[u].append(i)
        path[v].append(i)
        us.append(u)
        vs.append(v)
        ws.append(w)

    notes_k = [0] * n
    notes_b = [0] * n
    ans = [0] * n
    vis = [0] * n

    stk = []
    for i in range(n):
        if notes_k[i] == 0:
            notes_k[i] = 1
            stk.append(i)

            flg = False
            val = 0

            vals = []
            eids = []
            while stk:
                u = stk.pop()
                vals.append(notes_k[u] * notes_b[u])
                for eid in path[u]:
                    eids.append(eid)
                    v = us[eid] + vs[eid] - u
                    w = ws[eid]
                    if notes_k[v] == 0:
                        notes_k[v] = -notes_k[u]
                        notes_b[v] = w - notes_b[u]
                        stk.append(v)
                    elif notes_k[u] == notes_k[v]:
                        flg = True
                        val = (w - notes_b[u] - notes_b[v]) / (notes_k[u] + notes_k[v])

            if not flg:
                vals.sort()
                val = vals[len(vals) // 2]

            stk.append(i)
            ans[i] = val
            vis[i] = 1

            while stk:
                u = stk.pop()
                for eid in path[u]:
                    v = us[eid] + vs[eid] - u
                    w = ws[eid]
                    if vis[v] == 0:
                        vis[v] = 1
                        ans[v] = w - ans[u]
                        stk.append(v)

            for eid in eids:
                if abs(ans[us[eid]] + ans[vs[eid]] - ws[eid]) > 0.1:
                    print('NO')
                    exit()

    print('YES')
    print(' '.join(map(str, ans)))
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, m;
    cin >> n >> m;

    vector<int> us(m), vs(m), ws(m);
    vector<vector<int>> path(n);

    for (int i = 0; i < m; i ++) {
        cin >> us[i] >> vs[i] >> ws[i];
        us[i] --, vs[i] --;
        path[us[i]].emplace_back(i);
        path[vs[i]].emplace_back(i);
    }

    vector<int> notes_k(n, 0), notes_b(n, 0), vis(n, 0);
    vector<double> ans(n, 0);

    for (int i = 0; i < n; i ++) {
        if (notes_k[i] == 0) {
            notes_k[i] = 1;

            bool flg = false;
            double val;

            vector<int> vals, eids;
            auto dfs1 = [&] (auto &self, int u) -> void {
                vals.emplace_back(notes_k[u] * notes_b[u]);
                for (auto &eid: path[u]) {
                    eids.emplace_back(eid);
                    int v = us[eid] + vs[eid] - u, w = ws[eid];
                    if (notes_k[v] == 0) {
                        notes_k[v] = -notes_k[u];
                        notes_b[v] = w - notes_b[u];
                        self(self, v);
                    }
                    else if (notes_k[u] == notes_k[v]) {
                        flg = true;
                        val = 1.0 * (w - notes_b[u] - notes_b[v]) / (notes_k[u] + notes_k[v]);
                    }
                }
            };

            dfs1(dfs1, i);

            if (!flg) {
                sort(vals.begin(), vals.end());
                val = -vals[vals.size() / 2];
            }

            ans[i] = val;

            auto dfs2 = [&] (auto &self, int u) -> void {
                for (auto &eid: path[u]) {
                    int v = us[eid] + vs[eid] - u, w = ws[eid];
                    if (!vis[v]) {
                        vis[v] = 1;
                        ans[v] = w - ans[u];
                        self(self, v);
                    }
                }
            };

            dfs2(dfs2, i);

            for (auto &eid: eids) {
                if (abs(ans[us[eid]] + ans[vs[eid]] - ws[eid]) > 0.1) {
                    return cout << "NO", 0;
                }
            }
        }
    }

    cout << "YES\n";
    for (auto &x: ans)
        cout << x << ' ';

    return 0;
}
```

**提示 1：** 我们不在乎涂色格子的具体位置，只在乎有几列 / 几行被填过。

**提示 2：** 我们新填入一格时，上述数量如何转变？利用这点进行 DP 。

简单 DP 。

首先，涂色格子的位置并不重要，因为我们的目标是每行 / 每列都有涂色的格子。

而假设某一时刻，有 $i$ 行涂色，有 $j$ 列涂色。此时新涂一个格子，这两个变量怎么变呢？

- 有 $p_1=i\times j/n^2$ 的概率，涂在了原来就有涂色的行 / 列，不影响。

- 有 $p_2=i\times (n-j)/n^2$ 的概率，新增一列。

- 有 $p_3=(n-i)\times j/n^2$ 的概率，新增一行。

- 有 $p_4=(n-i)\times(n-j)/n^2$ 的概率，同时新增一行一列。

假设从 $i$ 行 $j$ 列的状态出发，到满足条件，需要的期望步数是 $dp[i][j]$ ，则：

$dp[i][j]=1(先执行一步)+(p_1dp[i][j]+p_2dp[i][j+1]+p_3dp[i+1][j]+p_4dp[i+1][j+1])(后续需要的期望步数)$

于是，将左右的 $dp[i][j]$ 移项后解方程，有：

$dp[i][j]=(1+p_2dp[i][j+1]+p_3dp[i+1][j]+p_4dp[i+1][j+1])/(1-p_1)$

利用上述转移关系进行 DP 即可。

时间复杂度为 $\mathcal{O}(n^2+m)$ 。后面的代码实现与前面给出的解释略有不同。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m = MII()
    cnt_r = [0] * n
    cnt_c = [0] * n

    for _ in range(m):
        x, y = GMI()
        cnt_r[x] = 1
        cnt_c[y] = 1

    v1 = n - sum(cnt_r)
    v2 = n - sum(cnt_c)

    dp = [[0] * (v2 + 2) for _ in range(v1 + 2)]

    for i in range(v1, -1, -1):
        for j in range(v2, -1, -1):
            if i == v1 and j == v2: continue
            dp[i][j] = (n * n + (v1 - i) * (v2 - j) * dp[i + 1][j + 1]
                        + (v1 - i) * (n - v2 + j) * dp[i + 1][j]
                        + (n - v1 + i) * (v2 - j) * dp[i][j + 1]) / (n * n - (n - v1 + i) * (n - v2 + j))

    print(dp[0][0])
```

C++ 做法如下——

```cpp []
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, m;
    cin >> n >> m;

    vector<int> cnt_r(n, 0), cnt_c(n, 0);
    int v1 = n, v2 = n;

    while (m --) {
        int x, y;
        cin >> x >> y;
        x --, y --;
        if (!cnt_r[x]) cnt_r[x] = 1, v1 --;
        if (!cnt_c[y]) cnt_c[y] = 1, v2 --;
    }

    vector<vector<long double>> dp(v1 + 2, vector<long double>(v2 + 2, 0));

    for (int i = v1; i >= 0; i --) {
        for (int j = v2; j >= 0; j --) {
            if (i == v1 && j == v2) continue;
            dp[i][j] = (long double)1.0 * (n * n 
                    + (v1 - i) * (v2 - j) * dp[i + 1][j + 1]
                    + (v1 - i) * (n - v2 + j) * dp[i + 1][j]
                    + (n - v1 + i) * (v2 - j) * dp[i][j + 1]) / (n * n - (n - v1 + i) * (n - v2 + j));
        }
    }

