            for (int i = 1; i < 20; i ++) {
                p = parent[i - 1][u];
                parent[i][u] = parent[i - 1][p];
                parent_weight[i][u] = max(parent_weight[i - 1][u], parent_weight[i - 1][p]);
            }

            for (int i = 19; i >= 0; i --)
