                            pres[nj][idx + 1] = oid * 101 + j;
                        }
                    }
                }
            }

            if (dp[100] > ddls[i] - cur_time) {
                flg = false;
                break;
            }

            cur_time += dp[100];
            int cur = 100;

            for (int j = cnt; j > 0; j --) {
                if (pres[cur][j] != -1) {
                    ans.emplace_back(pres[cur][j] / 101);
                    cur = pres[cur][j] % 101;
