            for (auto &v: path[u]) {
                if (v[0] != p) {
                    sz += self(self, v[0], u, v[1]);
                }
            }
            mi += (sz & 1 ? w : 0);
            ma += 1ll * min(n - sz, sz) * w;
            return sz;
        };

        dfs(dfs, 0, -1, 0);
        cout << mi << ' ' << ma << '\n';
    }

    return 0;
}
