{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    long long x;
    cin >> x;

    vector<pair<long long, long long>> prs;

    for (long long mi = 1; mi <= 2000000; mi ++) {
        long long a = mi * (mi + 1) * (2 * mi + 1) / 6;
        long long b = mi * (mi + 1) / 2;
        if (x >= a && (x - a) % b == 0) {
            long long w = mi, h = mi + (x - a) / b;
            prs.emplace_back(w, h);
