{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector<int> nums(n);
    for (auto &v: nums) cin >> v;

    vector<int> pref_val(n, 0), suff_val(n, 0);
    vector<long long> pref_tot(n, 0), suff_tot(n, 0);

    for (int i = 0; i < n - 1; i ++) {
        pref_val[i + 1] = max(pref_val[i] + 1, nums[i]);
