signed main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, m;
    cin >> n >> m;

    vector<string> grid(n);
    for (auto &s: grid) cin >> s;

    unionfind dsu(n + m);

    for (int i = 0; i < n; i ++) {
        for (int j = 0; j < m; j ++) {
            if (grid[i][j] == '=') {
                dsu.merge(i, n + j);
            }
        }
    }

    vector<vector<int>> path(n + m);
    vector<int> indegs(n + m, 0);

    for (int i = 0; i < n; i ++) {
        for (int j = 0; j < m; j ++) {
            int u = dsu.leader(i), v = dsu.leader(n + j);
            if (grid[i][j] == '<')  {
                path[u].emplace_back(v);
                indegs[v] ++;
            }
            else if (grid[i][j] == '>') {
                path[v].emplace_back(u);
                indegs[u] ++;
            }
        }
    }

    vector<int> stk, ans(n + m, 0);
    for (int i = 0; i < n + m; i ++) {
        if (indegs[i] == 0) {
            stk.emplace_back(i);
            ans[i] = 1;
        }
    }

    int cnt = 0;
    while (!stk.empty()) {
        int u = stk.back();
        stk.pop_back();
        cnt ++;
        for (auto &v: path[u]) {
            ans[v] = max(ans[v], ans[u] + 1);
            indegs[v] --;
            if (indegs[v] == 0) stk.emplace_back(v);
        }
    }

    if (cnt < n + m) cout << "No";
    else {
        cout << "Yes\n";
        for (int i = 0; i < n; i ++) cout << ans[dsu.leader(i)] << ' ';
        cout << '\n';
        for (int i = 0; i < m; i ++) cout << ans[dsu.leader(n + i)] << ' ';
    }

    return 0;
}
