        }
    }

    vector<vector<int>> dp(n, vector<int>(n, 0)), cnt(n, vector<int>(n, 0));

    for (int l = n - 1; l >= 0; l --) {
        if (s[l] == '?') cnt[l][l] = 1;

        for (int r = l + 1; r < n; r ++) {
            if (dp[l + 1][r - 1] == -1 || (s[l] != '?' && s[r] != '?' && s[l] != s[r]))
                dp[l][r] = -1;
            else {
                dp[l][r] = dp[l + 1][r - 1];
