                    dp[l][r] |= 1 << s[l] - 'a';
                else if (s[l] == '?' && s[r] != '?')
                    dp[l][r] |= 1 << s[r] - 'a';
                else if (s[l] == '?' && s[r] == '?')
                    cnt[l][r] ++;
            }
        }
    }

    vector<vector<int>> calc(18, vector<int>(1 << 17, 0));

    for (int l = 0; l < n; l ++) {
        for (int r = l; r < n; r ++) {
            if (dp[l][r] != -1) {
                for (int i = 1; i <= 17; i ++) {
                    calc[i][dp[l][r]] += pows[i][cnt[l][r] + ques[l] + ques[n] - ques[r + 1]];
                    if (calc[i][dp[l][r]] >= mod) calc[i][dp[l][r]] -= mod;
                }
            }
        }
    }

    for (int i = 1; i <= 17; i ++) {
        for (int j = 0; j < 17; j ++) {
            for (int msk = 0; msk < (1 << 17); msk ++) {
                if ((msk >> j) & 1) {
                    calc[i][msk] += calc[i][msk ^ (1 << j)];
                    if (calc[i][msk] >= mod) calc[i][msk] -= mod;
                }
            }
        }
    }

    int q;
    cin >> q;

    while (q --) {
        string s;
        cin >> s;
        int msk = 0;
        for (auto &c: s)
            msk |= 1 << c - 'a';
        cout << calc[s.size()][msk] << '\n';
    }

    return 0;
}
```

**提示 1：** 更小的桌子能放下的客人，更大的桌子也能放下。

**提示 2：** 根据提示 1，先在小桌子上安置客人对后续大桌子无影响。那放那一批呢？

简单贪心。

首先，更小的桌子意味着更强的约束。小的桌子能放下的人，大的桌子也一定能放下。

于是，我们尝试在最小的 $k$ 张桌子安置客人后，第 $k+1$ 张桌子的选择是更不受约束的，因此前 $k$ 张桌子可以使用贪心算法。

怎么贪心呢？我们找到不超过当前桌子容量的所有组别的还没有安置的人，取其中收益最大的一组即可。

上述过程可以通过排序和堆实现，时间复杂度为 $\mathcal{O}(n\log n)$ 。

本题还可以使用动态规划，让小桌子和更小组的人匹配，考虑前 $i$ 个桌子安置前 $j$ 组人的子集最多能创造多少收益。时间复杂度较高，为 $\mathcal{O}(n^2)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    cs = []
    ps = []

    for _ in range(n):
        c, p = MII()
        cs.append(c)
        ps.append(p)

    k = II()
    rs = LII()

    st_n = sorted(range(n), key=lambda x: cs[x])
    st_k = sorted(range(k), key=lambda x: rs[x])

    pt = 0
    hpq = []

    ans = [-1] * n

    for i in st_k:
        while pt < n and cs[st_n[pt]] <= rs[i]:
            heappush(hpq, -ps[st_n[pt]] * n + st_n[pt])
            pt += 1

        if hpq:
            ans[heappop(hpq) % n] = i

    cnt = 0
    tot = 0
    outs = []

    for i in range(n):
        if ans[i] != -1:
            cnt += 1
            tot += ps[i]
            outs.append(f'{i + 1} {ans[i] + 1}')

    print(cnt, tot)
    print('\n'.join(outs))
```

C++ 做法如下——

```cpp []
signed main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector<int> cs(n), ps(n);

    for (int i = 0; i < n; i ++)
        cin >> cs[i] >> ps[i];

    int k;
    cin >> k;

    vector<int> rs(k);
    for (int i = 0; i < k; i ++)
        cin >> rs[i];

    vector<int> st_n(n), st_k(k);

    iota(st_n.begin(), st_n.end(), 0);
    iota(st_k.begin(), st_k.end(), 0);

    sort(st_n.begin(), st_n.end(), [&] (int i, int j) {return cs[i] < cs[j];});
    sort(st_k.begin(), st_k.end(), [&] (int i, int j) {return rs[i] < rs[j];});

    priority_queue<pair<int, int>> pq;
    vector<int> ans(n, -1);
    int tot = 0, cnt = 0, pt = 0;

    for (auto &i: st_k) {
        while (pt < n && cs[st_n[pt]] <= rs[i]) {
            pq.push({ps[st_n[pt]], st_n[pt]});
            pt ++;
        }

        if (!pq.empty()) {
            tot += pq.top().first;
            cnt ++;
            ans[pq.top().second] = i;
            pq.pop();
        }
    }

    cout << cnt << ' ' << tot << '\n';

    for (int i = 0; i < n; i ++) {
        if (ans[i] != -1) {
            cout << i + 1 << ' ' << ans[i] + 1 << '\n';
        }
    }

    return 0;
}
