    if (power == 0) return 1 % mod;
    long long cur = quickPow(base, power / 2, mod);
    return power & 1 ? base * cur % mod * cur % mod : cur * cur % mod; 
}

signed main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, mod = 1e9 + 7;
    cin >> n;

    vector<int> f(n + 1, 1), g(n + 1, 1);

    for (int i = 1; i <= n; i ++)
        f[i] = 1ll * f[i-1] * i % mod;

    g[n] = quickPow(f[n], mod - 2, mod);

    for (int i = n; i >= 1; i --)
        g[i-1] = 1ll * g[i] * i % mod;

    auto inv = [&] (int x) -> int {
        return 1ll * f[x-1] * g[x] % mod;
    };

    vector<int> perm(n), used(n, 0);
    for (int i = 0; i < n; i ++) {
        cin >> perm[i], perm[i] --;
        if (perm[i] >= 0)
            used[perm[i]] = 1;
    }

    int x0 = 0, x1 = 0;
    for (int i = 0; i < n; i ++) {
        if (!used[i]) {
            if (perm[i] >= 0) x1 ++;
            else x0 ++;
        }
    }

    int ans = 0, cur = 1;
    for (int i = 0; i <= x0; i ++) {
        ans += 1ll * cur * f[x0 + x1 - i] % mod * f[x0] % mod * g[i] % mod * g[x0 - i] % mod;
        cur = -cur;
        if (ans >= mod) ans -= mod;
        if (ans < 0) ans += mod;
    }
    cout << ans;

    return 0;
}
```

**提示 1：** 当我们进行的操作是对数组进行 “较小” 的改动时，我们计算 “成本” 一类变量的好方式是：找到操作前后的数值会如何改变。

**提示 2：** 考虑将 $x$ 改成 $y$ ，哪些位置的成本会改变？总成本如何？如何最小化？

我们只把一个数字改成了另一个数字，相对原数组是不大的改变。考虑修改前后的成本差别，再结合初始成本，即可得到新的成本。

所以，我们先预处理得到原数组的成本。接下来考虑将 $x$ 改成 $y$ 之后，成本如何改变。

首先，如果相邻两项不包含 $x$ ，则对应的位置无需考虑。

否则，如果两项都是 $x$ ，那么全改成 $y$ 后成本仍然不变，因此无需考虑。

于是，唯一需要考虑的位置就是相邻两项中包含 $x$ 且不同的位置，而与 $x$ 不同的另一个数是不会改变的，设分别为 $v_1,v_2,\dots,v_k$ 。

原成本为 $\sum\limits_{i=1}^k|x-v_k|$ ，而新成本为 $\sum\limits_{i=1}^k|y-v_k|$ 。

对于后者这一绝对值函数，最小化的位置在中位数，因此只需排序，可以算出最小的新成本。原成本也很容易计算。

（这是因为我们可以把 $v_1,\dots, v_k$ 最大的和最小的配对。而由于绝对值表示数轴上的距离，因此有 $|y-v_i|+|y-v_j|\geq |v_i-v_j|$ 。于是配对后，最中间的区间位置都可以使得每个不等式取到最小值。）

而这样的总复杂度相当于对不同的 $k\log k$ 求和。而事实上，每个位置（相邻数字对）最多只会出现在两个 $k$ （ $nums[i]$ 和 $nums[i+1]$ ）的计算中，因此 $k$ 的求和是 $\mathcal{O}(n)$ 量级的，上述解法符合复杂度要求。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m = MII()
    nums = LII()

    cur = [0] * (n + 1)
    tmp = [[] for _ in range(n + 1)]

    orig = 0
    for i in range(1, m):
        v = abs(nums[i] - nums[i - 1])
        orig += v

        if nums[i] != nums[i-1]:
            cur[nums[i]] += v
            cur[nums[i-1]] += v
            tmp[nums[i]].append(nums[i-1])
            tmp[nums[i-1]].append(nums[i])

    res = 0
    for i in range(1, n + 1):
        if len(tmp[i]):
            tmp[i].sort()
            x = tmp[i][len(tmp[i]) // 2]
            res = max(res, cur[i] - sum(abs(x - v) for v in tmp[i]))

    print(orig - res)
```

C++ 做法如下——

```cpp []
signed main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, m;
    cin >> n >> m;

    vector<int> nums(m);
    for (auto &v: nums) cin >> v;

    long long orig = 0;
    vector<long long> cur(n + 1);
    vector<vector<int>> tmp(n + 1);

    for (int i = 1; i < m; i ++) {
        int v = abs(nums[i] - nums[i-1]);
        orig += v;

        if (nums[i] != nums[i-1]) {
            cur[nums[i]] += v;
            cur[nums[i-1]] += v;
            tmp[nums[i]].emplace_back(nums[i-1]);
            tmp[nums[i-1]].emplace_back(nums[i]);
        }
    }

    long long res = 0;

    for (int i = 1; i <= n; i ++) {
        if (tmp[i].size()) {
            sort(tmp[i].begin(), tmp[i].end());
            int x = tmp[i][tmp[i].size() / 2];

            long long cur_res = 0;
            for (auto &val: tmp[i]) cur_res += abs(val - x);

            res = max(res, cur[i] - cur_res);
        }
    }
    cout << orig - res;

    return 0;
}
```

**提示 1：** 怎样的序列是合法的？

**提示 2：** 如何调整你的序列使其合法？

首先考虑，调整后数组应当满足什么条件。

首先，只有 $s$ 位置可以是 $0$ ：如果 $s$ 位置不是 $0$ ，该位置也得修改；其他位置的 $0$ 也都得修改。

而对于剩下的数字，都应该至少非 $0$ 。同时，一旦 $x$ 在序列中，那么其 “父节点” 应当对应为 $x-1$ ，因此剩余的数字去重后应当是从 $1$ 开始的连续整数。

而一旦上述条件满足，我们把每个 $x$ 挂在任何一个 $x-1$ 的子节点位置即可，因此上述条件充要。

于是在考虑完 $0$ 的位置后，题目变成：修改数组元素，使得剩余元素是从 $1$ 开始的连续整数组成的数组。

接下来看我们怎么满足对应的条件。

不妨考虑枚举最后的数组由 $1\sim x$ 的数字组成。则操作次数首先至少为 $1\sim x$ 中未出现的数字个数。同时操作次数也至少为不在 $1\sim x$ 范围内的数字个数。两者取最大值即可。（因为里面的空总能填满，同时外面的数字也总能变进来，两件事也是可以直接同时进行的。）

（下面的代码不完全按照上述逻辑，但本质相同）

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, s = MII()
    s -= 1
    nums = LII()

    ans = 0
    cnt = [0] * n

    for i in range(n):
        if i == s:
            if nums[i]: ans += 1
        else: cnt[nums[i]] += 1

    cur = 0
    for i in range(1, n):
        if cnt[i]:
            cur += cnt[i]
        else:
            cur += 1
            ans += 1
        if cur >= n - 1: break

    print(ans)
```

