**提示 2：** 这个位运算只要有 $1$ 结果就是 $0$ 。所以从后往前推，只有最前面的那个 $1$ 有意义。

**提示 3：** 枚举最前面的 $1$ 的位置。

首先，仔细阅读这个位运算操作，可以发现，只要输入的两个元素中有 $1$ ，输出就一定是 $0$ 。

这件事很像我们的与运算，一遇到 $0$ 就清零了，这里类似地，一遇到 $1$ 就清零了。

于是，一旦我们从后往前对字符串进行操作的时候遇到 $1$ ，下一步结果一定是 $0$ ，因此 **我们只需考虑最前面的那个 $1$ 的位置，即可快速计算当前字符串的结果** 。

因此，我们枚举这个 $1$ 的位置。不妨设为 $i$ ，则只要 $i$ 不出现在字符串最后，字符串操作到只有 $1\sim i$ 位时候，一定全局都是 $0$ ，因此可以快速算出字符串的结果。

如果当前的 $1$ 的位置满足要求，则这个 $1$ 后面的所有 $0,1$ 都可以任意排列位置。设还有 $x$ 个 $0$ ， $y$ 个 $1$ ，则方案数有 $C_{x+y}^x$ 种。

为了计算组合数，可以预处理所有 $n!$ 及其逆元（即和 $n!$ 相乘取模后为 $1$ 的元素，关于质数 $p$ 的逆元可以使用 $p-2$ 次的结果进行计算）。

前者可以使用 $n!=n\times (n-1)!$ ，后者可以使用 $\frac{1}{(n-1)!}=n\times\frac{1}{n!}$ 。因此整体只需要先推出 $1!,2!,\dots,n!$ ，再得到 $n!$ 的逆元，最后反向推出 $(n-1)!\dots,1!$ 的逆元即可。

当然，还有两种特殊情况：

- 整个字符串中没有 $1$ ：可以选择直接模拟，看结果是否对应为 $g$ 。

- 字符串只有一个 $1$ ：此时 $1$ 可以放在末尾，查看这种情况的结果是否为 $g$ 。

综上，时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m, g = MII()

    mod = 10 ** 9 + 7
    fact = Factorial(n + m, mod)

    if m == 0:
        cur = 0
        for i in range(n - 1):
            cur = 1 - (cur | 0)
        if cur == g: print(1)
        else: print(0)

    elif m == 1:
        ans = 0
        cur = 0
        for i in range(n):
            if cur == g: ans += 1
            cur = 1 - (cur | 0)
        print(ans + (cur != g))

    else:
        ans = 0
        cur = 0
        for c0 in range(n + 1):
            if cur == g:
                ans += fact.combi(n + m - 1 - c0, n - c0)
                if ans >= mod:
                    ans -= mod
            cur = 1 - (cur | 0)
        print(ans)
```

C++ 做法如下——

```cpp []
long long quickPow(long long base, long long power, long long mod) {
    if (power == 0) return 1 % mod;
    long long cur = quickPow(base, power / 2, mod);
    return power & 1 ? base * cur % mod * cur % mod : cur * cur % mod; 
}

signed main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, m, g;
    cin >> n >> m >> g;

    int mod = 1e9 + 7;
    vector<int> f(n + m + 1, 1), rev(n + m + 1, 1);
    for (int i = 1; i <= n + m; i ++)
        f[i] = 1ll * f[i - 1] * i % mod;
    rev[n + m] = quickPow(f[n + m], mod - 2, mod);
    for (int i = n + m; i >= 1; i --)
        rev[i - 1] = 1ll * rev[i] * i % mod;

    if (!m) {
        int cur = 0;
        for (int i = 0; i < n - 1; i ++)
            cur = 1 - cur;
        cout << (cur == g ? 1 : 0);
    }
    else if (m == 1) {
        int ans = 0, cur = 0;
        for (int i = 0; i < n; i ++) {
            if (cur == g) ans ++;
            cur = 1 - cur;
        }
        cout << ans + (cur ^ g);
    }
    else {
        int ans = 0, cur = 0;
        for (int c0 = 0; c0 <= n; c0 ++) {
            if (cur == g) {
                ans += 1ll * f[n + m - 1 - c0] * rev[n - c0] % mod * rev[m - 1] % mod;
                if (ans >= mod) ans -= mod;
            }
            cur = 1 - cur;
        }
        cout << ans;
    }

    return 0;
}
```

**提示 1：** 我们只需要满足一个人的拿票比最后一个人多，于是只需要枚举这个人。

**提示 2：** 考虑两个人，我们要让一个人的选票比另一个人多，我们应该如何开启最多的投票站。

本题只需要让一个人的拿票比别人多，我们可以枚举这个人是谁，再看选哪个人最好。

考虑某个人 $i$ 的时候，其他人都不重要了，因此只需考虑两个人的情况下如何使得你选的这个人得票更多。

设你选的人的得票情况是 $a$ ，最后一个人的得票情况是 $b$ ，则要求 $\sum a_i\geq\sum b_i$ 。

移项后，有 $\sum (a_i-b_i)\geq 0$ ，因此只需关于 $a_i-b_i$ 逆序排序，取最大的若干个投票站且保证总和非负即可。

时间复杂度为 $\mathcal{O}(nm\log m)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m = MII()
    grid = [LII() for _ in range(m)]

    ans = 0
    idx = -1

    for i in range(n - 1):
        diff = [grid[j][n - 1] - grid[j][i] for j in range(m)]
        diff.sort()

        cur = 0
        for j in range(m):
            cur += diff[j]
            if cur > 0: break
            if j + 1 > ans:
                ans = j + 1
                idx = i

    print(m - ans)
    if ans == 0: print(' '.join(map(str, range(1, m + 1))))
    else:
        st_range = sorted(range(m), key=lambda x: grid[x][n - 1] - grid[x][idx])[ans:]
        print(' '.join(str(x + 1) for x in st_range))
```

C++ 做法如下——

```cpp []
signed main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, m;
    cin >> n >> m;

    vector<vector<int>> grid(m, vector<int>(n));
    for (int i = 0; i < m; i ++) {
        for (int j = 0; j < n; j ++) {
            cin >> grid[i][j];
        }
    }

    int ans = 0, idx = -1;
    for (int i = 0; i < n - 1; i ++) {
        vector<int> diff;
        for (int j = 0; j < m; j ++)
            diff.emplace_back(grid[j][n - 1] - grid[j][i]);
        sort(diff.begin(), diff.end());

        int cur = 0;
        for (int j = 0; j < m; j ++) {
            cur += diff[j];
            if (cur > 0) break;
            if (j + 1 > ans)
                ans = j + 1, idx = i;
        }
    }

    cout << m - ans << '\n';
    if (ans == 0)
        for (int j = 1; j <= n; j ++) cout << j << ' ';
    else {
        vector<int> st_range(m);
        iota(st_range.begin(), st_range.end(), 0);
        sort(st_range.begin(), st_range.end(), [&](int i, int j) {return grid[i][n - 1] - grid[i][idx] < grid[j][n - 1] - grid[j][idx];});
        for (int i = ans; i < m; i ++) cout << st_range[i] + 1 << ' ';
    }

    return 0;
}
