    string a, c;
    int b, d;

    cin >> b >> d >> a >> c;

    int m = c.size();

    vector<int> to_idx(m), cnt(m, 0);
    iota(to_idx.begin(), to_idx.end(), 0);

    for (int i = 0; i < m; i ++) {
        for (auto &ch: a) {
            if (ch == c[to_idx[i]]) {
