        for (int c1 = 0; c1 <= 3 && c1 <= tmp[1].size(); c1 ++) {
            for (int c2 = 0; c2 * 2 + c1 <= 3 && c2 <= tmp[2].size(); c2 ++) {
                for (int c3 = 0; c3 * 3 + c2 * 2 + c1 <= 3 && c3 <= tmp[3].size(); c3 ++) {
                    long long tot = 0;
                    int ma = 0;
                    for (int i = 0; i < c1; i ++) {
