                    for (int i = 0; i < c2; i ++) {
                        tot += tmp[2][i];
                        ma = max(ma, tmp[2][i]);
                    }
                    for (int i = 0; i < c3; i ++) {
                        tot += tmp[3][i];
                        ma = max(ma, tmp[3][i]);
                    }

                    for (int i = 0; i < 10; i ++) {
                        long long v = dp[i] + tot, ni = i + c1 + c2 + c3;
                        if (ni >= 10) {
                            v += ma;
                            ni -= 10;
                        }
