    vector<int> xs(n), ys(n), zs(n);
    for (int i = 0; i < n; i ++) 
        cin >> xs[i] >> ys[i] >> zs[i];

    vector<pair<int, int>> ans;

    auto solve1 = [&] (vector<int> tmp) -> vector<int> {
        sort(tmp.begin(), tmp.end(), [&](int i, int j) {return zs[i] < zs[j];});
        while (tmp.size() > 1) {
