            int x = resid.back();
            resid.pop_back();
            int y = resid.back();
            resid.pop_back();
            ans.emplace_back(x, y);
        }
    };

    vector<int> to_solve(n);
    iota(to_solve.begin(), to_solve.end(), 0);
    solve3(to_solve);

    for (auto &[x, y]: ans)
        cout << x + 1 << ' ' << y + 1 << '\n';


