    int v0 = 0, v1023 = 1023;
    while (n --) {
        char op;
        int x;
        cin >> op >> x;
        if (op == '|') v0 |= x, v1023 |= x;
        else if (op == '&') v0 &= x, v1023 &= x;
        else v0 ^= x, v1023 ^= x;
    }
