    int n, k;
    cin >> n >> k;
    cout << (n - 1) / k * 2 + min((n - 1) % k, 2) << '\n';
    for (int i = 1; i <= k; i ++)
        cout << n << ' ' << i << '\n';
    for (int i = k + 1; i < n; i ++)
        cout << i - k << ' ' << i << '\n';

