    for (int i = 0; i < n / 2; i ++) {
        ans[i] = i * 2 + 1;
        ans[n-1-i] = i * 2 + 1;
        ans[n+i] = (i + 1) * 2;
        ans[2*n-2-i] = (i + 1) * 2;
    }
    for (auto &x: ans) cout << (x ? x : n) << ' ';

