        cin >> x1 >> y1 >> x2 >> y2;
        x1 -- , y1 -- , x2 -- , y2 --;
        cout << (p1[x1] == p1[x2] && p2[y1] == p2[y2] ? "YES\n" : "NO\n");
    }

    return 0;
}
