    cin >> n >> x;
    int l = x, r = x;
    long long ans = 0;

    while (n --) {
        int nl, nr;
        cin >> nl >> nr;
        if (r < nl) {
            ans += nl - r;
            l = r;
            r = nl;
        }
        else if (l > nr) {
            ans += l - nr;
            r = l;
            l = nr;
        }
