                vector<int> ncur;
                for (auto &msk: cur[i]) {
                    int x = msk / m, y = msk % m;
                    for (auto &[dx, dy]: dirs) {
                        if (x + dx >= 0 && x + dx < n && y + dy >= 0 && y + dy < m && grid[x+dx][y+dy] == '.') {
