        print('?', x1, y1, x2, y2, flush=True)
        return II()

    def solve(x1, y1, x2, y2):
        l, r = x1, x2
        while l <= r:
            m = (l + r) // 2
            if query(m, y1, x2, y2):
                l = m + 1
            else:
                r = m - 1
        rectangles.append(r)

