    cout.tie(0);

    long long orig;
    int q;
    cin >> orig >> q;

    while (q --) {
        long long n;
        string s;
        cin >> n >> s;

        for (auto &c: s) {
            long long x = n & -n;
            if (c == 'L') {
                if (x > 1) n -= x / 2;
            }
            else if (c == 'R') {
                if (x > 1) n += x / 2;
