signed main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int t, mod = 998244353;
    cin >> t;

    while (t --) {
        int n, k;
        cin >> n >> k;

        vector<int> perm(n);
        for (auto &x: perm) cin >> x, x --;

        vector<int> pos(n);
        for (int i = 0; i < n; i ++)
            pos[perm[i]] = i;

