**提示 1：** 假设我们现在已经构造出了一个答案，那么在某个点新增一个叶子节点时，我们应该如何染色？

**提示 2：** 上述染色是最优的吗？

首先，如果我们已经完成了一棵树的染色，那么在任何一点新增一个叶子节点时，我们怎么对这个点出现的冰淇淋进行染色呢？

有如下几种情况：

- 该冰淇淋之前出现过：则一定在引出叶子节点的位置出现过，因此一定不会相互矛盾。

- 该冰淇淋之前没有出现过：此时需要赋值某种颜色。我们直接选取这个点没出现过的最小编号的颜色即可，因为这样既不会跟现有染色冲突，也使得这个节点出现的颜色编号的最大值最小。

上面两种情况都满足贪心要求，因此直接如此贪心即可。

时间复杂度为 $\mathcal{O}(n+m)$ ，由于要遍历一棵树，同时每个点的处理复杂度为该点的数组长度。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m = MII()
    ice_creams = [[] for _ in range(n)]

    for i in range(n):
        _, *ice_creams[i] = GMI()

    path = [[] for _ in range(n)]
    for _ in range(n - 1):
        u, v = GMI()
        path[u].append(v)
        path[v].append(u)

    used = [0] * m
    ans = [-1] * m

    vis = [0] * n

    stack = [0]

    while stack:
        u = stack.pop()
        vis[u] = 1

        for i in ice_creams[u]:
            if ans[i] != -1:
                used[ans[i]] = 1

        pt = 0
        for i in ice_creams[u]:
            if ans[i] == -1:
                while used[pt]: pt += 1
                ans[i] = pt
                used[pt] = 1

        for i in ice_creams[u]:
            used[ans[i]] = 0

        for v in path[u]:
            if not vis[v]:
                stack.append(v)

    for i in range(m):
        if ans[i] == -1: ans[i] = 1
        else: ans[i] += 1

    print(max(ans))
    print(' '.join(map(str, ans)))
```

C++ 做法如下——

```cpp []
signed main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, m;
    cin >> n >> m;

    vector<vector<int>> ice_creams(n);

    for (int i = 0; i < n; i ++) {
        int k;
        cin >> k;
        ice_creams[i].resize(k);
        for (auto &x: ice_creams[i])
            cin >> x, x --;
    }

    vector<vector<int>> path(n);

    for (int i = 0; i < n - 1; i ++) {
        int u, v;
        cin >> u >> v;
        u --;
        v --;
        path[u].push_back(v);
        path[v].push_back(u);
    }

    vector<int> ans(m, -1);
    vector<int> used(m);

    function<void(int, int)> dfs = [&] (int u, int p) {
        for (auto &x: ice_creams[u])
            if (ans[x] != -1)
                used[ans[x]] = 1;

        int pt = 0;
        for (auto &x: ice_creams[u])
            if (ans[x] == -1) {
                while (used[pt]) pt ++;
                ans[x] = pt;
                used[pt] = 1;
            }

        for (auto &x: ice_creams[u])
            used[ans[x]] = 0;

        for (auto &v: path[u])
            if (v != p)
                dfs(v, u);
    };

    dfs(0, -1);

    for (int i = 0; i < m; i ++) 
        ans[i] = (~ans[i] ? ans[i] + 1 : 1);

    cout << *max_element(ans.begin(), ans.end()) << '\n';
    for (auto &x: ans) cout << x << ' ';

    return 0;
}
