        for (int j = 0; j <= i; j ++)
            for (int k = i; k < n; k ++)
                if (abs(xs - px[i]) + abs(ys - py[i]) + px[k] - px[j] + py[k] - py[j] + min(px[k] - px[i] + py[k] - py[i], px[i] - px[j] + py[i] - py[j]) <= t)
                    ans = max(ans, k - j + 1);

    cout << ans << '\n';

    return 0;
}
