**提示 1：** 你知道这个字符串最后是合法的括号字符串，这就意味着最后左括号和右括号的数量是确定的。

**提示 2：** 接下来你要分配左括号和右括号。将左括号视为加一，右括号视为减一，为了使得中间不出现合法的严格前缀，即不出现为 $0$ 的前缀和，你应该怎么贪心分配？

首先，我们可以根据条件计算出左括号的数量。因为整个字符串是合法的，所以左括号数量应当占整体长度的一半，因此填入的左括号数量应当为长度的一半减去当前字符串中左括号的个数。

而为了保证我们填入的字符串“尽可能合法”，可以先看下上面的提示 2。

我们将左括号视为加一，右括号视为减一，那么在从头到尾遍历的过程中，不应该出现负数（否则不合法）和 $0$ （否则存在合法前缀），因此应该尽可能 **往前放左括号** ，这样可以使得前缀和尽可能大。

于是我们贪心往前放左括号，剩余的放右括号，最后判断构造出来的字符串是否合法即可。

时间复杂度为 $\mathcal{O}(n)$ .

#### 具体代码如下（只包含中间处理部分）——

Python 做法如下——

```Python []
def main():
    n = II()
    s = list(I())
    c1 = n // 2 - s.count('(')
    cur = 0
    for i in range(n):
        if s[i] == '(': cur += 1
        elif s[i] == ')': cur -= 1
        elif c1:
            s[i] = '('
            cur += 1
            c1 -= 1
        else:
            s[i] = ')'
            cur -= 1
        if cur <= 0 and i != n - 1:
            print(':(')
            break
    else:
        print(''.join(s) if cur == 0 else ':(')
```

C++ 做法如下——

```cpp []
signed main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    string s;
    cin >> n >> s;

    int cnt = 0;
    for (auto &c: s)
        cnt += (c == '(');

    int left = n / 2 - cnt, cur = 0;

    for (int i = 0; i < n; i ++) {
        if (s[i] == '(')
            cur ++;
        else if (s[i] == ')')
            cur --;
        else if (left) 
            s[i] = '(', cur ++, left --;
        else
            s[i] = ')', cur --;
        if (cur <= 0 && i != n - 1) {
            cout << ":(\n";
            return 0;
        }
    }
    cout << (cur == 0 ? s : ":(") << '\n';

    return 0;
}
```

**提示 1：** 这个数据范围允许我们预处理任意两点的距离。

**提示 2：** 考虑四个点构成的序列 $a\to b\to c\to d$ ，我们如果要枚举，应该选择其中最核心的一部分，你觉得是哪一部分呢？

首先，如上提示 1 所说，我们先预处理任意两点的距离。

接下来，我们要求 $a\to b\to c\to d$ 距离和的最大值。最直接的方式肯定是枚举，但我们枚举什么呢？

在这一个序列中，最特殊的是 $b\to c$ ，因为其是这个序列中最中间的部分，这保证了前后枚举是没有依赖关系的，只需要考虑能到达 $b$ 的所有 $a$ 和 $c$ 能到达的所有 $d$ .

因此，我们枚举 $b\to c$ ，接下来考虑如何选取 $a,d$ 。

我们一定选取距 $b$ 最远的几个 $a$ 之一，而为了不和 $c,d$ 中任何一个重复，因此我们应当 **取和 $b$ 距离最远的 $3$ 个之一**，这样总有能有不重复的剩下来；同时，类似地，为了避免和 $a,b$ 重复，我们应当 **取和 $c$ 距离最远的 $3$ 个之一** 。

因此我们枚举 $b\to c$ ，接下来枚举最远的 $3$ 个 $a,d$ 即可，总枚举次数也是 $\mathcal{O}(n^2)$ 的。

时间复杂度为 $\mathcal{O}(nm + n^2)$ ，来源于 BFS 和最后求答案。

#### 具体代码如下（只包含中间处理部分）——

Python 做法如下——

```Python []
def main():
    n, m = MII()
    path = [[] for _ in range(n)]
    rev_path = [[] for _ in range(n)]

    for _ in range(m):
        u, v = GMI()
        path[u].append(v)
        rev_path[v].append(u)

    def f(x, y):
        return x * n + y

    # 事实上无需把所有距离都存下来，我们只需要找前三大的
    # 因此计算完 u 出发的最短路后，可以只存前三大的数值，无需开 n * n 列表，这里只是为了显示做法
    # 事实上也没必要建反图，只需要对于 u 查看 dist[i][u] 数值即可，这里也是为了直观并完整展示逻辑
    dist = [-1] * (n * n)
    rev_dist = [-1] * (n * n)

    q = [0] * n
    for i in range(n):
        dist[f(i, i)] = 0
        q[0] = i
        l, r = 0, 1
        while l < r:
            u = q[l]
            l += 1
            for v in path[u]:
                if dist[f(i, v)] == -1:
                    dist[f(i, v)] = dist[f(i, u)] + 1
                    q[r] = v
                    r += 1

        rev_dist[f(i, i)] = 0
        q[0] = i
        l, r = 0, 1
        while l < r:
            u = q[l]
            l += 1
            for v in rev_path[u]:
                if rev_dist[f(i, v)] == -1:
                    rev_dist[f(i, v)] = rev_dist[f(i, u)] + 1
                    q[r] = v
                    r += 1

    ma = [[-1] * n for _ in range(3)]

    for i in range(n):
        for j in range(n):
            if dist[f(i, j)] > 0:
                if ma[0][i] == -1 or dist[f(i, j)] >= dist[f(i, ma[0][i])]:
                    ma[0][i], ma[1][i], ma[2][i] = j, ma[0][i], ma[1][i]
                elif ma[1][i] == -1 or dist[f(i, j)] >= dist[f(i, ma[1][i])]:
                    ma[1][i], ma[2][i] = j, ma[1][i]
                elif ma[2][i] == -1 or dist[f(i, j)] >= dist[f(i, ma[2][i])]:
                    ma[2][i] = j

    rev_ma = [[-1] * n for _ in range(3)]

    for i in range(n):
        for j in range(n):
            if rev_dist[f(i, j)] > 0:
                if rev_ma[0][i] == -1 or rev_dist[f(i, j)] >= rev_dist[f(i, rev_ma[0][i])]:
                    rev_ma[0][i], rev_ma[1][i], rev_ma[2][i] = j, rev_ma[0][i], rev_ma[1][i]
                elif rev_ma[1][i] == -1 or rev_dist[f(i, j)] >= rev_dist[f(i, rev_ma[1][i])]:
                    rev_ma[1][i], rev_ma[2][i] = j, rev_ma[1][i]
                elif rev_ma[2][i] == -1 or rev_dist[f(i, j)] >= rev_dist[f(i, rev_ma[2][i])]:
                    rev_ma[2][i] = j

    ans = 0
    chosen = []
    for b in range(n):
        for c in range(n):
            if b != c and dist[f(b, c)] > 0:
                for bi in range(3):
                    a = rev_ma[bi][b]
                    if a != -1 and a != b and a != c:
                        for ci in range(3):
                            d = ma[ci][c]
                            if d != -1 and d != a and d != b and d != c:
                                res = dist[f(a, b)] + dist[f(b, c)] + dist[f(c, d)]
                                if res > ans:
                                    ans = res
                                    chosen = [a, b, c, d]

    print(' '.join(str(x + 1) for x in chosen))
```

C++ 做法如下——

```cpp []
signed main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, m;
    cin >> n >> m;

    vector<vector<int>> g(n), rev_g(n);

    for (int i = 0; i < m; i ++) {
        int u, v;
        cin >> u >> v;
        u --, v --;
        g[u].push_back(v);
        rev_g[v].push_back(u);
    }

    vector<vector<pair<int, int>>> large3(3, vector<pair<int, int>>(n, make_pair(-1, 1)));
    vector<vector<pair<int, int>>> rev_large3(3, vector<pair<int, int>>(n, make_pair(-1, 1)));
    vector<vector<int>> dist(n, vector<int>(n, -1));

    vector<int> q;
    int l;
    for (int i = 0; i < n; i ++) {
        vector<int> revdist(n, -1);

        q.clear();
        dist[i][i] = 0;
        q.push_back(i);
        l = 0;

        while (l < q.size()) {
            int u = q[l];
            l ++;
            for (auto &v: g[u]) {
                if (dist[i][v] == -1) {
                    dist[i][v] = dist[i][u] + 1;
                    q.push_back(v);
                }
            }
        }

        q.clear();
        revdist[i] = 0;
        q.push_back(i);
        l = 0;

        while (l < q.size()) {
            int u = q[l];
            l ++;
            for (auto &v: rev_g[u]) {
                if (revdist[v] == -1) {
                    revdist[v] = revdist[u] + 1;
                    q.push_back(v);
                }
            }
        }

        for (int j = 0; j < n; j ++) {
            if (dist[i][j] > 0) {
                if (large3[0][i].second <= dist[i][j]) {
                    swap(large3[1][i], large3[2][i]);
                    swap(large3[0][i], large3[1][i]);
                    large3[0][i] = make_pair(j, dist[i][j]);
                }
                else if (large3[1][i].second <= dist[i][j]) {
                    swap(large3[1][i], large3[2][i]);
                    large3[1][i] = make_pair(j, dist[i][j]);
                }
                else if (large3[2][i].second < dist[i][j]) {
                    large3[2][i] = make_pair(j, dist[i][j]);
                }
            }
            if (revdist[j] > 0) {
                if (rev_large3[0][i].second <= revdist[j]) {
                    swap(rev_large3[1][i], rev_large3[2][i]);
                    swap(rev_large3[0][i], rev_large3[1][i]);
                    rev_large3[0][i] = make_pair(j, revdist[j]);
                }
                else if (rev_large3[1][i].second <= revdist[j]) {
                    swap(rev_large3[1][i], rev_large3[2][i]);
                    rev_large3[1][i] = make_pair(j, revdist[j]);
                }
                else if (rev_large3[2][i].second < revdist[j]) {
                    rev_large3[2][i] = make_pair(j, revdist[j]);
                }
            }
        }
    }

    int ans = 0;
    vector<int> outs(4);
    for (int b = 0; b < n; b ++)
        for (int c = 0; c < n; c ++) {
            if (dist[b][c] > 0) {
                for (int i = 0; i < 3; i ++) {
                    int a = rev_large3[i][b].first;
                    if (a != -1 && a != c) {
                        for (int j = 0; j < 3; j ++) {
                            int d = large3[j][c].first;
                            if (d != -1 && d != a && d != b && dist[a][b] + dist[b][c] + dist[c][d] > ans) {
                                ans = dist[a][b] + dist[b][c] + dist[c][d], outs[0] = a, outs[1] = b, outs[2] = c, outs[3] = d;
                            } 
                        }
                    }
                }
            }
        }

    for (auto &x: outs) cout << x + 1 << ' ';
    return 0;
}
```

**提示 1：** 为了使排名变好，我们应该放飞那些比我们厉害的人！

**提示 2：** 但放飞别人的过程中，我们自己的气球也变少了，所以也有别人超过了我们，这时候他们也进入了被放飞的备选列表！

本题显然是个贪心，最核心的思想是，用最少的气球放飞最多的比我们厉害的队伍。

那么，我们把每个比我们厉害的队伍放到一个列表中，我们每次选取其中放飞成本最低的，将其放飞，查看我们当前排名即可。

但由于我们的气球在上述过程中也变少了，因此也会有一些新队伍变得比我们厉害，我们需要加入他们到被放飞的“备选列表”中。

不断进行上述的贪心操作，直到我们最后没有气球了，或者没有比我们厉害的队伍了为止，过程中出现的最优排名即为答案。

那么上述过程如何维护呢？

我们需要从一个数据结构中不断添加元素，并取出最小元素，这件事情可以通过堆实现。

而往备选列表中添加的元素，实际上是关于 $t_i$ 逆序加入的，因此我们可以预先排序，使用一个指针记录上一次加入备选列表的元素，接下来便可以 $\mathcal{O}(1)$ 找到下一个加入备选列表的元素。

时间复杂度为 $\mathcal{O}(n\log n)$ .

（事实上，上面并没有完整证明为何这样是最优的，虽然每一步都是当时最优的。但看到的题解目前都是这么说的。）

#### 具体代码如下（只包含中间处理部分）——

Python 做法如下——

```Python []
def main():
    n = II()
    x, y = MII()

    ts = []
    ws = []

    for _ in range(n - 1):
        t, w = MII()
        ts.append(t)
        ws.append(w)

    st_range = sorted(range(n - 1), key=lambda x: ts[x])
    ts = [ts[i] for i in st_range]
    ws = [ws[i] for i in st_range]

    pt = n - 2
    hpq = []

    while pt >= 0 and ts[pt] > x:
        heappush(hpq, ws[pt] - ts[pt] + 1)
        pt -= 1

    ans = len(hpq) + 1
    while hpq and x >= hpq[0]:
        x -= heappop(hpq)
        while pt >= 0 and ts[pt] > x:
            heappush(hpq, ws[pt] - ts[pt] + 1)
            pt -= 1
        ans = min(ans, len(hpq) + 1)

    print(ans)
```

C++ 做法如下——

```cpp []
struct team {
    long long balloons;
    long long weight;
};

signed main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    long long x, y;
    cin >> x >> y;

    vector<team> teams(n - 1);

    for (int i = 0; i < n - 1; i ++) 
        cin >> teams[i].balloons >> teams[i].weight;

    sort(teams.begin(), teams.end(), [&] (team x, team y) {return x.balloons > y.balloons;});
    int pt = 0;

    priority_queue<long long, vector<long long>, greater<long long>> pq;
    while ((pt < n - 1) && (x < teams[pt].balloons)) {
        pq.push(teams[pt].weight - teams[pt].balloons + 1);
        pt += 1;
    }

    int ans = (int)pq.size();

    while (!pq.empty() && x >= pq.top()) {
        x -= pq.top();
        pq.pop();
        while ((pt < n - 1) && (x < teams[pt].balloons)) {
            pq.push(teams[pt].weight - teams[pt].balloons + 1);
            pt += 1;
        }
        ans = min(ans, (int)pq.size());
    }
    cout << ans + 1 << '\n';

    return 0;
}
```

**提示 1：** 我们假设我们有穿越技能，可以在每一期调整之前某一期的存款情况。

**提示 2：** 如果在提示 1 的假设下，我们在每一期的存款数量实质上就可以理解一个区间中任选的一个数。维护这个区间即可。

首先，因为我们事先知道了所有的事件，因此我们可以根据后面发生的事件调整前面的每一个时刻进行的存款操作。相当于我们是可以穿越的。

因此，**我们每次存款的时候无需完全确定自己存了多少，可以理解为存款后形成了一个当前总余额的 “可行区间”，这个区间内任何一个数值都可以成为总余额的当前数量** 。

这个区间在后续事件中很方便进行维护：

- 如果当前事件对应于资金的增长 / 减少，那么我们平移该区间即可。但同时，我们的上界需要和 $d$ 取最小值，因此，如果下界大于 $d$ 可以直接返回 `-1` .

- 如果当前事件需要检查余额是否非负，这种情况需要我们特别留意：

    - 如果此时右边界已经为负数了，那么我们此时只能存钱，区间重新恢复到 $[0,d]$ ，存钱次数加一。

    - 否则，不存钱也有合法的区间。而我们需要说明，此时不应该存钱。注意，存钱是为了避免后续存款出现负数的情况，但如果后续真的出现负数了，我们到时候再存也来得及，所以此时不应该存。

按照上述逻辑贪心即可。

时间复杂度为 $\mathcal{O}(n)$ .

#### 具体代码如下（只包含中间处理部分）——

Python 做法如下——

```Python []
def main():
    n, d = MII()
    nums = LII()

    ans = 0
    l, r = 0, 0
    for num in nums:
        if num == 0:
            l = max(l, 0)
            if r < 0:
                r = d
                ans += 1
        else:
            l += num
            r += num
            r = min(r, d)
            if l > d:
                print(-1)
                exit()

    print(ans)
```

C++ 做法如下——

```cpp []
signed main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, d;
    cin >> n >> d;
    int l = 0, r = 0, ans = 0;

    for (int i = 0; i < n; i ++) {
        int x;
        cin >> x;
        if (!x) {
            l = max(l, 0);
            if (r < 0) 
                r = d, ans ++;
        }
        else {
            l += x;
            r += x;
            if (l > d) {
                cout << -1 << '\n';
                return 0;
            }
            r = min(r, d);
        }
    }
    cout << ans << '\n';
    return 0;
}
